INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-10-01', 'colloc-10', 'Cụm học thuật · Nhóm 10', 'Academic Collocation List (Pearson/PTE) — nhóm 10 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 1, 'make a statement', 'đưa ra tuyên bố', 'v + n', '[{"en":"The minister will make a statement about the new law.","vi":"Bộ trưởng sẽ đưa ra tuyên bố về luật mới."},{"en":"She made a strong statement against the proposal.","vi":"Cô ấy đã đưa ra một tuyên bố mạnh mẽ phản đối đề xuất."},{"en":"The company made a statement to reassure its customers.","vi":"Công ty đã đưa ra tuyên bố để trấn an khách hàng."}]', '[]', NULL, '/ˈmeɪk ə ˈsteɪtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 2, 'make a transition', 'thực hiện sự chuyển đổi', 'v + n', '[{"en":"Many firms make a transition to clean energy slowly.","vi":"Nhiều công ty thực hiện sự chuyển đổi sang năng lượng sạch một cách chậm rãi."},{"en":"Students make a transition from school to university life.","vi":"Sinh viên thực hiện sự chuyển đổi từ trường phổ thông sang đời sống đại học."},{"en":"The country made a transition to a market economy.","vi":"Đất nước đã thực hiện sự chuyển đổi sang nền kinh tế thị trường."}]', '[]', NULL, '/ˈmeɪk ə trænˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 3, 'make an argument', 'đưa ra lập luận', 'v + n', '[{"en":"The writer makes an argument for stricter regulations.","vi":"Người viết đưa ra lập luận ủng hộ các quy định chặt chẽ hơn."},{"en":"You should support each claim when you make an argument.","vi":"Bạn nên hỗ trợ mỗi luận điểm khi đưa ra lập luận."},{"en":"She made a convincing argument during the debate.","vi":"Cô ấy đã đưa ra một lập luận thuyết phục trong cuộc tranh luận."}]', '[]', NULL, '/ˈmeɪk ən ˈɑːrgjumənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 4, 'make an assessment', 'đưa ra đánh giá', 'v + n', '[{"en":"The teacher makes an assessment of each student''s progress.","vi":"Giáo viên đưa ra đánh giá về tiến bộ của từng học sinh."},{"en":"Experts made an assessment of the environmental risks.","vi":"Các chuyên gia đã đưa ra đánh giá về các rủi ro môi trường."},{"en":"We need to make an assessment before approving the plan.","vi":"Chúng ta cần đưa ra đánh giá trước khi phê duyệt kế hoạch."}]', '[]', NULL, '/ˈmeɪk ən əˈsesmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 5, 'make an assumption', 'đưa ra giả định', 'v + n', '[{"en":"Do not make an assumption without checking the facts.","vi":"Đừng đưa ra giả định mà chưa kiểm tra sự thật."},{"en":"The model makes an assumption that prices stay stable.","vi":"Mô hình đưa ra giả định rằng giá cả giữ ổn định."},{"en":"Researchers often make an assumption to simplify analysis.","vi":"Các nhà nghiên cứu thường đưa ra giả định để đơn giản hóa phân tích."}]', '[]', NULL, '/ˈmeɪk ən əˈsʌmpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 6, 'make an impact', 'tạo ra ảnh hưởng', 'v + n', '[{"en":"Small changes can make an impact on the environment.","vi":"Những thay đổi nhỏ có thể tạo ra ảnh hưởng đến môi trường."},{"en":"The campaign made an impact on public attitudes.","vi":"Chiến dịch đã tạo ra ảnh hưởng đến thái độ của công chúng."},{"en":"Volunteers hope to make an impact in their community.","vi":"Các tình nguyện viên hy vọng tạo ra ảnh hưởng trong cộng đồng."}]', '[]', NULL, '/ˈmeɪk ən ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 7, 'make an impression', 'gây ấn tượng', 'v + n', '[{"en":"A strong introduction helps you make an impression on readers.","vi":"Một phần mở đầu mạnh giúp bạn gây ấn tượng với độc giả."},{"en":"The candidate made a good impression during the interview.","vi":"Ứng viên đã gây ấn tượng tốt trong buổi phỏng vấn."},{"en":"Her speech made a lasting impression on the audience.","vi":"Bài phát biểu của cô đã gây ấn tượng lâu dài với khán giả."}]', '[]', NULL, '/ˈmeɪk ən ɪmˈpreʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 8, 'make an observation', 'đưa ra nhận xét, quan sát', 'v + n', '[{"en":"The scientist made an observation about the cells'' behavior.","vi":"Nhà khoa học đã đưa ra một quan sát về hành vi của các tế bào."},{"en":"Let me make an observation about the survey results.","vi":"Cho tôi đưa ra một nhận xét về kết quả khảo sát."},{"en":"She made a sharp observation during the seminar.","vi":"Cô ấy đã đưa ra một nhận xét sắc sảo trong buổi hội thảo."}]', '[]', NULL, '/ˈmeɪk ən ˌɑːbzərˈveɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 9, 'male dominance', 'sự thống trị của nam giới', 'adj + n', '[{"en":"The study examines male dominance in senior management.","vi":"Nghiên cứu xem xét sự thống trị của nam giới ở cấp quản lý cao."},{"en":"Male dominance in the field has declined over time.","vi":"Sự thống trị của nam giới trong lĩnh vực này đã giảm theo thời gian."},{"en":"Many professions still show clear male dominance.","vi":"Nhiều ngành nghề vẫn cho thấy sự thống trị rõ rệt của nam giới."}]', '[]', NULL, '/ˈmeɪl ˈdɑːmɪnəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 10, 'manual worker', 'công nhân lao động chân tay', 'adj + n', '[{"en":"A manual worker often faces a higher risk of injury.","vi":"Công nhân lao động chân tay thường đối mặt nguy cơ chấn thương cao hơn."},{"en":"Wages for manual workers have risen in recent years.","vi":"Lương cho công nhân lao động chân tay đã tăng trong những năm gần đây."},{"en":"The factory employs many skilled manual workers.","vi":"Nhà máy thuê nhiều công nhân lao động chân tay lành nghề."}]', '[]', NULL, '/ˈmænjuəl ˈwɜːrkər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 11, 'manufacturing sector', 'khu vực sản xuất', 'adj + n', '[{"en":"The manufacturing sector employs millions of workers nationwide.","vi":"Khu vực sản xuất thuê hàng triệu lao động trên toàn quốc."},{"en":"Growth in the manufacturing sector boosted the economy.","vi":"Sự tăng trưởng của khu vực sản xuất đã thúc đẩy nền kinh tế."},{"en":"The manufacturing sector has adopted more automation recently.","vi":"Khu vực sản xuất gần đây đã áp dụng nhiều tự động hóa hơn."}]', '[]', NULL, '/ˌmænjəˈfæktʃərɪŋ ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 12, 'marked contrast', 'sự tương phản rõ rệt', 'adj + n', '[{"en":"There is a marked contrast between the two regions'' incomes.","vi":"Có một sự tương phản rõ rệt giữa thu nhập của hai vùng."},{"en":"The results show a marked contrast with earlier studies.","vi":"Kết quả cho thấy một sự tương phản rõ rệt với các nghiên cứu trước."},{"en":"Her calm tone was in marked contrast to the chaos.","vi":"Giọng điệu bình tĩnh của cô tương phản rõ rệt với sự hỗn loạn."}]', '[]', NULL, '/ˈmɑːrkt ˈkɑːntræst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 13, 'markedly different', 'khác biệt rõ rệt', 'adv + adj', '[{"en":"The two groups produced markedly different results.","vi":"Hai nhóm đã tạo ra những kết quả khác biệt rõ rệt."},{"en":"Urban life is markedly different from rural life.","vi":"Đời sống đô thị khác biệt rõ rệt so với đời sống nông thôn."},{"en":"Their views on the issue were markedly different.","vi":"Quan điểm của họ về vấn đề này khác biệt rõ rệt."}]', '[]', NULL, '/ˈmɑːrkɪdli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 14, 'maximum duration', 'thời lượng tối đa', 'adj + n', '[{"en":"The maximum duration of the exam is three hours.","vi":"Thời lượng tối đa của bài thi là ba giờ."},{"en":"The contract sets a maximum duration of two years.","vi":"Hợp đồng đặt ra thời lượng tối đa là hai năm."},{"en":"Each presentation has a maximum duration of ten minutes.","vi":"Mỗi bài thuyết trình có thời lượng tối đa là mười phút."}]', '[]', NULL, '/ˈmæksɪməm dʊˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 15, 'mean score', 'điểm trung bình', 'adj + n', '[{"en":"The mean score for the class was seventy-five percent.","vi":"Điểm trung bình của lớp là bảy mươi lăm phần trăm."},{"en":"Researchers compared the mean score of both groups.","vi":"Các nhà nghiên cứu so sánh điểm trung bình của cả hai nhóm."},{"en":"The mean score rose after the new teaching method.","vi":"Điểm trung bình tăng sau phương pháp giảng dạy mới."}]', '[]', NULL, '/ˈmiːn ˈskɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 16, 'meaningful way', 'cách có ý nghĩa', 'adj + n', '[{"en":"The project lets students apply theory in a meaningful way.","vi":"Dự án cho phép sinh viên áp dụng lý thuyết một cách có ý nghĩa."},{"en":"We should present the data in a meaningful way.","vi":"Chúng ta nên trình bày dữ liệu một cách có ý nghĩa."},{"en":"Volunteering connects people in a meaningful way.","vi":"Tình nguyện kết nối mọi người theo một cách có ý nghĩa."}]', '[]', NULL, '/ˈmiːnɪŋfəl ˈweɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 17, 'media coverage', 'sự đưa tin của truyền thông', 'n + n', '[{"en":"The event received wide media coverage across the country.","vi":"Sự kiện nhận được sự đưa tin rộng rãi của truyền thông khắp cả nước."},{"en":"Media coverage of the scandal lasted several weeks.","vi":"Sự đưa tin của truyền thông về vụ bê bối kéo dài vài tuần."},{"en":"Negative media coverage can damage a company''s reputation.","vi":"Sự đưa tin tiêu cực của truyền thông có thể làm hại danh tiếng công ty."}]', '[]', NULL, '/ˈmiːdiə ˈkʌvərɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 18, 'medical assistance', 'hỗ trợ y tế', 'adj + n', '[{"en":"The injured hikers needed immediate medical assistance.","vi":"Những người leo núi bị thương cần hỗ trợ y tế ngay lập tức."},{"en":"The charity provides medical assistance to remote villages.","vi":"Tổ chức từ thiện cung cấp hỗ trợ y tế cho các bản làng xa xôi."},{"en":"Travelers should know where to find medical assistance abroad.","vi":"Du khách nên biết tìm hỗ trợ y tế ở đâu khi ở nước ngoài."}]', '[]', NULL, '/ˈmedɪkəl əˈsɪstəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 19, 'medical treatment', 'điều trị y tế', 'adj + n', '[{"en":"The patient received medical treatment for several months.","vi":"Bệnh nhân đã được điều trị y tế trong vài tháng."},{"en":"Many people cannot afford proper medical treatment.","vi":"Nhiều người không đủ khả năng chi trả cho điều trị y tế đúng cách."},{"en":"Early medical treatment can prevent serious complications.","vi":"Điều trị y tế sớm có thể ngăn ngừa các biến chứng nghiêm trọng."}]', '[]', NULL, '/ˈmedɪkəl ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 20, 'meet criteria', 'đáp ứng tiêu chí', 'v + n', '[{"en":"Applicants must meet criteria before being accepted.","vi":"Ứng viên phải đáp ứng tiêu chí trước khi được chấp nhận."},{"en":"The proposal failed to meet criteria set by the committee.","vi":"Đề xuất đã không đáp ứng được tiêu chí mà hội đồng đặt ra."},{"en":"Only products that meet criteria receive the safety label.","vi":"Chỉ những sản phẩm đáp ứng tiêu chí mới nhận được nhãn an toàn."}]', '[]', NULL, '/ˈmiːt kraɪˈtɪriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 21, 'meet expectations', 'đáp ứng kỳ vọng', 'v + n', '[{"en":"The new product failed to meet expectations in sales.","vi":"Sản phẩm mới đã không đáp ứng kỳ vọng về doanh số."},{"en":"The course did not meet the students'' expectations.","vi":"Khóa học đã không đáp ứng kỳ vọng của sinh viên."},{"en":"Their performance exceeded and met all expectations.","vi":"Màn thể hiện của họ đã vượt qua và đáp ứng mọi kỳ vọng."}]', '[]', NULL, '/ˈmiːt ˌekspekˈteɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 22, 'meet a requirement', 'đáp ứng một yêu cầu', 'v + n', '[{"en":"Students must meet a requirement of forty credits to graduate.","vi":"Sinh viên phải đáp ứng yêu cầu bốn mươi tín chỉ để tốt nghiệp."},{"en":"The design did not meet a key safety requirement.","vi":"Thiết kế đã không đáp ứng một yêu cầu an toàn quan trọng."},{"en":"All candidates must meet a language requirement first.","vi":"Mọi ứng viên trước hết phải đáp ứng một yêu cầu về ngôn ngữ."}]', '[]', NULL, '/ˈmiːt ə rɪˈkwaɪərmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 23, 'meet a target', 'đạt được chỉ tiêu', 'v + n', '[{"en":"The team worked hard to meet a sales target.","vi":"Cả nhóm đã làm việc chăm chỉ để đạt được chỉ tiêu doanh số."},{"en":"The country aims to meet a target for clean energy.","vi":"Quốc gia này hướng tới đạt được chỉ tiêu về năng lượng sạch."},{"en":"They failed to meet a target set last year.","vi":"Họ đã không đạt được chỉ tiêu đặt ra năm ngoái."}]', '[]', NULL, '/ˈmiːt ə ˈtɑːrgɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 24, 'meet an objective', 'đạt được mục tiêu', 'v + n', '[{"en":"The program helped the school meet an objective on literacy.","vi":"Chương trình đã giúp nhà trường đạt được mục tiêu về xóa mù chữ."},{"en":"Each task is designed to meet an objective of the course.","vi":"Mỗi nhiệm vụ được thiết kế để đạt được một mục tiêu của khóa học."},{"en":"The company met an important objective ahead of schedule.","vi":"Công ty đã đạt được một mục tiêu quan trọng trước thời hạn."}]', '[]', NULL, '/ˈmiːt ən əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 25, 'mental health', 'sức khỏe tâm thần', 'adj + n', '[{"en":"Regular exercise can improve your mental health.","vi":"Tập thể dục đều đặn có thể cải thiện sức khỏe tâm thần của bạn."},{"en":"The university offers mental health support to students.","vi":"Trường đại học cung cấp hỗ trợ sức khỏe tâm thần cho sinh viên."},{"en":"Stress at work can harm long-term mental health.","vi":"Căng thẳng trong công việc có thể làm hại sức khỏe tâm thần lâu dài."}]', '[]', NULL, '/ˈmentəl ˈhelθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 26, 'mental illness', 'bệnh tâm thần', 'adj + n', '[{"en":"Many people with mental illness do not seek help.","vi":"Nhiều người mắc bệnh tâm thần không tìm kiếm sự giúp đỡ."},{"en":"The campaign aims to reduce the stigma of mental illness.","vi":"Chiến dịch nhằm giảm sự kỳ thị đối với bệnh tâm thần."},{"en":"Early treatment of mental illness improves recovery rates.","vi":"Điều trị sớm bệnh tâm thần cải thiện tỷ lệ hồi phục."}]', '[]', NULL, '/ˈmentəl ˈɪlnəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 27, 'mental state', 'trạng thái tâm lý', 'adj + n', '[{"en":"Lack of sleep can affect a person''s mental state.","vi":"Thiếu ngủ có thể ảnh hưởng đến trạng thái tâm lý của một người."},{"en":"The doctor assessed the patient''s mental state carefully.","vi":"Bác sĩ đã đánh giá cẩn thận trạng thái tâm lý của bệnh nhân."},{"en":"His calm mental state helped him handle the crisis.","vi":"Trạng thái tâm lý bình tĩnh đã giúp anh xử lý khủng hoảng."}]', '[]', NULL, '/ˈmentəl ˈsteɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 28, 'methodological approach', 'cách tiếp cận phương pháp luận', 'adj + n', '[{"en":"The study uses a quantitative methodological approach.","vi":"Nghiên cứu sử dụng cách tiếp cận phương pháp luận định lượng."},{"en":"Their methodological approach differs from earlier research.","vi":"Cách tiếp cận phương pháp luận của họ khác với nghiên cứu trước."},{"en":"A clear methodological approach makes results easier to trust.","vi":"Cách tiếp cận phương pháp luận rõ ràng làm kết quả dễ tin cậy hơn."}]', '[]', NULL, '/ˌmeθədəˈlɑːdʒɪkəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 29, 'methodological issue', 'vấn đề phương pháp luận', 'adj + n', '[{"en":"The reviewers raised a methodological issue with the sample.","vi":"Các phản biện đã nêu một vấn đề phương pháp luận về mẫu khảo sát."},{"en":"A methodological issue weakened the study''s conclusions.","vi":"Một vấn đề phương pháp luận đã làm suy yếu các kết luận của nghiên cứu."},{"en":"The author discusses each methodological issue in detail.","vi":"Tác giả thảo luận chi tiết từng vấn đề phương pháp luận."}]', '[]', NULL, '/ˌmeθədəˈlɑːdʒɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 30, 'methodological problem', 'khó khăn về phương pháp luận', 'adj + n', '[{"en":"A serious methodological problem affected the data quality.","vi":"Một khó khăn nghiêm trọng về phương pháp luận đã ảnh hưởng đến chất lượng dữ liệu."},{"en":"The team solved a methodological problem in the survey design.","vi":"Nhóm đã giải quyết một khó khăn về phương pháp luận trong thiết kế khảo sát."},{"en":"Critics pointed to a methodological problem in the analysis.","vi":"Các nhà phê bình chỉ ra một khó khăn về phương pháp luận trong phân tích."}]', '[]', NULL, '/ˌmeθədəˈlɑːdʒɪkəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 31, 'metropolitan area', 'khu vực đô thị lớn', 'adj + n', '[{"en":"Housing costs are highest in the metropolitan area.","vi":"Chi phí nhà ở cao nhất ở khu vực đô thị lớn."},{"en":"The metropolitan area has grown rapidly over the decade.","vi":"Khu vực đô thị lớn đã phát triển nhanh chóng trong thập kỷ qua."},{"en":"Public transport connects the whole metropolitan area.","vi":"Giao thông công cộng kết nối toàn bộ khu vực đô thị lớn."}]', '[]', NULL, '/ˌmetrəˈpɑːlɪtən ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 32, 'middle income', 'thu nhập trung bình', 'adj + n', '[{"en":"Many middle income families struggle with rising prices.","vi":"Nhiều gia đình thu nhập trung bình chật vật với giá cả tăng cao."},{"en":"The country has reached middle income status recently.","vi":"Quốc gia này gần đây đã đạt mức thu nhập trung bình."},{"en":"The policy targets middle income households specifically.","vi":"Chính sách nhắm cụ thể vào các hộ gia đình thu nhập trung bình."}]', '[]', NULL, '/ˈmɪdəl ˈɪnkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 33, 'middle management', 'quản lý cấp trung', 'adj + n', '[{"en":"Middle management connects senior leaders with regular staff.","vi":"Quản lý cấp trung kết nối lãnh đạo cấp cao với nhân viên thường."},{"en":"The company cut several middle management positions.","vi":"Công ty đã cắt giảm một số vị trí quản lý cấp trung."},{"en":"Good middle management improves communication across teams.","vi":"Quản lý cấp trung tốt cải thiện giao tiếp giữa các nhóm."}]', '[]', NULL, '/ˈmɪdəl ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 34, 'migrant worker', 'lao động nhập cư', 'adj + n', '[{"en":"Many migrant workers send money home to their families.","vi":"Nhiều lao động nhập cư gửi tiền về cho gia đình họ."},{"en":"The report studies the rights of migrant workers.","vi":"Báo cáo nghiên cứu quyền lợi của lao động nhập cư."},{"en":"Migrant workers often fill jobs that locals avoid.","vi":"Lao động nhập cư thường đảm nhận những công việc mà người địa phương né tránh."}]', '[]', NULL, '/ˈmaɪgrənt ˈwɜːrkər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 35, 'military action', 'hành động quân sự', 'adj + n', '[{"en":"The government threatened military action against the rebels.","vi":"Chính phủ đã đe dọa hành động quân sự chống lại quân nổi dậy."},{"en":"Many people protested against the military action abroad.","vi":"Nhiều người đã phản đối hành động quân sự ở nước ngoài."},{"en":"Diplomats hoped to avoid further military action.","vi":"Các nhà ngoại giao hy vọng tránh được hành động quân sự thêm nữa."}]', '[]', NULL, '/ˈmɪləteri ˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 36, 'military force', 'lực lượng quân sự', 'adj + n', '[{"en":"The country used military force to defend its borders.","vi":"Quốc gia này đã dùng lực lượng quân sự để bảo vệ biên giới."},{"en":"The use of military force was widely criticized.","vi":"Việc sử dụng lực lượng quân sự đã bị chỉ trích rộng rãi."},{"en":"Both sides agreed to withdraw their military forces.","vi":"Cả hai bên đã đồng ý rút lực lượng quân sự của mình."}]', '[]', NULL, '/ˈmɪləteri ˈfɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 37, 'military power', 'sức mạnh quân sự', 'adj + n', '[{"en":"The nation built up its military power over the decade.","vi":"Quốc gia này đã xây dựng sức mạnh quân sự trong suốt thập kỷ."},{"en":"Economic strength often supports military power.","vi":"Sức mạnh kinh tế thường hỗ trợ cho sức mạnh quân sự."},{"en":"Military power alone cannot guarantee lasting peace.","vi":"Riêng sức mạnh quân sự không thể đảm bảo hòa bình lâu dài."}]', '[]', NULL, '/ˈmɪləteri ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 38, 'military service', 'nghĩa vụ quân sự', 'adj + n', '[{"en":"In some countries, military service is compulsory for young men.","vi":"Ở một số nước, nghĩa vụ quân sự là bắt buộc với nam thanh niên."},{"en":"He completed his military service before attending university.","vi":"Anh ấy đã hoàn thành nghĩa vụ quân sự trước khi vào đại học."},{"en":"Many veterans struggle to adjust after military service.","vi":"Nhiều cựu binh chật vật thích nghi sau nghĩa vụ quân sự."}]', '[]', NULL, '/ˈmɪləteri ˈsɜːrvɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 39, 'minimum level', 'mức tối thiểu', 'adj + n', '[{"en":"Applicants must reach a minimum level of English.","vi":"Ứng viên phải đạt được mức tối thiểu về tiếng Anh."},{"en":"The law sets a minimum level of safety for workplaces.","vi":"Luật đặt ra một mức tối thiểu về an toàn cho nơi làm việc."},{"en":"Funding was cut to the minimum level this year.","vi":"Kinh phí đã bị cắt xuống mức tối thiểu trong năm nay."}]', '[]', NULL, '/ˈmɪnɪməm ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 40, 'minimum requirement', 'yêu cầu tối thiểu', 'adj + n', '[{"en":"A high school diploma is the minimum requirement for this job.","vi":"Bằng tốt nghiệp phổ thông là yêu cầu tối thiểu cho công việc này."},{"en":"The course has a minimum requirement of basic math.","vi":"Khóa học có yêu cầu tối thiểu về toán cơ bản."},{"en":"Students who meet the minimum requirement may apply early.","vi":"Sinh viên đáp ứng yêu cầu tối thiểu có thể nộp đơn sớm."}]', '[]', NULL, '/ˈmɪnɪməm rɪˈkwaɪərmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 41, 'minimum standard', 'tiêu chuẩn tối thiểu', 'adj + n', '[{"en":"The factory must meet a minimum standard of hygiene.","vi":"Nhà máy phải đạt một tiêu chuẩn tối thiểu về vệ sinh."},{"en":"Regulations set a minimum standard for building safety.","vi":"Các quy định đặt ra một tiêu chuẩn tối thiểu về an toàn xây dựng."},{"en":"All products fall below the minimum standard required.","vi":"Mọi sản phẩm đều dưới tiêu chuẩn tối thiểu được yêu cầu."}]', '[]', NULL, '/ˈmɪnɪməm ˈstændərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 42, 'minimum value', 'giá trị tối thiểu', 'adj + n', '[{"en":"The graph shows the minimum value reached in winter.","vi":"Biểu đồ cho thấy giá trị tối thiểu đạt được vào mùa đông."},{"en":"The function returns a minimum value of zero.","vi":"Hàm số trả về giá trị tối thiểu là không."},{"en":"Temperatures dropped to their minimum value at night.","vi":"Nhiệt độ giảm xuống giá trị tối thiểu vào ban đêm."}]', '[]', NULL, '/ˈmɪnɪməm ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 43, 'minimum wage', 'lương tối thiểu', 'adj + n', '[{"en":"The government raised the minimum wage this year.","vi":"Chính phủ đã tăng lương tối thiểu trong năm nay."},{"en":"Many workers earn only the minimum wage.","vi":"Nhiều người lao động chỉ kiếm được mức lương tối thiểu."},{"en":"A higher minimum wage can reduce poverty levels.","vi":"Lương tối thiểu cao hơn có thể giảm mức độ nghèo đói."}]', '[]', NULL, '/ˈmɪnɪməm ˈweɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 44, 'minor change', 'thay đổi nhỏ', 'adj + n', '[{"en":"The editor suggested only a minor change to the draft.","vi":"Biên tập viên chỉ đề xuất một thay đổi nhỏ cho bản thảo."},{"en":"A minor change in diet improved his energy levels.","vi":"Một thay đổi nhỏ trong chế độ ăn đã cải thiện mức năng lượng của anh."},{"en":"We made a minor change to the schedule.","vi":"Chúng tôi đã thực hiện một thay đổi nhỏ trong lịch trình."}]', '[]', NULL, '/ˈmaɪnər ˈtʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 45, 'minor role', 'vai trò nhỏ', 'adj + n', '[{"en":"Luck played only a minor role in their success.","vi":"May mắn chỉ đóng một vai trò nhỏ trong thành công của họ."},{"en":"She had a minor role in the school play.","vi":"Cô ấy có một vai trò nhỏ trong vở kịch của trường."},{"en":"Diet plays a minor role compared with genetics here.","vi":"Chế độ ăn đóng vai trò nhỏ so với yếu tố di truyền ở đây."}]', '[]', NULL, '/ˈmaɪnər ˈroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 46, 'minority group', 'nhóm thiểu số', 'n + n', '[{"en":"The policy aims to protect every minority group.","vi":"Chính sách nhằm bảo vệ mọi nhóm thiểu số."},{"en":"Members of the minority group faced discrimination at work.","vi":"Các thành viên của nhóm thiểu số đã đối mặt với phân biệt đối xử tại nơi làm việc."},{"en":"The survey included several ethnic minority groups.","vi":"Cuộc khảo sát bao gồm một số nhóm dân tộc thiểu số."}]', '[]', NULL, '/maɪˈnɔːrəti ˈgruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 47, 'missing data', 'dữ liệu bị thiếu', 'adj + n', '[{"en":"Missing data made the analysis less reliable.","vi":"Dữ liệu bị thiếu khiến phân tích kém tin cậy hơn."},{"en":"Researchers used a model to handle the missing data.","vi":"Các nhà nghiên cứu đã dùng một mô hình để xử lý dữ liệu bị thiếu."},{"en":"We must explain how missing data was treated.","vi":"Chúng ta phải giải thích cách dữ liệu bị thiếu được xử lý."}]', '[]', NULL, '/ˈmɪsɪŋ ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 48, 'modern culture', 'văn hóa hiện đại', 'adj + n', '[{"en":"Social media plays a big part in modern culture.","vi":"Mạng xã hội đóng một vai trò lớn trong văn hóa hiện đại."},{"en":"The exhibition explores themes in modern culture.","vi":"Triển lãm khám phá các chủ đề trong văn hóa hiện đại."},{"en":"Modern culture often values speed over patience.","vi":"Văn hóa hiện đại thường coi trọng tốc độ hơn sự kiên nhẫn."}]', '[]', NULL, '/ˈmɑːdərn ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 49, 'modern method', 'phương pháp hiện đại', 'adj + n', '[{"en":"Farmers adopted modern methods to increase their yields.","vi":"Nông dân đã áp dụng các phương pháp hiện đại để tăng năng suất."},{"en":"The hospital uses modern methods to treat the disease.","vi":"Bệnh viện sử dụng các phương pháp hiện đại để điều trị căn bệnh."},{"en":"Modern methods of teaching focus on active learning.","vi":"Các phương pháp giảng dạy hiện đại tập trung vào học chủ động."}]', '[]', NULL, '/ˈmɑːdərn ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 50, 'modern society', 'xã hội hiện đại', 'adj + n', '[{"en":"Technology shapes almost every part of modern society.","vi":"Công nghệ định hình hầu như mọi mặt của xã hội hiện đại."},{"en":"Modern society faces challenges like climate change.","vi":"Xã hội hiện đại đối mặt với những thách thức như biến đổi khí hậu."},{"en":"Education is highly valued in modern society.","vi":"Giáo dục được đánh giá cao trong xã hội hiện đại."}]', '[]', NULL, '/ˈmɑːdərn səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 51, 'modern technology', 'công nghệ hiện đại', 'adj + n', '[{"en":"Modern technology has transformed the way we work.","vi":"Công nghệ hiện đại đã thay đổi cách chúng ta làm việc."},{"en":"Doctors rely on modern technology to diagnose patients.","vi":"Bác sĩ dựa vào công nghệ hiện đại để chẩn đoán bệnh nhân."},{"en":"Modern technology makes long-distance communication easy.","vi":"Công nghệ hiện đại làm cho việc liên lạc đường dài trở nên dễ dàng."}]', '[]', NULL, '/ˈmɑːdərn tekˈnɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 52, 'modified form', 'dạng đã chỉnh sửa', 'adj + n', '[{"en":"The plant was grown in a genetically modified form.","vi":"Cây trồng được nuôi dưới một dạng biến đổi gen."},{"en":"The team tested a modified form of the original design.","vi":"Nhóm đã thử nghiệm một dạng đã chỉnh sửa của thiết kế gốc."},{"en":"The theory appears here in a slightly modified form.","vi":"Lý thuyết xuất hiện ở đây dưới một dạng được chỉnh sửa đôi chút."}]', '[]', NULL, '/ˈmɑːdɪfaɪd ˈfɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 53, 'modified version', 'phiên bản đã chỉnh sửa', 'adj + n', '[{"en":"The team released a modified version of the original software.","vi":"Nhóm đã phát hành một phiên bản chỉnh sửa của phần mềm gốc."},{"en":"Researchers tested a modified version of the standard experiment.","vi":"Các nhà nghiên cứu đã thử nghiệm một phiên bản chỉnh sửa của thí nghiệm chuẩn."},{"en":"She presented a modified version of her earlier proposal.","vi":"Cô đã trình bày một phiên bản chỉnh sửa của đề xuất trước đó."}]', '[]', NULL, '/ˈmɑːdəfaɪd ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 54, 'moral dilemma', 'tình huống khó xử về đạo đức', 'adj + n', '[{"en":"The doctor faced a serious moral dilemma during the emergency.","vi":"Bác sĩ đối mặt với một tình huống khó xử về đạo đức nghiêm trọng."},{"en":"The novel explores a moral dilemma about loyalty and truth.","vi":"Cuốn tiểu thuyết khám phá một tình huống đạo đức khó xử về lòng trung thành và sự thật."},{"en":"Students debated the moral dilemma raised in the case study.","vi":"Sinh viên tranh luận về tình huống đạo đức khó xử nêu trong nghiên cứu tình huống."}]', '[]', NULL, '/ˈmɔːrəl dɪˈlemə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 55, 'moral philosophy', 'triết học đạo đức', 'adj + n', '[{"en":"She wrote her thesis on a key question in moral philosophy.","vi":"Cô viết luận án về một câu hỏi cốt lõi trong triết học đạo đức."},{"en":"Moral philosophy examines how people should act toward others.","vi":"Triết học đạo đức xem xét con người nên hành xử với người khác ra sao."},{"en":"The course introduces students to classical moral philosophy.","vi":"Khóa học giới thiệu cho sinh viên triết học đạo đức cổ điển."}]', '[]', NULL, '/ˈmɔːrəl fəˈlɑːsəfi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 56, 'moral principle', 'nguyên tắc đạo đức', 'adj + n', '[{"en":"He refused to compromise his core moral principle for money.","vi":"Anh từ chối thỏa hiệp nguyên tắc đạo đức cốt lõi của mình vì tiền."},{"en":"The constitution rests on a firm moral principle of fairness.","vi":"Hiến pháp dựa trên một nguyên tắc đạo đức vững chắc về sự công bằng."},{"en":"Teachers try to instill a strong moral principle in children.","vi":"Giáo viên cố gắng gieo cho trẻ một nguyên tắc đạo đức vững chắc."}]', '[]', NULL, '/ˈmɔːrəl ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 57, 'multiple identities', 'nhiều bản sắc khác nhau', 'adj + n', '[{"en":"Many immigrants navigate multiple identities in their daily lives.","vi":"Nhiều người nhập cư cân bằng nhiều bản sắc trong cuộc sống hằng ngày."},{"en":"The study examines how people manage multiple identities online.","vi":"Nghiên cứu xem xét cách con người quản lý nhiều bản sắc trên mạng."},{"en":"Globalization allows individuals to hold multiple identities at once.","vi":"Toàn cầu hóa cho phép cá nhân mang nhiều bản sắc cùng lúc."}]', '[]', NULL, '/ˈmʌltəpəl aɪˈdentətiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 58, 'multiple sources', 'nhiều nguồn khác nhau', 'adj + n', '[{"en":"Good researchers verify facts using multiple sources of evidence.","vi":"Nhà nghiên cứu giỏi kiểm chứng sự thật bằng nhiều nguồn bằng chứng."},{"en":"The report draws on multiple sources for a balanced view.","vi":"Báo cáo dựa trên nhiều nguồn để có một góc nhìn cân bằng."},{"en":"Funding came from multiple sources, including private donors.","vi":"Kinh phí đến từ nhiều nguồn, bao gồm cả nhà tài trợ tư nhân."}]', '[]', NULL, '/ˈmʌltəpəl ˈsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 59, 'municipal government', 'chính quyền thành phố', 'adj + n', '[{"en":"The municipal government approved funding for the new park.","vi":"Chính quyền thành phố đã phê duyệt kinh phí cho công viên mới."},{"en":"Local services are usually managed by the municipal government.","vi":"Các dịch vụ địa phương thường do chính quyền thành phố quản lý."},{"en":"Residents petitioned the municipal government for better roads.","vi":"Người dân kiến nghị chính quyền thành phố cải thiện đường sá."}]', '[]', NULL, '/mjuːˈnɪsəpəl ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 60, 'mutual recognition', 'sự công nhận lẫn nhau', 'adj + n', '[{"en":"The treaty established mutual recognition of professional qualifications.","vi":"Hiệp ước thiết lập sự công nhận lẫn nhau về bằng cấp nghề nghiệp."},{"en":"Lasting peace requires mutual recognition between the two states.","vi":"Hòa bình bền vững đòi hỏi sự công nhận lẫn nhau giữa hai quốc gia."},{"en":"Mutual recognition of degrees makes student exchange easier.","vi":"Sự công nhận bằng cấp lẫn nhau giúp trao đổi sinh viên dễ hơn."}]', '[]', NULL, '/ˈmjuːtʃuəl ˌrekəɡˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 61, 'mutual support', 'sự hỗ trợ lẫn nhau', 'adj + n', '[{"en":"The two communities relied on mutual support during the crisis.","vi":"Hai cộng đồng đã dựa vào sự hỗ trợ lẫn nhau trong cơn khủng hoảng."},{"en":"A strong team is built on mutual support and trust.","vi":"Một đội ngũ vững mạnh được xây trên sự hỗ trợ và tin tưởng lẫn nhau."},{"en":"The agreement promotes mutual support between member countries.","vi":"Thỏa thuận thúc đẩy sự hỗ trợ lẫn nhau giữa các nước thành viên."}]', '[]', NULL, '/ˈmjuːtʃuəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 62, 'mutual trust', 'sự tin tưởng lẫn nhau', 'adj + n', '[{"en":"Successful partnerships depend on a high level of mutual trust.","vi":"Quan hệ đối tác thành công phụ thuộc vào mức độ tin tưởng lẫn nhau cao."},{"en":"Years of cooperation gradually built mutual trust between them.","vi":"Nhiều năm hợp tác dần xây dựng sự tin tưởng lẫn nhau giữa họ."},{"en":"Without mutual trust, the negotiations quickly broke down.","vi":"Thiếu sự tin tưởng lẫn nhau, cuộc đàm phán nhanh chóng đổ vỡ."}]', '[]', NULL, '/ˈmjuːtʃuəl trʌst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 63, 'mutual understanding', 'sự thấu hiểu lẫn nhau', 'adj + n', '[{"en":"Cultural exchange programs foster mutual understanding between nations.","vi":"Các chương trình giao lưu văn hóa nuôi dưỡng sự thấu hiểu lẫn nhau giữa các nước."},{"en":"Open dialogue is the first step toward mutual understanding.","vi":"Đối thoại cởi mở là bước đầu tiên hướng tới sự thấu hiểu lẫn nhau."},{"en":"They reached a mutual understanding after a long discussion.","vi":"Họ đạt được sự thấu hiểu lẫn nhau sau một cuộc thảo luận dài."}]', '[]', NULL, '/ˈmjuːtʃuəl ˌʌndərˈstændɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 64, 'mutually exclusive', 'loại trừ lẫn nhau', 'adv + adj', '[{"en":"These two goals are not mutually exclusive; we can pursue both.","vi":"Hai mục tiêu này không loại trừ lẫn nhau; ta có thể theo đuổi cả hai."},{"en":"In statistics, mutually exclusive events cannot occur together.","vi":"Trong thống kê, các sự kiện loại trừ lẫn nhau không thể xảy ra cùng lúc."},{"en":"Profit and sustainability need not be mutually exclusive aims.","vi":"Lợi nhuận và tính bền vững không nhất thiết là các mục tiêu loại trừ nhau."}]', '[]', NULL, '/ˈmjuːtʃuəli ɪkˈskluːsɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 65, 'narrow definition', 'định nghĩa hẹp', 'adj + n', '[{"en":"A narrow definition of success ignores personal happiness.","vi":"Một định nghĩa hẹp về thành công bỏ qua hạnh phúc cá nhân."},{"en":"The author rejects the narrow definition used in earlier studies.","vi":"Tác giả bác bỏ định nghĩa hẹp được dùng trong các nghiên cứu trước."},{"en":"Using a narrow definition limited the scope of the survey.","vi":"Việc dùng một định nghĩa hẹp đã giới hạn phạm vi của cuộc khảo sát."}]', '[]', NULL, '/ˈnæroʊ ˌdefəˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 66, 'narrow range of', 'phạm vi hẹp các', 'adj + n', '[{"en":"The study focused on a narrow range of economic indicators.","vi":"Nghiên cứu tập trung vào một phạm vi hẹp các chỉ số kinh tế."},{"en":"The species survives only within a narrow range of temperatures.","vi":"Loài này chỉ sống được trong một phạm vi hẹp các mức nhiệt độ."},{"en":"Critics said the policy addressed a narrow range of problems.","vi":"Giới phê bình nói chính sách chỉ giải quyết một phạm vi hẹp các vấn đề."}]', '[]', NULL, '/ˈnæroʊ ˈreɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 67, 'national average', 'mức trung bình toàn quốc', 'adj + n', '[{"en":"The region''s unemployment rate is below the national average.","vi":"Tỷ lệ thất nghiệp của vùng này thấp hơn mức trung bình toàn quốc."},{"en":"Test scores at this school exceed the national average.","vi":"Điểm thi tại trường này vượt mức trung bình toàn quốc."},{"en":"House prices here remain close to the national average.","vi":"Giá nhà ở đây vẫn gần mức trung bình toàn quốc."}]', '[]', NULL, '/ˈnæʃənəl ˈævərɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 68, 'national boundary', 'đường biên giới quốc gia', 'adj + n', '[{"en":"The river forms a natural national boundary between the two states.","vi":"Con sông tạo thành một đường biên giới quốc gia tự nhiên giữa hai bang."},{"en":"Trade often flows across the national boundary without restriction.","vi":"Thương mại thường lưu thông qua biên giới quốc gia mà không bị hạn chế."},{"en":"The treaty redrew the national boundary after the long war.","vi":"Hiệp ước đã vẽ lại đường biên giới quốc gia sau cuộc chiến dài."}]', '[]', NULL, '/ˈnæʃənəl ˈbaʊndəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 69, 'national conference', 'hội nghị toàn quốc', 'adj + n', '[{"en":"She presented her research at the national conference last spring.","vi":"Cô đã trình bày nghiên cứu của mình tại hội nghị toàn quốc mùa xuân năm ngoái."},{"en":"The national conference brought together experts from every region.","vi":"Hội nghị toàn quốc quy tụ các chuyên gia từ mọi vùng miền."},{"en":"Delegates debated new policies during the national conference.","vi":"Các đại biểu tranh luận về chính sách mới trong hội nghị toàn quốc."}]', '[]', NULL, '/ˈnæʃənəl ˈkɑːnfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 70, 'national culture', 'văn hóa dân tộc', 'adj + n', '[{"en":"Food and festivals are an essential part of national culture.","vi":"Ẩm thực và lễ hội là một phần thiết yếu của văn hóa dân tộc."},{"en":"Globalization has reshaped many aspects of national culture.","vi":"Toàn cầu hóa đã định hình lại nhiều khía cạnh của văn hóa dân tộc."},{"en":"The museum aims to preserve the country''s national culture.","vi":"Bảo tàng nhằm gìn giữ văn hóa dân tộc của đất nước."}]', '[]', NULL, '/ˈnæʃənəl ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 71, 'national economy', 'nền kinh tế quốc gia', 'adj + n', '[{"en":"Tourism contributes significantly to the national economy each year.","vi":"Du lịch đóng góp đáng kể cho nền kinh tế quốc gia mỗi năm."},{"en":"The pandemic severely weakened the national economy for months.","vi":"Đại dịch đã làm suy yếu nghiêm trọng nền kinh tế quốc gia trong nhiều tháng."},{"en":"Reforms were designed to strengthen the national economy gradually.","vi":"Các cải cách được thiết kế để dần củng cố nền kinh tế quốc gia."}]', '[]', NULL, '/ˈnæʃənəl ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 72, 'national government', 'chính phủ quốc gia', 'adj + n', '[{"en":"The national government announced a new education funding plan.","vi":"Chính phủ quốc gia đã công bố một kế hoạch tài trợ giáo dục mới."},{"en":"Local councils often depend on the national government for money.","vi":"Hội đồng địa phương thường phụ thuộc chính phủ quốc gia về kinh phí."},{"en":"The national government set strict targets for cutting emissions.","vi":"Chính phủ quốc gia đặt ra các mục tiêu nghiêm ngặt về cắt giảm khí thải."}]', '[]', NULL, '/ˈnæʃənəl ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 73, 'national identity', 'bản sắc dân tộc', 'adj + n', '[{"en":"Language plays a central role in shaping national identity.","vi":"Ngôn ngữ đóng vai trò trung tâm trong việc hình thành bản sắc dân tộc."},{"en":"The flag is a powerful symbol of national identity.","vi":"Lá cờ là một biểu tượng mạnh mẽ của bản sắc dân tộc."},{"en":"Sport can strengthen a shared sense of national identity.","vi":"Thể thao có thể củng cố ý thức chung về bản sắc dân tộc."}]', '[]', NULL, '/ˈnæʃənəl aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 74, 'national income', 'thu nhập quốc dân', 'adj + n', '[{"en":"Agriculture once accounted for most of the national income.","vi":"Nông nghiệp từng chiếm phần lớn thu nhập quốc dân."},{"en":"Economists measure growth by changes in national income.","vi":"Các nhà kinh tế đo lường tăng trưởng qua thay đổi của thu nhập quốc dân."},{"en":"A rise in national income usually improves living standards.","vi":"Thu nhập quốc dân tăng thường cải thiện mức sống."}]', '[]', NULL, '/ˈnæʃənəl ˈɪnkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 75, 'national institution', 'thể chế quốc gia', 'adj + n', '[{"en":"The library has become a respected national institution over time.","vi":"Thư viện đã trở thành một thể chế quốc gia được kính trọng theo thời gian."},{"en":"Trust in every national institution has declined in recent years.","vi":"Niềm tin vào mọi thể chế quốc gia đã giảm trong những năm gần đây."},{"en":"The reform strengthened a key national institution responsible for justice.","vi":"Cải cách đã củng cố một thể chế quốc gia quan trọng phụ trách công lý."}]', '[]', NULL, '/ˈnæʃənəl ˌɪnstəˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 76, 'national interest', 'lợi ích quốc gia', 'adj + n', '[{"en":"The government justified the policy as serving the national interest.","vi":"Chính phủ biện minh chính sách này nhằm phục vụ lợi ích quốc gia."},{"en":"Leaders must weigh personal gain against the national interest.","vi":"Các nhà lãnh đạo phải cân nhắc lợi ích cá nhân với lợi ích quốc gia."},{"en":"Protecting energy supplies is clearly in the national interest.","vi":"Bảo vệ nguồn cung năng lượng rõ ràng phục vụ lợi ích quốc gia."}]', '[]', NULL, '/ˈnæʃənəl ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 77, 'national language', 'ngôn ngữ quốc gia', 'adj + n', '[{"en":"The constitution names two official forms of the national language.","vi":"Hiến pháp ghi nhận hai dạng chính thức của ngôn ngữ quốc gia."},{"en":"Schools are required to teach the national language to all pupils.","vi":"Các trường buộc phải dạy ngôn ngữ quốc gia cho mọi học sinh."},{"en":"Promoting the national language helped unite the diverse population.","vi":"Việc đề cao ngôn ngữ quốc gia đã giúp gắn kết dân cư đa dạng."}]', '[]', NULL, '/ˈnæʃənəl ˈlæŋɡwɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 78, 'national legislation', 'luật pháp quốc gia', 'adj + n', '[{"en":"New national legislation now limits the use of plastic bags.","vi":"Luật pháp quốc gia mới hiện hạn chế việc sử dụng túi nhựa."},{"en":"Local rules must comply with existing national legislation.","vi":"Quy định địa phương phải tuân thủ luật pháp quốc gia hiện hành."},{"en":"National legislation on data privacy was strengthened last year.","vi":"Luật pháp quốc gia về quyền riêng tư dữ liệu đã được siết chặt năm ngoái."}]', '[]', NULL, '/ˈnæʃənəl ˌledʒəsˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 79, 'national market', 'thị trường quốc gia', 'adj + n', '[{"en":"The company expanded from local trade into the national market.","vi":"Công ty đã mở rộng từ buôn bán địa phương sang thị trường quốc gia."},{"en":"Imports increased competition across the national market.","vi":"Hàng nhập khẩu làm tăng cạnh tranh trên khắp thị trường quốc gia."},{"en":"A single national market makes pricing more consistent everywhere.","vi":"Một thị trường quốc gia thống nhất giúp giá cả nhất quán hơn ở mọi nơi."}]', '[]', NULL, '/ˈnæʃənəl ˈmɑːrkɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 80, 'national media', 'truyền thông quốc gia', 'adj + n', '[{"en":"The scandal was widely covered by the national media.","vi":"Vụ bê bối đã được truyền thông quốc gia đưa tin rộng rãi."},{"en":"The national media shapes how citizens view current events.","vi":"Truyền thông quốc gia định hình cách công dân nhìn nhận sự kiện hiện tại."},{"en":"Her discovery soon attracted attention from the national media.","vi":"Phát hiện của cô sớm thu hút sự chú ý của truyền thông quốc gia."}]', '[]', NULL, '/ˈnæʃənəl ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 81, 'national movement', 'phong trào dân tộc', 'adj + n', '[{"en":"The protest grew into a powerful national movement for change.","vi":"Cuộc biểu tình đã phát triển thành một phong trào dân tộc mạnh mẽ đòi thay đổi."},{"en":"Historians studied how the national movement gained popular support.","vi":"Các nhà sử học nghiên cứu cách phong trào dân tộc giành được sự ủng hộ rộng rãi."},{"en":"Young activists led the national movement toward independence.","vi":"Các nhà hoạt động trẻ dẫn dắt phong trào dân tộc hướng tới độc lập."}]', '[]', NULL, '/ˈnæʃənəl ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 82, 'national policy', 'chính sách quốc gia', 'adj + n', '[{"en":"The government introduced a new national policy on renewable energy.","vi":"Chính phủ đã ban hành một chính sách quốc gia mới về năng lượng tái tạo."},{"en":"Critics argued the national policy ignored rural communities.","vi":"Giới phê bình cho rằng chính sách quốc gia đã bỏ quên các cộng đồng nông thôn."},{"en":"A clear national policy helped coordinate the regional efforts.","vi":"Một chính sách quốc gia rõ ràng đã giúp phối hợp các nỗ lực ở các vùng."}]', '[]', NULL, '/ˈnæʃənəl ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 83, 'national press', 'báo chí quốc gia', 'adj + n', '[{"en":"The story made the front page of the national press.","vi":"Câu chuyện đã lên trang nhất của báo chí quốc gia."},{"en":"The national press criticized the minister''s recent decision.","vi":"Báo chí quốc gia đã chỉ trích quyết định gần đây của bộ trưởng."},{"en":"Local issues rarely reach the pages of the national press.","vi":"Các vấn đề địa phương hiếm khi lên được trang báo chí quốc gia."}]', '[]', NULL, '/ˈnæʃənəl pres/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 84, 'national security', 'an ninh quốc gia', 'adj + n', '[{"en":"The leak posed a serious threat to national security.","vi":"Vụ rò rỉ đã gây ra một mối đe dọa nghiêm trọng cho an ninh quốc gia."},{"en":"Officials cited national security to justify the new restrictions.","vi":"Các quan chức viện dẫn an ninh quốc gia để biện minh cho các hạn chế mới."},{"en":"Cyberattacks have become a major national security concern.","vi":"Các cuộc tấn công mạng đã trở thành mối lo lớn về an ninh quốc gia."}]', '[]', NULL, '/ˈnæʃənəl sɪˈkjʊrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 85, 'national survey', 'cuộc khảo sát toàn quốc', 'adj + n', '[{"en":"A recent national survey revealed rising levels of student stress.","vi":"Một cuộc khảo sát toàn quốc gần đây cho thấy mức độ căng thẳng của sinh viên gia tăng."},{"en":"The national survey collected responses from thousands of households.","vi":"Cuộc khảo sát toàn quốc đã thu thập câu trả lời từ hàng nghìn hộ gia đình."},{"en":"Results of the national survey will guide future health policy.","vi":"Kết quả của cuộc khảo sát toàn quốc sẽ định hướng chính sách y tế tương lai."}]', '[]', NULL, '/ˈnæʃənəl ˈsɜːrveɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 86, 'native speaker', 'người bản ngữ', 'adj + n', '[{"en":"Practicing with a native speaker improved her pronunciation quickly.","vi":"Luyện tập với một người bản ngữ đã cải thiện phát âm của cô nhanh chóng."},{"en":"A native speaker often notices subtle errors that textbooks miss.","vi":"Người bản ngữ thường nhận ra những lỗi tinh tế mà sách giáo khoa bỏ sót."},{"en":"The school hired a native speaker to lead conversation classes.","vi":"Trường đã thuê một người bản ngữ để dẫn dắt các lớp hội thoại."}]', '[]', NULL, '/ˈneɪtɪv ˈspiːkər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 87, 'natural conditions', 'điều kiện tự nhiên', 'adj + n', '[{"en":"These plants thrive only under specific natural conditions.","vi":"Những cây này chỉ phát triển tốt trong điều kiện tự nhiên cụ thể."},{"en":"Researchers observed the animals in their natural conditions.","vi":"Các nhà nghiên cứu quan sát các con vật trong điều kiện tự nhiên của chúng."},{"en":"The experiment tried to replicate the natural conditions of the lake.","vi":"Thí nghiệm cố tái tạo điều kiện tự nhiên của hồ nước."}]', '[]', NULL, '/ˈnætʃərəl kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 88, 'natural disaster', 'thảm họa thiên nhiên', 'adj + n', '[{"en":"The flood was the worst natural disaster in the region''s history.","vi":"Trận lụt là thảm họa thiên nhiên tồi tệ nhất trong lịch sử của vùng."},{"en":"Governments must prepare communities for any natural disaster.","vi":"Các chính phủ phải chuẩn bị cho cộng đồng trước mọi thảm họa thiên nhiên."},{"en":"Aid arrived slowly after the devastating natural disaster.","vi":"Viện trợ đến chậm sau thảm họa thiên nhiên tàn khốc."}]', '[]', NULL, '/ˈnætʃərəl dɪˈzæstər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 89, 'natural environment', 'môi trường tự nhiên', 'adj + n', '[{"en":"Industrial waste continues to damage the natural environment.","vi":"Chất thải công nghiệp tiếp tục hủy hoại môi trường tự nhiên."},{"en":"The park protects the natural environment for future generations.","vi":"Công viên bảo vệ môi trường tự nhiên cho các thế hệ tương lai."},{"en":"Studying animals in their natural environment yields better data.","vi":"Nghiên cứu động vật trong môi trường tự nhiên cho dữ liệu tốt hơn."}]', '[]', NULL, '/ˈnætʃərəl ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 90, 'natural history', 'lịch sử tự nhiên', 'adj + n', '[{"en":"The museum''s natural history collection attracts many young visitors.","vi":"Bộ sưu tập lịch sử tự nhiên của bảo tàng thu hút nhiều khách trẻ tuổi."},{"en":"Darwin''s voyage greatly advanced the study of natural history.","vi":"Chuyến đi của Darwin đã thúc đẩy mạnh việc nghiên cứu lịch sử tự nhiên."},{"en":"She wrote a popular book on the natural history of birds.","vi":"Cô đã viết một cuốn sách phổ biến về lịch sử tự nhiên của các loài chim."}]', '[]', NULL, '/ˈnætʃərəl ˈhɪstəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 91, 'natural language', 'ngôn ngữ tự nhiên', 'adj + n', '[{"en":"Computers still struggle to fully understand natural language.","vi":"Máy tính vẫn gặp khó khăn trong việc hiểu trọn vẹn ngôn ngữ tự nhiên."},{"en":"The app uses natural language to answer everyday questions.","vi":"Ứng dụng dùng ngôn ngữ tự nhiên để trả lời các câu hỏi hằng ngày."},{"en":"Natural language processing has improved rapidly in recent years.","vi":"Xử lý ngôn ngữ tự nhiên đã tiến bộ nhanh chóng trong những năm gần đây."}]', '[]', NULL, '/ˈnætʃərəl ˈlæŋɡwɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 92, 'natural law', 'luật tự nhiên', 'adj + n', '[{"en":"Philosophers debated whether natural law applies to all people.","vi":"Các triết gia tranh luận liệu luật tự nhiên có áp dụng cho mọi người không."},{"en":"The idea of natural law shaped early human rights theory.","vi":"Ý niệm về luật tự nhiên đã định hình lý thuyết nhân quyền sơ khai."},{"en":"He argued that justice should be grounded in natural law.","vi":"Ông lập luận rằng công lý nên được đặt trên nền tảng luật tự nhiên."}]', '[]', NULL, '/ˈnætʃərəl lɔː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 93, 'natural order', 'trật tự tự nhiên', 'adj + n', '[{"en":"Ancient thinkers believed everything followed a fixed natural order.","vi":"Các nhà tư tưởng cổ đại tin rằng mọi thứ tuân theo một trật tự tự nhiên cố định."},{"en":"The film questions whether technology disrupts the natural order.","vi":"Bộ phim đặt câu hỏi liệu công nghệ có phá vỡ trật tự tự nhiên không."},{"en":"Predators and prey maintain a delicate natural order.","vi":"Kẻ săn mồi và con mồi duy trì một trật tự tự nhiên mong manh."}]', '[]', NULL, '/ˈnætʃərəl ˈɔːrdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 94, 'natural philosophy', 'triết học tự nhiên', 'adj + n', '[{"en":"Before modern science, physics was called natural philosophy.","vi":"Trước khoa học hiện đại, vật lý được gọi là triết học tự nhiên."},{"en":"Newton''s work transformed the field of natural philosophy.","vi":"Công trình của Newton đã biến đổi lĩnh vực triết học tự nhiên."},{"en":"The lecture traced the roots of natural philosophy in Greece.","vi":"Bài giảng đã truy nguồn gốc của triết học tự nhiên ở Hy Lạp."}]', '[]', NULL, '/ˈnætʃərəl fəˈlɑːsəfi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 95, 'natural process', 'quá trình tự nhiên', 'adj + n', '[{"en":"Decay is a natural process that recycles nutrients in soil.","vi":"Phân hủy là một quá trình tự nhiên tái chế dưỡng chất trong đất."},{"en":"Aging is a natural process that affects every living thing.","vi":"Lão hóa là một quá trình tự nhiên ảnh hưởng đến mọi sinh vật."},{"en":"The river changes course through a slow natural process.","vi":"Dòng sông đổi dòng qua một quá trình tự nhiên chậm rãi."}]', '[]', NULL, '/ˈnætʃərəl ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 96, 'natural resources', 'tài nguyên thiên nhiên', 'adj + n', '[{"en":"The country is rich in natural resources such as oil and gas.","vi":"Đất nước này giàu tài nguyên thiên nhiên như dầu mỏ và khí đốt."},{"en":"Overuse of natural resources threatens long-term sustainability.","vi":"Việc khai thác quá mức tài nguyên thiên nhiên đe dọa tính bền vững lâu dài."},{"en":"The treaty aims to manage shared natural resources fairly.","vi":"Hiệp ước nhằm quản lý công bằng các tài nguyên thiên nhiên chung."}]', '[]', NULL, '/ˈnætʃərəl ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 97, 'natural right', 'quyền tự nhiên', 'adj + n', '[{"en":"Many thinkers regard freedom as a basic natural right.","vi":"Nhiều nhà tư tưởng coi tự do là một quyền tự nhiên căn bản."},{"en":"The declaration was based on the idea of natural right.","vi":"Bản tuyên ngôn dựa trên ý niệm về quyền tự nhiên."},{"en":"He argued that property is not an absolute natural right.","vi":"Ông lập luận rằng tài sản không phải là một quyền tự nhiên tuyệt đối."}]', '[]', NULL, '/ˈnætʃərəl raɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 98, 'natural science', 'khoa học tự nhiên', 'adj + n', '[{"en":"She decided to major in a natural science at university.","vi":"Cô đã quyết định chọn ngành chính là một môn khoa học tự nhiên ở đại học."},{"en":"Natural science relies heavily on observation and experiment.","vi":"Khoa học tự nhiên phụ thuộc nhiều vào quan sát và thí nghiệm."},{"en":"The grant supports research across several natural science fields.","vi":"Khoản tài trợ hỗ trợ nghiên cứu trên nhiều lĩnh vực khoa học tự nhiên."}]', '[]', NULL, '/ˈnætʃərəl ˈsaɪəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 99, 'natural tendency', 'khuynh hướng tự nhiên', 'adj + n', '[{"en":"People have a natural tendency to trust familiar faces.","vi":"Con người có một khuynh hướng tự nhiên là tin những gương mặt quen thuộc."},{"en":"The market shows a natural tendency to correct over time.","vi":"Thị trường cho thấy một khuynh hướng tự nhiên là tự điều chỉnh theo thời gian."},{"en":"Children display a natural tendency to imitate adults.","vi":"Trẻ em thể hiện một khuynh hướng tự nhiên là bắt chước người lớn."}]', '[]', NULL, '/ˈnætʃərəl ˈtendənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 100, 'natural world', 'thế giới tự nhiên', 'adj + n', '[{"en":"Her photographs capture the beauty of the natural world.","vi":"Những bức ảnh của cô ghi lại vẻ đẹp của thế giới tự nhiên."},{"en":"Science helps us understand patterns in the natural world.","vi":"Khoa học giúp chúng ta hiểu các quy luật trong thế giới tự nhiên."},{"en":"Children should spend more time exploring the natural world.","vi":"Trẻ em nên dành nhiều thời gian hơn để khám phá thế giới tự nhiên."}]', '[]', NULL, '/ˈnætʃərəl wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 101, 'naturally occurring', 'xuất hiện tự nhiên', 'adv + adj', '[{"en":"Vitamin D is a naturally occurring substance in sunlight.","vi":"Vitamin D là một chất xuất hiện tự nhiên trong ánh nắng mặt trời."},{"en":"The study focused on naturally occurring chemicals in plants.","vi":"Nghiên cứu tập trung vào các hóa chất xuất hiện tự nhiên trong thực vật."},{"en":"Some naturally occurring minerals are mined for industrial use.","vi":"Một số khoáng chất xuất hiện tự nhiên được khai thác cho mục đích công nghiệp."}]', '[]', NULL, '/ˈnætʃərəli əˈkɜːrɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 102, 'necessary information', 'thông tin cần thiết', 'adj + n', '[{"en":"Please gather all the necessary information before the meeting.","vi":"Vui lòng thu thập tất cả thông tin cần thiết trước cuộc họp."},{"en":"The form requests only the necessary information from applicants.","vi":"Biểu mẫu chỉ yêu cầu thông tin cần thiết từ người nộp đơn."},{"en":"Without the necessary information, we cannot make a decision.","vi":"Thiếu thông tin cần thiết, chúng ta không thể đưa ra quyết định."}]', '[]', NULL, '/ˈnesəseri ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 103, 'negative aspect', 'khía cạnh tiêu cực', 'adj + n', '[{"en":"The essay discusses one negative aspect of social media use.","vi":"Bài luận bàn về một khía cạnh tiêu cực của việc dùng mạng xã hội."},{"en":"Every technology has a negative aspect worth considering.","vi":"Mọi công nghệ đều có một khía cạnh tiêu cực đáng cân nhắc."},{"en":"She acknowledged the negative aspect of working long hours.","vi":"Cô thừa nhận khía cạnh tiêu cực của việc làm việc nhiều giờ."}]', '[]', NULL, '/ˈneɡətɪv ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 104, 'negative attitude', 'thái độ tiêu cực', 'adj + n', '[{"en":"His negative attitude discouraged the rest of the team.","vi":"Thái độ tiêu cực của anh đã làm nản lòng cả đội."},{"en":"The survey measured students'' negative attitude toward exams.","vi":"Cuộc khảo sát đo lường thái độ tiêu cực của sinh viên với kỳ thi."},{"en":"A negative attitude can make small problems seem huge.","vi":"Thái độ tiêu cực có thể khiến vấn đề nhỏ trở nên to lớn."}]', '[]', NULL, '/ˈneɡətɪv ˈætətuːd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 105, 'negative connotation', 'hàm ý tiêu cực', 'adj + n', '[{"en":"The word \"cheap\" often carries a negative connotation.","vi":"Từ \"rẻ tiền\" thường mang một hàm ý tiêu cực."},{"en":"Writers should avoid terms with a strong negative connotation.","vi":"Người viết nên tránh những từ có hàm ý tiêu cực mạnh."},{"en":"In some cultures the label has a negative connotation.","vi":"Ở một số nền văn hóa, nhãn này mang hàm ý tiêu cực."}]', '[]', NULL, '/ˈneɡətɪv ˌkɑːnəˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 106, 'negative consequences', 'hậu quả tiêu cực', 'adj + n', '[{"en":"The policy had several negative consequences for small businesses.","vi":"Chính sách đã gây ra nhiều hậu quả tiêu cực cho doanh nghiệp nhỏ."},{"en":"Skipping sleep regularly leads to serious negative consequences.","vi":"Thường xuyên thiếu ngủ dẫn đến những hậu quả tiêu cực nghiêm trọng."},{"en":"Researchers warned about the negative consequences of pollution.","vi":"Các nhà nghiên cứu cảnh báo về hậu quả tiêu cực của ô nhiễm."}]', '[]', NULL, '/ˈneɡətɪv ˈkɑːnsəkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 107, 'negative correlation', 'mối tương quan nghịch', 'adj + n', '[{"en":"The data showed a negative correlation between stress and sleep.","vi":"Dữ liệu cho thấy mối tương quan nghịch giữa căng thẳng và giấc ngủ."},{"en":"There is a clear negative correlation between price and demand.","vi":"Có một mối tương quan nghịch rõ ràng giữa giá cả và nhu cầu."},{"en":"A negative correlation means one variable rises as another falls.","vi":"Mối tương quan nghịch nghĩa là một biến tăng khi biến kia giảm."}]', '[]', NULL, '/ˈneɡətɪv ˌkɔːrəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 108, 'negative effect', 'tác động tiêu cực', 'adj + n', '[{"en":"Excessive screen time can have a negative effect on sleep.","vi":"Thời gian dùng màn hình quá mức có thể gây tác động tiêu cực đến giấc ngủ."},{"en":"The drought had a negative effect on this year''s harvest.","vi":"Hạn hán đã gây tác động tiêu cực đến vụ mùa năm nay."},{"en":"Noise pollution has a negative effect on concentration.","vi":"Ô nhiễm tiếng ồn có tác động tiêu cực đến sự tập trung."}]', '[]', NULL, '/ˈneɡətɪv ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 109, 'negative feedback', 'phản hồi tiêu cực', 'adj + n', '[{"en":"She handled the negative feedback calmly and improved her work.","vi":"Cô đón nhận phản hồi tiêu cực một cách bình tĩnh và cải thiện công việc."},{"en":"Constructive negative feedback can help students grow faster.","vi":"Phản hồi tiêu cực mang tính xây dựng có thể giúp sinh viên tiến bộ nhanh hơn."},{"en":"The product received negative feedback from early reviewers.","vi":"Sản phẩm nhận phản hồi tiêu cực từ những người đánh giá ban đầu."}]', '[]', NULL, '/ˈneɡətɪv ˈfiːdbæk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 110, 'negative impact', 'ảnh hưởng tiêu cực', 'adj + n', '[{"en":"Tourism can have a negative impact on fragile ecosystems.","vi":"Du lịch có thể gây ảnh hưởng tiêu cực đến các hệ sinh thái mong manh."},{"en":"The new tax had a negative impact on consumer spending.","vi":"Thuế mới đã gây ảnh hưởng tiêu cực đến chi tiêu của người tiêu dùng."},{"en":"Researchers measured the negative impact of stress on health.","vi":"Các nhà nghiên cứu đo lường ảnh hưởng tiêu cực của căng thẳng đến sức khỏe."}]', '[]', NULL, '/ˈneɡətɪv ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 111, 'negative outcome', 'kết quả tiêu cực', 'adj + n', '[{"en":"Poor planning often leads to a negative outcome for projects.","vi":"Lập kế hoạch kém thường dẫn đến một kết quả tiêu cực cho các dự án."},{"en":"The trial produced a surprisingly negative outcome for patients.","vi":"Thử nghiệm đã cho một kết quả tiêu cực đáng ngạc nhiên với bệnh nhân."},{"en":"We must prepare for any negative outcome of the negotiations.","vi":"Chúng ta phải chuẩn bị cho bất kỳ kết quả tiêu cực nào của cuộc đàm phán."}]', '[]', NULL, '/ˈneɡətɪv ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 112, 'negative side', 'mặt tiêu cực', 'adj + n', '[{"en":"Every opportunity has a negative side worth weighing carefully.","vi":"Mọi cơ hội đều có một mặt tiêu cực đáng cân nhắc kỹ."},{"en":"The article highlights the negative side of rapid urban growth.","vi":"Bài viết làm nổi bật mặt tiêu cực của tăng trưởng đô thị nhanh."},{"en":"On the negative side, the plan is extremely expensive.","vi":"Về mặt tiêu cực, kế hoạch này cực kỳ tốn kém."}]', '[]', NULL, '/ˈneɡətɪv saɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 113, 'negative stereotype', 'định kiến tiêu cực', 'adj + n', '[{"en":"The campaign aims to challenge a common negative stereotype.","vi":"Chiến dịch nhằm thách thức một định kiến tiêu cực phổ biến."},{"en":"Media often reinforces a negative stereotype about teenagers.","vi":"Truyền thông thường củng cố một định kiến tiêu cực về thanh thiếu niên."},{"en":"Education can help break down each negative stereotype slowly.","vi":"Giáo dục có thể giúp dần phá bỏ từng định kiến tiêu cực."}]', '[]', NULL, '/ˈneɡətɪv ˈsteriətaɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 114, 'negative value', 'giá trị âm', 'adj + n', '[{"en":"A negative value in the equation indicates a loss.","vi":"Một giá trị âm trong phương trình cho thấy một khoản lỗ."},{"en":"The sensor returned a negative value due to a calibration error.","vi":"Cảm biến trả về một giá trị âm do lỗi hiệu chuẩn."},{"en":"Temperatures fell to a negative value overnight.","vi":"Nhiệt độ đã giảm xuống một giá trị âm qua đêm."}]', '[]', NULL, '/ˈneɡətɪv ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 115, 'negative view', 'cái nhìn tiêu cực', 'adj + n', '[{"en":"The author takes a negative view of unregulated markets.","vi":"Tác giả có một cái nhìn tiêu cực về các thị trường không được quản lý."},{"en":"Many residents hold a negative view of the proposed development.","vi":"Nhiều cư dân có cái nhìn tiêu cực về dự án phát triển được đề xuất."},{"en":"Her negative view of the plan changed after the presentation.","vi":"Cái nhìn tiêu cực của cô về kế hoạch đã thay đổi sau buổi thuyết trình."}]', '[]', NULL, '/ˈneɡətɪv vjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 116, 'negatively correlated with', 'tương quan nghịch với', 'adv + vpp', '[{"en":"Anxiety levels were negatively correlated with exam performance.","vi":"Mức độ lo âu có tương quan nghịch với kết quả thi."},{"en":"Income is often negatively correlated with reported stress.","vi":"Thu nhập thường có tương quan nghịch với mức căng thẳng được ghi nhận."},{"en":"Screen time was negatively correlated with hours of sleep.","vi":"Thời gian dùng màn hình có tương quan nghịch với số giờ ngủ."}]', '[]', NULL, '/ˈneɡətɪvli ˈkɔːrəleɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 117, 'new initiative', 'sáng kiến mới', 'adj + n', '[{"en":"The school launched a new initiative to reduce food waste.","vi":"Nhà trường đã khởi động một sáng kiến mới để giảm lãng phí thực phẩm."},{"en":"The new initiative encourages employees to share fresh ideas.","vi":"Sáng kiến mới khuyến khích nhân viên chia sẻ những ý tưởng mới mẻ."},{"en":"Funding was secured for a new initiative on clean energy.","vi":"Kinh phí đã được bảo đảm cho một sáng kiến mới về năng lượng sạch."}]', '[]', NULL, '/nuː ɪˈnɪʃətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 118, 'new insight', 'hiểu biết sâu sắc mới', 'adj + n', '[{"en":"The experiment offered a new insight into how memory works.","vi":"Thí nghiệm đã mang lại một hiểu biết sâu sắc mới về cách trí nhớ hoạt động."},{"en":"Her interviews provided a new insight into rural poverty.","vi":"Các cuộc phỏng vấn của cô đã cho một góc nhìn sâu sắc mới về nghèo đói nông thôn."},{"en":"The data gave researchers a new insight into climate change.","vi":"Dữ liệu đã cho các nhà nghiên cứu một hiểu biết mới về biến đổi khí hậu."}]', '[]', NULL, '/nuː ˈɪnsaɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 119, 'new perspective', 'góc nhìn mới', 'adj + n', '[{"en":"Traveling abroad gave her a completely new perspective on life.","vi":"Đi du lịch nước ngoài đã cho cô một góc nhìn hoàn toàn mới về cuộc sống."},{"en":"The book offers a new perspective on a familiar problem.","vi":"Cuốn sách mang đến một góc nhìn mới về một vấn đề quen thuộc."},{"en":"Hearing other students brought a new perspective to the debate.","vi":"Lắng nghe các sinh viên khác đã mang một góc nhìn mới vào cuộc tranh luận."}]', '[]', NULL, '/nuː pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 120, 'newly acquired', 'vừa mới có được', 'adv + vpp', '[{"en":"She used her newly acquired skills to redesign the website.","vi":"Cô đã dùng những kỹ năng vừa mới có được để thiết kế lại trang web."},{"en":"The museum displayed its newly acquired ancient artifacts.","vi":"Bảo tàng đã trưng bày các cổ vật vừa mới có được."},{"en":"He applied his newly acquired knowledge during the internship.","vi":"Anh áp dụng kiến thức vừa mới có được trong kỳ thực tập."}]', '[]', NULL, '/ˈnuːli əˈkwaɪərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 121, 'newly created', 'vừa mới được tạo ra', 'adv + vpp', '[{"en":"The newly created department will oversee online learning.","vi":"Phòng ban vừa mới được tạo ra sẽ giám sát việc học trực tuyến."},{"en":"She was appointed to a newly created leadership position.","vi":"Cô được bổ nhiệm vào một vị trí lãnh đạo vừa mới được tạo ra."},{"en":"The newly created fund supports young local entrepreneurs.","vi":"Quỹ vừa mới được tạo ra hỗ trợ các doanh nhân địa phương trẻ tuổi."}]', '[]', NULL, '/ˈnuːli kriˈeɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 122, 'newly discovered', 'vừa mới được phát hiện', 'adv + vpp', '[{"en":"Scientists named the newly discovered species after its habitat.","vi":"Các nhà khoa học đặt tên loài vừa mới được phát hiện theo môi trường sống của nó."},{"en":"The newly discovered manuscript changed how we read the poem.","vi":"Bản thảo vừa mới được phát hiện đã thay đổi cách chúng ta đọc bài thơ."},{"en":"A newly discovered planet may have conditions suited to life.","vi":"Một hành tinh vừa mới được phát hiện có thể có điều kiện phù hợp cho sự sống."}]', '[]', NULL, '/ˈnuːli dɪˈskʌvərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 123, 'newly emerging', 'vừa mới nổi lên', 'adv + adj', '[{"en":"The report examines several newly emerging digital technologies.","vi":"Báo cáo xem xét một số công nghệ số vừa mới nổi lên."},{"en":"Investors are watching the newly emerging green energy sector.","vi":"Các nhà đầu tư đang theo dõi ngành năng lượng xanh vừa mới nổi lên."},{"en":"Newly emerging markets offer both risks and opportunities.","vi":"Các thị trường vừa mới nổi lên mang lại cả rủi ro lẫn cơ hội."}]', '[]', NULL, '/ˈnuːli ɪˈmɜːrdʒɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 124, 'newly established', 'vừa mới được thành lập', 'adv + adj', '[{"en":"The newly established institute focuses on climate research.","vi":"Viện vừa mới được thành lập tập trung vào nghiên cứu khí hậu."},{"en":"A newly established committee will review the proposals.","vi":"Một ủy ban vừa mới được thành lập sẽ xem xét các đề xuất."},{"en":"The newly established company hired dozens of graduates.","vi":"Công ty vừa mới được thành lập đã tuyển hàng chục sinh viên tốt nghiệp."}]', '[]', NULL, '/ˈnuːli ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 125, 'newly formed', 'vừa mới được hình thành', 'adv + vpp', '[{"en":"The newly formed alliance promised closer economic cooperation.","vi":"Liên minh vừa mới được hình thành đã hứa hẹn hợp tác kinh tế chặt chẽ hơn."},{"en":"A newly formed group of volunteers cleaned up the riverbank.","vi":"Một nhóm tình nguyện viên vừa mới được hình thành đã dọn sạch bờ sông."},{"en":"Stars are born within newly formed clouds of cosmic gas.","vi":"Các ngôi sao ra đời bên trong những đám khí vũ trụ vừa mới được hình thành."}]', '[]', NULL, '/ˈnuːli fɔːrmd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 126, 'next decade', 'thập kỷ tới', 'adj + n', '[{"en":"Experts predict major changes in transport over the next decade.","vi":"Các chuyên gia dự đoán những thay đổi lớn về giao thông trong thập kỷ tới."},{"en":"The company plans to double its workforce in the next decade.","vi":"Công ty dự định tăng gấp đôi lực lượng lao động trong thập kỷ tới."},{"en":"Renewable energy should dominate the market within the next decade.","vi":"Năng lượng tái tạo sẽ chiếm lĩnh thị trường trong thập kỷ tới."}]', '[]', NULL, '/nekst ˈdekeɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 127, 'next generation', 'thế hệ tiếp theo', 'adj + n', '[{"en":"We must protect the environment for the next generation.","vi":"Chúng ta phải bảo vệ môi trường cho thế hệ tiếp theo."},{"en":"The school inspires the next generation of young scientists.","vi":"Ngôi trường truyền cảm hứng cho thế hệ nhà khoa học trẻ tiếp theo."},{"en":"These devices represent the next generation of mobile technology.","vi":"Những thiết bị này đại diện cho thế hệ công nghệ di động tiếp theo."}]', '[]', NULL, '/nekst ˌdʒenəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 128, 'next phase', 'giai đoạn tiếp theo', 'adj + n', '[{"en":"The project will enter its next phase early next year.","vi":"Dự án sẽ bước vào giai đoạn tiếp theo vào đầu năm sau."},{"en":"The next phase of research focuses on long-term effects.","vi":"Giai đoạn nghiên cứu tiếp theo tập trung vào các tác động lâu dài."},{"en":"Funding will determine whether the next phase goes ahead.","vi":"Kinh phí sẽ quyết định liệu giai đoạn tiếp theo có được tiến hành không."}]', '[]', NULL, '/nekst feɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 129, 'normal conditions', 'điều kiện bình thường', 'adj + n', '[{"en":"Under normal conditions, the machine runs without any problems.","vi":"Trong điều kiện bình thường, máy chạy mà không có vấn đề gì."},{"en":"The reaction proceeds slowly under normal conditions.","vi":"Phản ứng diễn ra chậm trong điều kiện bình thường."},{"en":"Service usually resumes within hours under normal conditions.","vi":"Dịch vụ thường được khôi phục trong vài giờ ở điều kiện bình thường."}]', '[]', NULL, '/ˈnɔːrməl kənˈdɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 130, 'normal development', 'sự phát triển bình thường', 'adj + n', '[{"en":"Good nutrition is essential for a child''s normal development.","vi":"Dinh dưỡng tốt là điều thiết yếu cho sự phát triển bình thường của trẻ."},{"en":"The study tracks the normal development of language in infants.","vi":"Nghiên cứu theo dõi sự phát triển bình thường của ngôn ngữ ở trẻ sơ sinh."},{"en":"Stress can interfere with the normal development of the brain.","vi":"Căng thẳng có thể cản trở sự phát triển bình thường của não bộ."}]', '[]', NULL, '/ˈnɔːrməl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 131, 'normal distribution', 'phân phối chuẩn', 'adj + n', '[{"en":"The test scores followed a clear normal distribution.","vi":"Điểm thi tuân theo một phân phối chuẩn rõ ràng."},{"en":"A normal distribution is symmetric around its mean value.","vi":"Phân phối chuẩn đối xứng quanh giá trị trung bình của nó."},{"en":"Many statistical methods assume an underlying normal distribution.","vi":"Nhiều phương pháp thống kê giả định một phân phối chuẩn cơ bản."}]', '[]', NULL, '/ˈnɔːrməl ˌdɪstrəˈbjuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 132, 'normal practice', 'thông lệ thường thấy', 'adj + n', '[{"en":"It is normal practice to cite all of your sources.","vi":"Việc trích dẫn mọi nguồn của bạn là một thông lệ thường thấy."},{"en":"Reviewing the budget monthly is normal practice in this firm.","vi":"Rà soát ngân sách hằng tháng là thông lệ thường thấy ở công ty này."},{"en":"It became normal practice to back up files every night.","vi":"Việc sao lưu tệp mỗi đêm đã trở thành thông lệ thường thấy."}]', '[]', NULL, '/ˈnɔːrməl ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 133, 'notable exception', 'ngoại lệ đáng chú ý', 'adj + n', '[{"en":"Most students passed, with one notable exception in the group.","vi":"Hầu hết sinh viên đều đậu, với một ngoại lệ đáng chú ý trong nhóm."},{"en":"Prices rose everywhere, with food being a notable exception.","vi":"Giá cả tăng ở khắp nơi, với thực phẩm là một ngoại lệ đáng chú ý."},{"en":"Few authors of that era, with one notable exception, survive today.","vi":"Ít tác giả thời đó, trừ một ngoại lệ đáng chú ý, còn được biết đến ngày nay."}]', '[]', NULL, '/ˈnoʊtəbəl ɪkˈsepʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 134, 'nuclear energy', 'năng lượng hạt nhân', 'adj + n', '[{"en":"Some countries rely heavily on nuclear energy for electricity.","vi":"Một số quốc gia phụ thuộc nhiều vào năng lượng hạt nhân để sản xuất điện."},{"en":"Debates about nuclear energy focus on safety and waste.","vi":"Các cuộc tranh luận về năng lượng hạt nhân tập trung vào an toàn và chất thải."},{"en":"Nuclear energy produces very low carbon emissions overall.","vi":"Năng lượng hạt nhân tạo ra lượng khí thải carbon rất thấp về tổng thể."}]', '[]', NULL, '/ˈnuːkliər ˈenərdʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 135, 'nuclear family', 'gia đình hạt nhân (cha mẹ và con cái)', 'adj + n', '[{"en":"The nuclear family has become less common in modern societies.","vi":"Gia đình hạt nhân đã trở nên ít phổ biến hơn trong xã hội hiện đại."},{"en":"Her research compares the nuclear family across different cultures.","vi":"Nghiên cứu của cô so sánh gia đình hạt nhân giữa các nền văn hóa khác nhau."},{"en":"Many policies were designed around the traditional nuclear family.","vi":"Nhiều chính sách được thiết kế xoay quanh gia đình hạt nhân truyền thống."}]', '[]', NULL, '/ˈnuːkliər ˈfæməli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 136, 'nuclear power', 'năng lượng hạt nhân', 'adj + n', '[{"en":"Several countries rely on nuclear power for their electricity.","vi":"Một số quốc gia dựa vào năng lượng hạt nhân để cung cấp điện."},{"en":"The debate over nuclear power remains highly controversial today.","vi":"Cuộc tranh luận về năng lượng hạt nhân vẫn rất gây tranh cãi ngày nay."},{"en":"Nuclear power produces large amounts of energy without burning fuel.","vi":"Năng lượng hạt nhân tạo ra lượng năng lượng lớn mà không đốt nhiên liệu."}]', '[]', NULL, '/ˈnuːkliər ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 137, 'nuclear war', 'chiến tranh hạt nhân', 'adj + n', '[{"en":"The threat of nuclear war shaped global politics for decades.","vi":"Mối đe dọa chiến tranh hạt nhân đã định hình chính trị toàn cầu suốt nhiều thập kỷ."},{"en":"Many leaders have worked to reduce the risk of nuclear war.","vi":"Nhiều nhà lãnh đạo đã nỗ lực giảm nguy cơ chiến tranh hạt nhân."},{"en":"A nuclear war would have catastrophic consequences for the planet.","vi":"Một cuộc chiến tranh hạt nhân sẽ gây hậu quả thảm khốc cho hành tinh."}]', '[]', NULL, '/ˈnuːkliər wɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 138, 'nuclear weapon', 'vũ khí hạt nhân', 'adj + n', '[{"en":"International treaties aim to limit the spread of nuclear weapons.","vi":"Các hiệp ước quốc tế nhằm hạn chế sự phổ biến của vũ khí hạt nhân."},{"en":"Building a nuclear weapon requires highly enriched radioactive material.","vi":"Chế tạo một vũ khí hạt nhân đòi hỏi vật liệu phóng xạ được làm giàu cao."},{"en":"The country agreed to dismantle its nuclear weapons program.","vi":"Quốc gia này đồng ý dỡ bỏ chương trình vũ khí hạt nhân của mình."}]', '[]', NULL, '/ˈnuːkliər ˈwepən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 139, 'numerical data', 'dữ liệu dạng số', 'adj + n', '[{"en":"The study relies on numerical data collected from many sources.","vi":"Nghiên cứu dựa vào dữ liệu dạng số được thu thập từ nhiều nguồn."},{"en":"Researchers analyzed the numerical data using statistical software.","vi":"Các nhà nghiên cứu phân tích dữ liệu dạng số bằng phần mềm thống kê."},{"en":"Numerical data can be displayed clearly in charts and tables.","vi":"Dữ liệu dạng số có thể được trình bày rõ ràng trong biểu đồ và bảng."}]', '[]', NULL, '/nuːˈmerɪkəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 140, 'numerical value', 'giá trị bằng số', 'adj + n', '[{"en":"Each variable was assigned a specific numerical value in the model.","vi":"Mỗi biến số được gán một giá trị bằng số cụ thể trong mô hình."},{"en":"The numerical value of the result depends on the measurement units.","vi":"Giá trị bằng số của kết quả phụ thuộc vào đơn vị đo lường."},{"en":"Converting the data into numerical values made comparison much easier.","vi":"Việc chuyển dữ liệu thành các giá trị bằng số giúp so sánh dễ hơn nhiều."}]', '[]', NULL, '/nuːˈmerɪkəl ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 141, 'numerous studies', 'nhiều nghiên cứu', 'adj + n', '[{"en":"Numerous studies have confirmed the link between diet and health.","vi":"Nhiều nghiên cứu đã xác nhận mối liên hệ giữa chế độ ăn và sức khỏe."},{"en":"Her conclusion is supported by numerous studies across the field.","vi":"Kết luận của cô được hỗ trợ bởi nhiều nghiên cứu trong lĩnh vực này."},{"en":"Numerous studies suggest that sleep improves memory and learning.","vi":"Nhiều nghiên cứu cho thấy giấc ngủ cải thiện trí nhớ và việc học."}]', '[]', NULL, '/ˈnuːmərəs ˈstʌdiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 142, 'objective criteria', 'tiêu chí khách quan', 'adj + n', '[{"en":"Applicants are evaluated using clear and objective criteria.","vi":"Các ứng viên được đánh giá bằng tiêu chí rõ ràng và khách quan."},{"en":"Objective criteria help reduce bias in the selection process.","vi":"Tiêu chí khách quan giúp giảm thiên kiến trong quá trình tuyển chọn."},{"en":"The committee agreed on objective criteria before reviewing the cases.","vi":"Hội đồng thống nhất các tiêu chí khách quan trước khi xem xét các hồ sơ."}]', '[]', NULL, '/əbˈdʒektɪv kraɪˈtɪriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 143, 'objective reality', 'thực tại khách quan', 'adj + n', '[{"en":"Philosophers debate whether we can truly know objective reality.","vi":"Các triết gia tranh luận liệu ta có thể thực sự biết thực tại khách quan."},{"en":"Science aims to describe objective reality independent of opinion.","vi":"Khoa học nhằm mô tả thực tại khách quan độc lập với quan điểm cá nhân."},{"en":"Our perceptions sometimes differ from objective reality itself.","vi":"Nhận thức của chúng ta đôi khi khác với chính thực tại khách quan."}]', '[]', NULL, '/əbˈdʒektɪv riˈæləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 144, 'obtain data', 'thu thập dữ liệu', 'v + n', '[{"en":"Researchers obtained data through surveys and direct observation.","vi":"Các nhà nghiên cứu thu thập dữ liệu qua khảo sát và quan sát trực tiếp."},{"en":"It was difficult to obtain reliable data from remote regions.","vi":"Rất khó để thu thập dữ liệu đáng tin cậy từ các vùng xa xôi."},{"en":"The team obtained data on weather patterns over several years.","vi":"Nhóm đã thu thập dữ liệu về các kiểu thời tiết trong nhiều năm."}]', '[]', NULL, '/əbˈteɪn ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 145, 'obtain information', 'thu thập thông tin', 'v + n', '[{"en":"Students learned how to obtain information from reliable sources.","vi":"Sinh viên học cách thu thập thông tin từ các nguồn đáng tin cậy."},{"en":"The journalist struggled to obtain information about the closed case.","vi":"Nhà báo gặp khó khăn khi thu thập thông tin về vụ án đã khép lại."},{"en":"You can obtain information about the course on the website.","vi":"Bạn có thể thu thập thông tin về khóa học trên trang web."}]', '[]', NULL, '/əbˈteɪn ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 146, 'obtain a result', 'đạt được một kết quả', 'v + n', '[{"en":"The scientists repeated the experiment to obtain a reliable result.","vi":"Các nhà khoa học lặp lại thí nghiệm để đạt được một kết quả đáng tin cậy."},{"en":"We obtained a result that closely matched our initial prediction.","vi":"Chúng tôi đạt được một kết quả khớp chặt với dự đoán ban đầu."},{"en":"To obtain a clear result, they controlled every variable carefully.","vi":"Để đạt được một kết quả rõ ràng, họ kiểm soát cẩn thận mọi biến số."}]', '[]', NULL, '/əbˈteɪn ə rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 147, 'obvious difference', 'sự khác biệt rõ ràng', 'adj + n', '[{"en":"There is an obvious difference between the two writing styles.","vi":"Có một sự khác biệt rõ ràng giữa hai phong cách viết."},{"en":"The results showed an obvious difference between the test groups.","vi":"Kết quả cho thấy một sự khác biệt rõ ràng giữa các nhóm thử nghiệm."},{"en":"Despite the obvious difference, both methods reached similar conclusions.","vi":"Bất chấp sự khác biệt rõ ràng, cả hai phương pháp đều đi đến kết luận tương tự."}]', '[]', NULL, '/ˈɑːbviəs ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 148, 'obvious example', 'ví dụ rõ ràng', 'adj + n', '[{"en":"Social media is an obvious example of rapid technological change.","vi":"Mạng xã hội là một ví dụ rõ ràng về sự thay đổi công nghệ nhanh chóng."},{"en":"The author gives an obvious example to illustrate her point.","vi":"Tác giả đưa ra một ví dụ rõ ràng để minh họa cho luận điểm của mình."},{"en":"An obvious example of this trend can be seen in cities.","vi":"Một ví dụ rõ ràng cho xu hướng này có thể thấy ở các thành phố."}]', '[]', NULL, '/ˈɑːbviəs ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 149, 'obvious point', 'điểm hiển nhiên', 'adj + n', '[{"en":"She made the obvious point that more funding was needed.","vi":"Cô nêu ra điểm hiển nhiên rằng cần thêm kinh phí."},{"en":"It may seem an obvious point, but it deserves emphasis.","vi":"Điều này có vẻ là một điểm hiển nhiên, nhưng nó đáng được nhấn mạnh."},{"en":"The lecturer began with an obvious point before deeper analysis.","vi":"Giảng viên bắt đầu bằng một điểm hiển nhiên trước khi phân tích sâu hơn."}]', '[]', NULL, '/ˈɑːbviəs pɔɪnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-10-01', 150, 'obvious reason', 'lý do hiển nhiên', 'adj + n', '[{"en":"For obvious reasons, the names of participants were kept private.","vi":"Vì những lý do hiển nhiên, tên của những người tham gia được giữ kín."},{"en":"There is no obvious reason why the experiment failed.","vi":"Không có lý do hiển nhiên nào giải thích vì sao thí nghiệm thất bại."},{"en":"She left the meeting early for an obvious reason.","vi":"Cô rời cuộc họp sớm vì một lý do hiển nhiên."}]', '[]', NULL, '/ˈɑːbviəs ˈriːzən/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-11-01', 'colloc-11', 'Cụm học thuật · Nhóm 11', 'Academic Collocation List (Pearson/PTE) — nhóm 11 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 1, 'occur frequently', 'xảy ra thường xuyên', 'v + adv', '[{"en":"Such errors occur frequently when data is entered by hand.","vi":"Những lỗi như vậy xảy ra thường xuyên khi dữ liệu được nhập bằng tay."},{"en":"Earthquakes occur frequently along this active fault line.","vi":"Động đất xảy ra thường xuyên dọc theo đường đứt gãy hoạt động này."},{"en":"These misunderstandings occur frequently in cross-cultural communication.","vi":"Những hiểu lầm này xảy ra thường xuyên trong giao tiếp đa văn hóa."}]', '[]', NULL, '/əˈkɜːr ˈfriːkwəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 2, 'occur naturally', 'xảy ra một cách tự nhiên', 'v + adv', '[{"en":"These minerals occur naturally in the surrounding rock formations.","vi":"Những khoáng chất này xuất hiện tự nhiên trong các thành tạo đá xung quanh."},{"en":"Some chemical reactions occur naturally without any human intervention.","vi":"Một số phản ứng hóa học xảy ra tự nhiên mà không cần con người can thiệp."},{"en":"Variation occurs naturally within every large population of organisms.","vi":"Sự biến dị xảy ra tự nhiên trong mọi quần thể sinh vật lớn."}]', '[]', NULL, '/əˈkɜːr ˈnætʃərəli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 3, 'offer insight into', 'đem lại hiểu biết sâu sắc về', 'v + n', '[{"en":"The interviews offer insight into how patients experience treatment.","vi":"Các cuộc phỏng vấn đem lại hiểu biết sâu sắc về cách bệnh nhân trải nghiệm điều trị."},{"en":"Her diary offers insight into daily life during the war.","vi":"Nhật ký của cô đem lại hiểu biết sâu sắc về đời sống thường ngày trong chiến tranh."},{"en":"These findings offer insight into the causes of climate change.","vi":"Những phát hiện này đem lại hiểu biết sâu sắc về nguyên nhân biến đổi khí hậu."}]', '[]', NULL, '/ˈɔːfər ˈɪnsaɪt ˈɪntuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 4, 'offer an opportunity', 'mang lại một cơ hội', 'v + n', '[{"en":"The program offers an opportunity to study abroad for a year.","vi":"Chương trình mang lại một cơ hội du học một năm."},{"en":"This crisis also offers an opportunity to rethink old policies.","vi":"Cuộc khủng hoảng này cũng mang lại một cơ hội để xem lại các chính sách cũ."},{"en":"Volunteering offers an opportunity to gain valuable practical experience.","vi":"Tình nguyện mang lại một cơ hội để có được kinh nghiệm thực tế quý báu."}]', '[]', NULL, '/ˈɔːfər ən ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 5, 'official statistics', 'số liệu thống kê chính thức', 'adj + n', '[{"en":"According to official statistics, unemployment fell over the past year.","vi":"Theo số liệu thống kê chính thức, thất nghiệp đã giảm trong năm qua."},{"en":"Official statistics often underestimate the size of the informal economy.","vi":"Số liệu thống kê chính thức thường đánh giá thấp quy mô kinh tế phi chính thức."},{"en":"The report compares official statistics from several different countries.","vi":"Báo cáo so sánh số liệu thống kê chính thức từ nhiều quốc gia khác nhau."}]', '[]', NULL, '/əˈfɪʃəl stəˈtɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 6, 'once established', 'một khi đã được thiết lập', 'adv + vpp', '[{"en":"Once established, these habits are very difficult to change.","vi":"Một khi đã được hình thành, những thói quen này rất khó thay đổi."},{"en":"Once established, the new system reduced waiting times significantly.","vi":"Một khi đã được thiết lập, hệ thống mới giảm đáng kể thời gian chờ."},{"en":"Once established, a reputation can shape how others perceive you.","vi":"Một khi đã được tạo dựng, danh tiếng có thể định hình cách người khác nhìn bạn."}]', '[]', NULL, '/wʌns ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 7, 'ongoing debate', 'cuộc tranh luận đang diễn ra', 'adj + n', '[{"en":"There is an ongoing debate about the best teaching methods.","vi":"Đang có một cuộc tranh luận về phương pháp giảng dạy tốt nhất."},{"en":"The paper contributes to the ongoing debate over privacy rights.","vi":"Bài viết đóng góp vào cuộc tranh luận đang diễn ra về quyền riêng tư."},{"en":"This question lies at the heart of an ongoing debate.","vi":"Câu hỏi này nằm ở trung tâm của một cuộc tranh luận đang diễn ra."}]', '[]', NULL, '/ˈɑːnˌɡoʊɪŋ dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 8, 'ongoing process', 'quá trình đang diễn ra liên tục', 'adj + n', '[{"en":"Learning a language is an ongoing process that never fully ends.","vi":"Học một ngôn ngữ là một quá trình liên tục không bao giờ thực sự kết thúc."},{"en":"Reform is an ongoing process rather than a single event.","vi":"Cải cách là một quá trình liên tục chứ không phải một sự kiện đơn lẻ."},{"en":"Maintaining trust within a team is an ongoing process.","vi":"Duy trì sự tin tưởng trong một đội nhóm là một quá trình liên tục."}]', '[]', NULL, '/ˈɑːnˌɡoʊɪŋ ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 9, 'online access', 'quyền truy cập trực tuyến', 'adj + n', '[{"en":"Students are given online access to the full library catalog.","vi":"Sinh viên được cấp quyền truy cập trực tuyến vào toàn bộ danh mục thư viện."},{"en":"Online access to medical records improves communication between doctors.","vi":"Truy cập trực tuyến vào hồ sơ y tế cải thiện giao tiếp giữa các bác sĩ."},{"en":"Limited online access remains a barrier in many rural areas.","vi":"Truy cập trực tuyến hạn chế vẫn là rào cản ở nhiều vùng nông thôn."}]', '[]', NULL, '/ˈɑːnˌlaɪn ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 10, 'online database', 'cơ sở dữ liệu trực tuyến', 'adj + n', '[{"en":"The articles were retrieved from a large online database.","vi":"Các bài báo được lấy từ một cơ sở dữ liệu trực tuyến lớn."},{"en":"An online database lets researchers search thousands of records quickly.","vi":"Một cơ sở dữ liệu trực tuyến cho phép nhà nghiên cứu tìm hàng nghìn bản ghi nhanh chóng."},{"en":"The university maintains an online database of past dissertations.","vi":"Trường đại học duy trì một cơ sở dữ liệu trực tuyến về các luận án trước đây."}]', '[]', NULL, '/ˈɑːnˌlaɪn ˈdeɪtəˌbeɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 11, 'online journal', 'tạp chí trực tuyến', 'adj + n', '[{"en":"Her study was published in a respected online journal.","vi":"Nghiên cứu của cô được công bố trên một tạp chí trực tuyến uy tín."},{"en":"Many online journals make their articles freely available to readers.","vi":"Nhiều tạp chí trực tuyến cho phép độc giả tiếp cận miễn phí các bài báo."},{"en":"An online journal can reach a global audience almost instantly.","vi":"Một tạp chí trực tuyến có thể tiếp cận độc giả toàn cầu gần như ngay lập tức."}]', '[]', NULL, '/ˈɑːnˌlaɪn ˈdʒɜːrnəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 12, 'online version', 'phiên bản trực tuyến', 'adj + n', '[{"en":"The online version of the book includes interactive exercises.","vi":"Phiên bản trực tuyến của cuốn sách có các bài tập tương tác."},{"en":"Readers can access the online version free of charge.","vi":"Độc giả có thể truy cập phiên bản trực tuyến miễn phí."},{"en":"The online version is updated more often than the print edition.","vi":"Phiên bản trực tuyến được cập nhật thường xuyên hơn bản in."}]', '[]', NULL, '/ˈɑːnˌlaɪn ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 13, 'open access', 'truy cập mở (miễn phí)', 'adj + n', '[{"en":"Open access allows anyone to read research without paying fees.","vi":"Truy cập mở cho phép bất kỳ ai đọc nghiên cứu mà không phải trả phí."},{"en":"The journal moved to an open access model last year.","vi":"Tạp chí đã chuyển sang mô hình truy cập mở vào năm ngoái."},{"en":"Open access publishing has changed how scientists share their work.","vi":"Xuất bản theo hình thức truy cập mở đã thay đổi cách các nhà khoa học chia sẻ công trình."}]', '[]', NULL, '/ˈoʊpən ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 14, 'opening chapter', 'chương mở đầu', 'adj + n', '[{"en":"The opening chapter introduces the main characters and setting.","vi":"Chương mở đầu giới thiệu các nhân vật chính và bối cảnh."},{"en":"Her opening chapter clearly outlines the aims of the thesis.","vi":"Chương mở đầu của cô nêu rõ các mục tiêu của luận án."},{"en":"A strong opening chapter often determines whether readers continue.","vi":"Một chương mở đầu mạnh mẽ thường quyết định liệu độc giả có đọc tiếp hay không."}]', '[]', NULL, '/ˈoʊpənɪŋ ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 15, 'opening section', 'phần mở đầu', 'adj + n', '[{"en":"The opening section explains the background to the study.","vi":"Phần mở đầu giải thích bối cảnh của nghiên cứu."},{"en":"In the opening section, the author states her main argument.","vi":"Trong phần mở đầu, tác giả nêu ra luận điểm chính của mình."},{"en":"The opening section should capture the reader''s attention immediately.","vi":"Phần mở đầu nên thu hút sự chú ý của độc giả ngay lập tức."}]', '[]', NULL, '/ˈoʊpənɪŋ ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 16, 'opinion leader', 'người dẫn dắt dư luận', 'n + n', '[{"en":"Opinion leaders strongly influence how communities respond to new ideas.","vi":"Những người dẫn dắt dư luận ảnh hưởng mạnh đến cách cộng đồng phản ứng với ý tưởng mới."},{"en":"Marketers often target opinion leaders to spread their messages.","vi":"Các nhà tiếp thị thường nhắm đến người dẫn dắt dư luận để lan tỏa thông điệp."},{"en":"An opinion leader can shape public attitudes within a group.","vi":"Một người dẫn dắt dư luận có thể định hình thái độ chung trong một nhóm."}]', '[]', NULL, '/əˈpɪnjən ˈliːdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 17, 'optimal solution', 'giải pháp tối ưu', 'adj + n', '[{"en":"The algorithm searches for the optimal solution among many options.","vi":"Thuật toán tìm kiếm giải pháp tối ưu trong số nhiều phương án."},{"en":"Finding the optimal solution required balancing cost against speed.","vi":"Tìm ra giải pháp tối ưu đòi hỏi cân bằng giữa chi phí và tốc độ."},{"en":"There is rarely a single optimal solution to complex problems.","vi":"Hiếm khi có một giải pháp tối ưu duy nhất cho các vấn đề phức tạp."}]', '[]', NULL, '/ˈɑːptɪməl səˈluːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 18, 'oral history', 'lịch sử truyền miệng', 'adj + n', '[{"en":"Oral history preserves the memories of people who lived events.","vi":"Lịch sử truyền miệng lưu giữ ký ức của những người đã trải qua sự kiện."},{"en":"She recorded oral history from elders in the village.","vi":"Cô ghi lại lịch sử truyền miệng từ những người cao tuổi trong làng."},{"en":"Oral history offers perspectives often missing from written records.","vi":"Lịch sử truyền miệng mang đến những góc nhìn mà tài liệu viết thường thiếu."}]', '[]', NULL, '/ˈɔːrəl ˈhɪstəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 19, 'oral presentation', 'bài thuyết trình nói', 'adj + n', '[{"en":"Each student must give an oral presentation at the end.","vi":"Mỗi sinh viên phải thực hiện một bài thuyết trình nói vào cuối kỳ."},{"en":"Her oral presentation clearly summarized the results of the project.","vi":"Bài thuyết trình nói của cô tóm tắt rõ ràng kết quả của dự án."},{"en":"Good preparation makes an oral presentation far more convincing.","vi":"Chuẩn bị tốt khiến một bài thuyết trình nói thuyết phục hơn nhiều."}]', '[]', NULL, '/ˈɔːrəl ˌprezənˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 20, 'organizing principle', 'nguyên tắc tổ chức (sắp xếp)', 'adj + n', '[{"en":"Chronology serves as the main organizing principle of the book.","vi":"Trình tự thời gian đóng vai trò là nguyên tắc tổ chức chính của cuốn sách."},{"en":"The essay lacks a clear organizing principle to guide readers.","vi":"Bài luận thiếu một nguyên tắc tổ chức rõ ràng để dẫn dắt độc giả."},{"en":"Equality became the central organizing principle of the movement.","vi":"Bình đẳng trở thành nguyên tắc tổ chức trung tâm của phong trào."}]', '[]', NULL, '/ˈɔːrɡəˌnaɪzɪŋ ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 21, 'organizational structure', 'cơ cấu tổ chức', 'adj + n', '[{"en":"The company changed its organizational structure to improve efficiency.","vi":"Công ty thay đổi cơ cấu tổ chức để cải thiện hiệu quả."},{"en":"A flat organizational structure can speed up decision making.","vi":"Một cơ cấu tổ chức phẳng có thể tăng tốc việc ra quyết định."},{"en":"The report analyzes the organizational structure of large hospitals.","vi":"Báo cáo phân tích cơ cấu tổ chức của các bệnh viện lớn."}]', '[]', NULL, '/ˌɔːrɡənɪˈzeɪʃənəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 22, 'original author', 'tác giả gốc', 'adj + n', '[{"en":"The translation stays faithful to the original author''s intentions.","vi":"Bản dịch giữ trung thành với ý định của tác giả gốc."},{"en":"We could not identify the original author of the manuscript.","vi":"Chúng tôi không thể xác định tác giả gốc của bản thảo."},{"en":"The original author published the theory more than a century ago.","vi":"Tác giả gốc đã công bố lý thuyết này hơn một thế kỷ trước."}]', '[]', NULL, '/əˈrɪdʒənəl ˈɔːθər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 23, 'original context', 'bối cảnh ban đầu', 'adj + n', '[{"en":"The quotation loses meaning when removed from its original context.","vi":"Câu trích dẫn mất ý nghĩa khi bị tách khỏi bối cảnh ban đầu."},{"en":"Understanding the original context helps explain the author''s choices.","vi":"Hiểu bối cảnh ban đầu giúp giải thích các lựa chọn của tác giả."},{"en":"The artifact was studied within its original cultural context.","vi":"Hiện vật được nghiên cứu trong bối cảnh văn hóa ban đầu của nó."}]', '[]', NULL, '/əˈrɪdʒənəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 24, 'original data', 'dữ liệu gốc', 'adj + n', '[{"en":"Researchers should always preserve the original data for verification.","vi":"Các nhà nghiên cứu nên luôn lưu giữ dữ liệu gốc để kiểm chứng."},{"en":"The original data was lost when the hard drive failed.","vi":"Dữ liệu gốc bị mất khi ổ cứng hỏng."},{"en":"Other scholars can reanalyze the original data to test the findings.","vi":"Các học giả khác có thể phân tích lại dữ liệu gốc để kiểm tra kết quả."}]', '[]', NULL, '/əˈrɪdʒənəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 25, 'original intent', 'ý định ban đầu', 'adj + n', '[{"en":"Judges sometimes debate the original intent of the lawmakers.","vi":"Các thẩm phán đôi khi tranh luận về ý định ban đầu của các nhà lập pháp."},{"en":"The reform drifted far from its original intent over time.","vi":"Cuộc cải cách dần đi xa khỏi ý định ban đầu theo thời gian."},{"en":"She explained the original intent behind the controversial policy.","vi":"Cô giải thích ý định ban đầu đằng sau chính sách gây tranh cãi."}]', '[]', NULL, '/əˈrɪdʒənəl ɪnˈtent/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 26, 'original meaning', 'nghĩa gốc', 'adj + n', '[{"en":"Over centuries, the word lost much of its original meaning.","vi":"Qua nhiều thế kỷ, từ này đã mất phần lớn nghĩa gốc."},{"en":"Scholars try to recover the original meaning of the ancient text.","vi":"Các học giả cố gắng khôi phục nghĩa gốc của văn bản cổ."},{"en":"A careful translation preserves the original meaning of the poem.","vi":"Một bản dịch cẩn thận giữ được nghĩa gốc của bài thơ."}]', '[]', NULL, '/əˈrɪdʒənəl ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 27, 'original model', 'mô hình ban đầu', 'adj + n', '[{"en":"The new theory builds directly on the original model.","vi":"Lý thuyết mới được xây dựng trực tiếp dựa trên mô hình ban đầu."},{"en":"Researchers revised the original model after new data appeared.","vi":"Các nhà nghiên cứu sửa đổi mô hình ban đầu sau khi có dữ liệu mới."},{"en":"The original model failed to account for several key variables.","vi":"Mô hình ban đầu không tính đến một số biến số quan trọng."}]', '[]', NULL, '/əˈrɪdʒənəl ˈmɑːdəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 28, 'original position', 'vị trí ban đầu', 'adj + n', '[{"en":"After the debate, she returned to her original position.","vi":"Sau cuộc tranh luận, cô quay lại với lập trường ban đầu của mình."},{"en":"The springs push the lever back to its original position.","vi":"Các lò xo đẩy đòn bẩy trở về vị trí ban đầu của nó."},{"en":"He defended his original position despite strong opposition.","vi":"Anh bảo vệ lập trường ban đầu của mình bất chấp sự phản đối mạnh mẽ."}]', '[]', NULL, '/əˈrɪdʒənəl pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 29, 'original research', 'nghiên cứu nguyên bản (tự thực hiện)', 'adj + n', '[{"en":"A doctoral thesis must contain genuine original research.","vi":"Một luận án tiến sĩ phải chứa đựng nghiên cứu nguyên bản thực sự."},{"en":"The journal only publishes original research, not literature reviews.","vi":"Tạp chí chỉ công bố nghiên cứu nguyên bản, không đăng tổng quan tài liệu."},{"en":"Her original research challenged several long-held assumptions.","vi":"Nghiên cứu nguyên bản của cô thách thức nhiều giả định lâu đời."}]', '[]', NULL, '/əˈrɪdʒənəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 30, 'original source', 'nguồn gốc (nguồn nguyên bản)', 'adj + n', '[{"en":"Always check the original source before citing a statistic.","vi":"Luôn kiểm tra nguồn gốc trước khi trích dẫn một con số thống kê."},{"en":"The claim could not be traced to its original source.","vi":"Khẳng định này không thể truy ngược về nguồn gốc của nó."},{"en":"Quoting the original source strengthens the credibility of your essay.","vi":"Trích dẫn nguồn gốc làm tăng độ tin cậy cho bài luận của bạn."}]', '[]', NULL, '/əˈrɪdʒənəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 31, 'original text', 'văn bản gốc', 'adj + n', '[{"en":"The translator stayed close to the original text throughout.","vi":"Người dịch bám sát văn bản gốc trong suốt quá trình."},{"en":"Comparing versions reveals small changes from the original text.","vi":"So sánh các phiên bản cho thấy những thay đổi nhỏ so với văn bản gốc."},{"en":"Students were asked to read the original text, not a summary.","vi":"Sinh viên được yêu cầu đọc văn bản gốc, không phải bản tóm tắt."}]', '[]', NULL, '/əˈrɪdʒənəl tekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 32, 'original version', 'phiên bản gốc', 'adj + n', '[{"en":"The original version of the film was much longer.","vi":"Phiên bản gốc của bộ phim dài hơn nhiều."},{"en":"Many readers still prefer the original version of the novel.","vi":"Nhiều độc giả vẫn thích phiên bản gốc của cuốn tiểu thuyết hơn."},{"en":"The original version contained errors that were later corrected.","vi":"Phiên bản gốc chứa những lỗi sau này đã được sửa."}]', '[]', NULL, '/əˈrɪdʒənəl ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 33, 'original work', 'tác phẩm nguyên bản', 'adj + n', '[{"en":"The exhibition features original works by several famous painters.","vi":"Triển lãm trưng bày các tác phẩm nguyên bản của vài họa sĩ nổi tiếng."},{"en":"Plagiarism means presenting someone else''s ideas as original work.","vi":"Đạo văn nghĩa là trình bày ý tưởng của người khác như tác phẩm nguyên bản."},{"en":"Her dissertation was praised as a piece of original work.","vi":"Luận án của cô được khen ngợi là một công trình nguyên bản."}]', '[]', NULL, '/əˈrɪdʒənəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 34, 'originally developed', 'được phát triển ban đầu', 'adv + vpp', '[{"en":"The technology was originally developed for military purposes.","vi":"Công nghệ này ban đầu được phát triển cho mục đích quân sự."},{"en":"This method was originally developed by a small research team.","vi":"Phương pháp này ban đầu được phát triển bởi một nhóm nghiên cứu nhỏ."},{"en":"The drug was originally developed to treat a different disease.","vi":"Loại thuốc này ban đầu được phát triển để điều trị một căn bệnh khác."}]', '[]', NULL, '/əˈrɪdʒənəli dɪˈveləpt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 35, 'originally intended', 'vốn được dự định ban đầu', 'adv + vpp', '[{"en":"The building was originally intended to be a library.","vi":"Tòa nhà vốn được dự định ban đầu làm một thư viện."},{"en":"The funds were originally intended for emergency relief programs.","vi":"Khoản tiền vốn được dự định ban đầu cho các chương trình cứu trợ khẩn cấp."},{"en":"The policy reached groups it was not originally intended to help.","vi":"Chính sách tiếp cận những nhóm mà ban đầu nó không dự định giúp đỡ."}]', '[]', NULL, '/əˈrɪdʒənəli ɪnˈtendɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 36, 'overall aim', 'mục tiêu tổng thể', 'adj + n', '[{"en":"The overall aim of the project is to reduce poverty.","vi":"Mục tiêu tổng thể của dự án là giảm nghèo."},{"en":"Each task supports the overall aim of the research.","vi":"Mỗi nhiệm vụ đều hỗ trợ cho mục tiêu tổng thể của nghiên cứu."},{"en":"She kept the overall aim in mind throughout the study.","vi":"Cô luôn ghi nhớ mục tiêu tổng thể trong suốt quá trình nghiên cứu."}]', '[]', NULL, '/ˌoʊvərˈɔːl eɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 37, 'overall effect', 'tác động tổng thể', 'adj + n', '[{"en":"The overall effect of the policy was hard to measure.","vi":"Tác động tổng thể của chính sách rất khó đo lường."},{"en":"These small changes had a significant overall effect on costs.","vi":"Những thay đổi nhỏ này có tác động tổng thể đáng kể lên chi phí."},{"en":"The overall effect of the design was calm and welcoming.","vi":"Hiệu ứng tổng thể của thiết kế tạo cảm giác bình yên và thân thiện."}]', '[]', NULL, '/ˌoʊvərˈɔːl ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 38, 'overall level', 'mức độ tổng thể', 'adj + n', '[{"en":"The overall level of satisfaction rose after the changes.","vi":"Mức độ hài lòng tổng thể tăng lên sau những thay đổi."},{"en":"Researchers measured the overall level of pollution in the river.","vi":"Các nhà nghiên cứu đo mức độ ô nhiễm tổng thể của con sông."},{"en":"The overall level of skill in the group was impressive.","vi":"Trình độ kỹ năng tổng thể của nhóm rất ấn tượng."}]', '[]', NULL, '/ˌoʊvərˈɔːl ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 39, 'overall performance', 'hiệu suất tổng thể', 'adj + n', '[{"en":"The new method improved the overall performance of the system.","vi":"Phương pháp mới cải thiện hiệu suất tổng thể của hệ thống."},{"en":"Her overall performance this year exceeded everyone''s expectations.","vi":"Thành tích tổng thể của cô năm nay vượt mọi kỳ vọng."},{"en":"Sleep and diet both affect a student''s overall performance.","vi":"Giấc ngủ và chế độ ăn đều ảnh hưởng đến thành tích tổng thể của sinh viên."}]', '[]', NULL, '/ˌoʊvərˈɔːl pərˈfɔːrməns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 40, 'overall picture', 'bức tranh toàn cảnh', 'adj + n', '[{"en":"Combining the studies gives us a clearer overall picture.","vi":"Kết hợp các nghiên cứu cho ta một bức tranh toàn cảnh rõ ràng hơn."},{"en":"A single statistic rarely shows the overall picture accurately.","vi":"Một con số thống kê đơn lẻ hiếm khi phản ánh chính xác bức tranh toàn cảnh."},{"en":"The summary helps readers grasp the overall picture quickly.","vi":"Phần tóm tắt giúp độc giả nắm bắt bức tranh toàn cảnh nhanh chóng."}]', '[]', NULL, '/ˌoʊvərˈɔːl ˈpɪktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 41, 'overall rate', 'tỷ lệ tổng thể', 'adj + n', '[{"en":"The overall rate of unemployment fell slightly last quarter.","vi":"Tỷ lệ thất nghiệp tổng thể giảm nhẹ trong quý trước."},{"en":"Vaccination raised the overall rate of immunity in the population.","vi":"Tiêm chủng nâng tỷ lệ miễn dịch tổng thể trong dân số."},{"en":"Despite local spikes, the overall rate remained fairly stable.","vi":"Dù có những đợt tăng cục bộ, tỷ lệ tổng thể vẫn khá ổn định."}]', '[]', NULL, '/ˌoʊvərˈɔːl reɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 42, 'overall structure', 'cấu trúc tổng thể', 'adj + n', '[{"en":"The essay''s overall structure guides the reader through the argument.","vi":"Cấu trúc tổng thể của bài luận dẫn dắt độc giả qua lập luận."},{"en":"Understanding the overall structure helps you follow the lecture.","vi":"Hiểu cấu trúc tổng thể giúp bạn theo dõi bài giảng."},{"en":"The overall structure of the molecule determines its function.","vi":"Cấu trúc tổng thể của phân tử quyết định chức năng của nó."}]', '[]', NULL, '/ˌoʊvərˈɔːl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 43, 'overwhelming majority', 'đại đa số áp đảo', 'adj + n', '[{"en":"The overwhelming majority of respondents supported the new plan.","vi":"Đại đa số áp đảo người được hỏi ủng hộ kế hoạch mới."},{"en":"An overwhelming majority of scientists agree on this conclusion.","vi":"Đại đa số áp đảo các nhà khoa học đồng ý với kết luận này."},{"en":"The motion passed with an overwhelming majority of votes.","vi":"Đề xuất được thông qua với đa số phiếu áp đảo."}]', '[]', NULL, '/ˌoʊvərˈwelmɪŋ məˈdʒɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 44, 'paid employment', 'công việc được trả lương', 'adj + n', '[{"en":"Many students balance paid employment with their university studies.","vi":"Nhiều sinh viên cân bằng công việc được trả lương với việc học đại học."},{"en":"Access to paid employment greatly improves financial independence.","vi":"Tiếp cận công việc được trả lương cải thiện đáng kể sự độc lập tài chính."},{"en":"The study examined barriers to paid employment for disabled people.","vi":"Nghiên cứu xem xét những rào cản đối với công việc được trả lương cho người khuyết tật."}]', '[]', NULL, '/peɪd ɪmˈplɔɪmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 45, 'paramount importance', 'tầm quan trọng tối cao', 'adj + n', '[{"en":"Patient safety is of paramount importance in every hospital.","vi":"An toàn của bệnh nhân có tầm quan trọng tối cao trong mọi bệnh viện."},{"en":"Accuracy is of paramount importance when reporting scientific data.","vi":"Tính chính xác có tầm quan trọng tối cao khi báo cáo dữ liệu khoa học."},{"en":"For this mission, clear communication is of paramount importance.","vi":"Đối với nhiệm vụ này, giao tiếp rõ ràng có tầm quan trọng tối cao."}]', '[]', NULL, '/ˈpærəˌmaʊnt ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 46, 'particular area', 'lĩnh vực cụ thể', 'adj + n', '[{"en":"She specializes in a particular area of molecular biology.","vi":"Cô chuyên về một lĩnh vực cụ thể của sinh học phân tử."},{"en":"The report focuses on one particular area of public policy.","vi":"Báo cáo tập trung vào một lĩnh vực cụ thể của chính sách công."},{"en":"This particular area of the brain controls language processing.","vi":"Vùng cụ thể này của não điều khiển việc xử lý ngôn ngữ."}]', '[]', NULL, '/pərˈtɪkjələr ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 47, 'particular aspect', 'khía cạnh cụ thể', 'adj + n', '[{"en":"The chapter explores one particular aspect of human memory.","vi":"Chương này khám phá một khía cạnh cụ thể của trí nhớ con người."},{"en":"Each interview focused on a particular aspect of their work.","vi":"Mỗi cuộc phỏng vấn tập trung vào một khía cạnh cụ thể trong công việc của họ."},{"en":"This particular aspect of the theory remains poorly understood.","vi":"Khía cạnh cụ thể này của lý thuyết vẫn còn ít được hiểu rõ."}]', '[]', NULL, '/pərˈtɪkjələr ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 48, 'particular emphasis', 'sự nhấn mạnh đặc biệt', 'adj + n', '[{"en":"The course places particular emphasis on practical laboratory skills.","vi":"Khóa học đặc biệt nhấn mạnh vào các kỹ năng thực hành trong phòng thí nghiệm."},{"en":"She gave particular emphasis to ethical issues in her lecture.","vi":"Cô đặc biệt nhấn mạnh các vấn đề đạo đức trong bài giảng của mình."},{"en":"The policy puts particular emphasis on early childhood education.","vi":"Chính sách này đặc biệt nhấn mạnh vào giáo dục mầm non."}]', '[]', NULL, '/pərˈtɪkjələr ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 49, 'particular feature', 'đặc điểm cụ thể', 'adj + n', '[{"en":"One particular feature of the design attracted the most attention.","vi":"Một đặc điểm cụ thể của thiết kế thu hút sự chú ý nhiều nhất."},{"en":"This particular feature distinguishes the species from its relatives.","vi":"Đặc điểm cụ thể này phân biệt loài này với các loài họ hàng."},{"en":"The author highlights a particular feature of the local dialect.","vi":"Tác giả làm nổi bật một đặc điểm cụ thể của phương ngữ địa phương."}]', '[]', NULL, '/pərˈtɪkjələr ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 50, 'particular focus', 'trọng tâm cụ thể', 'adj + n', '[{"en":"The study has a particular focus on young first-time voters.","vi":"Nghiên cứu có trọng tâm cụ thể là những cử tri trẻ lần đầu đi bầu."},{"en":"Her work places particular focus on sustainable urban transport.","vi":"Công việc của cô đặt trọng tâm cụ thể vào giao thông đô thị bền vững."},{"en":"This chapter gives particular focus to the economic consequences.","vi":"Chương này dành trọng tâm cụ thể cho các hệ quả kinh tế."}]', '[]', NULL, '/pərˈtɪkjələr ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 51, 'particular individual', 'một cá nhân cụ thể', 'adj + n', '[{"en":"The policy was not designed to target any particular individual.","vi":"Chính sách không được thiết kế để nhắm vào bất kỳ cá nhân cụ thể nào."},{"en":"Responsibility cannot always be traced to one particular individual.","vi":"Trách nhiệm không phải lúc nào cũng truy về một cá nhân cụ thể."},{"en":"The case study follows one particular individual over ten years.","vi":"Nghiên cứu trường hợp theo dõi một cá nhân cụ thể trong mười năm."}]', '[]', NULL, '/pərˈtɪkjələr ˌɪndɪˈvɪdʒuəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 52, 'particular meaning', 'ý nghĩa cụ thể', 'adj + n', '[{"en":"The word carries a particular meaning in legal contexts.","vi":"Từ này mang một ý nghĩa cụ thể trong ngữ cảnh pháp lý."},{"en":"This symbol had a particular meaning for the ancient community.","vi":"Biểu tượng này có một ý nghĩa cụ thể đối với cộng đồng cổ xưa."},{"en":"Each color in the diagram conveys a particular meaning.","vi":"Mỗi màu trong sơ đồ truyền tải một ý nghĩa cụ thể."}]', '[]', NULL, '/pərˈtɪkjələr ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 53, 'particularly acute', 'đặc biệt nghiêm trọng (gay gắt)', 'adv + adj', '[{"en":"The housing shortage is particularly acute in large cities.","vi":"Tình trạng thiếu nhà ở đặc biệt nghiêm trọng tại các thành phố lớn."},{"en":"Water scarcity becomes particularly acute during the dry season.","vi":"Tình trạng khan hiếm nước trở nên đặc biệt nghiêm trọng vào mùa khô."},{"en":"The problem is particularly acute among low-income families.","vi":"Vấn đề này đặc biệt nghiêm trọng ở các gia đình thu nhập thấp."}]', '[]', NULL, '/pərˈtɪkjələrli əˈkjuːt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 54, 'particularly apparent', 'đặc biệt rõ ràng', 'adv + adj', '[{"en":"The difference is particularly apparent in the youngest age group.","vi":"Sự khác biệt đặc biệt rõ ràng ở nhóm tuổi nhỏ nhất."},{"en":"This trend becomes particularly apparent when data is graphed.","vi":"Xu hướng này trở nên đặc biệt rõ ràng khi dữ liệu được vẽ biểu đồ."},{"en":"The effect was particularly apparent after the second treatment.","vi":"Hiệu ứng đặc biệt rõ ràng sau lần điều trị thứ hai."}]', '[]', NULL, '/pərˈtɪkjələrli əˈpærənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 55, 'particularly appropriate', 'đặc biệt phù hợp', 'adv + adj', '[{"en":"This method is particularly appropriate for small data sets.","vi":"Phương pháp này đặc biệt phù hợp với các tập dữ liệu nhỏ."},{"en":"The example seems particularly appropriate for beginning students.","vi":"Ví dụ này có vẻ đặc biệt phù hợp với sinh viên mới bắt đầu."},{"en":"Her tone was particularly appropriate for such a sensitive topic.","vi":"Giọng điệu của cô đặc biệt phù hợp với một chủ đề nhạy cảm như vậy."}]', '[]', NULL, '/pərˈtɪkjələrli əˈproʊpriət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 56, 'particularly concerned with', 'đặc biệt quan tâm đến', 'adv + vpp', '[{"en":"The author is particularly concerned with questions of social justice.","vi":"Tác giả đặc biệt quan tâm đến các vấn đề công bằng xã hội."},{"en":"This branch of study is particularly concerned with human behavior.","vi":"Nhánh nghiên cứu này đặc biệt quan tâm đến hành vi con người."},{"en":"Regulators are particularly concerned with protecting consumer privacy.","vi":"Các cơ quan quản lý đặc biệt quan tâm đến việc bảo vệ quyền riêng tư người tiêu dùng."}]', '[]', NULL, '/pərˈtɪkjələrli kənˈsɜːrnd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 57, 'particularly effective', 'đặc biệt hiệu quả', 'adv + adj', '[{"en":"Visual aids are particularly effective when explaining complex ideas.","vi":"Phương tiện trực quan đặc biệt hiệu quả khi giải thích các ý tưởng phức tạp."},{"en":"The new treatment proved particularly effective in older patients.","vi":"Phương pháp điều trị mới tỏ ra đặc biệt hiệu quả ở bệnh nhân lớn tuổi."},{"en":"This strategy is particularly effective at reducing student anxiety.","vi":"Chiến lược này đặc biệt hiệu quả trong việc giảm lo âu cho sinh viên."}]', '[]', NULL, '/pərˈtɪkjələrli ɪˈfektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 58, 'particularly evident', 'đặc biệt rõ nét', 'adv + adj', '[{"en":"This pattern is particularly evident in urban populations.","vi":"Khuôn mẫu này đặc biệt rõ nét ở các quần thể đô thị."},{"en":"Her influence is particularly evident in later literary works.","vi":"Ảnh hưởng của cô đặc biệt rõ nét trong các tác phẩm văn học về sau."},{"en":"The improvement was particularly evident during the final tests.","vi":"Sự cải thiện đặc biệt rõ nét trong các bài kiểm tra cuối cùng."}]', '[]', NULL, '/pərˈtɪkjələrli ˈevɪdənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 59, 'particularly influential', 'đặc biệt có ảnh hưởng', 'adv + adj', '[{"en":"Her early essays were particularly influential among young scholars.","vi":"Những bài luận đầu tay của cô đặc biệt có ảnh hưởng với các học giả trẻ."},{"en":"This theory proved particularly influential in modern economics.","vi":"Lý thuyết này tỏ ra đặc biệt có ảnh hưởng trong kinh tế học hiện đại."},{"en":"One book was particularly influential in shaping public opinion.","vi":"Một cuốn sách đặc biệt có ảnh hưởng trong việc định hình dư luận."}]', '[]', NULL, '/pərˈtɪkjələrli ˌɪnfluˈenʃəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 60, 'particularly relevant', 'đặc biệt liên quan (thích đáng)', 'adv + adj', '[{"en":"These findings are particularly relevant to current health policy.","vi":"Những phát hiện này đặc biệt liên quan đến chính sách y tế hiện hành."},{"en":"The example felt particularly relevant to the students'' own lives.","vi":"Ví dụ này cảm thấy đặc biệt liên quan đến cuộc sống của chính các sinh viên."},{"en":"This argument is particularly relevant in the digital age.","vi":"Lập luận này đặc biệt thích đáng trong thời đại số."}]', '[]', NULL, '/pərˈtɪkjələrli ˈreləvənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 61, 'particularly sensitive', 'đặc biệt nhạy cảm', 'adv + adj', '[{"en":"The interview touched on a particularly sensitive personal topic.","vi":"Cuộc phỏng vấn chạm đến một chủ đề cá nhân đặc biệt nhạy cảm."},{"en":"Young children are particularly sensitive to changes in routine.","vi":"Trẻ nhỏ đặc biệt nhạy cảm với những thay đổi trong thói quen."},{"en":"This instrument is particularly sensitive to small temperature shifts.","vi":"Thiết bị này đặc biệt nhạy cảm với những thay đổi nhiệt độ nhỏ."}]', '[]', NULL, '/pərˈtɪkjələrli ˈsensətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 62, 'particularly significant', 'đặc biệt quan trọng (đáng kể)', 'adv + adj', '[{"en":"This discovery was particularly significant for cancer research.","vi":"Phát hiện này đặc biệt quan trọng đối với nghiên cứu ung thư."},{"en":"The difference between the groups was particularly significant.","vi":"Sự khác biệt giữa các nhóm là đặc biệt đáng kể."},{"en":"Her contribution was particularly significant in that field.","vi":"Đóng góp của cô đặc biệt quan trọng trong lĩnh vực đó."}]', '[]', NULL, '/pərˈtɪkjələrli sɪɡˈnɪfɪkənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 63, 'particularly striking', 'đặc biệt nổi bật (ấn tượng)', 'adv + adj', '[{"en":"One result was particularly striking and surprised the whole team.","vi":"Một kết quả đặc biệt nổi bật và khiến cả nhóm bất ngờ."},{"en":"The contrast between the two regions is particularly striking.","vi":"Sự tương phản giữa hai khu vực đặc biệt nổi bật."},{"en":"Her use of color is particularly striking in these paintings.","vi":"Cách cô dùng màu sắc đặc biệt ấn tượng trong những bức tranh này."}]', '[]', NULL, '/pərˈtɪkjələrli ˈstraɪkɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 64, 'particularly successful', 'đặc biệt thành công', 'adv + adj', '[{"en":"The campaign was particularly successful among younger audiences.","vi":"Chiến dịch đặc biệt thành công với đối tượng khán giả trẻ."},{"en":"This approach has been particularly successful in rural schools.","vi":"Cách tiếp cận này đặc biệt thành công ở các trường nông thôn."},{"en":"Her first novel was particularly successful with critics.","vi":"Cuốn tiểu thuyết đầu tay của cô đặc biệt thành công với giới phê bình."}]', '[]', NULL, '/pərˈtɪkjələrli səkˈsesfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 65, 'particularly suited to', 'đặc biệt phù hợp với', 'adv + vpp', '[{"en":"This software is particularly suited to large-scale data analysis.","vi":"Phần mềm này đặc biệt phù hợp với phân tích dữ liệu quy mô lớn."},{"en":"The plant is particularly suited to hot and dry climates.","vi":"Loài cây này đặc biệt phù hợp với khí hậu nóng và khô."},{"en":"Her skills are particularly suited to collaborative research projects.","vi":"Kỹ năng của cô đặc biệt phù hợp với các dự án nghiên cứu hợp tác."}]', '[]', NULL, '/pərˈtɪkjələrli ˈsuːtɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 66, 'particularly useful', 'đặc biệt hữu ích', 'adv + adj', '[{"en":"This guide is particularly useful for first-year students.","vi":"Cuốn cẩm nang này đặc biệt hữu ích cho sinh viên năm nhất."},{"en":"The technique is particularly useful when time is limited.","vi":"Kỹ thuật này đặc biệt hữu ích khi thời gian hạn chế."},{"en":"Such maps are particularly useful for planning field research.","vi":"Những bản đồ như vậy đặc biệt hữu ích cho việc lập kế hoạch nghiên cứu thực địa."}]', '[]', NULL, '/pərˈtɪkjələrli ˈjuːsfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 67, 'particularly valuable', 'đặc biệt giá trị', 'adv + adj', '[{"en":"This dataset is particularly valuable for studying long-term climate trends.","vi":"Bộ dữ liệu này đặc biệt giá trị cho việc nghiên cứu xu hướng khí hậu dài hạn."},{"en":"Her feedback was particularly valuable during the early drafting stage.","vi":"Phản hồi của cô đặc biệt giá trị trong giai đoạn viết nháp ban đầu."},{"en":"Such firsthand accounts are particularly valuable to historians.","vi":"Những lời kể trực tiếp như vậy đặc biệt giá trị đối với các nhà sử học."}]', '[]', NULL, '/pərˈtɪkjələrli ˈvæljəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 68, 'partly responsible for', 'một phần chịu trách nhiệm về', 'adv + adj', '[{"en":"Poor management was partly responsible for the project''s failure.","vi":"Quản lý kém một phần chịu trách nhiệm về sự thất bại của dự án."},{"en":"The new policy is partly responsible for the recent decline.","vi":"Chính sách mới một phần chịu trách nhiệm về sự suy giảm gần đây."},{"en":"Genetics may be partly responsible for these behavioral differences.","vi":"Di truyền có thể một phần chịu trách nhiệm về những khác biệt hành vi này."}]', '[]', NULL, '/ˈpɑːrtli rɪˈspɑːnsəbəl fər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 69, 'party leader', 'lãnh đạo đảng', 'n + n', '[{"en":"The party leader announced a major shift in policy yesterday.","vi":"Lãnh đạo đảng đã công bố một thay đổi lớn về chính sách hôm qua."},{"en":"Members voted to elect a new party leader this spring.","vi":"Các thành viên đã bỏ phiếu bầu lãnh đạo đảng mới vào mùa xuân này."},{"en":"Critics accused the party leader of ignoring grassroots concerns.","vi":"Các nhà phê bình cáo buộc lãnh đạo đảng phớt lờ mối lo của cơ sở."}]', '[]', NULL, '/ˈpɑːrti ˈliːdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 70, 'past research', 'nghiên cứu trước đây', 'adj + n', '[{"en":"Past research has shown a clear link between diet and health.","vi":"Nghiên cứu trước đây đã chỉ ra mối liên hệ rõ ràng giữa chế độ ăn và sức khỏe."},{"en":"Our study builds on past research into bilingual education.","vi":"Nghiên cứu của chúng tôi dựa trên các nghiên cứu trước đây về giáo dục song ngữ."},{"en":"Past research largely ignored the role of social factors.","vi":"Nghiên cứu trước đây phần lớn bỏ qua vai trò của các yếu tố xã hội."}]', '[]', NULL, '/pæst ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 71, 'peace treaty', 'hiệp ước hòa bình', 'n + n', '[{"en":"The two nations finally signed a peace treaty after years of war.","vi":"Hai quốc gia cuối cùng đã ký hiệp ước hòa bình sau nhiều năm chiến tranh."},{"en":"Historians still debate the terms of that peace treaty.","vi":"Các nhà sử học vẫn còn tranh luận về các điều khoản của hiệp ước hòa bình đó."},{"en":"The peace treaty redrew the borders across the region.","vi":"Hiệp ước hòa bình đã vẽ lại biên giới trên khắp khu vực."}]', '[]', NULL, '/piːs ˈtriːti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 72, 'perceived importance', 'tầm quan trọng được nhận thức', 'adj + n', '[{"en":"The perceived importance of the issue influenced voter behavior.","vi":"Tầm quan trọng được nhận thức của vấn đề đã ảnh hưởng đến hành vi cử tri."},{"en":"Researchers measured the perceived importance of each factor.","vi":"Các nhà nghiên cứu đo lường tầm quan trọng được nhận thức của từng yếu tố."},{"en":"Its perceived importance grew as media coverage increased.","vi":"Tầm quan trọng được nhận thức của nó tăng lên khi truyền thông đưa tin nhiều hơn."}]', '[]', NULL, '/pərˈsiːvd ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 73, 'perceived need', 'nhu cầu được nhận thức', 'adj + n', '[{"en":"The perceived need for reform drove the new legislation forward.","vi":"Nhu cầu cải cách được nhận thức đã thúc đẩy đạo luật mới tiến triển."},{"en":"Marketing often creates a perceived need for new products.","vi":"Tiếp thị thường tạo ra nhu cầu được nhận thức đối với sản phẩm mới."},{"en":"A perceived need for security shaped these community decisions.","vi":"Nhu cầu an ninh được nhận thức đã định hình những quyết định cộng đồng này."}]', '[]', NULL, '/pərˈsiːvd niːd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 74, 'perceived threat', 'mối đe dọa được nhận thức', 'adj + n', '[{"en":"A perceived threat can trigger strong emotional reactions in people.","vi":"Một mối đe dọa được nhận thức có thể kích hoạt phản ứng cảm xúc mạnh ở con người."},{"en":"The perceived threat of competition pushed the firm to innovate.","vi":"Mối đe dọa cạnh tranh được nhận thức đã thúc đẩy công ty đổi mới."},{"en":"Policies often respond to a perceived threat rather than a real one.","vi":"Chính sách thường phản ứng với mối đe dọa được nhận thức hơn là mối đe dọa thực."}]', '[]', NULL, '/pərˈsiːvd θret/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 75, 'perform a function', 'thực hiện một chức năng', 'v + n', '[{"en":"Each organ in the body performs a vital function.","vi":"Mỗi cơ quan trong cơ thể thực hiện một chức năng thiết yếu."},{"en":"These cells perform a function essential to the immune system.","vi":"Những tế bào này thực hiện một chức năng thiết yếu đối với hệ miễn dịch."},{"en":"The software can perform a complex function with a single click.","vi":"Phần mềm có thể thực hiện một chức năng phức tạp chỉ với một cú nhấp."}]', '[]', NULL, '/pərˈfɔːrm ə ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 76, 'perform a study', 'tiến hành một nghiên cứu', 'v + n', '[{"en":"Scientists performed a study to test the new vaccine''s safety.","vi":"Các nhà khoa học đã tiến hành một nghiên cứu để kiểm tra độ an toàn của vắc-xin mới."},{"en":"The team performed a study on sleep and academic performance.","vi":"Nhóm đã tiến hành một nghiên cứu về giấc ngủ và kết quả học tập."},{"en":"We performed a study involving over two thousand participants.","vi":"Chúng tôi đã tiến hành một nghiên cứu với hơn hai nghìn người tham gia."}]', '[]', NULL, '/pərˈfɔːrm ə ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 77, 'perform a task', 'thực hiện một nhiệm vụ', 'v + n', '[{"en":"Participants were asked to perform a simple memory task.","vi":"Người tham gia được yêu cầu thực hiện một nhiệm vụ ghi nhớ đơn giản."},{"en":"Robots can perform a repetitive task far faster than humans.","vi":"Robot có thể thực hiện một nhiệm vụ lặp lại nhanh hơn nhiều so với con người."},{"en":"Stress can affect how well we perform a difficult task.","vi":"Căng thẳng có thể ảnh hưởng đến việc ta thực hiện một nhiệm vụ khó tốt đến đâu."}]', '[]', NULL, '/pərˈfɔːrm ə tæsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 78, 'personal choice', 'lựa chọn cá nhân', 'adj + n', '[{"en":"Whether to attend the ceremony is ultimately a personal choice.","vi":"Có dự buổi lễ hay không rốt cuộc là một lựa chọn cá nhân."},{"en":"The study respects each participant''s personal choice about treatment.","vi":"Nghiên cứu tôn trọng lựa chọn cá nhân của mỗi người tham gia về việc điều trị."},{"en":"Diet is often framed as a personal choice rather than policy.","vi":"Chế độ ăn thường được xem là lựa chọn cá nhân hơn là vấn đề chính sách."}]', '[]', NULL, '/ˈpɜːrsənəl tʃɔɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 79, 'personal circumstances', 'hoàn cảnh cá nhân', 'adj + n', '[{"en":"Students may defer enrollment due to difficult personal circumstances.","vi":"Sinh viên có thể hoãn nhập học vì hoàn cảnh cá nhân khó khăn."},{"en":"The court considered her personal circumstances before sentencing.","vi":"Tòa án đã xem xét hoàn cảnh cá nhân của cô trước khi tuyên án."},{"en":"Each application is assessed against the applicant''s personal circumstances.","vi":"Mỗi hồ sơ được đánh giá dựa trên hoàn cảnh cá nhân của người nộp đơn."}]', '[]', NULL, '/ˈpɜːrsənəl ˈsɜːrkəmstænsəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 80, 'personal communication', 'trao đổi cá nhân', 'adj + n', '[{"en":"The author cited a personal communication from a leading expert.","vi":"Tác giả đã trích dẫn một trao đổi cá nhân từ một chuyên gia hàng đầu."},{"en":"Details were confirmed through personal communication with the researcher.","vi":"Các chi tiết được xác nhận qua trao đổi cá nhân với nhà nghiên cứu."},{"en":"In academic writing, personal communication is cited carefully.","vi":"Trong văn viết học thuật, trao đổi cá nhân được trích dẫn một cách cẩn thận."}]', '[]', NULL, '/ˈpɜːrsənəl kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 81, 'personal contact', 'tiếp xúc cá nhân', 'adj + n', '[{"en":"Personal contact with mentors often shapes a student''s career path.","vi":"Tiếp xúc cá nhân với người hướng dẫn thường định hình con đường sự nghiệp của sinh viên."},{"en":"Online learning can reduce personal contact between classmates.","vi":"Học trực tuyến có thể làm giảm tiếp xúc cá nhân giữa các bạn cùng lớp."},{"en":"She built her network through years of personal contact.","vi":"Cô xây dựng mạng lưới của mình qua nhiều năm tiếp xúc cá nhân."}]', '[]', NULL, '/ˈpɜːrsənəl ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 82, 'personal control', 'khả năng tự kiểm soát', 'adj + n', '[{"en":"A sense of personal control reduces stress in difficult situations.","vi":"Cảm giác tự kiểm soát giúp giảm căng thẳng trong các tình huống khó khăn."},{"en":"The program aims to increase patients'' personal control over recovery.","vi":"Chương trình nhằm tăng khả năng tự kiểm soát của bệnh nhân đối với việc hồi phục."},{"en":"People with greater personal control tend to feel more satisfied.","vi":"Những người có khả năng tự kiểm soát cao hơn thường cảm thấy hài lòng hơn."}]', '[]', NULL, '/ˈpɜːrsənəl kənˈtroʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 83, 'personal experience', 'trải nghiệm cá nhân', 'adj + n', '[{"en":"She drew on personal experience to illustrate her main argument.","vi":"Cô dựa vào trải nghiệm cá nhân để minh họa cho luận điểm chính của mình."},{"en":"Personal experience alone is rarely enough to prove a theory.","vi":"Riêng trải nghiệm cá nhân hiếm khi đủ để chứng minh một lý thuyết."},{"en":"The interviews captured each nurse''s personal experience of the crisis.","vi":"Các cuộc phỏng vấn ghi lại trải nghiệm cá nhân của mỗi y tá về cuộc khủng hoảng."}]', '[]', NULL, '/ˈpɜːrsənəl ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 84, 'personal information', 'thông tin cá nhân', 'adj + n', '[{"en":"The website collects personal information without clear consent.","vi":"Trang web thu thập thông tin cá nhân mà không có sự đồng ý rõ ràng."},{"en":"Researchers must protect the personal information of all participants.","vi":"Các nhà nghiên cứu phải bảo vệ thông tin cá nhân của mọi người tham gia."},{"en":"New laws restrict how companies share personal information online.","vi":"Luật mới hạn chế cách các công ty chia sẻ thông tin cá nhân trên mạng."}]', '[]', NULL, '/ˈpɜːrsənəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 85, 'personal interest', 'sở thích cá nhân', 'adj + n', '[{"en":"His personal interest in astronomy led him to study physics.","vi":"Sở thích cá nhân về thiên văn đã đưa anh đến với việc học vật lý."},{"en":"The topic reflects the writer''s deep personal interest in history.","vi":"Chủ đề phản ánh sở thích cá nhân sâu sắc của tác giả về lịch sử."},{"en":"Students perform better when they have a personal interest in the subject.","vi":"Sinh viên học tốt hơn khi có sở thích cá nhân với môn học."}]', '[]', NULL, '/ˈpɜːrsənəl ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 86, 'personal knowledge', 'hiểu biết cá nhân', 'adj + n', '[{"en":"The witness spoke from personal knowledge of the events.","vi":"Nhân chứng nói dựa trên hiểu biết cá nhân về các sự kiện."},{"en":"Personal knowledge of the region helped the team plan the survey.","vi":"Hiểu biết cá nhân về khu vực đã giúp nhóm lên kế hoạch khảo sát."},{"en":"Scientists must distinguish personal knowledge from verified evidence.","vi":"Các nhà khoa học phải phân biệt hiểu biết cá nhân với bằng chứng đã được kiểm chứng."}]', '[]', NULL, '/ˈpɜːrsənəl ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 87, 'personal quality', 'phẩm chất cá nhân', 'adj + n', '[{"en":"Patience is a personal quality valued highly in teaching.","vi":"Kiên nhẫn là một phẩm chất cá nhân được đánh giá cao trong giảng dạy."},{"en":"Employers assess each candidate''s personal qualities during interviews.","vi":"Nhà tuyển dụng đánh giá phẩm chất cá nhân của từng ứng viên trong các cuộc phỏng vấn."},{"en":"Leadership depends on personal qualities as much as on skills.","vi":"Khả năng lãnh đạo phụ thuộc vào phẩm chất cá nhân nhiều như vào kỹ năng."}]', '[]', NULL, '/ˈpɜːrsənəl ˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 88, 'personal relationship', 'mối quan hệ cá nhân', 'adj + n', '[{"en":"A strong personal relationship with clients improves long-term trust.","vi":"Một mối quan hệ cá nhân vững chắc với khách hàng cải thiện niềm tin lâu dài."},{"en":"The study explored how personal relationships affect job satisfaction.","vi":"Nghiên cứu khám phá cách các mối quan hệ cá nhân ảnh hưởng đến sự hài lòng công việc."},{"en":"Maintaining a personal relationship across distance can be challenging.","vi":"Duy trì một mối quan hệ cá nhân qua khoảng cách có thể đầy thử thách."}]', '[]', NULL, '/ˈpɜːrsənəl rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 89, 'personal responsibility', 'trách nhiệm cá nhân', 'adj + n', '[{"en":"The campaign encourages personal responsibility for the environment.","vi":"Chiến dịch khuyến khích trách nhiệm cá nhân đối với môi trường."},{"en":"He accepted full personal responsibility for the mistake.","vi":"Anh đã chấp nhận hoàn toàn trách nhiệm cá nhân về sai lầm đó."},{"en":"Good health partly depends on a sense of personal responsibility.","vi":"Sức khỏe tốt một phần phụ thuộc vào ý thức trách nhiệm cá nhân."}]', '[]', NULL, '/ˈpɜːrsənəl rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 90, 'personal safety', 'an toàn cá nhân', 'adj + n', '[{"en":"The training covered personal safety in remote fieldwork settings.","vi":"Khóa đào tạo bao gồm an toàn cá nhân trong môi trường khảo sát thực địa xa xôi."},{"en":"Many residents worry about personal safety after dark.","vi":"Nhiều cư dân lo lắng về an toàn cá nhân sau khi trời tối."},{"en":"Workers received clear guidelines on personal safety procedures.","vi":"Người lao động nhận được hướng dẫn rõ ràng về các quy trình an toàn cá nhân."}]', '[]', NULL, '/ˈpɜːrsənəl ˈseɪfti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 91, 'personal space', 'không gian riêng tư', 'adj + n', '[{"en":"Crowded trains can make passengers feel they lack personal space.","vi":"Tàu đông đúc có thể khiến hành khách cảm thấy thiếu không gian riêng tư."},{"en":"Notions of personal space vary widely across different cultures.","vi":"Quan niệm về không gian riêng tư khác nhau rất nhiều giữa các nền văn hóa."},{"en":"Respecting personal space is important during one-on-one interviews.","vi":"Tôn trọng không gian riêng tư là điều quan trọng trong các cuộc phỏng vấn riêng."}]', '[]', NULL, '/ˈpɜːrsənəl speɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 92, 'physical activity', 'hoạt động thể chất', 'adj + n', '[{"en":"Regular physical activity lowers the risk of heart disease.","vi":"Hoạt động thể chất đều đặn làm giảm nguy cơ mắc bệnh tim."},{"en":"The study linked daily physical activity to better mood.","vi":"Nghiên cứu liên hệ hoạt động thể chất hằng ngày với tâm trạng tốt hơn."},{"en":"Schools should provide more time for physical activity.","vi":"Các trường học nên dành nhiều thời gian hơn cho hoạt động thể chất."}]', '[]', NULL, '/ˈfɪzɪkəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 93, 'physical appearance', 'ngoại hình', 'adj + n', '[{"en":"First impressions often rely too heavily on physical appearance.","vi":"Ấn tượng đầu tiên thường phụ thuộc quá nhiều vào ngoại hình."},{"en":"The study examined how physical appearance affects hiring decisions.","vi":"Nghiên cứu xem xét ngoại hình ảnh hưởng thế nào đến quyết định tuyển dụng."},{"en":"Media pressure about physical appearance can harm young people.","vi":"Áp lực từ truyền thông về ngoại hình có thể gây hại cho người trẻ."}]', '[]', NULL, '/ˈfɪzɪkəl əˈpɪrəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 94, 'physical characteristics', 'đặc điểm thể chất', 'adj + n', '[{"en":"Scientists recorded the physical characteristics of each specimen.","vi":"Các nhà khoa học đã ghi lại đặc điểm thể chất của từng mẫu vật."},{"en":"Soil''s physical characteristics affect how well crops grow.","vi":"Đặc điểm thể chất của đất ảnh hưởng đến mức độ phát triển của cây trồng."},{"en":"The two species differ in several key physical characteristics.","vi":"Hai loài khác nhau ở một vài đặc điểm thể chất quan trọng."}]', '[]', NULL, '/ˈfɪzɪkəl ˌkærəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 95, 'physical contact', 'tiếp xúc cơ thể', 'adj + n', '[{"en":"Some sports involve frequent physical contact between players.","vi":"Một số môn thể thao có nhiều tiếp xúc cơ thể giữa các cầu thủ."},{"en":"Norms about physical contact differ greatly across cultures.","vi":"Các chuẩn mực về tiếp xúc cơ thể khác nhau rất nhiều giữa các nền văn hóa."},{"en":"The disease spreads mainly through direct physical contact.","vi":"Căn bệnh lây lan chủ yếu qua tiếp xúc cơ thể trực tiếp."}]', '[]', NULL, '/ˈfɪzɪkəl ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 96, 'physical development', 'sự phát triển thể chất', 'adj + n', '[{"en":"Good nutrition supports healthy physical development in children.","vi":"Dinh dưỡng tốt hỗ trợ sự phát triển thể chất khỏe mạnh ở trẻ em."},{"en":"The study tracked physical development from birth to adolescence.","vi":"Nghiên cứu theo dõi sự phát triển thể chất từ khi sinh đến tuổi thiếu niên."},{"en":"Play is essential for both physical and cognitive development.","vi":"Vui chơi là thiết yếu cho cả sự phát triển thể chất lẫn nhận thức."}]', '[]', NULL, '/ˈfɪzɪkəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 97, 'physical environment', 'môi trường vật chất', 'adj + n', '[{"en":"The physical environment of a classroom can affect concentration.","vi":"Môi trường vật chất của lớp học có thể ảnh hưởng đến sự tập trung."},{"en":"Urban planning shapes the physical environment we live in.","vi":"Quy hoạch đô thị định hình môi trường vật chất mà chúng ta sống trong đó."},{"en":"Animals adapt their behavior to the surrounding physical environment.","vi":"Động vật thích nghi hành vi với môi trường vật chất xung quanh."}]', '[]', NULL, '/ˈfɪzɪkəl ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 98, 'physical features', 'đặc trưng vật lý', 'adj + n', '[{"en":"The map highlights the main physical features of the landscape.","vi":"Bản đồ làm nổi bật các đặc trưng vật lý chính của cảnh quan."},{"en":"Geographers study the physical features that shape river systems.","vi":"Các nhà địa lý nghiên cứu những đặc trưng vật lý định hình hệ thống sông."},{"en":"Distinct physical features make the region easy to identify.","vi":"Những đặc trưng vật lý riêng biệt khiến khu vực dễ nhận ra."}]', '[]', NULL, '/ˈfɪzɪkəl ˈfiːtʃərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 99, 'physical health', 'sức khỏe thể chất', 'adj + n', '[{"en":"Sleep has a strong impact on overall physical health.","vi":"Giấc ngủ có tác động mạnh đến sức khỏe thể chất tổng thể."},{"en":"The program improves both physical health and mental wellbeing.","vi":"Chương trình cải thiện cả sức khỏe thể chất lẫn tinh thần."},{"en":"Poor diet over time damages long-term physical health.","vi":"Chế độ ăn kém theo thời gian gây hại cho sức khỏe thể chất lâu dài."}]', '[]', NULL, '/ˈfɪzɪkəl helθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 100, 'physical needs', 'nhu cầu thể chất', 'adj + n', '[{"en":"Good care addresses both the physical needs and emotional needs.","vi":"Sự chăm sóc tốt đáp ứng cả nhu cầu thể chất lẫn nhu cầu cảm xúc."},{"en":"Infants depend entirely on adults to meet their physical needs.","vi":"Trẻ sơ sinh hoàn toàn phụ thuộc vào người lớn để đáp ứng nhu cầu thể chất."},{"en":"Shelter design must consider the physical needs of residents.","vi":"Thiết kế nơi trú ẩn phải xem xét nhu cầu thể chất của cư dân."}]', '[]', NULL, '/ˈfɪzɪkəl niːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 101, 'physical presence', 'sự hiện diện trực tiếp', 'adj + n', '[{"en":"The teacher''s physical presence helped keep students focused.","vi":"Sự hiện diện trực tiếp của giáo viên giúp học sinh tập trung."},{"en":"Remote work reduces the need for physical presence in offices.","vi":"Làm việc từ xa giảm nhu cầu hiện diện trực tiếp tại văn phòng."},{"en":"A strong physical presence can reassure people during emergencies.","vi":"Một sự hiện diện trực tiếp mạnh mẽ có thể trấn an mọi người khi khẩn cấp."}]', '[]', NULL, '/ˈfɪzɪkəl ˈprezəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 102, 'physical properties', 'tính chất vật lý', 'adj + n', '[{"en":"The experiment measured the physical properties of the new material.","vi":"Thí nghiệm đo lường tính chất vật lý của vật liệu mới."},{"en":"Temperature changes alter the physical properties of metals.","vi":"Sự thay đổi nhiệt độ làm thay đổi tính chất vật lý của kim loại."},{"en":"Engineers test physical properties before approving any design.","vi":"Các kỹ sư kiểm tra tính chất vật lý trước khi phê duyệt bất kỳ thiết kế nào."}]', '[]', NULL, '/ˈfɪzɪkəl ˈprɑːpərtiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 103, 'physical proximity', 'khoảng cách gần về vật lý', 'adj + n', '[{"en":"Physical proximity often increases the chance of friendship forming.","vi":"Khoảng cách gần về vật lý thường làm tăng khả năng hình thành tình bạn."},{"en":"The study found physical proximity boosted team collaboration.","vi":"Nghiên cứu phát hiện khoảng cách gần về vật lý thúc đẩy hợp tác nhóm."},{"en":"Online tools reduce the importance of physical proximity at work.","vi":"Công cụ trực tuyến làm giảm tầm quan trọng của khoảng cách gần về vật lý trong công việc."}]', '[]', NULL, '/ˈfɪzɪkəl prɑːkˈsɪməti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 104, 'physical science', 'khoa học tự nhiên', 'adj + n', '[{"en":"She specialized in physical science before turning to engineering.","vi":"Cô chuyên về khoa học tự nhiên trước khi chuyển sang kỹ thuật."},{"en":"The curriculum balances physical science with social studies.","vi":"Chương trình học cân bằng giữa khoa học tự nhiên và khoa học xã hội."},{"en":"Advances in physical science have transformed modern medicine.","vi":"Những tiến bộ trong khoa học tự nhiên đã biến đổi y học hiện đại."}]', '[]', NULL, '/ˈfɪzɪkəl ˈsaɪəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 105, 'physical space', 'không gian vật lý', 'adj + n', '[{"en":"The library lacks enough physical space for group study.","vi":"Thư viện thiếu không gian vật lý đủ cho việc học nhóm."},{"en":"Digital archives store records without taking up physical space.","vi":"Kho lưu trữ số lưu giữ hồ sơ mà không chiếm không gian vật lý."},{"en":"The design maximizes physical space in small apartments.","vi":"Thiết kế tận dụng tối đa không gian vật lý trong các căn hộ nhỏ."}]', '[]', NULL, '/ˈfɪzɪkəl speɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 106, 'physical symptom', 'triệu chứng thể chất', 'adj + n', '[{"en":"Anxiety can produce a physical symptom such as a racing heart.","vi":"Lo âu có thể gây ra triệu chứng thể chất như tim đập nhanh."},{"en":"Doctors look for any physical symptom that signals infection.","vi":"Bác sĩ tìm kiếm bất kỳ triệu chứng thể chất nào báo hiệu nhiễm trùng."},{"en":"Stress often shows up first as a physical symptom.","vi":"Căng thẳng thường biểu hiện đầu tiên dưới dạng một triệu chứng thể chất."}]', '[]', NULL, '/ˈfɪzɪkəl ˈsɪmptəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 107, 'physical world', 'thế giới vật chất', 'adj + n', '[{"en":"Science seeks to explain how the physical world works.","vi":"Khoa học tìm cách giải thích cách thế giới vật chất vận hành."},{"en":"Virtual reality blurs the line with the physical world.","vi":"Thực tế ảo làm mờ ranh giới với thế giới vật chất."},{"en":"Children learn about the physical world through play and exploration.","vi":"Trẻ em học về thế giới vật chất thông qua vui chơi và khám phá."}]', '[]', NULL, '/ˈfɪzɪkəl wɜːrld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 108, 'pilot study', 'nghiên cứu thí điểm', 'n + n', '[{"en":"A pilot study tested the survey before the full rollout.","vi":"Một nghiên cứu thí điểm đã kiểm tra bảng khảo sát trước khi triển khai đầy đủ."},{"en":"Results from the pilot study guided the final research design.","vi":"Kết quả từ nghiên cứu thí điểm đã định hướng thiết kế nghiên cứu cuối cùng."},{"en":"The pilot study involved only thirty volunteers.","vi":"Nghiên cứu thí điểm chỉ có ba mươi tình nguyện viên tham gia."}]', '[]', NULL, '/ˈpaɪlət ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 109, 'pioneering work', 'công trình tiên phong', 'adj + n', '[{"en":"Her pioneering work transformed how we understand genetics.","vi":"Công trình tiên phong của bà đã thay đổi cách chúng ta hiểu về di truyền."},{"en":"The award honored decades of pioneering work in robotics.","vi":"Giải thưởng vinh danh nhiều thập kỷ công trình tiên phong trong lĩnh vực robot."},{"en":"Pioneering work in this field often goes unrecognized for years.","vi":"Công trình tiên phong trong lĩnh vực này thường không được công nhận trong nhiều năm."}]', '[]', NULL, '/ˌpaɪəˈnɪrɪŋ wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 110, 'pivotal role', 'vai trò then chốt', 'adj + n', '[{"en":"Education plays a pivotal role in reducing inequality.","vi":"Giáo dục đóng vai trò then chốt trong việc giảm bất bình đẳng."},{"en":"She played a pivotal role in negotiating the agreement.","vi":"Cô đã đóng vai trò then chốt trong việc đàm phán thỏa thuận."},{"en":"Technology has a pivotal role in modern healthcare delivery.","vi":"Công nghệ giữ vai trò then chốt trong việc cung cấp dịch vụ y tế hiện đại."}]', '[]', NULL, '/ˈpɪvətəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 111, 'place emphasis', 'đặt sự nhấn mạnh', 'v + n', '[{"en":"The course places emphasis on practical skills over theory.","vi":"Khóa học đặt sự nhấn mạnh vào kỹ năng thực hành hơn là lý thuyết."},{"en":"Researchers place emphasis on reproducible and transparent methods.","vi":"Các nhà nghiên cứu đặt sự nhấn mạnh vào phương pháp minh bạch và có thể tái lập."},{"en":"The report places emphasis on the needs of rural communities.","vi":"Báo cáo đặt sự nhấn mạnh vào nhu cầu của các cộng đồng nông thôn."}]', '[]', NULL, '/pleɪs ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 112, 'planning stage', 'giai đoạn lập kế hoạch', 'n + n', '[{"en":"The project is still in its early planning stage.","vi":"Dự án vẫn còn trong giai đoạn lập kế hoạch ban đầu."},{"en":"Stakeholders were consulted during the planning stage of the program.","vi":"Các bên liên quan được tham vấn trong giai đoạn lập kế hoạch của chương trình."},{"en":"Many problems can be avoided at the planning stage.","vi":"Nhiều vấn đề có thể được tránh ngay từ giai đoạn lập kế hoạch."}]', '[]', NULL, '/ˈplænɪŋ steɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 113, 'plausible explanation', 'lời giải thích hợp lý', 'adj + n', '[{"en":"The theory offers a plausible explanation for the unusual results.","vi":"Lý thuyết đưa ra một lời giải thích hợp lý cho những kết quả bất thường."},{"en":"No plausible explanation has yet been found for the anomaly.","vi":"Vẫn chưa tìm ra lời giải thích hợp lý nào cho điều bất thường này."},{"en":"A plausible explanation must fit all the available evidence.","vi":"Một lời giải thích hợp lý phải phù hợp với mọi bằng chứng hiện có."}]', '[]', NULL, '/ˈplɔːzəbəl ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 114, 'play a role in', 'đóng vai trò trong', 'v + n', '[{"en":"Genes play a role in determining a person''s risk of disease.","vi":"Gen đóng vai trò trong việc xác định nguy cơ mắc bệnh của một người."},{"en":"Social media plays a role in shaping public opinion today.","vi":"Mạng xã hội đóng vai trò trong việc định hình dư luận ngày nay."},{"en":"Climate change plays a role in the spread of certain diseases.","vi":"Biến đổi khí hậu đóng vai trò trong sự lan rộng của một số bệnh."}]', '[]', NULL, '/pleɪ ə roʊl ɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 115, 'political activism', 'hoạt động chính trị tích cực', 'adj + n', '[{"en":"Student political activism grew sharply during the 1960s.","vi":"Hoạt động chính trị tích cực của sinh viên tăng mạnh trong những năm 1960."},{"en":"Online platforms have changed the nature of political activism.","vi":"Các nền tảng trực tuyến đã thay đổi bản chất của hoạt động chính trị tích cực."},{"en":"Her political activism focused on environmental justice.","vi":"Hoạt động chính trị tích cực của bà tập trung vào công lý môi trường."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈæktɪvɪzəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 116, 'political activity', 'hoạt động chính trị', 'adj + n', '[{"en":"The law restricts political activity by certain public officials.","vi":"Luật hạn chế hoạt động chính trị của một số quan chức nhà nước."},{"en":"Voter turnout is one measure of political activity.","vi":"Tỷ lệ cử tri đi bầu là một thước đo của hoạt động chính trị."},{"en":"Economic hardship often increases political activity among citizens.","vi":"Khó khăn kinh tế thường làm gia tăng hoạt động chính trị trong dân chúng."}]', '[]', NULL, '/pəˈlɪtɪkəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 117, 'political agenda', 'chương trình nghị sự chính trị', 'adj + n', '[{"en":"Education reform sits high on the government''s political agenda.","vi":"Cải cách giáo dục nằm ở vị trí cao trong chương trình nghị sự chính trị của chính phủ."},{"en":"Critics argued the report served a hidden political agenda.","vi":"Các nhà phê bình cho rằng báo cáo phục vụ một chương trình nghị sự chính trị ẩn giấu."},{"en":"Each party tried to set the national political agenda.","vi":"Mỗi đảng đều cố gắng định hình chương trình nghị sự chính trị quốc gia."}]', '[]', NULL, '/pəˈlɪtɪkəl əˈdʒendə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 118, 'political arena', 'vũ đài chính trị', 'adj + n', '[{"en":"She entered the political arena after a long legal career.","vi":"Bà bước vào vũ đài chính trị sau một sự nghiệp pháp lý dài."},{"en":"Women remain underrepresented in the political arena.","vi":"Phụ nữ vẫn còn ít được đại diện trên vũ đài chính trị."},{"en":"The scandal reshaped the entire political arena overnight.","vi":"Vụ bê bối đã định hình lại toàn bộ vũ đài chính trị chỉ sau một đêm."}]', '[]', NULL, '/pəˈlɪtɪkəl əˈriːnə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 119, 'political authority', 'quyền lực chính trị', 'adj + n', '[{"en":"The constitution defines the limits of political authority.","vi":"Hiến pháp xác định giới hạn của quyền lực chính trị."},{"en":"Local councils were granted greater political authority.","vi":"Các hội đồng địa phương được trao quyền lực chính trị lớn hơn."},{"en":"Religious leaders once held significant political authority.","vi":"Các lãnh đạo tôn giáo từng nắm giữ quyền lực chính trị đáng kể."}]', '[]', NULL, '/pəˈlɪtɪkəl əˈθɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 120, 'political circumstances', 'hoàn cảnh chính trị', 'adj + n', '[{"en":"The reform succeeded due to favorable political circumstances.","vi":"Cuộc cải cách thành công nhờ hoàn cảnh chính trị thuận lợi."},{"en":"Changing political circumstances forced the policy to be revised.","vi":"Hoàn cảnh chính trị thay đổi buộc chính sách phải được sửa đổi."},{"en":"Historians stress the political circumstances of the era.","vi":"Các nhà sử học nhấn mạnh hoàn cảnh chính trị của thời đại đó."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈsɜːrkəmstænsəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 121, 'political climate', 'bầu không khí chính trị', 'adj + n', '[{"en":"The tense political climate discouraged open public debate.","vi":"Bầu không khí chính trị căng thẳng đã cản trở tranh luận công khai."},{"en":"Investors are wary because of the uncertain political climate.","vi":"Các nhà đầu tư thận trọng vì bầu không khí chính trị bất ổn."},{"en":"The reform reflects the changing political climate of the decade.","vi":"Cuộc cải cách phản ánh bầu không khí chính trị đang thay đổi của thập kỷ."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈklaɪmət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 122, 'political conflict', 'xung đột chính trị', 'adj + n', '[{"en":"Years of political conflict left the country deeply divided.","vi":"Nhiều năm xung đột chính trị đã khiến đất nước bị chia rẽ sâu sắc."},{"en":"The treaty aimed to resolve longstanding political conflict.","vi":"Hiệp ước nhằm giải quyết xung đột chính trị kéo dài."},{"en":"Economic inequality often fuels political conflict.","vi":"Bất bình đẳng kinh tế thường thổi bùng xung đột chính trị."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 123, 'political consciousness', 'ý thức chính trị', 'adj + n', '[{"en":"The movement raised the political consciousness of young voters.","vi":"Phong trào đã nâng cao ý thức chính trị của các cử tri trẻ."},{"en":"Education can deepen a citizen''s political consciousness.","vi":"Giáo dục có thể làm sâu sắc thêm ý thức chính trị của công dân."},{"en":"Rising political consciousness fueled demands for reform.","vi":"Ý thức chính trị gia tăng đã thúc đẩy các đòi hỏi cải cách."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈkɑːnʃəsnəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 124, 'political consensus', 'sự đồng thuận chính trị', 'adj + n', '[{"en":"Reaching a political consensus on the budget proved difficult.","vi":"Đạt được sự đồng thuận chính trị về ngân sách tỏ ra khó khăn."},{"en":"There is broad political consensus that healthcare needs reform.","vi":"Có sự đồng thuận chính trị rộng rãi rằng y tế cần được cải cách."},{"en":"The fragile political consensus collapsed within months.","vi":"Sự đồng thuận chính trị mong manh đã sụp đổ chỉ trong vài tháng."}]', '[]', NULL, '/pəˈlɪtɪkəl kənˈsensəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 125, 'political consequences', 'hệ quả chính trị', 'adj + n', '[{"en":"The decision had serious political consequences for the leadership.","vi":"Quyết định này gây ra những hệ quả chính trị nghiêm trọng cho ban lãnh đạo."},{"en":"Economic crises often carry far-reaching political consequences.","vi":"Khủng hoảng kinh tế thường kéo theo những hệ quả chính trị sâu rộng."},{"en":"Analysts warned about the political consequences of inaction.","vi":"Các nhà phân tích cảnh báo về hệ quả chính trị của việc không hành động."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈkɑːnsəkwensəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 126, 'political consideration', 'yếu tố cân nhắc chính trị', 'adj + n', '[{"en":"Political considerations often shape how budgets are allocated.","vi":"Các yếu tố cân nhắc chính trị thường định hình cách phân bổ ngân sách."},{"en":"The minister insisted no political consideration influenced the ruling.","vi":"Bộ trưởng khẳng định không có yếu tố cân nhắc chính trị nào ảnh hưởng đến phán quyết."},{"en":"Scientific advice should outweigh short-term political considerations.","vi":"Lời khuyên khoa học nên được coi trọng hơn các yếu tố cân nhắc chính trị ngắn hạn."}]', '[]', NULL, '/pəˈlɪtɪkəl kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 127, 'political context', 'bối cảnh chính trị', 'adj + n', '[{"en":"The novel can only be understood in its political context.","vi":"Cuốn tiểu thuyết chỉ có thể được hiểu trong bối cảnh chính trị của nó."},{"en":"Researchers examined the policy within its broader political context.","vi":"Các nhà nghiên cứu xem xét chính sách trong bối cảnh chính trị rộng hơn."},{"en":"The political context of the war shaped its outcome.","vi":"Bối cảnh chính trị của cuộc chiến đã định hình kết cục của nó."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 128, 'political culture', 'văn hóa chính trị', 'adj + n', '[{"en":"A nation''s political culture shapes how citizens engage with power.","vi":"Văn hóa chính trị của một quốc gia định hình cách công dân tham gia vào quyền lực."},{"en":"The book compares political culture across several democracies.","vi":"Cuốn sách so sánh văn hóa chính trị giữa nhiều nền dân chủ."},{"en":"Distrust of authority is rooted in the local political culture.","vi":"Sự ngờ vực chính quyền bắt nguồn từ văn hóa chính trị địa phương."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 129, 'political debate', 'tranh luận chính trị', 'adj + n', '[{"en":"Immigration remains at the center of political debate.","vi":"Vấn đề nhập cư vẫn là trung tâm của tranh luận chính trị."},{"en":"The reform sparked intense political debate across the country.","vi":"Cuộc cải cách đã châm ngòi cho tranh luận chính trị gay gắt trên cả nước."},{"en":"Television transformed the style of modern political debate.","vi":"Truyền hình đã biến đổi phong cách của tranh luận chính trị hiện đại."}]', '[]', NULL, '/pəˈlɪtɪkəl dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 130, 'political dimension', 'khía cạnh chính trị', 'adj + n', '[{"en":"The crisis has an economic and a political dimension.","vi":"Cuộc khủng hoảng có cả khía cạnh kinh tế lẫn khía cạnh chính trị."},{"en":"Scholars often overlook the political dimension of religious change.","vi":"Các học giả thường bỏ qua khía cạnh chính trị của sự thay đổi tôn giáo."},{"en":"Every major reform carries a political dimension.","vi":"Mọi cuộc cải cách lớn đều mang một khía cạnh chính trị."}]', '[]', NULL, '/pəˈlɪtɪkəl dɪˈmenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 131, 'political economy', 'kinh tế chính trị', 'adj + n', '[{"en":"The course introduces the basics of political economy.","vi":"Khóa học giới thiệu những kiến thức cơ bản về kinh tế chính trị."},{"en":"Her thesis analyzed the political economy of global trade.","vi":"Luận án của cô phân tích kinh tế chính trị của thương mại toàn cầu."},{"en":"Political economy examines how power and markets interact.","vi":"Kinh tế chính trị nghiên cứu cách quyền lực và thị trường tương tác."}]', '[]', NULL, '/pəˈlɪtɪkəl ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 132, 'political environment', 'môi trường chính trị', 'adj + n', '[{"en":"A stable political environment encourages foreign investment.","vi":"Một môi trường chính trị ổn định khuyến khích đầu tư nước ngoài."},{"en":"The reforms reshaped the country''s political environment.","vi":"Các cuộc cải cách đã định hình lại môi trường chính trị của đất nước."},{"en":"Businesses must adapt to a shifting political environment.","vi":"Các doanh nghiệp phải thích nghi với môi trường chính trị đang thay đổi."}]', '[]', NULL, '/pəˈlɪtɪkəl ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 133, 'political factors', 'các yếu tố chính trị', 'adj + n', '[{"en":"Political factors strongly influenced where the funds were spent.","vi":"Các yếu tố chính trị đã ảnh hưởng mạnh đến nơi nguồn quỹ được chi tiêu."},{"en":"The analysis weighed economic and political factors together.","vi":"Bản phân tích cân nhắc cùng lúc các yếu tố kinh tế và chính trị."},{"en":"Political factors often delay important infrastructure projects.","vi":"Các yếu tố chính trị thường làm chậm trễ các dự án hạ tầng quan trọng."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 134, 'political identity', 'bản sắc chính trị', 'adj + n', '[{"en":"Many young people form their political identity at university.","vi":"Nhiều người trẻ hình thành bản sắc chính trị của mình ở đại học."},{"en":"Region and religion both shape political identity here.","vi":"Cả vùng miền lẫn tôn giáo đều định hình bản sắc chính trị ở đây."},{"en":"The study explored how migration affects political identity.","vi":"Nghiên cứu khám phá cách di cư ảnh hưởng đến bản sắc chính trị."}]', '[]', NULL, '/pəˈlɪtɪkəl aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 135, 'political ideology', 'hệ tư tưởng chính trị', 'adj + n', '[{"en":"His political ideology shifted noticeably over the decades.","vi":"Hệ tư tưởng chính trị của ông thay đổi rõ rệt qua nhiều thập kỷ."},{"en":"The party''s political ideology centers on individual freedom.","vi":"Hệ tư tưởng chính trị của đảng xoay quanh tự do cá nhân."},{"en":"Media can reinforce a particular political ideology.","vi":"Truyền thông có thể củng cố một hệ tư tưởng chính trị nhất định."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌaɪdiˈɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 136, 'political implications', 'hàm ý chính trị', 'adj + n', '[{"en":"The discovery has significant political implications for the region.","vi":"Phát hiện này có những hàm ý chính trị quan trọng đối với khu vực."},{"en":"Researchers rarely discuss the political implications of their findings.","vi":"Các nhà nghiên cứu hiếm khi bàn về hàm ý chính trị trong phát hiện của họ."},{"en":"The ruling carries political implications well beyond the courtroom.","vi":"Phán quyết này mang hàm ý chính trị vượt xa khỏi phòng xử án."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌɪmplɪˈkeɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 137, 'political instability', 'bất ổn chính trị', 'adj + n', '[{"en":"Years of political instability damaged the national economy.","vi":"Nhiều năm bất ổn chính trị đã gây thiệt hại cho nền kinh tế quốc gia."},{"en":"Political instability can quickly drive away foreign investors.","vi":"Bất ổn chính trị có thể nhanh chóng khiến nhà đầu tư nước ngoài rút lui."},{"en":"The region suffers from ongoing political instability.","vi":"Khu vực này chịu đựng tình trạng bất ổn chính trị kéo dài."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌɪnstəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 138, 'political institution', 'thể chế chính trị', 'adj + n', '[{"en":"Strong political institutions help protect citizens'' rights.","vi":"Các thể chế chính trị vững mạnh giúp bảo vệ quyền của công dân."},{"en":"The reform aimed to modernize outdated political institutions.","vi":"Cuộc cải cách nhằm hiện đại hóa các thể chế chính trị lỗi thời."},{"en":"Trust in political institutions has declined in recent years.","vi":"Niềm tin vào các thể chế chính trị đã suy giảm trong những năm gần đây."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 139, 'political leader', 'lãnh đạo chính trị', 'adj + n', '[{"en":"A respected political leader can unite a divided nation.","vi":"Một nhà lãnh đạo chính trị được tôn trọng có thể đoàn kết một quốc gia chia rẽ."},{"en":"Several political leaders attended the international summit.","vi":"Một số lãnh đạo chính trị đã tham dự hội nghị thượng đỉnh quốc tế."},{"en":"The political leader faced criticism over the new tax plan.","vi":"Nhà lãnh đạo chính trị đối mặt với chỉ trích về kế hoạch thuế mới."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈliːdər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 140, 'political mobilization', 'sự huy động chính trị', 'adj + n', '[{"en":"Social media has accelerated political mobilization among youth.","vi":"Mạng xã hội đã thúc đẩy sự huy động chính trị trong giới trẻ."},{"en":"The strike was the result of sustained political mobilization.","vi":"Cuộc đình công là kết quả của sự huy động chính trị bền bỉ."},{"en":"Effective political mobilization requires both organization and trust.","vi":"Sự huy động chính trị hiệu quả đòi hỏi cả tổ chức lẫn niềm tin."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌmoʊbələˈzeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 141, 'political movement', 'phong trào chính trị', 'adj + n', '[{"en":"The political movement gained millions of supporters within a year.","vi":"Phong trào chính trị đã giành được hàng triệu người ủng hộ trong một năm."},{"en":"Historians traced the origins of the political movement carefully.","vi":"Các nhà sử học đã lần theo nguồn gốc của phong trào chính trị một cách cẩn thận."},{"en":"The political movement demanded greater rights for workers.","vi":"Phong trào chính trị đòi hỏi quyền lợi nhiều hơn cho người lao động."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 142, 'political organization', 'tổ chức chính trị', 'adj + n', '[{"en":"The political organization campaigned for fairer voting laws.","vi":"Tổ chức chính trị đã vận động cho luật bầu cử công bằng hơn."},{"en":"Several political organizations joined forces during the election.","vi":"Một số tổ chức chính trị đã hợp lực trong cuộc bầu cử."},{"en":"Members built the political organization from the ground up.","vi":"Các thành viên đã xây dựng tổ chức chính trị từ con số không."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌɔːrɡənəˈzeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 143, 'political participation', 'sự tham gia chính trị', 'adj + n', '[{"en":"Lower voting ages may increase youth political participation.","vi":"Hạ tuổi bầu cử có thể làm tăng sự tham gia chính trị của giới trẻ."},{"en":"The study measured political participation across income groups.","vi":"Nghiên cứu đo lường sự tham gia chính trị giữa các nhóm thu nhập."},{"en":"Education tends to boost political participation among citizens.","vi":"Giáo dục có xu hướng thúc đẩy sự tham gia chính trị của công dân."}]', '[]', NULL, '/pəˈlɪtɪkəl pɑːrˌtɪsəˈpeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 144, 'political party', 'đảng phái chính trị', 'adj + n', '[{"en":"A new political party emerged ahead of the general election.","vi":"Một đảng phái chính trị mới xuất hiện trước thềm cuộc tổng tuyển cử."},{"en":"Each political party published a detailed economic manifesto.","vi":"Mỗi đảng phái chính trị công bố một cương lĩnh kinh tế chi tiết."},{"en":"Membership in the political party has grown steadily.","vi":"Số thành viên của đảng phái chính trị này đã tăng đều đặn."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈpɑːrti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 145, 'political philosophy', 'triết học chính trị', 'adj + n', '[{"en":"The lecture introduced students to classical political philosophy.","vi":"Bài giảng giới thiệu cho sinh viên về triết học chính trị cổ điển."},{"en":"His political philosophy drew heavily on Enlightenment thinkers.","vi":"Triết học chính trị của ông chịu ảnh hưởng lớn từ các nhà tư tưởng Khai sáng."},{"en":"Debates in political philosophy still shape modern law.","vi":"Những tranh luận trong triết học chính trị vẫn định hình luật pháp hiện đại."}]', '[]', NULL, '/pəˈlɪtɪkəl fəˈlɑːsəfi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 146, 'political reality', 'thực tế chính trị', 'adj + n', '[{"en":"Ideal policies must adjust to the political reality on the ground.","vi":"Các chính sách lý tưởng phải điều chỉnh theo thực tế chính trị tại chỗ."},{"en":"The political reality made sweeping reform almost impossible.","vi":"Thực tế chính trị khiến cải cách toàn diện gần như bất khả thi."},{"en":"Leaders cannot ignore the harsh political reality they face.","vi":"Các nhà lãnh đạo không thể phớt lờ thực tế chính trị khắc nghiệt họ đối mặt."}]', '[]', NULL, '/pəˈlɪtɪkəl riˈæləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 147, 'political reform', 'cải cách chính trị', 'adj + n', '[{"en":"Public pressure finally led to genuine political reform.","vi":"Áp lực từ công chúng cuối cùng đã dẫn đến cải cách chính trị thực sự."},{"en":"The movement demanded sweeping political reform and accountability.","vi":"Phong trào đòi hỏi cải cách chính trị toàn diện và trách nhiệm giải trình."},{"en":"Political reform often happens slowly and unevenly.","vi":"Cải cách chính trị thường diễn ra chậm chạp và không đồng đều."}]', '[]', NULL, '/pəˈlɪtɪkəl rɪˈfɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 148, 'political representation', 'sự đại diện chính trị', 'adj + n', '[{"en":"Minorities have long fought for fair political representation.","vi":"Các nhóm thiểu số từ lâu đã đấu tranh cho sự đại diện chính trị công bằng."},{"en":"Quotas were introduced to improve women''s political representation.","vi":"Hạn ngạch được áp dụng để cải thiện sự đại diện chính trị của phụ nữ."},{"en":"Rural areas often lack adequate political representation.","vi":"Các vùng nông thôn thường thiếu sự đại diện chính trị đầy đủ."}]', '[]', NULL, '/pəˈlɪtɪkəl ˌreprɪzenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 149, 'political significance', 'tầm quan trọng về chính trị', 'adj + n', '[{"en":"The treaty had enormous political significance for the region.","vi":"Hiệp ước có ý nghĩa chính trị to lớn đối với khu vực."},{"en":"Historians still debate the political significance of that speech.","vi":"Các nhà sử học vẫn tranh luận về tầm quan trọng chính trị của bài phát biểu đó."},{"en":"Few people grasped the political significance of the new law.","vi":"Ít người hiểu được ý nghĩa chính trị của đạo luật mới."}]', '[]', NULL, '/pəˈlɪtɪkəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-11-01', 150, 'political spectrum', 'phổ chính trị (các khuynh hướng chính trị)', 'adj + n', '[{"en":"Voters across the political spectrum supported the reform.","vi":"Cử tri thuộc mọi khuynh hướng chính trị đều ủng hộ cải cách."},{"en":"Her views sit at the far end of the political spectrum.","vi":"Quan điểm của cô nằm ở cực xa của phổ chính trị."},{"en":"The debate attracted parties from across the political spectrum.","vi":"Cuộc tranh luận thu hút các đảng từ khắp phổ chính trị."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈspektrəm/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-12-01', 'colloc-12', 'Cụm học thuật · Nhóm 12', 'Academic Collocation List (Pearson/PTE) — nhóm 12 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 1, 'political stability', 'sự ổn định về chính trị', 'adj + n', '[{"en":"Foreign investors value the country''s long-term political stability.","vi":"Nhà đầu tư nước ngoài coi trọng sự ổn định chính trị lâu dài của đất nước."},{"en":"Economic growth often depends on political stability.","vi":"Tăng trưởng kinh tế thường phụ thuộc vào sự ổn định chính trị."},{"en":"The coup destroyed decades of hard-won political stability.","vi":"Cuộc đảo chính phá hủy hàng thập kỷ ổn định chính trị khó khăn lắm mới có."}]', '[]', NULL, '/pəˈlɪtɪkəl stəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 2, 'political status', 'địa vị chính trị', 'adj + n', '[{"en":"The region''s political status remains a sensitive issue.","vi":"Địa vị chính trị của khu vực vẫn là vấn đề nhạy cảm."},{"en":"Citizens demanded a change in their political status.","vi":"Người dân đòi thay đổi địa vị chính trị của họ."},{"en":"The treaty clarified the territory''s political status.","vi":"Hiệp ước làm rõ địa vị chính trị của vùng lãnh thổ."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈstætəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 3, 'political structure', 'cơ cấu chính trị', 'adj + n', '[{"en":"The book analyzes the political structure of ancient Rome.","vi":"Cuốn sách phân tích cơ cấu chính trị của La Mã cổ đại."},{"en":"A weak political structure left the nation vulnerable.","vi":"Một cơ cấu chính trị yếu khiến quốc gia dễ bị tổn thương."},{"en":"Reformers tried to redesign the entire political structure.","vi":"Những nhà cải cách cố thiết kế lại toàn bộ cơ cấu chính trị."}]', '[]', NULL, '/pəˈlɪtɪkəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 4, 'politically correct', 'đúng chuẩn mực chính trị xã hội', 'adv + adj', '[{"en":"He chose politically correct language to avoid offending anyone.","vi":"Anh chọn ngôn từ đúng mực để tránh xúc phạm bất kỳ ai."},{"en":"Some critics say the campaign was too politically correct.","vi":"Một số người chỉ trích cho rằng chiến dịch quá khuôn phép về chính trị xã hội."},{"en":"The textbook was revised to be more politically correct.","vi":"Cuốn giáo trình được sửa lại cho đúng chuẩn mực hơn."}]', '[]', NULL, '/pəˈlɪtɪkli kəˈrekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 5, 'politically motivated', 'có động cơ chính trị', 'adv + vpp', '[{"en":"Critics claimed the arrests were politically motivated.","vi":"Những người chỉ trích cho rằng các vụ bắt giữ có động cơ chính trị."},{"en":"The lawsuit looked politically motivated rather than legal.","vi":"Vụ kiện trông có động cơ chính trị hơn là pháp lý."},{"en":"Analysts described the decision as politically motivated.","vi":"Các nhà phân tích mô tả quyết định này là có động cơ chính trị."}]', '[]', NULL, '/pəˈlɪtɪkli ˈmoʊtɪveɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 6, 'poorly understood', 'chưa được hiểu rõ', 'adv + vpp', '[{"en":"The disease remains poorly understood despite years of research.","vi":"Căn bệnh vẫn chưa được hiểu rõ dù đã nghiên cứu nhiều năm."},{"en":"These chemical reactions are still poorly understood.","vi":"Những phản ứng hóa học này vẫn chưa được hiểu rõ."},{"en":"The long-term effects are poorly understood by scientists.","vi":"Các tác động lâu dài vẫn chưa được giới khoa học hiểu rõ."}]', '[]', NULL, '/ˈpʊrli ˌʌndərˈstʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 7, 'popular culture', 'văn hóa đại chúng', 'adj + n', '[{"en":"The film reflects many themes from popular culture.","vi":"Bộ phim phản ánh nhiều chủ đề từ văn hóa đại chúng."},{"en":"Social media has reshaped modern popular culture.","vi":"Mạng xã hội đã định hình lại văn hóa đại chúng hiện đại."},{"en":"The course examines how popular culture influences young people.","vi":"Khóa học xem xét cách văn hóa đại chúng ảnh hưởng giới trẻ."}]', '[]', NULL, '/ˈpɑːpjələr ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 8, 'popular media', 'truyền thông đại chúng', 'adj + n', '[{"en":"Popular media often simplifies complex scientific ideas.","vi":"Truyền thông đại chúng thường đơn giản hóa các ý tưởng khoa học phức tạp."},{"en":"The story spread quickly through popular media.","vi":"Câu chuyện lan nhanh qua truyền thông đại chúng."},{"en":"Popular media shapes how the public sees the issue.","vi":"Truyền thông đại chúng định hình cách công chúng nhìn nhận vấn đề."}]', '[]', NULL, '/ˈpɑːpjələr ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 9, 'pose a challenge', 'đặt ra một thách thức', 'v + n', '[{"en":"Climate change will pose a challenge for future generations.","vi":"Biến đổi khí hậu sẽ đặt ra thách thức cho các thế hệ tương lai."},{"en":"Rapid growth can pose a challenge to small companies.","vi":"Tăng trưởng nhanh có thể đặt ra thách thức cho các công ty nhỏ."},{"en":"New regulations pose a challenge for many manufacturers.","vi":"Các quy định mới đặt ra thách thức cho nhiều nhà sản xuất."}]', '[]', NULL, '/poʊz ə ˈtʃælɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 10, 'pose a problem', 'gây ra một vấn đề', 'v + n', '[{"en":"Heavy traffic poses a problem for emergency services.","vi":"Giao thông đông đúc gây ra vấn đề cho các dịch vụ khẩn cấp."},{"en":"Missing data can pose a problem for the analysis.","vi":"Dữ liệu thiếu có thể gây ra vấn đề cho việc phân tích."},{"en":"Rising costs pose a problem for the whole industry.","vi":"Chi phí tăng gây ra vấn đề cho cả ngành."}]', '[]', NULL, '/poʊz ə ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 11, 'pose a question', 'đặt ra một câu hỏi', 'v + n', '[{"en":"These results pose a question about the original theory.","vi":"Những kết quả này đặt ra câu hỏi về lý thuyết ban đầu."},{"en":"The teacher posed a question that puzzled the students.","vi":"Giáo viên đặt ra một câu hỏi khiến học sinh bối rối."},{"en":"The findings pose a question worth further investigation.","vi":"Phát hiện này đặt ra câu hỏi đáng được nghiên cứu thêm."}]', '[]', NULL, '/poʊz ə ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 12, 'pose a threat to', 'đặt ra mối đe dọa đối với', 'v + n', '[{"en":"Pollution can pose a threat to public health.","vi":"Ô nhiễm có thể đặt ra mối đe dọa đối với sức khỏe cộng đồng."},{"en":"Invasive species pose a threat to local ecosystems.","vi":"Các loài xâm lấn đặt ra mối đe dọa đối với hệ sinh thái địa phương."},{"en":"Cyberattacks pose a threat to national security.","vi":"Các cuộc tấn công mạng đặt ra mối đe dọa đối với an ninh quốc gia."}]', '[]', NULL, '/poʊz ə θret tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 13, 'positive action', 'hành động tích cực', 'adj + n', '[{"en":"The government took positive action to reduce unemployment.","vi":"Chính phủ đã có hành động tích cực để giảm thất nghiệp."},{"en":"Positive action is needed to protect endangered species.","vi":"Cần có hành động tích cực để bảo vệ các loài nguy cấp."},{"en":"The campaign encouraged positive action on recycling.","vi":"Chiến dịch khuyến khích hành động tích cực về tái chế."}]', '[]', NULL, '/ˈpɑːzətɪv ˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 14, 'positive aspect', 'khía cạnh tích cực', 'adj + n', '[{"en":"The report highlights the positive aspect of remote work.","vi":"Báo cáo nhấn mạnh khía cạnh tích cực của làm việc từ xa."},{"en":"One positive aspect of the change was lower costs.","vi":"Một khía cạnh tích cực của sự thay đổi là chi phí thấp hơn."},{"en":"Students discussed the positive aspect of online learning.","vi":"Học sinh thảo luận về khía cạnh tích cực của học trực tuyến."}]', '[]', NULL, '/ˈpɑːzətɪv ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 15, 'positive attitude', 'thái độ tích cực', 'adj + n', '[{"en":"A positive attitude helps students cope with difficult exams.","vi":"Thái độ tích cực giúp học sinh đối phó với các kỳ thi khó."},{"en":"Employers value a positive attitude toward teamwork.","vi":"Nhà tuyển dụng coi trọng thái độ tích cực với làm việc nhóm."},{"en":"She kept a positive attitude despite many setbacks.","vi":"Cô giữ thái độ tích cực dù gặp nhiều trở ngại."}]', '[]', NULL, '/ˈpɑːzətɪv ˈætɪtuːd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 16, 'positive connotation', 'hàm ý tích cực', 'adj + n', '[{"en":"The word carries a strong positive connotation in English.","vi":"Từ này mang một hàm ý tích cực mạnh trong tiếng Anh."},{"en":"Marketers prefer terms with a positive connotation.","vi":"Người làm tiếp thị thích các từ có hàm ý tích cực."},{"en":"Unlike its synonym, this word has a positive connotation.","vi":"Khác với từ đồng nghĩa, từ này có hàm ý tích cực."}]', '[]', NULL, '/ˈpɑːzətɪv ˌkɑːnəˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 17, 'positive correlation', 'mối tương quan thuận', 'adj + n', '[{"en":"The study found a positive correlation between exercise and mood.","vi":"Nghiên cứu tìm thấy mối tương quan thuận giữa tập luyện và tâm trạng."},{"en":"There is a positive correlation between income and education.","vi":"Có một mối tương quan thuận giữa thu nhập và trình độ học vấn."},{"en":"Researchers reported a positive correlation in the data.","vi":"Các nhà nghiên cứu báo cáo một mối tương quan thuận trong dữ liệu."}]', '[]', NULL, '/ˈpɑːzətɪv ˌkɔːrəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 18, 'positive discrimination', 'phân biệt đối xử tích cực (ưu tiên nhóm yếu thế)', 'adj + n', '[{"en":"Some universities use positive discrimination to widen access.","vi":"Một số trường đại học dùng ưu tiên tích cực để mở rộng cơ hội."},{"en":"Positive discrimination remains a controversial policy choice.","vi":"Phân biệt đối xử tích cực vẫn là một lựa chọn chính sách gây tranh cãi."},{"en":"Critics argue positive discrimination can create new inequalities.","vi":"Người chỉ trích cho rằng ưu tiên tích cực có thể tạo bất bình đẳng mới."}]', '[]', NULL, '/ˈpɑːzətɪv dɪˌskrɪmɪˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 19, 'positive effect', 'tác động tích cực', 'adj + n', '[{"en":"Regular sleep has a positive effect on memory.","vi":"Ngủ đều đặn có tác động tích cực đến trí nhớ."},{"en":"The new policy had a positive effect on attendance.","vi":"Chính sách mới có tác động tích cực đến tỷ lệ đi học."},{"en":"Reading widely has a positive effect on writing skills.","vi":"Đọc nhiều có tác động tích cực đến kỹ năng viết."}]', '[]', NULL, '/ˈpɑːzətɪv ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 20, 'positive feature', 'đặc điểm tích cực', 'adj + n', '[{"en":"A positive feature of the design is its simplicity.","vi":"Một đặc điểm tích cực của thiết kế là sự đơn giản."},{"en":"The most positive feature of the app is its speed.","vi":"Đặc điểm tích cực nhất của ứng dụng là tốc độ."},{"en":"Flexibility is a positive feature of the new system.","vi":"Tính linh hoạt là một đặc điểm tích cực của hệ thống mới."}]', '[]', NULL, '/ˈpɑːzətɪv ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 21, 'positive feedback', 'phản hồi tích cực', 'adj + n', '[{"en":"The teacher gave positive feedback on the student''s essay.","vi":"Giáo viên đưa ra phản hồi tích cực về bài luận của học sinh."},{"en":"Customers left positive feedback about the service.","vi":"Khách hàng để lại phản hồi tích cực về dịch vụ."},{"en":"Positive feedback encourages learners to keep practicing.","vi":"Phản hồi tích cực khuyến khích người học tiếp tục luyện tập."}]', '[]', NULL, '/ˈpɑːzətɪv ˈfiːdbæk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 22, 'positive image', 'hình ảnh tích cực', 'adj + n', '[{"en":"The company worked hard to build a positive image.","vi":"Công ty nỗ lực xây dựng một hình ảnh tích cực."},{"en":"Advertising aims to create a positive image of the brand.","vi":"Quảng cáo nhằm tạo một hình ảnh tích cực về thương hiệu."},{"en":"The city promotes a positive image to attract tourists.","vi":"Thành phố quảng bá một hình ảnh tích cực để thu hút du khách."}]', '[]', NULL, '/ˈpɑːzətɪv ˈɪmɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 23, 'positive impact', 'ảnh hưởng tích cực', 'adj + n', '[{"en":"Volunteering can have a positive impact on the community.","vi":"Tình nguyện có thể có ảnh hưởng tích cực đến cộng đồng."},{"en":"The program had a positive impact on student grades.","vi":"Chương trình có ảnh hưởng tích cực đến điểm số của học sinh."},{"en":"Clean energy has a positive impact on the environment.","vi":"Năng lượng sạch có ảnh hưởng tích cực đến môi trường."}]', '[]', NULL, '/ˈpɑːzətɪv ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 24, 'positive influence', 'ảnh hưởng tích cực (sự tác động tốt)', 'adj + n', '[{"en":"A good mentor can be a positive influence on young people.","vi":"Một người cố vấn tốt có thể là ảnh hưởng tích cực với giới trẻ."},{"en":"Her teacher had a lasting positive influence on her career.","vi":"Giáo viên của cô có ảnh hưởng tích cực lâu dài đến sự nghiệp."},{"en":"Reading widely had a positive influence on his thinking.","vi":"Đọc nhiều có ảnh hưởng tích cực đến tư duy của anh."}]', '[]', NULL, '/ˈpɑːzətɪv ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 25, 'positive outcome', 'kết quả tích cực', 'adj + n', '[{"en":"Early treatment increases the chance of a positive outcome.","vi":"Điều trị sớm tăng cơ hội có một kết quả tích cực."},{"en":"The negotiations led to a positive outcome for both sides.","vi":"Các cuộc đàm phán dẫn đến kết quả tích cực cho cả hai bên."},{"en":"Researchers hoped for a positive outcome from the trial.","vi":"Các nhà nghiên cứu hy vọng có kết quả tích cực từ thử nghiệm."}]', '[]', NULL, '/ˈpɑːzətɪv ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 26, 'positive relationship', 'mối quan hệ tích cực (tương quan thuận)', 'adj + n', '[{"en":"The data show a positive relationship between study time and grades.","vi":"Dữ liệu cho thấy mối quan hệ thuận giữa thời gian học và điểm số."},{"en":"Teachers build a positive relationship with their students.","vi":"Giáo viên xây dựng mối quan hệ tích cực với học sinh."},{"en":"A positive relationship with clients improves business results.","vi":"Mối quan hệ tích cực với khách hàng cải thiện kết quả kinh doanh."}]', '[]', NULL, '/ˈpɑːzətɪv rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 27, 'positive result', 'kết quả tích cực', 'adj + n', '[{"en":"The experiment produced a clear positive result.","vi":"Thí nghiệm tạo ra một kết quả tích cực rõ ràng."},{"en":"A positive result confirmed the team''s hypothesis.","vi":"Một kết quả tích cực xác nhận giả thuyết của nhóm."},{"en":"The treatment showed a positive result within weeks.","vi":"Phương pháp điều trị cho kết quả tích cực trong vài tuần."}]', '[]', NULL, '/ˈpɑːzətɪv rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 28, 'positive value', 'giá trị dương (giá trị tích cực)', 'adj + n', '[{"en":"The function returns a positive value for all valid inputs.","vi":"Hàm trả về một giá trị dương cho mọi đầu vào hợp lệ."},{"en":"A positive value indicates growth over the period.","vi":"Một giá trị dương cho thấy sự tăng trưởng trong giai đoạn đó."},{"en":"Education holds a positive value in every society.","vi":"Giáo dục mang một giá trị tích cực trong mọi xã hội."}]', '[]', NULL, '/ˈpɑːzətɪv ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 29, 'positive view', 'quan điểm tích cực', 'adj + n', '[{"en":"Most respondents held a positive view of the changes.","vi":"Hầu hết người trả lời có quan điểm tích cực về những thay đổi."},{"en":"She maintained a positive view despite the criticism.","vi":"Cô giữ một quan điểm tích cực dù bị chỉ trích."},{"en":"The author takes a positive view of technological progress.","vi":"Tác giả có quan điểm tích cực về tiến bộ công nghệ."}]', '[]', NULL, '/ˈpɑːzətɪv vjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 30, 'positively associated with', 'có liên hệ thuận với', 'adv + vpp', '[{"en":"Higher income is positively associated with better health.","vi":"Thu nhập cao hơn có liên hệ thuận với sức khỏe tốt hơn."},{"en":"Sleep quality was positively associated with concentration.","vi":"Chất lượng giấc ngủ có liên hệ thuận với khả năng tập trung."},{"en":"Reading habits are positively associated with vocabulary size.","vi":"Thói quen đọc có liên hệ thuận với vốn từ vựng."}]', '[]', NULL, '/ˈpɑːzətɪvli əˈsoʊʃieɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 31, 'positively correlated with', 'tương quan thuận với', 'adv + vpp', '[{"en":"Test scores were positively correlated with study hours.","vi":"Điểm thi tương quan thuận với số giờ học."},{"en":"Temperature is positively correlated with ice-cream sales.","vi":"Nhiệt độ tương quan thuận với doanh số kem."},{"en":"Job satisfaction was positively correlated with productivity.","vi":"Sự hài lòng công việc tương quan thuận với năng suất."}]', '[]', NULL, '/ˈpɑːzətɪvli ˈkɔːrəleɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 32, 'possible consequences', 'những hậu quả có thể xảy ra', 'adj + n', '[{"en":"The report outlines the possible consequences of inaction.","vi":"Báo cáo nêu ra những hậu quả có thể xảy ra nếu không hành động."},{"en":"Students must consider the possible consequences of their choices.","vi":"Học sinh phải cân nhắc những hậu quả có thể xảy ra từ lựa chọn của mình."},{"en":"Scientists warned about the possible consequences of warming.","vi":"Các nhà khoa học cảnh báo về những hậu quả có thể xảy ra của sự ấm lên."}]', '[]', NULL, '/ˈpɑːsəbəl ˈkɑːnsəkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 33, 'possible explanation', 'một cách giải thích khả dĩ', 'adj + n', '[{"en":"One possible explanation is a flaw in the method.","vi":"Một cách giải thích khả dĩ là sai sót trong phương pháp."},{"en":"The author offers a possible explanation for the results.","vi":"Tác giả đưa ra một cách giải thích khả dĩ cho các kết quả."},{"en":"Several possible explanations remain to be tested.","vi":"Vẫn còn vài cách giải thích khả dĩ cần được kiểm chứng."}]', '[]', NULL, '/ˈpɑːsəbəl ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 34, 'possible outcome', 'kết quả có thể xảy ra', 'adj + n', '[{"en":"The model predicts every possible outcome of the experiment.","vi":"Mô hình dự đoán mọi kết quả có thể xảy ra của thí nghiệm."},{"en":"We must prepare for the worst possible outcome.","vi":"Chúng ta phải chuẩn bị cho kết quả tệ nhất có thể xảy ra."},{"en":"Each possible outcome was carefully analyzed.","vi":"Mỗi kết quả có thể xảy ra đều được phân tích kỹ lưỡng."}]', '[]', NULL, '/ˈpɑːsəbəl ˈaʊtkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 35, 'possible source', 'nguồn gốc có thể có', 'adj + n', '[{"en":"The team investigated every possible source of the error.","vi":"Nhóm điều tra mọi nguồn gốc có thể có của sai sót."},{"en":"Contaminated water is a possible source of the disease.","vi":"Nước ô nhiễm là một nguồn gốc có thể có của căn bệnh."},{"en":"Researchers identified a possible source of funding.","vi":"Các nhà nghiên cứu xác định một nguồn tài trợ có thể có."}]', '[]', NULL, '/ˈpɑːsəbəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 36, 'potential benefits', 'những lợi ích tiềm năng', 'adj + n', '[{"en":"The study examines the potential benefits of meditation.","vi":"Nghiên cứu xem xét những lợi ích tiềm năng của thiền."},{"en":"Investors weighed the potential benefits against the risks.","vi":"Nhà đầu tư cân nhắc những lợi ích tiềm năng so với rủi ro."},{"en":"The report highlights the potential benefits of the new policy.","vi":"Báo cáo nhấn mạnh những lợi ích tiềm năng của chính sách mới."}]', '[]', NULL, '/pəˈtenʃəl ˈbenɪfɪts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 37, 'potential conflict', 'xung đột tiềm ẩn', 'adj + n', '[{"en":"The manager spotted a potential conflict between the teams.","vi":"Người quản lý phát hiện một xung đột tiềm ẩn giữa các nhóm."},{"en":"Clear rules help avoid potential conflict over resources.","vi":"Quy định rõ ràng giúp tránh xung đột tiềm ẩn về nguồn lực."},{"en":"The treaty was designed to reduce potential conflict.","vi":"Hiệp ước được thiết kế để giảm xung đột tiềm ẩn."}]', '[]', NULL, '/pəˈtenʃəl ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 38, 'potential customer', 'khách hàng tiềm năng', 'adj + n', '[{"en":"The advertisement targets every potential customer in the city.","vi":"Quảng cáo nhắm đến mọi khách hàng tiềm năng trong thành phố."},{"en":"A friendly website attracts each potential customer quickly.","vi":"Một trang web thân thiện thu hút mỗi khách hàng tiềm năng nhanh chóng."},{"en":"Sales staff follow up with every potential customer.","vi":"Nhân viên bán hàng theo dõi mọi khách hàng tiềm năng."}]', '[]', NULL, '/pəˈtenʃəl ˈkʌstəmər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 39, 'potential harm', 'tác hại tiềm ẩn', 'adj + n', '[{"en":"The study warns of potential harm from excessive screen time.","vi":"Nghiên cứu cảnh báo về tác hại tiềm ẩn từ việc dùng màn hình quá nhiều."},{"en":"Doctors weigh the potential harm of each treatment.","vi":"Bác sĩ cân nhắc tác hại tiềm ẩn của mỗi phương pháp điều trị."},{"en":"Regulators assess the potential harm of new chemicals.","vi":"Cơ quan quản lý đánh giá tác hại tiềm ẩn của các hóa chất mới."}]', '[]', NULL, '/pəˈtenʃəl hɑːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 40, 'potential impact', 'tác động tiềm tàng', 'adj + n', '[{"en":"Researchers studied the potential impact of rising sea levels.","vi":"Các nhà nghiên cứu nghiên cứu tác động tiềm tàng của mực nước biển dâng."},{"en":"The report assesses the potential impact of the merger.","vi":"Báo cáo đánh giá tác động tiềm tàng của vụ sáp nhập."},{"en":"Planners considered the potential impact on local traffic.","vi":"Các nhà quy hoạch xem xét tác động tiềm tàng đến giao thông địa phương."}]', '[]', NULL, '/pəˈtenʃəl ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 41, 'potential problem', 'vấn đề tiềm ẩn', 'adj + n', '[{"en":"The engineer identified a potential problem with the design.","vi":"Kỹ sư xác định một vấn đề tiềm ẩn trong thiết kế."},{"en":"Early testing helps reveal any potential problem.","vi":"Kiểm thử sớm giúp phát hiện bất kỳ vấn đề tiềm ẩn nào."},{"en":"Managers discussed every potential problem before launch.","vi":"Các nhà quản lý thảo luận mọi vấn đề tiềm ẩn trước khi ra mắt."}]', '[]', NULL, '/pəˈtenʃəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 42, 'potential risk', 'rủi ro tiềm ẩn', 'adj + n', '[{"en":"The label warns users of any potential risk.","vi":"Nhãn cảnh báo người dùng về bất kỳ rủi ro tiềm ẩn nào."},{"en":"Investors must understand the potential risk involved.","vi":"Nhà đầu tư phải hiểu rủi ro tiềm ẩn liên quan."},{"en":"The team reduced the potential risk through careful planning.","vi":"Nhóm giảm rủi ro tiềm ẩn nhờ lập kế hoạch cẩn thận."}]', '[]', NULL, '/pəˈtenʃəl rɪsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 43, 'potential source', 'nguồn tiềm năng', 'adj + n', '[{"en":"Solar energy is a potential source of clean power.","vi":"Năng lượng mặt trời là một nguồn tiềm năng cho điện sạch."},{"en":"Bias is a potential source of error in surveys.","vi":"Thiên kiến là một nguồn tiềm năng gây sai số trong khảo sát."},{"en":"The lake is a potential source of drinking water.","vi":"Hồ là một nguồn tiềm năng cung cấp nước uống."}]', '[]', NULL, '/pəˈtenʃəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 44, 'potential value', 'giá trị tiềm năng', 'adj + n', '[{"en":"Investors recognized the potential value of the technology.","vi":"Nhà đầu tư nhận ra giá trị tiềm năng của công nghệ này."},{"en":"The land has great potential value for development.","vi":"Khu đất có giá trị tiềm năng lớn cho phát triển."},{"en":"The study underestimates the potential value of the data.","vi":"Nghiên cứu đánh giá thấp giá trị tiềm năng của dữ liệu."}]', '[]', NULL, '/pəˈtenʃəl ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 45, 'potentially dangerous', 'có thể nguy hiểm', 'adv + adj', '[{"en":"The chemical is potentially dangerous if mishandled.","vi":"Hóa chất này có thể nguy hiểm nếu xử lý sai cách."},{"en":"Driving while tired is potentially dangerous.","vi":"Lái xe khi mệt mỏi có thể nguy hiểm."},{"en":"The study identified a potentially dangerous side effect.","vi":"Nghiên cứu xác định một tác dụng phụ có thể nguy hiểm."}]', '[]', NULL, '/pəˈtenʃəli ˈdeɪndʒərəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 46, 'powerful force', 'một lực lượng mạnh mẽ', 'adj + n', '[{"en":"Education is a powerful force for social change.","vi":"Giáo dục là một lực lượng mạnh mẽ thúc đẩy thay đổi xã hội."},{"en":"Gravity is a powerful force shaping the universe.","vi":"Trọng lực là một lực mạnh mẽ định hình vũ trụ."},{"en":"Public opinion became a powerful force in the debate.","vi":"Dư luận trở thành một lực lượng mạnh mẽ trong cuộc tranh luận."}]', '[]', NULL, '/ˈpaʊərfəl fɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 47, 'powerful group', 'một nhóm có quyền lực', 'adj + n', '[{"en":"A powerful group of investors controlled the company.","vi":"Một nhóm nhà đầu tư có quyền lực kiểm soát công ty."},{"en":"The reform threatened several powerful groups in society.","vi":"Cuộc cải cách đe dọa vài nhóm có quyền lực trong xã hội."},{"en":"A powerful group lobbied against the new tax.","vi":"Một nhóm có quyền lực vận động chống lại loại thuế mới."}]', '[]', NULL, '/ˈpaʊərfəl ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 48, 'powerful influence', 'ảnh hưởng mạnh mẽ', 'adj + n', '[{"en":"The media has a powerful influence on public opinion.","vi":"Truyền thông có ảnh hưởng mạnh mẽ đến dư luận."},{"en":"His writing had a powerful influence on later authors.","vi":"Tác phẩm của ông có ảnh hưởng mạnh mẽ đến các tác giả sau này."},{"en":"Parents exert a powerful influence on their children.","vi":"Cha mẹ có ảnh hưởng mạnh mẽ đến con cái."}]', '[]', NULL, '/ˈpaʊərfəl ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 49, 'powerful tool', 'một công cụ mạnh mẽ', 'adj + n', '[{"en":"Statistics is a powerful tool for understanding data.","vi":"Thống kê là một công cụ mạnh mẽ để hiểu dữ liệu."},{"en":"The internet is a powerful tool for learning.","vi":"Internet là một công cụ mạnh mẽ cho việc học."},{"en":"Language is a powerful tool for shaping ideas.","vi":"Ngôn ngữ là một công cụ mạnh mẽ để định hình ý tưởng."}]', '[]', NULL, '/ˈpaʊərfəl tuːl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 50, 'practical consideration', 'yếu tố thực tiễn cần cân nhắc', 'adj + n', '[{"en":"Cost is an important practical consideration in the plan.","vi":"Chi phí là một yếu tố thực tiễn quan trọng cần cân nhắc trong kế hoạch."},{"en":"Practical considerations limited the scope of the study.","vi":"Những yếu tố thực tiễn đã giới hạn phạm vi của nghiên cứu."},{"en":"We balanced ideals against practical considerations.","vi":"Chúng tôi cân bằng giữa lý tưởng và các yếu tố thực tiễn."}]', '[]', NULL, '/ˈpræktɪkəl kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 51, 'practical difficulties', 'những khó khăn thực tế', 'adj + n', '[{"en":"The project faced many practical difficulties at first.","vi":"Dự án gặp nhiều khó khăn thực tế lúc ban đầu."},{"en":"Practical difficulties delayed the start of the trial.","vi":"Những khó khăn thực tế làm chậm việc bắt đầu thử nghiệm."},{"en":"Researchers described the practical difficulties of fieldwork.","vi":"Các nhà nghiên cứu mô tả những khó khăn thực tế của công việc thực địa."}]', '[]', NULL, '/ˈpræktɪkəl ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 52, 'practical issue', 'vấn đề thực tế', 'adj + n', '[{"en":"The meeting focused on one practical issue at a time.","vi":"Cuộc họp tập trung vào một vấn đề thực tế tại mỗi thời điểm."},{"en":"Funding is a practical issue every charity must face.","vi":"Tài trợ là một vấn đề thực tế mà mọi tổ chức từ thiện phải đối mặt."},{"en":"The committee resolved several practical issues quickly.","vi":"Ủy ban giải quyết nhanh chóng vài vấn đề thực tế."}]', '[]', NULL, '/ˈpræktɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 53, 'practical significance', 'ý nghĩa thực tiễn', 'adj + n', '[{"en":"The findings have real practical significance for teachers.","vi":"Phát hiện này có ý nghĩa thực tiễn thật sự đối với giáo viên."},{"en":"The author explains the practical significance of the theory.","vi":"Tác giả giải thích ý nghĩa thực tiễn của lý thuyết."},{"en":"A small effect may still have practical significance.","vi":"Một hiệu ứng nhỏ vẫn có thể có ý nghĩa thực tiễn."}]', '[]', NULL, '/ˈpræktɪkəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 54, 'preceding chapter', 'chương trước đó', 'adj + n', '[{"en":"As noted in the preceding chapter, the data were limited.","vi":"Như đã nêu trong chương trước đó, dữ liệu còn hạn chế."},{"en":"The preceding chapter introduced the main theoretical framework.","vi":"Chương trước đó đã giới thiệu khung lý thuyết chính."},{"en":"This section builds on the preceding chapter''s argument.","vi":"Phần này dựa trên lập luận của chương trước đó."}]', '[]', NULL, '/prɪˈsiːdɪŋ ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 55, 'preceding discussion', 'phần thảo luận trước đó', 'adj + n', '[{"en":"The preceding discussion raised several important questions.","vi":"Phần thảo luận trước đó đã nêu ra vài câu hỏi quan trọng."},{"en":"These conclusions follow from the preceding discussion.","vi":"Những kết luận này rút ra từ phần thảo luận trước đó."},{"en":"The preceding discussion clarified the key terms.","vi":"Phần thảo luận trước đó đã làm rõ các thuật ngữ chính."}]', '[]', NULL, '/prɪˈsiːdɪŋ dɪˈskʌʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 56, 'preceding section', 'phần trước đó', 'adj + n', '[{"en":"The preceding section described the research methods.","vi":"Phần trước đó đã mô tả các phương pháp nghiên cứu."},{"en":"As shown in the preceding section, the results vary.","vi":"Như đã thấy ở phần trước đó, các kết quả có sự khác biệt."},{"en":"This argument extends ideas from the preceding section.","vi":"Lập luận này mở rộng các ý tưởng từ phần trước đó."}]', '[]', NULL, '/prɪˈsiːdɪŋ ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 57, 'precise definition', 'định nghĩa chính xác', 'adj + n', '[{"en":"The term lacks a precise definition in the literature.","vi":"Thuật ngữ này thiếu một định nghĩa chính xác trong tài liệu."},{"en":"A precise definition helps avoid misunderstanding.","vi":"Một định nghĩa chính xác giúp tránh hiểu lầm."},{"en":"Scientists agreed on a precise definition of the unit.","vi":"Các nhà khoa học đã thống nhất một định nghĩa chính xác cho đơn vị."}]', '[]', NULL, '/prɪˈsaɪs ˌdefɪˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 58, 'precise nature', 'bản chất cụ thể', 'adj + n', '[{"en":"The precise nature of the link is still unclear.","vi":"Bản chất cụ thể của mối liên hệ vẫn chưa rõ ràng."},{"en":"Researchers debated the precise nature of the disorder.","vi":"Các nhà nghiên cứu tranh luận về bản chất cụ thể của chứng rối loạn."},{"en":"We need more data to understand its precise nature.","vi":"Chúng ta cần thêm dữ liệu để hiểu bản chất cụ thể của nó."}]', '[]', NULL, '/prɪˈsaɪs ˈneɪtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 59, 'predictive power', 'khả năng dự đoán', 'adj + n', '[{"en":"The model has strong predictive power for short-term trends.","vi":"Mô hình có khả năng dự đoán mạnh đối với các xu hướng ngắn hạn."},{"en":"Adding variables improved the model''s predictive power.","vi":"Việc thêm biến số đã cải thiện khả năng dự đoán của mô hình."},{"en":"The theory''s predictive power impressed the researchers.","vi":"Khả năng dự đoán của lý thuyết gây ấn tượng với các nhà nghiên cứu."}]', '[]', NULL, '/prɪˈdɪktɪv ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 60, 'preferential treatment', 'sự đối xử ưu ái', 'adj + n', '[{"en":"Employees complained about preferential treatment for managers.","vi":"Nhân viên phàn nàn về sự đối xử ưu ái dành cho quản lý."},{"en":"The policy bans preferential treatment based on connections.","vi":"Chính sách cấm sự đối xử ưu ái dựa trên quan hệ."},{"en":"Some customers receive preferential treatment for loyalty.","vi":"Một số khách hàng nhận được sự đối xử ưu ái vì lòng trung thành."}]', '[]', NULL, '/ˌprefəˈrenʃəl ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 61, 'preliminary data', 'dữ liệu sơ bộ', 'adj + n', '[{"en":"The preliminary data suggest a promising trend.","vi":"Dữ liệu sơ bộ cho thấy một xu hướng đầy hứa hẹn."},{"en":"Researchers shared preliminary data at the conference.","vi":"Các nhà nghiên cứu chia sẻ dữ liệu sơ bộ tại hội nghị."},{"en":"Preliminary data must be confirmed by larger studies.","vi":"Dữ liệu sơ bộ cần được xác nhận bằng các nghiên cứu lớn hơn."}]', '[]', NULL, '/prɪˈlɪmɪneri ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 62, 'preliminary findings', 'những phát hiện sơ bộ', 'adj + n', '[{"en":"Preliminary findings indicate a need for further research.","vi":"Những phát hiện sơ bộ cho thấy cần nghiên cứu thêm."},{"en":"The team presented preliminary findings to the committee.","vi":"Nhóm trình bày những phát hiện sơ bộ cho ủy ban."},{"en":"These preliminary findings should be treated with caution.","vi":"Những phát hiện sơ bộ này nên được xem xét thận trọng."}]', '[]', NULL, '/prɪˈlɪmɪneri ˈfaɪndɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 63, 'preliminary result', 'kết quả sơ bộ', 'adj + n', '[{"en":"The preliminary result looks promising but needs confirmation.","vi":"Kết quả sơ bộ trông hứa hẹn nhưng cần được xác nhận."},{"en":"Each preliminary result was reviewed by two experts.","vi":"Mỗi kết quả sơ bộ đều được hai chuyên gia xem xét."},{"en":"The preliminary result supported the team''s hypothesis.","vi":"Kết quả sơ bộ ủng hộ giả thuyết của nhóm."}]', '[]', NULL, '/prɪˈlɪmɪneri rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 64, 'premature death', 'cái chết yểu (tử vong sớm)', 'adj + n', '[{"en":"Smoking is a leading cause of premature death.","vi":"Hút thuốc là một nguyên nhân hàng đầu gây tử vong sớm."},{"en":"The study links air pollution to premature death.","vi":"Nghiên cứu liên kết ô nhiễm không khí với tử vong sớm."},{"en":"Better healthcare can prevent many premature deaths.","vi":"Chăm sóc y tế tốt hơn có thể ngăn nhiều ca tử vong sớm."}]', '[]', NULL, '/ˌpriːməˈtʃʊr deθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 65, 'present context', 'bối cảnh hiện tại', 'adj + n', '[{"en":"In the present context, the old theory no longer applies.","vi":"Trong bối cảnh hiện tại, lý thuyết cũ không còn áp dụng được."},{"en":"The present context demands a new approach to teaching.","vi":"Bối cảnh hiện tại đòi hỏi một cách tiếp cận mới trong giảng dạy."},{"en":"These rules make sense only in the present context.","vi":"Những quy tắc này chỉ hợp lý trong bối cảnh hiện tại."}]', '[]', NULL, '/ˈpreznt ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 66, 'present data', 'trình bày dữ liệu', 'v + n', '[{"en":"The authors present data from three separate experiments.","vi":"Các tác giả trình bày dữ liệu từ ba thí nghiệm riêng biệt."},{"en":"Researchers must present data clearly and honestly.","vi":"Các nhà nghiên cứu phải trình bày dữ liệu rõ ràng và trung thực."},{"en":"She used charts to present data to the audience.","vi":"Cô dùng biểu đồ để trình bày dữ liệu cho khán giả."}]', '[]', NULL, '/prɪˈzent ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 67, 'present difficulties', 'gây ra khó khăn', 'v + n', '[{"en":"Translating poetry can present difficulties for any scholar.","vi":"Dịch thơ có thể gây ra khó khăn cho bất kỳ học giả nào."},{"en":"Limited funding present difficulties for many new projects.","vi":"Nguồn tài trợ hạn chế gây ra khó khăn cho nhiều dự án mới."},{"en":"Remote locations present difficulties for data collection.","vi":"Các địa điểm xa xôi gây ra khó khăn cho việc thu thập dữ liệu."}]', '[]', NULL, '/prɪˈzent ˈdɪfɪkəltiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 68, 'present evidence', 'đưa ra bằng chứng', 'v + n', '[{"en":"The lawyer will present evidence to support the claim.","vi":"Luật sư sẽ đưa ra bằng chứng để hỗ trợ cho lập luận."},{"en":"The authors present evidence from several recent studies.","vi":"Các tác giả đưa ra bằng chứng từ vài nghiên cứu gần đây."},{"en":"Scientists present evidence that the climate is changing.","vi":"Các nhà khoa học đưa ra bằng chứng rằng khí hậu đang thay đổi."}]', '[]', NULL, '/prɪˈzent ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 69, 'present a challenge', 'đặt ra một thách thức', 'v + n', '[{"en":"Large classes present a challenge for individual attention.","vi":"Lớp học đông đặt ra một thách thức cho việc quan tâm từng học sinh."},{"en":"New technology can present a challenge for older workers.","vi":"Công nghệ mới có thể đặt ra một thách thức cho người lao động lớn tuổi."},{"en":"The disease continues to present a challenge to doctors.","vi":"Căn bệnh tiếp tục đặt ra một thách thức cho các bác sĩ."}]', '[]', NULL, '/prɪˈzent ə ˈtʃælɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 70, 'present a summary', 'trình bày một bản tóm tắt', 'v + n', '[{"en":"The final chapter present a summary of the main findings.","vi":"Chương cuối trình bày một bản tóm tắt các phát hiện chính."},{"en":"She will present a summary of the report tomorrow.","vi":"Cô sẽ trình bày một bản tóm tắt của báo cáo vào ngày mai."},{"en":"Speakers present a summary before the detailed analysis.","vi":"Diễn giả trình bày một bản tóm tắt trước khi phân tích chi tiết."}]', '[]', NULL, '/prɪˈzent ə ˈsʌməri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 71, 'present an argument', 'trình bày một lập luận', 'v + n', '[{"en":"The essay must present an argument supported by evidence.","vi":"Bài luận phải trình bày một lập luận được hỗ trợ bằng bằng chứng."},{"en":"He clearly present an argument for stricter regulation.","vi":"Anh trình bày rõ ràng một lập luận ủng hộ quy định chặt chẽ hơn."},{"en":"Students learn to present an argument logically.","vi":"Học sinh học cách trình bày một lập luận một cách logic."}]', '[]', NULL, '/prɪˈzent ən ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 72, 'presidential election', 'cuộc bầu cử tổng thống', 'adj + n', '[{"en":"The presidential election attracted record voter turnout.","vi":"Cuộc bầu cử tổng thống thu hút số cử tri đi bầu kỷ lục."},{"en":"Analysts studied the results of the presidential election.","vi":"Các nhà phân tích nghiên cứu kết quả của cuộc bầu cử tổng thống."},{"en":"The presidential election dominated the news for months.","vi":"Cuộc bầu cử tổng thống chiếm sóng tin tức suốt nhiều tháng."}]', '[]', NULL, '/ˌprezɪˈdenʃəl ɪˈlekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 73, 'previous chapter', 'chương trước', 'adj + n', '[{"en":"The previous chapter explained the research design.","vi":"Chương trước đã giải thích thiết kế nghiên cứu."},{"en":"This argument was introduced in the previous chapter.","vi":"Lập luận này đã được giới thiệu ở chương trước."},{"en":"Readers should review the previous chapter first.","vi":"Người đọc nên xem lại chương trước trước tiên."}]', '[]', NULL, '/ˈpriːviəs ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 74, 'previous decade', 'thập kỷ trước', 'adj + n', '[{"en":"Unemployment fell sharply over the previous decade.","vi":"Tỷ lệ thất nghiệp giảm mạnh trong thập kỷ trước."},{"en":"The previous decade saw rapid growth in technology.","vi":"Thập kỷ trước chứng kiến sự phát triển nhanh của công nghệ."},{"en":"Prices rose steadily throughout the previous decade.","vi":"Giá cả tăng đều đặn suốt thập kỷ trước."}]', '[]', NULL, '/ˈpriːviəs ˈdekeɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 75, 'previous discussion', 'phần thảo luận trước', 'adj + n', '[{"en":"The previous discussion focused on theoretical models.","vi":"Phần thảo luận trước tập trung vào các mô hình lý thuyết."},{"en":"This point builds on our previous discussion.","vi":"Điểm này dựa trên phần thảo luận trước của chúng ta."},{"en":"As the previous discussion showed, opinions differ widely.","vi":"Như phần thảo luận trước cho thấy, các ý kiến rất khác nhau."}]', '[]', NULL, '/ˈpriːviəs dɪˈskʌʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 76, 'previous experience', 'kinh nghiệm trước đây', 'adj + n', '[{"en":"Previous experience in teaching helped her get the job.","vi":"Kinh nghiệm giảng dạy trước đây giúp cô có được công việc."},{"en":"The role requires previous experience in marketing.","vi":"Vị trí này yêu cầu kinh nghiệm trước đây trong lĩnh vực tiếp thị."},{"en":"His previous experience made the transition easier.","vi":"Kinh nghiệm trước đây của anh giúp quá trình chuyển đổi dễ dàng hơn."}]', '[]', NULL, '/ˈpriːviəs ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 77, 'previous generation', 'thế hệ trước', 'adj + n', '[{"en":"The previous generation faced very different challenges.","vi":"Thế hệ trước đã đối mặt với những thách thức rất khác."},{"en":"Young people often reject the values of the previous generation.","vi":"Người trẻ thường bác bỏ các giá trị của thế hệ trước."},{"en":"This device is far faster than the previous generation.","vi":"Thiết bị này nhanh hơn nhiều so với thế hệ trước."}]', '[]', NULL, '/ˈpriːviəs ˌdʒenəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 78, 'previous knowledge', 'kiến thức đã có từ trước', 'adj + n', '[{"en":"The course assumes no previous knowledge of statistics.","vi":"Khóa học không đòi hỏi kiến thức trước về thống kê."},{"en":"Learners connect new ideas to their previous knowledge.","vi":"Người học kết nối ý tưởng mới với kiến thức đã có từ trước."},{"en":"Previous knowledge of the topic made the reading easier.","vi":"Kiến thức có từ trước về chủ đề khiến việc đọc dễ hơn."}]', '[]', NULL, '/ˈpriːviəs ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 79, 'previous paragraph', 'đoạn văn trước', 'adj + n', '[{"en":"The previous paragraph introduced the central claim.","vi":"Đoạn văn trước đã giới thiệu luận điểm trung tâm."},{"en":"This idea was mentioned in the previous paragraph.","vi":"Ý tưởng này đã được nhắc đến ở đoạn văn trước."},{"en":"The example supports the point made in the previous paragraph.","vi":"Ví dụ hỗ trợ cho luận điểm nêu ở đoạn văn trước."}]', '[]', NULL, '/ˈpriːviəs ˈpærəɡræf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 80, 'previous part', 'phần trước', 'adj + n', '[{"en":"The previous part of the report covered the survey results.","vi":"Phần trước của báo cáo đã đề cập đến kết quả khảo sát."},{"en":"This section continues from the previous part.","vi":"Phần này nối tiếp từ phần trước."},{"en":"Refer to the previous part for the full definitions.","vi":"Hãy tham khảo phần trước để xem đầy đủ các định nghĩa."}]', '[]', NULL, '/ˈpriːviəs pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 81, 'previous research', 'nghiên cứu trước đây', 'adj + n', '[{"en":"Previous research suggests a strong link between diet and mood.","vi":"Các nghiên cứu trước đây cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và tâm trạng."},{"en":"Our findings build directly on previous research in this field.","vi":"Phát hiện của chúng tôi dựa trực tiếp vào nghiên cứu trước đây trong lĩnh vực này."},{"en":"Previous research had largely ignored younger age groups.","vi":"Nghiên cứu trước đây phần lớn đã bỏ qua các nhóm tuổi trẻ hơn."}]', '[]', NULL, '/ˈpriːviəs rɪˈsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 82, 'previous section', 'phần trước đó', 'adj + n', '[{"en":"As noted in the previous section, the method has clear limits.","vi":"Như đã nêu ở phần trước, phương pháp này có những hạn chế rõ ràng."},{"en":"The previous section described the data collection process in detail.","vi":"Phần trước đã mô tả chi tiết quá trình thu thập dữ liệu."},{"en":"We now extend the model introduced in the previous section.","vi":"Bây giờ chúng tôi mở rộng mô hình đã giới thiệu ở phần trước."}]', '[]', NULL, '/ˈpriːviəs ˈsekʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 83, 'previous study', 'nghiên cứu trước', 'adj + n', '[{"en":"A previous study reported similar results among older patients.","vi":"Một nghiên cứu trước đã báo cáo kết quả tương tự ở bệnh nhân lớn tuổi."},{"en":"This finding contradicts a previous study from the same lab.","vi":"Phát hiện này mâu thuẫn với một nghiên cứu trước từ cùng phòng thí nghiệm."},{"en":"Unlike the previous study, we used a larger sample size.","vi":"Khác với nghiên cứu trước, chúng tôi dùng cỡ mẫu lớn hơn."}]', '[]', NULL, '/ˈpriːviəs ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 84, 'previous work', 'công trình trước đây', 'adj + n', '[{"en":"Our approach combines ideas from several lines of previous work.","vi":"Cách tiếp cận của chúng tôi kết hợp ý tưởng từ nhiều công trình trước đây."},{"en":"Previous work in this area focused mainly on urban populations.","vi":"Công trình trước đây trong lĩnh vực này chủ yếu tập trung vào dân cư thành thị."},{"en":"She summarized her previous work before presenting new results.","vi":"Cô tóm tắt các công trình trước đây trước khi trình bày kết quả mới."}]', '[]', NULL, '/ˈpriːviəs wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 85, 'previously described', 'đã được mô tả trước đó', 'adv + vpp', '[{"en":"The samples were prepared using a previously described protocol.","vi":"Các mẫu được chuẩn bị theo quy trình đã mô tả trước đó."},{"en":"We applied the previously described technique to a new dataset.","vi":"Chúng tôi áp dụng kỹ thuật đã mô tả trước đó cho một tập dữ liệu mới."},{"en":"These symptoms match the condition previously described in the literature.","vi":"Các triệu chứng này khớp với tình trạng đã được mô tả trước đó trong tài liệu."}]', '[]', NULL, '/ˈpriːviəsli dɪˈskraɪbd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 86, 'previously discussed', 'đã được thảo luận trước đó', 'adv + vpp', '[{"en":"The factors previously discussed all contribute to higher costs.","vi":"Các yếu tố đã thảo luận trước đó đều góp phần làm tăng chi phí."},{"en":"As previously discussed, the policy affects rural areas most.","vi":"Như đã thảo luận trước đó, chính sách này ảnh hưởng nhiều nhất đến nông thôn."},{"en":"This section revisits a problem previously discussed in chapter two.","vi":"Phần này xem lại một vấn đề đã thảo luận trước đó ở chương hai."}]', '[]', NULL, '/ˈpriːviəsli dɪˈskʌst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 87, 'previously known', 'đã được biết đến trước đó', 'adv + vpp', '[{"en":"The species was previously known only from a single region.","vi":"Loài này trước đó chỉ được biết đến ở một vùng duy nhất."},{"en":"This gene was not previously known to affect growth.","vi":"Gen này trước đó chưa được biết là ảnh hưởng đến sự tăng trưởng."},{"en":"The site was previously known by a different local name.","vi":"Địa điểm này trước đó được biết đến bằng một tên địa phương khác."}]', '[]', NULL, '/ˈpriːviəsli noʊn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 88, 'previously mentioned', 'đã được nhắc đến trước đó', 'adv + vpp', '[{"en":"The previously mentioned limitations apply to this analysis too.","vi":"Các hạn chế đã nhắc đến trước đó cũng áp dụng cho phân tích này."},{"en":"As previously mentioned, the survey covered three countries.","vi":"Như đã nhắc đến trước đó, khảo sát bao gồm ba quốc gia."},{"en":"We now return to the previously mentioned example for clarity.","vi":"Bây giờ chúng tôi quay lại ví dụ đã nhắc đến trước đó cho rõ ràng."}]', '[]', NULL, '/ˈpriːviəsli ˈmenʃənd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 89, 'previously thought', 'vốn được cho là trước đây', 'adv + vpp', '[{"en":"The disease spreads faster than previously thought.","vi":"Căn bệnh lây lan nhanh hơn so với những gì người ta từng nghĩ."},{"en":"These ruins are older than previously thought by historians.","vi":"Những tàn tích này cổ hơn so với điều các nhà sử học từng nghĩ."},{"en":"The two effects are more closely linked than previously thought.","vi":"Hai tác động này liên kết chặt chẽ hơn so với điều từng được cho là."}]', '[]', NULL, '/ˈpriːviəsli θɔːt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 90, 'primarily concerned with', 'chủ yếu quan tâm đến', 'adv + vpp', '[{"en":"This chapter is primarily concerned with economic policy and trade.","vi":"Chương này chủ yếu quan tâm đến chính sách kinh tế và thương mại."},{"en":"The study was primarily concerned with how children learn language.","vi":"Nghiên cứu chủ yếu quan tâm đến cách trẻ em học ngôn ngữ."},{"en":"Early researchers were primarily concerned with measuring physical traits.","vi":"Các nhà nghiên cứu thời kỳ đầu chủ yếu quan tâm đến việc đo lường đặc điểm thể chất."}]', '[]', NULL, '/praɪˈmerəli kənˈsɜːrnd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 91, 'primarily responsible for', 'chịu trách nhiệm chính cho', 'adv + adj', '[{"en":"These cells are primarily responsible for the immune response.","vi":"Các tế bào này chịu trách nhiệm chính cho phản ứng miễn dịch."},{"en":"Local councils are primarily responsible for waste collection services.","vi":"Hội đồng địa phương chịu trách nhiệm chính cho dịch vụ thu gom rác."},{"en":"One enzyme is primarily responsible for breaking down the toxin.","vi":"Một enzyme chịu trách nhiệm chính cho việc phân hủy độc tố."}]', '[]', NULL, '/praɪˈmerəli rɪˈspɑːnsəbəl fər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 92, 'primary aim', 'mục tiêu chính', 'adj + n', '[{"en":"The primary aim of this study is to reduce error rates.","vi":"Mục tiêu chính của nghiên cứu này là giảm tỷ lệ lỗi."},{"en":"Our primary aim was to improve access for rural patients.","vi":"Mục tiêu chính của chúng tôi là cải thiện khả năng tiếp cận cho bệnh nhân nông thôn."},{"en":"The program''s primary aim is helping students develop critical thinking.","vi":"Mục tiêu chính của chương trình là giúp học sinh phát triển tư duy phản biện."}]', '[]', NULL, '/ˈpraɪmeri eɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 93, 'primary care', 'chăm sóc sức khỏe ban đầu', 'adj + n', '[{"en":"Most patients first seek help through primary care services.","vi":"Hầu hết bệnh nhân tìm kiếm sự hỗ trợ đầu tiên qua dịch vụ chăm sóc sức khỏe ban đầu."},{"en":"Investing in primary care reduces pressure on hospitals.","vi":"Đầu tư vào chăm sóc sức khỏe ban đầu giúp giảm áp lực cho bệnh viện."},{"en":"Primary care doctors often manage chronic conditions over time.","vi":"Bác sĩ chăm sóc ban đầu thường quản lý các bệnh mãn tính theo thời gian."}]', '[]', NULL, '/ˈpraɪmeri ker/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 94, 'primary concern', 'mối quan tâm hàng đầu', 'adj + n', '[{"en":"Safety remains the primary concern for everyone on the team.","vi":"An toàn vẫn là mối quan tâm hàng đầu của mọi người trong nhóm."},{"en":"Rising costs are a primary concern for many small businesses.","vi":"Chi phí tăng là mối quan tâm hàng đầu của nhiều doanh nghiệp nhỏ."},{"en":"The primary concern of parents was their children''s education.","vi":"Mối quan tâm hàng đầu của phụ huynh là việc học của con cái."}]', '[]', NULL, '/ˈpraɪmeri kənˈsɜːrn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 95, 'primary data', 'dữ liệu sơ cấp', 'adj + n', '[{"en":"We collected primary data through interviews and field surveys.","vi":"Chúng tôi thu thập dữ liệu sơ cấp qua phỏng vấn và khảo sát thực địa."},{"en":"Primary data offers fresh insight that existing records cannot.","vi":"Dữ liệu sơ cấp mang lại hiểu biết mới mà hồ sơ có sẵn không có."},{"en":"The thesis relies on primary data gathered over two years.","vi":"Luận án dựa vào dữ liệu sơ cấp thu thập trong hai năm."}]', '[]', NULL, '/ˈpraɪmeri ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 96, 'primary education', 'giáo dục tiểu học', 'adj + n', '[{"en":"Free primary education is a basic right in many countries.","vi":"Giáo dục tiểu học miễn phí là quyền cơ bản ở nhiều quốc gia."},{"en":"Quality primary education lays the foundation for later learning.","vi":"Giáo dục tiểu học chất lượng đặt nền tảng cho việc học sau này."},{"en":"The reform aims to expand primary education in remote villages.","vi":"Cuộc cải cách nhằm mở rộng giáo dục tiểu học ở các làng xa xôi."}]', '[]', NULL, '/ˈpraɪmeri ˌedʒəˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 97, 'primary focus', 'trọng tâm chính', 'adj + n', '[{"en":"The primary focus of the report is renewable energy growth.","vi":"Trọng tâm chính của báo cáo là sự tăng trưởng năng lượng tái tạo."},{"en":"Customer satisfaction has become the company''s primary focus this year.","vi":"Sự hài lòng của khách hàng đã trở thành trọng tâm chính của công ty năm nay."},{"en":"Her primary focus during the project was data quality.","vi":"Trọng tâm chính của cô trong dự án là chất lượng dữ liệu."}]', '[]', NULL, '/ˈpraɪmeri ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 98, 'primary function', 'chức năng chính', 'adj + n', '[{"en":"The heart''s primary function is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu đi khắp cơ thể."},{"en":"The primary function of the device is to monitor temperature.","vi":"Chức năng chính của thiết bị là theo dõi nhiệt độ."},{"en":"A library''s primary function is to provide access to knowledge.","vi":"Chức năng chính của thư viện là cung cấp khả năng tiếp cận tri thức."}]', '[]', NULL, '/ˈpraɪmeri ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 99, 'primary objective', 'mục tiêu chính', 'adj + n', '[{"en":"The primary objective is to lower unemployment in the region.","vi":"Mục tiêu chính là giảm tỷ lệ thất nghiệp trong khu vực."},{"en":"Reducing waste was the primary objective of the new plan.","vi":"Giảm rác thải là mục tiêu chính của kế hoạch mới."},{"en":"Each team set a clear primary objective for the quarter.","vi":"Mỗi nhóm đặt ra một mục tiêu chính rõ ràng cho quý."}]', '[]', NULL, '/ˈpraɪmeri əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 100, 'primary purpose', 'mục đích chính', 'adj + n', '[{"en":"The primary purpose of the survey was to gather opinions.","vi":"Mục đích chính của khảo sát là thu thập ý kiến."},{"en":"Its primary purpose is to protect users from online fraud.","vi":"Mục đích chính của nó là bảo vệ người dùng khỏi lừa đảo trực tuyến."},{"en":"The fund''s primary purpose is supporting research in medicine.","vi":"Mục đích chính của quỹ là hỗ trợ nghiên cứu y học."}]', '[]', NULL, '/ˈpraɪmeri ˈpɜːrpəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 101, 'primary reason', 'lý do chính', 'adj + n', '[{"en":"Cost was the primary reason for delaying the project.","vi":"Chi phí là lý do chính khiến dự án bị trì hoãn."},{"en":"The primary reason for the change is improved efficiency.","vi":"Lý do chính cho sự thay đổi là cải thiện hiệu quả."},{"en":"Poor weather was the primary reason for the low turnout.","vi":"Thời tiết xấu là lý do chính cho lượng người tham dự thấp."}]', '[]', NULL, '/ˈpraɪmeri ˈriːzən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 102, 'primary research', 'nghiên cứu sơ cấp', 'adj + n', '[{"en":"The essay combines primary research with published statistics.","vi":"Bài luận kết hợp nghiên cứu sơ cấp với số liệu thống kê đã công bố."},{"en":"Conducting primary research requires careful planning and ethical approval.","vi":"Tiến hành nghiên cứu sơ cấp đòi hỏi lập kế hoạch kỹ lưỡng và phê duyệt đạo đức."},{"en":"Students learn primary research methods such as interviews and observation.","vi":"Sinh viên học các phương pháp nghiên cứu sơ cấp như phỏng vấn và quan sát."}]', '[]', NULL, '/ˈpraɪmeri rɪˈsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 103, 'primary responsibility', 'trách nhiệm chính', 'adj + n', '[{"en":"Her primary responsibility is managing the research budget carefully.","vi":"Trách nhiệm chính của cô là quản lý ngân sách nghiên cứu cẩn thận."},{"en":"Schools bear primary responsibility for keeping students safe.","vi":"Trường học gánh trách nhiệm chính trong việc giữ an toàn cho học sinh."},{"en":"The minister''s primary responsibility is overseeing public health policy.","vi":"Trách nhiệm chính của bộ trưởng là giám sát chính sách y tế công cộng."}]', '[]', NULL, '/ˈpraɪmeri rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 104, 'primary source', 'nguồn sơ cấp', 'adj + n', '[{"en":"Letters and diaries serve as a valuable primary source.","vi":"Thư từ và nhật ký là nguồn sơ cấp quý giá."},{"en":"Historians prefer a primary source to a later commentary.","vi":"Các nhà sử học thích nguồn sơ cấp hơn là bình luận về sau."},{"en":"The interview became the primary source for her dissertation.","vi":"Cuộc phỏng vấn trở thành nguồn sơ cấp cho luận văn của cô."}]', '[]', NULL, '/ˈpraɪmeri sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 105, 'primary task', 'nhiệm vụ chính', 'adj + n', '[{"en":"The primary task of the committee is reviewing applications.","vi":"Nhiệm vụ chính của ủy ban là xem xét các đơn đăng ký."},{"en":"His primary task was to translate the documents accurately.","vi":"Nhiệm vụ chính của anh là dịch các tài liệu một cách chính xác."},{"en":"Our primary task this week is testing the new software.","vi":"Nhiệm vụ chính của chúng tôi tuần này là kiểm thử phần mềm mới."}]', '[]', NULL, '/ˈpraɪmeri tæsk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 106, 'prime example', 'ví dụ điển hình', 'adj + n', '[{"en":"This city is a prime example of rapid urban growth.","vi":"Thành phố này là ví dụ điển hình của sự phát triển đô thị nhanh chóng."},{"en":"Her speech offered a prime example of persuasive writing.","vi":"Bài phát biểu của cô là ví dụ điển hình của lối viết thuyết phục."},{"en":"The reform is a prime example of successful public policy.","vi":"Cuộc cải cách là ví dụ điển hình của chính sách công thành công."}]', '[]', NULL, '/praɪm ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 107, 'prime time', 'khung giờ vàng', 'adj + n', '[{"en":"The debate was broadcast during prime time on national television.","vi":"Cuộc tranh luận được phát sóng vào khung giờ vàng trên truyền hình quốc gia."},{"en":"Advertising during prime time costs far more than late slots.","vi":"Quảng cáo vào khung giờ vàng tốn kém hơn nhiều so với khung giờ khuya."},{"en":"The popular show dominates prime time every weekday evening.","vi":"Chương trình nổi tiếng thống trị khung giờ vàng mỗi tối ngày thường."}]', '[]', NULL, '/praɪm taɪm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 108, 'principal source', 'nguồn chủ yếu', 'adj + n', '[{"en":"Coal was once the principal source of energy worldwide.","vi":"Than đá từng là nguồn năng lượng chủ yếu trên toàn thế giới."},{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chủ yếu của hòn đảo."},{"en":"Newspapers remain a principal source of local news for many.","vi":"Báo chí vẫn là nguồn tin tức địa phương chủ yếu với nhiều người."}]', '[]', NULL, '/ˈprɪnsəpəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 109, 'prior experience', 'kinh nghiệm trước đó', 'adj + n', '[{"en":"No prior experience is needed to join the workshop.","vi":"Không cần kinh nghiệm trước đó để tham gia hội thảo."},{"en":"Her prior experience in nursing helped during the crisis.","vi":"Kinh nghiệm điều dưỡng trước đó của cô đã giúp ích trong khủng hoảng."},{"en":"Applicants with prior experience are given strong preference.","vi":"Ứng viên có kinh nghiệm trước đó được ưu tiên rõ rệt."}]', '[]', NULL, '/ˈpraɪər ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 110, 'prior knowledge', 'kiến thức nền có sẵn', 'adj + n', '[{"en":"Learners connect new ideas to their prior knowledge.","vi":"Người học kết nối ý tưởng mới với kiến thức nền có sẵn của mình."},{"en":"The test assumes some prior knowledge of basic statistics.","vi":"Bài kiểm tra giả định có sẵn một số kiến thức cơ bản về thống kê."},{"en":"Teachers should assess students'' prior knowledge before each unit.","vi":"Giáo viên nên đánh giá kiến thức nền của học sinh trước mỗi bài."}]', '[]', NULL, '/ˈpraɪər ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 111, 'private individual', 'cá nhân riêng lẻ', 'adj + n', '[{"en":"A private individual donated the land to the city.","vi":"Một cá nhân riêng lẻ đã hiến tặng mảnh đất cho thành phố."},{"en":"The law protects a private individual''s personal data online.","vi":"Luật bảo vệ dữ liệu cá nhân của một cá nhân riêng lẻ trên mạng."},{"en":"Such loans are rarely available to a private individual.","vi":"Những khoản vay như vậy hiếm khi dành cho một cá nhân riêng lẻ."}]', '[]', NULL, '/ˈpraɪvət ˌɪndɪˈvɪdʒuəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 112, 'private investment', 'đầu tư tư nhân', 'adj + n', '[{"en":"Private investment in clean energy rose sharply last year.","vi":"Đầu tư tư nhân vào năng lượng sạch tăng mạnh năm ngoái."},{"en":"The government hopes to attract more private investment in transport.","vi":"Chính phủ hy vọng thu hút thêm đầu tư tư nhân vào giao thông."},{"en":"Private investment often complements public funding for large projects.","vi":"Đầu tư tư nhân thường bổ sung cho nguồn vốn công cho các dự án lớn."}]', '[]', NULL, '/ˈpraɪvət ɪnˈvestmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 113, 'private sector', 'khu vực tư nhân', 'adj + n', '[{"en":"Many graduates prefer jobs in the private sector.","vi":"Nhiều sinh viên tốt nghiệp thích công việc trong khu vực tư nhân."},{"en":"The private sector now delivers many former public services.","vi":"Khu vực tư nhân hiện cung cấp nhiều dịch vụ công trước đây."},{"en":"Wages in the private sector vary widely across industries.","vi":"Tiền lương trong khu vực tư nhân chênh lệch lớn giữa các ngành."}]', '[]', NULL, '/ˈpraɪvət ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 114, 'private sphere', 'lĩnh vực riêng tư', 'adj + n', '[{"en":"These decisions belong to the private sphere, not the state.","vi":"Những quyết định này thuộc lĩnh vực riêng tư, không phải của nhà nước."},{"en":"Historically, women were confined to the private sphere of home.","vi":"Trong lịch sử, phụ nữ bị giới hạn trong lĩnh vực riêng tư của gia đình."},{"en":"The book explores how technology invades the private sphere.","vi":"Cuốn sách khám phá cách công nghệ xâm phạm lĩnh vực riêng tư."}]', '[]', NULL, '/ˈpraɪvət sfɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 115, 'privileged position', 'vị thế đặc quyền', 'adj + n', '[{"en":"Wealthy families often enjoy a privileged position in society.","vi":"Các gia đình giàu có thường có vị thế đặc quyền trong xã hội."},{"en":"The bank holds a privileged position in the local economy.","vi":"Ngân hàng giữ vị thế đặc quyền trong nền kinh tế địa phương."},{"en":"Editors occupy a privileged position in shaping public opinion.","vi":"Các biên tập viên chiếm vị thế đặc quyền trong việc định hình dư luận."}]', '[]', NULL, '/ˈprɪvəlɪdʒd pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 116, 'problem area', 'lĩnh vực có vấn đề', 'n + n', '[{"en":"The audit identified several problem areas in the system.","vi":"Cuộc kiểm toán đã xác định một số lĩnh vực có vấn đề trong hệ thống."},{"en":"Traffic congestion is a major problem area for the city.","vi":"Tắc nghẽn giao thông là một lĩnh vực có vấn đề lớn của thành phố."},{"en":"The teacher focused revision on each student''s main problem areas.","vi":"Giáo viên tập trung ôn tập vào các lĩnh vực có vấn đề chính của từng học sinh."}]', '[]', NULL, '/ˈprɑːbləm ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 117, 'process data', 'xử lý dữ liệu', 'v + n', '[{"en":"The software can process data from thousands of sensors instantly.","vi":"Phần mềm có thể xử lý dữ liệu từ hàng nghìn cảm biến ngay lập tức."},{"en":"Analysts process data carefully before drawing any conclusions.","vi":"Các nhà phân tích xử lý dữ liệu cẩn thận trước khi rút ra kết luận."},{"en":"Companies must process data fairly under privacy law.","vi":"Các công ty phải xử lý dữ liệu một cách công bằng theo luật bảo mật."}]', '[]', NULL, '/ˈprɑːses ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 118, 'process information', 'xử lý thông tin', 'v + n', '[{"en":"The brain can process information remarkably quickly.","vi":"Não bộ có thể xử lý thông tin nhanh một cách đáng kinh ngạc."},{"en":"Children process information differently from adults in many tasks.","vi":"Trẻ em xử lý thông tin khác với người lớn trong nhiều nhiệm vụ."},{"en":"The system helps users process information from multiple sources.","vi":"Hệ thống giúp người dùng xử lý thông tin từ nhiều nguồn."}]', '[]', NULL, '/ˈprɑːses ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 119, 'professional activity', 'hoạt động nghề nghiệp', 'adj + n', '[{"en":"Teaching is the main professional activity recorded in her file.","vi":"Giảng dạy là hoạt động nghề nghiệp chính được ghi trong hồ sơ của cô."},{"en":"Conferences are an important professional activity for researchers.","vi":"Hội nghị là một hoạt động nghề nghiệp quan trọng đối với nhà nghiên cứu."},{"en":"The survey tracked the professional activity of recent graduates.","vi":"Khảo sát theo dõi hoạt động nghề nghiệp của sinh viên mới tốt nghiệp."}]', '[]', NULL, '/prəˈfeʃənəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 120, 'professional body', 'tổ chức nghề nghiệp', 'adj + n', '[{"en":"The professional body sets ethical standards for all members.","vi":"Tổ chức nghề nghiệp đặt ra các tiêu chuẩn đạo đức cho mọi thành viên."},{"en":"Engineers must register with the relevant professional body.","vi":"Các kỹ sư phải đăng ký với tổ chức nghề nghiệp liên quan."},{"en":"A professional body can revoke a member''s license for misconduct.","vi":"Tổ chức nghề nghiệp có thể thu hồi giấy phép của thành viên vì vi phạm."}]', '[]', NULL, '/prəˈfeʃənəl ˈbɑːdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 121, 'professional colleague', 'đồng nghiệp', 'adj + n', '[{"en":"She discussed the diagnosis with a professional colleague first.","vi":"Cô thảo luận chẩn đoán với một đồng nghiệp trước."},{"en":"Sharing ideas with a professional colleague improves your own work.","vi":"Chia sẻ ý tưởng với đồng nghiệp giúp cải thiện công việc của bạn."},{"en":"He praised a professional colleague for the careful analysis.","vi":"Anh khen ngợi một đồng nghiệp vì sự phân tích cẩn thận."}]', '[]', NULL, '/prəˈfeʃənəl ˈkɑːliːɡ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 122, 'professional development', 'phát triển nghề nghiệp', 'adj + n', '[{"en":"The school funds ongoing professional development for its teachers.","vi":"Trường tài trợ cho việc phát triển nghề nghiệp liên tục cho giáo viên."},{"en":"Professional development helps staff keep up with new methods.","vi":"Phát triển nghề nghiệp giúp nhân viên theo kịp các phương pháp mới."},{"en":"She attends workshops as part of her professional development.","vi":"Cô tham dự các hội thảo như một phần của việc phát triển nghề nghiệp."}]', '[]', NULL, '/prəˈfeʃənəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 123, 'professional experience', 'kinh nghiệm nghề nghiệp', 'adj + n', '[{"en":"Years of professional experience shaped his teaching style.","vi":"Nhiều năm kinh nghiệm nghề nghiệp đã định hình phong cách giảng dạy của ông."},{"en":"The internship gives students valuable professional experience early.","vi":"Kỳ thực tập mang lại cho sinh viên kinh nghiệm nghề nghiệp quý giá từ sớm."},{"en":"Employers value relevant professional experience over formal qualifications.","vi":"Nhà tuyển dụng coi trọng kinh nghiệm nghề nghiệp liên quan hơn bằng cấp chính thức."}]', '[]', NULL, '/prəˈfeʃənəl ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 124, 'professional knowledge', 'kiến thức chuyên môn', 'adj + n', '[{"en":"Doctors must constantly update their professional knowledge.","vi":"Bác sĩ phải liên tục cập nhật kiến thức chuyên môn của mình."},{"en":"Her deep professional knowledge made the report highly reliable.","vi":"Kiến thức chuyên môn sâu rộng của cô khiến báo cáo rất đáng tin cậy."},{"en":"The course builds professional knowledge through real case studies.","vi":"Khóa học xây dựng kiến thức chuyên môn qua các tình huống thực tế."}]', '[]', NULL, '/prəˈfeʃənəl ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 125, 'professional practice', 'hành nghề chuyên môn', 'adj + n', '[{"en":"Ethics guidelines shape everyday professional practice in medicine.","vi":"Hướng dẫn đạo đức định hình việc hành nghề chuyên môn hằng ngày trong y khoa."},{"en":"Reflection is central to improving one''s professional practice.","vi":"Sự tự suy ngẫm là cốt lõi để cải thiện việc hành nghề chuyên môn."},{"en":"The course connects academic theory with real professional practice.","vi":"Khóa học kết nối lý thuyết học thuật với việc hành nghề chuyên môn thực tế."}]', '[]', NULL, '/prəˈfeʃənəl ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 126, 'professional qualification', 'chứng chỉ hành nghề', 'adj + n', '[{"en":"The role requires a recognized professional qualification in accounting.","vi":"Vị trí này đòi hỏi một chứng chỉ hành nghề được công nhận về kế toán."},{"en":"She earned her professional qualification after three years of study.","vi":"Cô đạt được chứng chỉ hành nghề sau ba năm học tập."},{"en":"Some professional qualifications must be renewed every few years.","vi":"Một số chứng chỉ hành nghề phải được gia hạn vài năm một lần."}]', '[]', NULL, '/prəˈfeʃənəl ˌkwɑːləfəˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 127, 'professional staff', 'đội ngũ nhân viên chuyên môn', 'adj + n', '[{"en":"The clinic employs highly trained professional staff around the clock.","vi":"Phòng khám có đội ngũ nhân viên chuyên môn được đào tạo bài bản suốt ngày đêm."},{"en":"Professional staff handle inquiries that volunteers cannot answer.","vi":"Nhân viên chuyên môn xử lý các thắc mắc mà tình nguyện viên không thể trả lời."},{"en":"The university expanded its professional staff to support research.","vi":"Trường đại học mở rộng đội ngũ nhân viên chuyên môn để hỗ trợ nghiên cứu."}]', '[]', NULL, '/prəˈfeʃənəl stæf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 128, 'professional standard', 'chuẩn mực nghề nghiệp', 'adj + n', '[{"en":"All work must meet a high professional standard.","vi":"Mọi công việc phải đáp ứng chuẩn mực nghề nghiệp cao."},{"en":"Breaching the professional standard can lead to disciplinary action.","vi":"Vi phạm chuẩn mực nghề nghiệp có thể dẫn đến biện pháp kỷ luật."},{"en":"The association reviews its professional standards every five years.","vi":"Hiệp hội xem xét lại các chuẩn mực nghề nghiệp của mình năm năm một lần."}]', '[]', NULL, '/prəˈfeʃənəl ˈstændərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 129, 'professional status', 'địa vị nghề nghiệp', 'adj + n', '[{"en":"Gaining professional status often requires passing a formal exam.","vi":"Đạt được địa vị nghề nghiệp thường đòi hỏi phải vượt qua kỳ thi chính thức."},{"en":"The reform raised the professional status of nurses nationwide.","vi":"Cuộc cải cách nâng cao địa vị nghề nghiệp của y tá trên toàn quốc."},{"en":"Teachers fought hard to protect their professional status.","vi":"Giáo viên đấu tranh mạnh mẽ để bảo vệ địa vị nghề nghiệp của mình."}]', '[]', NULL, '/prəˈfeʃənəl ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 130, 'professional support', 'hỗ trợ chuyên môn', 'adj + n', '[{"en":"Patients receive professional support throughout their recovery.","vi":"Bệnh nhân nhận được hỗ trợ chuyên môn trong suốt quá trình hồi phục."},{"en":"New teachers benefit from professional support during their first year.","vi":"Giáo viên mới hưởng lợi từ hỗ trợ chuyên môn trong năm đầu tiên."},{"en":"The charity offers professional support to families in crisis.","vi":"Tổ chức từ thiện cung cấp hỗ trợ chuyên môn cho các gia đình gặp khủng hoảng."}]', '[]', NULL, '/prəˈfeʃənəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 131, 'professional training', 'đào tạo chuyên môn', 'adj + n', '[{"en":"The program offers professional training for future social workers.","vi":"Chương trình cung cấp đào tạo chuyên môn cho nhân viên xã hội tương lai."},{"en":"Without proper professional training, errors become far more likely.","vi":"Nếu không có đào tạo chuyên môn phù hợp, sai sót dễ xảy ra hơn nhiều."},{"en":"She completed her professional training at a leading hospital.","vi":"Cô hoàn thành đào tạo chuyên môn tại một bệnh viện hàng đầu."}]', '[]', NULL, '/prəˈfeʃənəl ˈtreɪnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 132, 'professional work', 'công việc chuyên môn', 'adj + n', '[{"en":"Her professional work spans both teaching and clinical research.","vi":"Công việc chuyên môn của cô trải dài cả giảng dạy lẫn nghiên cứu lâm sàng."},{"en":"He balances professional work with caring for his family.","vi":"Anh cân bằng công việc chuyên môn với việc chăm sóc gia đình."},{"en":"The exhibition displays professional work by emerging architects.","vi":"Triển lãm trưng bày công việc chuyên môn của các kiến trúc sư mới nổi."}]', '[]', NULL, '/prəˈfeʃənəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 133, 'profound effect', 'ảnh hưởng sâu sắc', 'adj + n', '[{"en":"The new policy had a profound effect on rural communities.","vi":"Chính sách mới có ảnh hưởng sâu sắc đến các cộng đồng nông thôn."},{"en":"Early childhood experiences have a profound effect on development.","vi":"Trải nghiệm thời thơ ấu có ảnh hưởng sâu sắc đến sự phát triển."},{"en":"Her mentor''s advice had a profound effect on her career.","vi":"Lời khuyên của người cố vấn có ảnh hưởng sâu sắc đến sự nghiệp của cô."}]', '[]', NULL, '/prəˈfaʊnd ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 134, 'profound impact', 'tác động sâu sắc', 'adj + n', '[{"en":"The internet has had a profound impact on daily life.","vi":"Internet đã có tác động sâu sắc đến cuộc sống hằng ngày."},{"en":"Climate change is expected to have a profound impact globally.","vi":"Biến đổi khí hậu được dự đoán sẽ có tác động sâu sắc trên toàn cầu."},{"en":"The reform had a profound impact on how schools operate.","vi":"Cuộc cải cách có tác động sâu sắc đến cách các trường vận hành."}]', '[]', NULL, '/prəˈfaʊnd ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 135, 'prominent feature', 'đặc điểm nổi bật', 'adj + n', '[{"en":"The tower is a prominent feature of the city skyline.","vi":"Tòa tháp là đặc điểm nổi bật của đường chân trời thành phố."},{"en":"Repetition is a prominent feature of the poet''s style.","vi":"Sự lặp lại là đặc điểm nổi bật trong phong cách của nhà thơ."},{"en":"Strong color contrast is a prominent feature of her paintings.","vi":"Sự tương phản màu mạnh mẽ là đặc điểm nổi bật trong tranh của cô."}]', '[]', NULL, '/ˈprɑːmɪnənt ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 136, 'prominent member', 'thành viên nổi bật', 'adj + n', '[{"en":"She was a prominent member of the research committee.","vi":"Bà là một thành viên nổi bật của ủy ban nghiên cứu."},{"en":"He became a prominent member of the local business community.","vi":"Ông trở thành một thành viên nổi bật của cộng đồng doanh nghiệp địa phương."},{"en":"Several prominent members of the party opposed the new bill.","vi":"Một số thành viên nổi bật của đảng phản đối dự luật mới."}]', '[]', NULL, '/ˈprɑːmɪnənt ˈmembər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 137, 'prominent role', 'vai trò nổi bật', 'adj + n', '[{"en":"Women played a prominent role in the social movement.","vi":"Phụ nữ đóng vai trò nổi bật trong phong trào xã hội."},{"en":"Technology now plays a prominent role in modern teaching.","vi":"Công nghệ ngày nay đóng vai trò nổi bật trong giảng dạy hiện đại."},{"en":"The charity took a prominent role in the relief effort.","vi":"Tổ chức từ thiện đóng vai trò nổi bật trong nỗ lực cứu trợ."}]', '[]', NULL, '/ˈprɑːmɪnənt roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 138, 'promote equality', 'thúc đẩy bình đẳng', 'v + n', '[{"en":"The new law aims to promote equality in the workplace.","vi":"Luật mới nhằm thúc đẩy bình đẳng tại nơi làm việc."},{"en":"Schools can promote equality by treating all students fairly.","vi":"Trường học có thể thúc đẩy bình đẳng bằng cách đối xử công bằng với mọi học sinh."},{"en":"The campaign was designed to promote equality between the sexes.","vi":"Chiến dịch được thiết kế để thúc đẩy bình đẳng giữa hai giới."}]', '[]', NULL, '/prəˈmoʊt ɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 139, 'promote the development of', 'thúc đẩy sự phát triển của', 'v + n', '[{"en":"These programs promote the development of critical thinking skills.","vi":"Các chương trình này thúc đẩy sự phát triển của kỹ năng tư duy phản biện."},{"en":"Funding helps promote the development of renewable energy sources.","vi":"Nguồn vốn giúp thúc đẩy sự phát triển của các nguồn năng lượng tái tạo."},{"en":"Good nutrition can promote the development of healthy children.","vi":"Dinh dưỡng tốt có thể thúc đẩy sự phát triển của trẻ em khỏe mạnh."}]', '[]', NULL, '/prəˈmoʊt ðə dɪˈveləpmənt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 140, 'properly understood', 'được hiểu đúng đắn', 'adv + vpp', '[{"en":"When properly understood, the theory explains many observations.","vi":"Khi được hiểu đúng đắn, lý thuyết này giải thích nhiều quan sát."},{"en":"The risks must be properly understood before any decision.","vi":"Các rủi ro phải được hiểu đúng đắn trước khi đưa ra quyết định nào."},{"en":"Properly understood, the data point to a clear trend.","vi":"Nếu được hiểu đúng đắn, dữ liệu chỉ ra một xu hướng rõ ràng."}]', '[]', NULL, '/ˈprɑːpərli ˌʌndərˈstʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 141, 'proposed legislation', 'dự thảo luật', 'adj + n', '[{"en":"The proposed legislation would tighten rules on data privacy.","vi":"Dự thảo luật sẽ siết chặt các quy định về quyền riêng tư dữ liệu."},{"en":"Critics argue the proposed legislation could harm small businesses.","vi":"Các nhà phê bình cho rằng dự thảo luật có thể gây hại cho doanh nghiệp nhỏ."},{"en":"The committee will review the proposed legislation next week.","vi":"Ủy ban sẽ xem xét dự thảo luật vào tuần tới."}]', '[]', NULL, '/prəˈpoʊzd ˌledʒɪsˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 142, 'prove successful', 'tỏ ra thành công', 'v + adj', '[{"en":"The new strategy is likely to prove successful over time.","vi":"Chiến lược mới có khả năng tỏ ra thành công theo thời gian."},{"en":"If the trial proves successful, the drug will be approved.","vi":"Nếu thử nghiệm tỏ ra thành công, loại thuốc sẽ được phê duyệt."},{"en":"The pilot scheme proved successful and was quickly expanded.","vi":"Chương trình thí điểm tỏ ra thành công và nhanh chóng được mở rộng."}]', '[]', NULL, '/pruːv səkˈsesfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 143, 'prove useful', 'tỏ ra hữu ích', 'v + adj', '[{"en":"These notes may prove useful when you revise later.","vi":"Những ghi chú này có thể tỏ ra hữu ích khi bạn ôn lại sau."},{"en":"The model proved useful for predicting seasonal demand.","vi":"Mô hình tỏ ra hữu ích trong việc dự đoán nhu cầu theo mùa."},{"en":"Her language skills proved useful during the field study.","vi":"Kỹ năng ngôn ngữ của cô tỏ ra hữu ích trong chuyến nghiên cứu thực địa."}]', '[]', NULL, '/pruːv ˈjuːsfəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 144, 'provide access to', 'cung cấp quyền truy cập đến', 'v + n', '[{"en":"The library aims to provide access to digital archives.","vi":"Thư viện hướng tới cung cấp quyền truy cập đến kho lưu trữ số."},{"en":"The program provides access to clean water in rural areas.","vi":"Chương trình cung cấp khả năng tiếp cận nước sạch ở vùng nông thôn."},{"en":"Scholarships provide access to higher education for low-income students.","vi":"Học bổng cung cấp cơ hội tiếp cận giáo dục đại học cho sinh viên thu nhập thấp."}]', '[]', NULL, '/prəˈvaɪd ˈækses tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 145, 'provide assistance', 'cung cấp sự hỗ trợ', 'v + n', '[{"en":"Volunteers provide assistance to families affected by the flood.","vi":"Tình nguyện viên cung cấp sự hỗ trợ cho các gia đình bị ảnh hưởng bởi lũ."},{"en":"The office provides assistance to students with disabilities.","vi":"Văn phòng cung cấp sự hỗ trợ cho sinh viên khuyết tật."},{"en":"International agencies provide assistance during humanitarian crises.","vi":"Các cơ quan quốc tế cung cấp sự hỗ trợ trong khủng hoảng nhân đạo."}]', '[]', NULL, '/prəˈvaɪd əˈsɪstəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 146, 'provide care', 'cung cấp sự chăm sóc', 'v + n', '[{"en":"Nurses provide care for patients throughout the night.","vi":"Y tá cung cấp sự chăm sóc cho bệnh nhân suốt đêm."},{"en":"The charity provides care for elderly people living alone.","vi":"Tổ chức từ thiện cung cấp sự chăm sóc cho người già sống một mình."},{"en":"Family members often provide care without any formal training.","vi":"Các thành viên gia đình thường cung cấp sự chăm sóc mà không được đào tạo chính thức."}]', '[]', NULL, '/prəˈvaɪd ker/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 147, 'provide context', 'cung cấp bối cảnh', 'v + n', '[{"en":"The introduction provides context for the entire argument.","vi":"Phần mở đầu cung cấp bối cảnh cho toàn bộ lập luận."},{"en":"Historical examples provide context for current political debates.","vi":"Các ví dụ lịch sử cung cấp bối cảnh cho các cuộc tranh luận chính trị hiện nay."},{"en":"A short summary can provide context for new readers.","vi":"Một bản tóm tắt ngắn có thể cung cấp bối cảnh cho độc giả mới."}]', '[]', NULL, '/prəˈvaɪd ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 148, 'provide coverage', 'cung cấp sự bao phủ', 'v + n', '[{"en":"The policy provides coverage for both accidents and illness.","vi":"Chính sách cung cấp sự bảo hiểm cho cả tai nạn lẫn bệnh tật."},{"en":"New towers provide coverage to previously unconnected rural areas.","vi":"Các cột phát sóng mới cung cấp sự phủ sóng cho vùng nông thôn trước đây chưa kết nối."},{"en":"The network struggles to provide coverage in mountainous regions.","vi":"Mạng lưới gặp khó khăn trong việc cung cấp phủ sóng ở vùng núi."}]', '[]', NULL, '/prəˈvaɪd ˈkʌvərɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 149, 'provide data', 'cung cấp dữ liệu', 'v + n', '[{"en":"The sensors provide data on temperature and humidity continuously.","vi":"Các cảm biến cung cấp dữ liệu về nhiệt độ và độ ẩm liên tục."},{"en":"Participants agreed to provide data for the long-term study.","vi":"Người tham gia đồng ý cung cấp dữ liệu cho nghiên cứu dài hạn."},{"en":"The census provides data used by planners and researchers.","vi":"Cuộc điều tra dân số cung cấp dữ liệu cho các nhà quy hoạch và nghiên cứu."}]', '[]', NULL, '/prəˈvaɪd ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-12-01', 150, 'provide details', 'cung cấp chi tiết', 'v + n', '[{"en":"Please provide details of your previous work experience.","vi":"Vui lòng cung cấp chi tiết về kinh nghiệm làm việc trước đây của bạn."},{"en":"The report fails to provide details about the methodology.","vi":"Báo cáo không cung cấp chi tiết về phương pháp luận."},{"en":"The website provides details on opening hours and fees.","vi":"Trang web cung cấp chi tiết về giờ mở cửa và phí."}]', '[]', NULL, '/prəˈvaɪd ˈdiːteɪlz/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-13-01', 'colloc-13', 'Cụm học thuật · Nhóm 13', 'Academic Collocation List (Pearson/PTE) — nhóm 13 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 1, 'provide evidence', 'cung cấp bằng chứng', 'v + n', '[{"en":"The study provides evidence that exercise improves memory.","vi":"Nghiên cứu cung cấp bằng chứng rằng tập thể dục cải thiện trí nhớ."},{"en":"You must provide evidence to support every claim you make.","vi":"Bạn phải cung cấp bằng chứng để hỗ trợ cho mọi khẳng định của mình."},{"en":"Fossils provide evidence of life from millions of years ago.","vi":"Hóa thạch cung cấp bằng chứng về sự sống từ hàng triệu năm trước."}]', '[]', NULL, '/prəˈvaɪd ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 2, 'provide feedback', 'đưa ra phản hồi', 'v + n', '[{"en":"The tutor will provide feedback on your draft next week.","vi":"Người hướng dẫn sẽ đưa ra phản hồi về bản nháp của bạn tuần tới."},{"en":"Managers should provide feedback that is specific and constructive.","vi":"Quản lý nên đưa ra phản hồi cụ thể và mang tính xây dựng."},{"en":"Students are encouraged to provide feedback on the course.","vi":"Sinh viên được khuyến khích đưa ra phản hồi về khóa học."}]', '[]', NULL, '/prəˈvaɪd ˈfiːdbæk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 3, 'provide guidance', 'đưa ra sự hướng dẫn', 'v + n', '[{"en":"The handbook provides guidance for new staff members.","vi":"Cuốn sổ tay đưa ra sự hướng dẫn cho các nhân viên mới."},{"en":"Mentors provide guidance to students throughout their final year.","vi":"Người cố vấn đưa ra sự hướng dẫn cho sinh viên suốt năm cuối."},{"en":"The agency provides guidance on applying for research grants.","vi":"Cơ quan đưa ra sự hướng dẫn về việc xin tài trợ nghiên cứu."}]', '[]', NULL, '/prəˈvaɪd ˈɡaɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 4, 'provide information', 'cung cấp thông tin', 'v + n', '[{"en":"The leaflet provides information about local health services.","vi":"Tờ rơi cung cấp thông tin về các dịch vụ y tế địa phương."},{"en":"Witnesses agreed to provide information to the investigators.","vi":"Các nhân chứng đồng ý cung cấp thông tin cho các điều tra viên."},{"en":"The website provides information on visa requirements for travelers.","vi":"Trang web cung cấp thông tin về yêu cầu thị thực cho khách du lịch."}]', '[]', NULL, '/prəˈvaɪd ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 5, 'provide insight into', 'mang lại hiểu biết sâu về', 'v + n', '[{"en":"The interviews provide insight into how patients cope daily.","vi":"Các cuộc phỏng vấn mang lại hiểu biết sâu về cách bệnh nhân xoay xở hằng ngày."},{"en":"These letters provide insight into life during the war.","vi":"Những lá thư này mang lại hiểu biết sâu về cuộc sống thời chiến."},{"en":"The data provide insight into changing consumer habits.","vi":"Dữ liệu mang lại hiểu biết sâu về thói quen tiêu dùng đang thay đổi."}]', '[]', NULL, '/prəˈvaɪd ˈɪnsaɪt ˈɪntə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 6, 'provide material', 'cung cấp tài liệu', 'v + n', '[{"en":"The archive provides material for students researching local history.","vi":"Kho lưu trữ cung cấp tài liệu cho sinh viên nghiên cứu lịch sử địa phương."},{"en":"These case studies provide material for classroom discussion.","vi":"Các tình huống nghiên cứu này cung cấp tài liệu cho thảo luận trên lớp."},{"en":"The publisher will provide material for the new textbook.","vi":"Nhà xuất bản sẽ cung cấp tài liệu cho cuốn giáo trình mới."}]', '[]', NULL, '/prəˈvaɪd məˈtɪriəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 7, 'provide resources', 'cung cấp nguồn lực', 'v + n', '[{"en":"The government provides resources for schools in poorer regions.","vi":"Chính phủ cung cấp nguồn lực cho các trường ở vùng nghèo hơn."},{"en":"The platform provides resources for teachers planning online lessons.","vi":"Nền tảng cung cấp nguồn lực cho giáo viên lên kế hoạch bài học trực tuyến."},{"en":"Donors provide resources that keep the clinic running.","vi":"Các nhà tài trợ cung cấp nguồn lực giúp phòng khám duy trì hoạt động."}]', '[]', NULL, '/prəˈvaɪd ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 8, 'provide support', 'cung cấp sự hỗ trợ', 'v + n', '[{"en":"The university provides support for students facing financial hardship.","vi":"Trường đại học cung cấp sự hỗ trợ cho sinh viên gặp khó khăn tài chính."},{"en":"Counselors provide support to anyone struggling with stress.","vi":"Cố vấn cung cấp sự hỗ trợ cho bất kỳ ai đang vật lộn với căng thẳng."},{"en":"Family and friends provide support during difficult times.","vi":"Gia đình và bạn bè cung cấp sự hỗ trợ trong những lúc khó khăn."}]', '[]', NULL, '/prəˈvaɪd səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 9, 'provide a benefit', 'mang lại lợi ích', 'v + n', '[{"en":"Regular exercise can provide a benefit to mental health.","vi":"Tập thể dục đều đặn có thể mang lại lợi ích cho sức khỏe tinh thần."},{"en":"The new system provides a benefit to both staff and customers.","vi":"Hệ thống mới mang lại lợi ích cho cả nhân viên lẫn khách hàng."},{"en":"Even small changes can provide a benefit over time.","vi":"Ngay cả những thay đổi nhỏ cũng có thể mang lại lợi ích theo thời gian."}]', '[]', NULL, '/prəˈvaɪd ə ˈbenɪfɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 10, 'provide a clue', 'đưa ra một manh mối', 'v + n', '[{"en":"The fingerprints provided a clue to the suspect''s identity.","vi":"Dấu vân tay đưa ra một manh mối về danh tính nghi phạm."},{"en":"Word choice can provide a clue to the author''s attitude.","vi":"Cách chọn từ có thể đưa ra một manh mối về thái độ của tác giả."},{"en":"These ancient tools provide a clue about early human life.","vi":"Những công cụ cổ này đưa ra một manh mối về đời sống con người thuở sơ khai."}]', '[]', NULL, '/prəˈvaɪd ə kluː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 11, 'provide a focus', 'tạo một trọng tâm', 'v + n', '[{"en":"A clear question provides a focus for the whole essay.","vi":"Một câu hỏi rõ ràng tạo một trọng tâm cho toàn bộ bài luận."},{"en":"The festival provides a focus for community life each summer.","vi":"Lễ hội tạo một trọng tâm cho đời sống cộng đồng mỗi mùa hè."},{"en":"Setting goals provides a focus for the team''s daily work.","vi":"Việc đặt mục tiêu tạo một trọng tâm cho công việc hằng ngày của nhóm."}]', '[]', NULL, '/prəˈvaɪd ə ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 12, 'provide a foundation for', 'tạo nền tảng cho', 'v + n', '[{"en":"Early reading skills provide a foundation for later learning.","vi":"Kỹ năng đọc sớm tạo nền tảng cho việc học sau này."},{"en":"These findings provide a foundation for further research in the area.","vi":"Những phát hiện này tạo nền tảng cho nghiên cứu sâu hơn trong lĩnh vực này."},{"en":"Trust provides a foundation for any successful working relationship.","vi":"Sự tin tưởng tạo nền tảng cho bất kỳ mối quan hệ làm việc thành công nào."}]', '[]', NULL, '/prəˈvaɪd ə faʊnˈdeɪʃən fər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 13, 'provide a service', 'cung cấp một dịch vụ', 'v + n', '[{"en":"The hospital aims to provide a service that meets local needs.","vi":"Bệnh viện hướng tới cung cấp một dịch vụ đáp ứng nhu cầu địa phương."},{"en":"Companies must provide a service that customers genuinely value.","vi":"Các công ty phải cung cấp một dịch vụ mà khách hàng thực sự coi trọng."},{"en":"Volunteers provide a service free of charge to the community.","vi":"Tình nguyện viên cung cấp một dịch vụ miễn phí cho cộng đồng."}]', '[]', NULL, '/prəˈvaɪd ə ˈsɜːrvəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 14, 'provide a source', 'cung cấp một nguồn', 'v + n', '[{"en":"Interviews provide a source of rich qualitative data for analysis.","vi":"Các cuộc phỏng vấn cung cấp một nguồn dữ liệu định tính phong phú để phân tích."},{"en":"These archives provide a source of valuable historical evidence.","vi":"Các kho lưu trữ này cung cấp một nguồn bằng chứng lịch sử quý giá."},{"en":"The river provides a source of water for nearby farms.","vi":"Con sông cung cấp một nguồn nước cho các trang trại gần đó."}]', '[]', NULL, '/prəˈvaɪd ə ˈsɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 15, 'provide a summary', 'đưa ra một bản tóm tắt', 'v + n', '[{"en":"The abstract should provide a summary of the entire study.","vi":"Phần tóm lược nên đưa ra một bản tóm tắt của toàn bộ nghiên cứu."},{"en":"Please provide a summary of your main findings on this page.","vi":"Vui lòng đưa ra một bản tóm tắt các phát hiện chính ở trang này."},{"en":"The report provides a summary before discussing the details.","vi":"Bản báo cáo đưa ra một bản tóm tắt trước khi thảo luận chi tiết."}]', '[]', NULL, '/prəˈvaɪd ə ˈsʌməri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 16, 'provide an alternative', 'đưa ra một lựa chọn thay thế', 'v + n', '[{"en":"The author provides an alternative to the standard explanation.","vi":"Tác giả đưa ra một lựa chọn thay thế cho cách giải thích tiêu chuẩn."},{"en":"Solar power provides an alternative to fossil fuels in cities.","vi":"Năng lượng mặt trời đưa ra một lựa chọn thay thế nhiên liệu hóa thạch ở thành phố."},{"en":"This method provides an alternative when resources are limited.","vi":"Phương pháp này đưa ra một lựa chọn thay thế khi nguồn lực hạn chế."}]', '[]', NULL, '/prəˈvaɪd ən ɔːlˈtɜːrnətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 17, 'provide an example', 'đưa ra một ví dụ', 'v + n', '[{"en":"The lecturer provided an example to clarify the abstract concept.","vi":"Giảng viên đã đưa ra một ví dụ để làm rõ khái niệm trừu tượng."},{"en":"Can you provide an example that supports your argument here?","vi":"Bạn có thể đưa ra một ví dụ ủng hộ lập luận của mình không?"},{"en":"The textbook provides an example after each new definition.","vi":"Sách giáo khoa đưa ra một ví dụ sau mỗi định nghĩa mới."}]', '[]', NULL, '/prəˈvaɪd ən ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 18, 'provide an explanation', 'đưa ra một lời giải thích', 'v + n', '[{"en":"The study provides an explanation for the unexpected results.","vi":"Nghiên cứu đưa ra một lời giải thích cho những kết quả bất ngờ."},{"en":"Teachers should provide an explanation that students can follow.","vi":"Giáo viên nên đưa ra một lời giải thích mà học sinh có thể theo kịp."},{"en":"He provided an explanation for his absence from the meeting.","vi":"Anh ấy đưa ra một lời giải thích cho việc vắng mặt tại cuộc họp."}]', '[]', NULL, '/prəˈvaɪd ən ˌekspləˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 19, 'provide an illustration', 'đưa ra một minh họa', 'v + n', '[{"en":"The case study provides an illustration of the theory in practice.","vi":"Nghiên cứu tình huống đưa ra một minh họa cho lý thuyết trong thực tế."},{"en":"This diagram provides an illustration of the whole process clearly.","vi":"Sơ đồ này đưa ra một minh họa rõ ràng về toàn bộ quá trình."},{"en":"The author provides an illustration to make the point concrete.","vi":"Tác giả đưa ra một minh họa để làm cho ý tưởng trở nên cụ thể."}]', '[]', NULL, '/prəˈvaɪd ən ˌɪləˈstreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 20, 'provide an indication of', 'cho thấy một dấu hiệu về', 'v + n', '[{"en":"These figures provide an indication of the project''s overall success.","vi":"Những con số này cho thấy một dấu hiệu về thành công chung của dự án."},{"en":"Test scores provide an indication of how students are progressing.","vi":"Điểm kiểm tra cho thấy một dấu hiệu về cách học sinh đang tiến bộ."},{"en":"The survey provides an indication of public opinion on the issue.","vi":"Cuộc khảo sát cho thấy một dấu hiệu về ý kiến công chúng về vấn đề này."}]', '[]', NULL, '/prəˈvaɪd ən ˌɪndɪˈkeɪʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 21, 'provide an opportunity', 'tạo ra một cơ hội', 'v + n', '[{"en":"Internships provide an opportunity to apply classroom knowledge practically.","vi":"Thực tập tạo ra một cơ hội để áp dụng kiến thức trên lớp vào thực tế."},{"en":"The conference provides an opportunity to meet leading researchers.","vi":"Hội nghị tạo ra một cơ hội để gặp gỡ các nhà nghiên cứu hàng đầu."},{"en":"Studying abroad provides an opportunity to learn a new language.","vi":"Du học tạo ra một cơ hội để học một ngôn ngữ mới."}]', '[]', NULL, '/prəˈvaɪd ən ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 22, 'provide an overview of', 'cung cấp một cái nhìn tổng quan về', 'v + n', '[{"en":"This chapter provides an overview of the major theories involved.","vi":"Chương này cung cấp một cái nhìn tổng quan về các lý thuyết chính liên quan."},{"en":"The introduction provides an overview of the entire research field.","vi":"Phần mở đầu cung cấp một cái nhìn tổng quan về toàn bộ lĩnh vực nghiên cứu."},{"en":"Let me provide an overview of the steps before we begin.","vi":"Hãy để mình cung cấp một cái nhìn tổng quan về các bước trước khi bắt đầu."}]', '[]', NULL, '/prəˈvaɪd ən ˈoʊvərvjuː əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 23, 'public access', 'quyền tiếp cận công cộng', 'adj + n', '[{"en":"The new law guarantees public access to government records.","vi":"Luật mới đảm bảo quyền tiếp cận công cộng đối với hồ sơ chính phủ."},{"en":"The park offers public access to the riverside walking trails.","vi":"Công viên mở quyền tiếp cận công cộng tới các lối đi bộ ven sông."},{"en":"Researchers fought to ensure public access to the data set.","vi":"Các nhà nghiên cứu đấu tranh để đảm bảo quyền tiếp cận công cộng với tập dữ liệu."}]', '[]', NULL, '/ˈpʌblɪk ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 24, 'public administration', 'hành chính công', 'adj + n', '[{"en":"She studies public administration and the reform of local government.","vi":"Cô ấy nghiên cứu hành chính công và việc cải cách chính quyền địa phương."},{"en":"Efficient public administration is essential for delivering basic services.","vi":"Hành chính công hiệu quả là điều thiết yếu để cung cấp dịch vụ cơ bản."},{"en":"The course covers public administration in developing countries.","vi":"Khóa học bao quát hành chính công ở các nước đang phát triển."}]', '[]', NULL, '/ˈpʌblɪk ədˌmɪnəˈstreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 25, 'public attitudes', 'thái độ của công chúng', 'adj + n', '[{"en":"The survey tracked public attitudes toward climate change over time.","vi":"Cuộc khảo sát theo dõi thái độ của công chúng đối với biến đổi khí hậu theo thời gian."},{"en":"Public attitudes to immigration have shifted in recent decades.","vi":"Thái độ của công chúng với nhập cư đã thay đổi trong những thập kỷ gần đây."},{"en":"Media coverage can strongly influence public attitudes on policy.","vi":"Đưa tin trên truyền thông có thể tác động mạnh đến thái độ của công chúng về chính sách."}]', '[]', NULL, '/ˈpʌblɪk ˈætətuːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 26, 'public authority', 'cơ quan công quyền', 'adj + n', '[{"en":"Each public authority must publish its annual spending report.","vi":"Mỗi cơ quan công quyền phải công bố báo cáo chi tiêu hàng năm."},{"en":"The decision was challenged before the relevant public authority.","vi":"Quyết định này bị khiếu nại trước cơ quan công quyền liên quan."},{"en":"A public authority is accountable to the citizens it serves.","vi":"Một cơ quan công quyền phải chịu trách nhiệm trước những công dân mà nó phục vụ."}]', '[]', NULL, '/ˈpʌblɪk əˈθɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 27, 'public awareness', 'nhận thức của công chúng', 'adj + n', '[{"en":"The campaign aims to raise public awareness of mental health issues.","vi":"Chiến dịch nhằm nâng cao nhận thức của công chúng về vấn đề sức khỏe tâm thần."},{"en":"Greater public awareness led to changes in recycling habits.","vi":"Nhận thức của công chúng cao hơn dẫn đến thay đổi thói quen tái chế."},{"en":"Schools play a key role in building public awareness early.","vi":"Trường học đóng vai trò quan trọng trong việc xây dựng nhận thức của công chúng từ sớm."}]', '[]', NULL, '/ˈpʌblɪk əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 28, 'public debate', 'cuộc tranh luận công khai', 'adj + n', '[{"en":"The proposal sparked a heated public debate across the nation.","vi":"Đề xuất này đã châm ngòi một cuộc tranh luận công khai sôi nổi trên cả nước."},{"en":"Open public debate is vital for a healthy democracy to thrive.","vi":"Tranh luận công khai cởi mở là thiết yếu để một nền dân chủ lành mạnh phát triển."},{"en":"Scientists joined the public debate about renewable energy policy.","vi":"Các nhà khoa học tham gia cuộc tranh luận công khai về chính sách năng lượng tái tạo."}]', '[]', NULL, '/ˈpʌblɪk dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 29, 'public discourse', 'diễn ngôn công cộng', 'adj + n', '[{"en":"Social media has transformed the nature of public discourse today.","vi":"Mạng xã hội đã làm thay đổi bản chất của diễn ngôn công cộng ngày nay."},{"en":"The book analyses how language shapes public discourse on race.","vi":"Cuốn sách phân tích cách ngôn ngữ định hình diễn ngôn công cộng về chủng tộc."},{"en":"Politicians often dominate public discourse during election seasons.","vi":"Các chính trị gia thường chi phối diễn ngôn công cộng trong mùa bầu cử."}]', '[]', NULL, '/ˈpʌblɪk ˈdɪskɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 30, 'public display', 'sự phô bày công khai', 'adj + n', '[{"en":"The artifacts are on public display in the city museum.","vi":"Các hiện vật đang được phô bày công khai tại bảo tàng thành phố."},{"en":"Norms about public display of emotion vary across cultures.","vi":"Các chuẩn mực về sự phô bày cảm xúc công khai khác nhau giữa các nền văn hóa."},{"en":"A public display of support encouraged the protesting workers.","vi":"Sự phô bày ủng hộ công khai đã khích lệ những công nhân biểu tình."}]', '[]', NULL, '/ˈpʌblɪk dɪˈspleɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 31, 'public domain', 'phạm vi công cộng', 'adj + n', '[{"en":"Once copyright expires, a work enters the public domain freely.","vi":"Khi bản quyền hết hạn, một tác phẩm tự do bước vào phạm vi công cộng."},{"en":"These images are in the public domain and free to reuse.","vi":"Những hình ảnh này thuộc phạm vi công cộng và được tái sử dụng miễn phí."},{"en":"The report placed the findings in the public domain at last.","vi":"Bản báo cáo cuối cùng đã đưa các phát hiện vào phạm vi công cộng."}]', '[]', NULL, '/ˈpʌblɪk doʊˈmeɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 32, 'public expenditure', 'chi tiêu công', 'adj + n', '[{"en":"The government pledged to reduce public expenditure next year.","vi":"Chính phủ cam kết giảm chi tiêu công vào năm tới."},{"en":"Health and education account for most public expenditure here.","vi":"Y tế và giáo dục chiếm phần lớn chi tiêu công ở đây."},{"en":"Rising public expenditure put pressure on the national budget.","vi":"Chi tiêu công gia tăng tạo áp lực lên ngân sách quốc gia."}]', '[]', NULL, '/ˈpʌblɪk ɪkˈspendətʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 33, 'public funds', 'ngân quỹ công', 'adj + n', '[{"en":"The project was financed entirely from public funds last year.","vi":"Dự án được tài trợ hoàn toàn từ ngân quỹ công vào năm ngoái."},{"en":"Auditors check how public funds are spent on local services.","vi":"Kiểm toán viên kiểm tra cách ngân quỹ công được chi cho dịch vụ địa phương."},{"en":"Misuse of public funds led to a lengthy formal investigation.","vi":"Việc lạm dụng ngân quỹ công dẫn đến một cuộc điều tra chính thức kéo dài."}]', '[]', NULL, '/ˈpʌblɪk fʌndz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 34, 'public image', 'hình ảnh trước công chúng', 'adj + n', '[{"en":"The company worked hard to improve its public image after the scandal.","vi":"Công ty nỗ lực cải thiện hình ảnh trước công chúng sau vụ bê bối."},{"en":"A positive public image can attract both talent and investors.","vi":"Một hình ảnh tích cực trước công chúng có thể thu hút cả nhân tài lẫn nhà đầu tư."},{"en":"Politicians carefully manage their public image during campaigns.","vi":"Các chính trị gia cẩn thận quản lý hình ảnh trước công chúng trong các chiến dịch."}]', '[]', NULL, '/ˈpʌblɪk ˈɪmɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 35, 'public institution', 'thiết chế công', 'adj + n', '[{"en":"A university is a public institution that serves the wider society.","vi":"Trường đại học là một thiết chế công phục vụ cho xã hội rộng lớn hơn."},{"en":"Trust in public institutions has declined in many countries.","vi":"Niềm tin vào các thiết chế công đã suy giảm ở nhiều quốc gia."},{"en":"Every public institution must follow strict transparency rules.","vi":"Mọi thiết chế công đều phải tuân theo các quy tắc minh bạch nghiêm ngặt."}]', '[]', NULL, '/ˈpʌblɪk ˌɪnstəˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 36, 'public perception', 'cảm nhận của công chúng', 'adj + n', '[{"en":"Media coverage shaped public perception of the new vaccine quickly.","vi":"Đưa tin truyền thông nhanh chóng định hình cảm nhận của công chúng về vắc-xin mới."},{"en":"Public perception of risk often differs from expert assessments.","vi":"Cảm nhận của công chúng về rủi ro thường khác với đánh giá của chuyên gia."},{"en":"The study measured changes in public perception over six months.","vi":"Nghiên cứu đo lường những thay đổi trong cảm nhận của công chúng qua sáu tháng."}]', '[]', NULL, '/ˈpʌblɪk pərˈsepʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 37, 'public policy', 'chính sách công', 'adj + n', '[{"en":"Researchers hope their findings will inform future public policy.","vi":"Các nhà nghiên cứu hy vọng phát hiện của họ sẽ định hướng chính sách công tương lai."},{"en":"Public policy on housing varies widely between the two cities.","vi":"Chính sách công về nhà ở khác nhau rất nhiều giữa hai thành phố."},{"en":"She advises lawmakers on public policy related to education.","vi":"Cô ấy tư vấn cho các nhà lập pháp về chính sách công liên quan đến giáo dục."}]', '[]', NULL, '/ˈpʌblɪk ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 38, 'public sector', 'khu vực công', 'adj + n', '[{"en":"Many graduates seek stable employment in the public sector.","vi":"Nhiều sinh viên tốt nghiệp tìm kiếm việc làm ổn định trong khu vực công."},{"en":"Wages in the public sector rose slightly compared to last year.","vi":"Mức lương trong khu vực công tăng nhẹ so với năm ngoái."},{"en":"The reform reshaped how the public sector delivers its services.","vi":"Cuộc cải cách định hình lại cách khu vực công cung cấp dịch vụ."}]', '[]', NULL, '/ˈpʌblɪk ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 39, 'public sphere', 'không gian công cộng', 'adj + n', '[{"en":"Newspapers once dominated debate within the public sphere entirely.","vi":"Báo chí từng chi phối hoàn toàn tranh luận trong không gian công cộng."},{"en":"Women gradually gained a stronger voice in the public sphere.","vi":"Phụ nữ dần có tiếng nói mạnh mẽ hơn trong không gian công cộng."},{"en":"The internet has expanded the public sphere beyond national borders.","vi":"Internet đã mở rộng không gian công cộng vượt ra ngoài biên giới quốc gia."}]', '[]', NULL, '/ˈpʌblɪk sfɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 40, 'public transport', 'giao thông công cộng', 'adj + n', '[{"en":"Improving public transport could reduce traffic in the city center.","vi":"Cải thiện giao thông công cộng có thể giảm ùn tắc ở trung tâm thành phố."},{"en":"Many residents rely on public transport to reach their workplaces.","vi":"Nhiều cư dân phụ thuộc vào giao thông công cộng để đến nơi làm việc."},{"en":"Cheaper public transport encourages people to leave cars at home.","vi":"Giao thông công cộng rẻ hơn khuyến khích mọi người để xe ở nhà."}]', '[]', NULL, '/ˈpʌblɪk ˈtrænspɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 41, 'public welfare', 'phúc lợi công cộng', 'adj + n', '[{"en":"The policy was designed to protect public welfare during the crisis.","vi":"Chính sách được thiết kế để bảo vệ phúc lợi công cộng trong khủng hoảng."},{"en":"Governments must balance economic growth with public welfare needs.","vi":"Chính phủ phải cân bằng tăng trưởng kinh tế với nhu cầu phúc lợi công cộng."},{"en":"Critics argued the plan ignored long-term public welfare entirely.","vi":"Những người phê bình cho rằng kế hoạch hoàn toàn bỏ qua phúc lợi công cộng lâu dài."}]', '[]', NULL, '/ˈpʌblɪk ˈwelfer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 42, 'publicly available', 'công khai cho mọi người', 'adv + adj', '[{"en":"The full data set is now publicly available on the website.","vi":"Toàn bộ tập dữ liệu hiện đã được công khai cho mọi người trên trang web."},{"en":"Researchers prefer sources that are publicly available and verifiable.","vi":"Các nhà nghiên cứu thích những nguồn công khai cho mọi người và có thể kiểm chứng."},{"en":"These reports became publicly available after the new law passed.","vi":"Các báo cáo này trở nên công khai cho mọi người sau khi luật mới được thông qua."}]', '[]', NULL, '/ˈpʌblɪkli əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 43, 'publish research', 'công bố nghiên cứu', 'v + n', '[{"en":"Scholars must publish research regularly to advance their careers.","vi":"Các học giả phải công bố nghiên cứu thường xuyên để thăng tiến sự nghiệp."},{"en":"The team plans to publish research on the new treatment soon.","vi":"Nhóm dự định sớm công bố nghiên cứu về phương pháp điều trị mới."},{"en":"Universities encourage staff to publish research in leading journals.","vi":"Các trường đại học khuyến khích nhân viên công bố nghiên cứu trên tạp chí hàng đầu."}]', '[]', NULL, '/ˈpʌblɪʃ ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 44, 'publish a journal', 'xuất bản một tạp chí', 'v + n', '[{"en":"The society plans to publish a journal on environmental science.","vi":"Hội dự định xuất bản một tạp chí về khoa học môi trường."},{"en":"They publish a journal four times a year for members.","vi":"Họ xuất bản một tạp chí bốn lần mỗi năm cho các thành viên."},{"en":"The department decided to publish a journal entirely online.","vi":"Khoa quyết định xuất bản một tạp chí hoàn toàn trực tuyến."}]', '[]', NULL, '/ˈpʌblɪʃ ə ˈdʒɜːrnəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 45, 'publish a report', 'công bố một báo cáo', 'v + n', '[{"en":"The agency will publish a report on air quality next month.","vi":"Cơ quan này sẽ công bố một báo cáo về chất lượng không khí vào tháng tới."},{"en":"Researchers publish a report summarizing their findings each year.","vi":"Các nhà nghiên cứu công bố một báo cáo tóm tắt phát hiện của họ mỗi năm."},{"en":"The committee voted to publish a report before the deadline.","vi":"Ủy ban đã bỏ phiếu công bố một báo cáo trước thời hạn."}]', '[]', NULL, '/ˈpʌblɪʃ ə rɪˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 46, 'publish an article', 'đăng một bài báo', 'v + n', '[{"en":"She hopes to publish an article in a respected academic journal.","vi":"Cô ấy hy vọng đăng một bài báo trên một tạp chí học thuật uy tín."},{"en":"The newspaper agreed to publish an article on local pollution.","vi":"Tờ báo đồng ý đăng một bài báo về ô nhiễm địa phương."},{"en":"It can take months to publish an article after peer review.","vi":"Có thể mất nhiều tháng để đăng một bài báo sau khi bình duyệt."}]', '[]', NULL, '/ˈpʌblɪʃ ən ˈɑːrtɪkəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 47, 'published literature', 'tài liệu đã xuất bản', 'adj + n', '[{"en":"The review surveyed all published literature on childhood obesity.","vi":"Bài tổng quan khảo sát toàn bộ tài liệu đã xuất bản về béo phì ở trẻ em."},{"en":"Existing published literature offers little guidance on this topic.","vi":"Tài liệu đã xuất bản hiện có cung cấp rất ít hướng dẫn về chủ đề này."},{"en":"She compared her results with the wider published literature carefully.","vi":"Cô ấy cẩn thận so sánh kết quả với tài liệu đã xuất bản rộng hơn."}]', '[]', NULL, '/ˈpʌblɪʃt ˈlɪtərətʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 48, 'published material', 'tài liệu đã được công bố', 'adj + n', '[{"en":"The course relies heavily on recently published material for reading.","vi":"Khóa học dựa nhiều vào tài liệu đã được công bố gần đây để đọc."},{"en":"Students must cite all published material used in their essays.","vi":"Sinh viên phải trích dẫn mọi tài liệu đã được công bố dùng trong bài luận."},{"en":"The database collects published material from hundreds of sources.","vi":"Cơ sở dữ liệu thu thập tài liệu đã được công bố từ hàng trăm nguồn."}]', '[]', NULL, '/ˈpʌblɪʃt məˈtɪriəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 49, 'published research', 'nghiên cứu đã công bố', 'adj + n', '[{"en":"Her argument draws on a large body of published research.","vi":"Lập luận của cô dựa trên một khối lượng lớn nghiên cứu đã công bố."},{"en":"Published research on the topic remains surprisingly limited so far.","vi":"Nghiên cứu đã công bố về chủ đề này vẫn còn hạn chế đáng ngạc nhiên."},{"en":"We evaluated published research before designing our own experiment.","vi":"Chúng tôi đánh giá nghiên cứu đã công bố trước khi thiết kế thí nghiệm riêng."}]', '[]', NULL, '/ˈpʌblɪʃt ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 50, 'published work', 'công trình đã xuất bản', 'adj + n', '[{"en":"His published work has influenced researchers across several disciplines.","vi":"Công trình đã xuất bản của ông đã ảnh hưởng đến nhiều ngành nghiên cứu."},{"en":"The committee assessed each candidate''s published work very closely.","vi":"Ủy ban đánh giá rất kỹ công trình đã xuất bản của từng ứng viên."},{"en":"Most of her published work focuses on language acquisition.","vi":"Phần lớn công trình đã xuất bản của cô tập trung vào việc tiếp thu ngôn ngữ."}]', '[]', NULL, '/ˈpʌblɪʃt wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 51, 'purchasing power', 'sức mua', 'adj + n', '[{"en":"Rising inflation steadily eroded the purchasing power of households.","vi":"Lạm phát gia tăng làm xói mòn dần sức mua của các hộ gia đình."},{"en":"Higher wages increased the purchasing power of ordinary workers.","vi":"Mức lương cao hơn làm tăng sức mua của những người lao động bình thường."},{"en":"Economists compare purchasing power across countries using special indices.","vi":"Các nhà kinh tế so sánh sức mua giữa các nước bằng những chỉ số đặc biệt."}]', '[]', NULL, '/ˈpɜːrtʃəsɪŋ ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 52, 'qualitative analysis', 'phân tích định tính', 'adj + n', '[{"en":"The thesis combines qualitative analysis with detailed statistical modeling.","vi":"Luận văn kết hợp phân tích định tính với mô hình thống kê chi tiết."},{"en":"Qualitative analysis of the interviews revealed several recurring themes.","vi":"Phân tích định tính các cuộc phỏng vấn cho thấy vài chủ đề lặp lại."},{"en":"She used qualitative analysis to interpret the open-ended responses.","vi":"Cô ấy dùng phân tích định tính để diễn giải các câu trả lời mở."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 53, 'qualitative approach', 'phương pháp tiếp cận định tính', 'adj + n', '[{"en":"A qualitative approach suits research exploring lived human experience.","vi":"Phương pháp tiếp cận định tính phù hợp với nghiên cứu khám phá trải nghiệm con người."},{"en":"The author adopted a qualitative approach to study classroom behavior.","vi":"Tác giả áp dụng phương pháp tiếp cận định tính để nghiên cứu hành vi trong lớp."},{"en":"A qualitative approach can uncover meanings that numbers often miss.","vi":"Phương pháp tiếp cận định tính có thể khám phá ý nghĩa mà con số thường bỏ sót."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 54, 'qualitative data', 'dữ liệu định tính', 'adj + n', '[{"en":"The interviews generated rich qualitative data for the final report.","vi":"Các cuộc phỏng vấn tạo ra dữ liệu định tính phong phú cho báo cáo cuối."},{"en":"Coding qualitative data carefully takes considerable time and patience.","vi":"Mã hóa dữ liệu định tính cẩn thận đòi hỏi nhiều thời gian và kiên nhẫn."},{"en":"Qualitative data helped explain why the numbers looked so unusual.","vi":"Dữ liệu định tính giúp giải thích vì sao các con số trông bất thường."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 55, 'qualitative method', 'phương pháp định tính', 'adj + n', '[{"en":"She chose a qualitative method to explore students'' personal attitudes.","vi":"Cô ấy chọn một phương pháp định tính để khám phá thái độ cá nhân của học sinh."},{"en":"A qualitative method captures depth that surveys alone cannot reach.","vi":"Một phương pháp định tính nắm bắt chiều sâu mà chỉ khảo sát không thể đạt được."},{"en":"The study mixes a qualitative method with quantitative measurement tools.","vi":"Nghiên cứu kết hợp một phương pháp định tính với các công cụ đo lường định lượng."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 56, 'qualitative research', 'nghiên cứu định tính', 'adj + n', '[{"en":"Qualitative research often relies on interviews, observation, and case studies.","vi":"Nghiên cứu định tính thường dựa vào phỏng vấn, quan sát và nghiên cứu tình huống."},{"en":"Her qualitative research explored how patients cope with chronic illness.","vi":"Nghiên cứu định tính của cô khám phá cách bệnh nhân đối phó với bệnh mãn tính."},{"en":"Good qualitative research demands careful attention to participants'' words.","vi":"Nghiên cứu định tính tốt đòi hỏi chú ý kỹ đến lời nói của người tham gia."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 57, 'qualitative study', 'nghiên cứu định tính', 'adj + n', '[{"en":"The qualitative study followed ten families over an entire year.","vi":"Nghiên cứu định tính theo dõi mười gia đình trong suốt một năm."},{"en":"A qualitative study can reveal unexpected patterns in everyday behavior.","vi":"Một nghiên cứu định tính có thể tiết lộ những khuôn mẫu bất ngờ trong hành vi hàng ngày."},{"en":"They published a qualitative study based on detailed teacher interviews.","vi":"Họ công bố một nghiên cứu định tính dựa trên phỏng vấn giáo viên chi tiết."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪv ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 58, 'qualitatively different', 'khác biệt về chất', 'adv + adj', '[{"en":"The two approaches are qualitatively different, not merely a matter of degree.","vi":"Hai cách tiếp cận khác biệt về chất, không chỉ là vấn đề mức độ."},{"en":"Children''s reasoning becomes qualitatively different as they mature.","vi":"Lập luận của trẻ trở nên khác biệt về chất khi chúng trưởng thành."},{"en":"Online learning is qualitatively different from traditional classroom teaching.","vi":"Học trực tuyến khác biệt về chất so với giảng dạy truyền thống trên lớp."}]', '[]', NULL, '/ˈkwɑːlɪteɪtɪvli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 59, 'quantitative analysis', 'phân tích định lượng', 'adj + n', '[{"en":"Quantitative analysis confirmed a strong link between the two variables.","vi":"Phân tích định lượng xác nhận mối liên hệ chặt chẽ giữa hai biến."},{"en":"The report includes quantitative analysis of national survey results.","vi":"Bản báo cáo bao gồm phân tích định lượng kết quả khảo sát quốc gia."},{"en":"She performed quantitative analysis using specialized statistical software.","vi":"Cô ấy thực hiện phân tích định lượng bằng phần mềm thống kê chuyên dụng."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 60, 'quantitative approach', 'phương pháp tiếp cận định lượng', 'adj + n', '[{"en":"A quantitative approach allows researchers to test hypotheses with numbers.","vi":"Phương pháp tiếp cận định lượng cho phép nhà nghiên cứu kiểm định giả thuyết bằng số liệu."},{"en":"The team favored a quantitative approach to measure clear outcomes.","vi":"Nhóm ưa chuộng phương pháp tiếp cận định lượng để đo lường kết quả rõ ràng."},{"en":"A quantitative approach works best when large samples are available.","vi":"Phương pháp tiếp cận định lượng hiệu quả nhất khi có sẵn mẫu lớn."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 61, 'quantitative data', 'dữ liệu định lượng', 'adj + n', '[{"en":"The researchers collected quantitative data from thousands of survey responses.","vi":"Các nhà nghiên cứu thu thập dữ liệu định lượng từ hàng nghìn phản hồi khảo sát."},{"en":"Quantitative data can be summarized using means and standard deviations.","vi":"Dữ liệu định lượng có thể được tóm tắt bằng giá trị trung bình và độ lệch chuẩn."},{"en":"They analyzed quantitative data to detect trends across several years.","vi":"Họ phân tích dữ liệu định lượng để phát hiện xu hướng qua nhiều năm."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 62, 'quantitative method', 'phương pháp định lượng', 'adj + n', '[{"en":"A quantitative method lets researchers measure relationships between variables precisely.","vi":"Một phương pháp định lượng cho phép nhà nghiên cứu đo chính xác mối quan hệ giữa các biến."},{"en":"The course teaches a quantitative method for analyzing economic data.","vi":"Khóa học dạy một phương pháp định lượng để phân tích dữ liệu kinh tế."},{"en":"Many social scientists combine a quantitative method with interviews.","vi":"Nhiều nhà khoa học xã hội kết hợp một phương pháp định lượng với phỏng vấn."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 63, 'quantitative research', 'nghiên cứu định lượng', 'adj + n', '[{"en":"Quantitative research relies on numerical data and statistical testing methods.","vi":"Nghiên cứu định lượng dựa vào dữ liệu số và các phương pháp kiểm định thống kê."},{"en":"His quantitative research measured the effect of class size on grades.","vi":"Nghiên cứu định lượng của ông đo lường tác động của sĩ số lớp đến điểm số."},{"en":"Quantitative research can reveal patterns across very large populations.","vi":"Nghiên cứu định lượng có thể tiết lộ các khuôn mẫu trên những quần thể rất lớn."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 64, 'quantitative result', 'kết quả định lượng', 'adj + n', '[{"en":"The quantitative result showed a significant rise in test scores.","vi":"Kết quả định lượng cho thấy sự gia tăng đáng kể về điểm kiểm tra."},{"en":"Each quantitative result was checked against the original raw data.","vi":"Mỗi kết quả định lượng được đối chiếu với dữ liệu thô ban đầu."},{"en":"They interpreted the quantitative result alongside qualitative feedback carefully.","vi":"Họ diễn giải kết quả định lượng cùng với phản hồi định tính một cách cẩn thận."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 65, 'quantitative study', 'nghiên cứu định lượng', 'adj + n', '[{"en":"The quantitative study surveyed five hundred students across three universities.","vi":"Nghiên cứu định lượng khảo sát năm trăm sinh viên ở ba trường đại học."},{"en":"A large quantitative study can produce more generalizable conclusions overall.","vi":"Một nghiên cứu định lượng lớn có thể tạo ra kết luận khái quát hơn."},{"en":"They designed a quantitative study to test the proposed hypothesis.","vi":"Họ thiết kế một nghiên cứu định lượng để kiểm định giả thuyết được đề xuất."}]', '[]', NULL, '/ˈkwɑːntɪteɪtɪv ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 66, 'racial differences', 'sự khác biệt chủng tộc', 'adj + n', '[{"en":"The study examined racial differences in access to quality healthcare.","vi":"Nghiên cứu xem xét sự khác biệt chủng tộc trong việc tiếp cận chăm sóc y tế chất lượng."},{"en":"Researchers found persistent racial differences in average household income.","vi":"Các nhà nghiên cứu phát hiện sự khác biệt chủng tộc dai dẳng về thu nhập hộ gia đình."},{"en":"Racial differences in test scores often reflect unequal opportunities.","vi":"Sự khác biệt chủng tộc về điểm kiểm tra thường phản ánh cơ hội bất bình đẳng."}]', '[]', NULL, '/ˈreɪʃəl ˈdɪfərənsəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 67, 'racial discrimination', 'phân biệt chủng tộc', 'adj + n', '[{"en":"The new law explicitly prohibits racial discrimination in the workplace.","vi":"Luật mới cấm rõ ràng phân biệt chủng tộc tại nơi làm việc."},{"en":"Many activists devoted their lives to fighting racial discrimination.","vi":"Nhiều nhà hoạt động cống hiến cả đời để chống lại phân biệt chủng tộc."},{"en":"The report documented widespread racial discrimination in housing markets.","vi":"Bản báo cáo ghi nhận phân biệt chủng tộc lan rộng trong thị trường nhà ở."}]', '[]', NULL, '/ˈreɪʃəl dɪˌskrɪmɪˈneɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 68, 'racial equality', 'bình đẳng chủng tộc', 'adj + n', '[{"en":"The movement campaigned tirelessly for racial equality and civil rights.","vi":"Phong trào vận động không mệt mỏi cho bình đẳng chủng tộc và quyền công dân."},{"en":"True racial equality requires changes in both law and attitudes.","vi":"Bình đẳng chủng tộc thực sự đòi hỏi thay đổi cả luật pháp lẫn thái độ."},{"en":"Schools play an important part in promoting racial equality early.","vi":"Trường học đóng vai trò quan trọng trong việc thúc đẩy bình đẳng chủng tộc từ sớm."}]', '[]', NULL, '/ˈreɪʃəl ɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 69, 'racial group', 'nhóm chủng tộc', 'adj + n', '[{"en":"The survey compared health outcomes between several major racial groups.","vi":"Cuộc khảo sát so sánh kết quả sức khỏe giữa vài nhóm chủng tộc lớn."},{"en":"Each racial group faced distinct barriers in the labor market.","vi":"Mỗi nhóm chủng tộc đối mặt với những rào cản riêng trên thị trường lao động."},{"en":"Census data tracks the size of every racial group nationally.","vi":"Dữ liệu điều tra dân số theo dõi quy mô của từng nhóm chủng tộc trên toàn quốc."}]', '[]', NULL, '/ˈreɪʃəl ɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 70, 'racial stereotype', 'định kiến chủng tộc', 'adj + n', '[{"en":"The film challenges a common racial stereotype found in older media.","vi":"Bộ phim thách thức một định kiến chủng tộc phổ biến trong truyền thông cũ."},{"en":"Repeated exposure to a racial stereotype can shape young minds.","vi":"Tiếp xúc lặp lại với một định kiến chủng tộc có thể định hình tâm trí trẻ."},{"en":"Educators work hard to dismantle every harmful racial stereotype.","vi":"Các nhà giáo dục nỗ lực để xóa bỏ mọi định kiến chủng tộc gây hại."}]', '[]', NULL, '/ˈreɪʃəl ˈsteriətaɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 71, 'radical change', 'sự thay đổi triệt để', 'adj + n', '[{"en":"The reform brought radical change to the entire education system.","vi":"Cuộc cải cách mang lại sự thay đổi triệt để cho toàn bộ hệ thống giáo dục."},{"en":"Technology has driven radical change in how people communicate daily.","vi":"Công nghệ đã thúc đẩy sự thay đổi triệt để trong cách con người giao tiếp hàng ngày."},{"en":"Such radical change often meets strong resistance from established groups.","vi":"Sự thay đổi triệt để như vậy thường gặp phải sự phản kháng mạnh từ các nhóm cố hữu."}]', '[]', NULL, '/ˈrædɪkəl tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 72, 'radical critique', 'sự phê phán triệt để', 'adj + n', '[{"en":"The book offers a radical critique of mainstream economic theory.","vi":"Cuốn sách đưa ra một sự phê phán triệt để đối với lý thuyết kinh tế chủ đạo."},{"en":"Her essay presents a radical critique of modern consumer culture.","vi":"Bài luận của cô trình bày một sự phê phán triệt để văn hóa tiêu dùng hiện đại."},{"en":"A radical critique questions assumptions that others simply take for granted.","vi":"Một sự phê phán triệt để chất vấn những giả định mà người khác mặc nhiên chấp nhận."}]', '[]', NULL, '/ˈrædɪkəl krɪˈtiːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 73, 'radical differences', 'những khác biệt căn bản', 'adj + n', '[{"en":"The two cultures show radical differences in their family structures.","vi":"Hai nền văn hóa cho thấy những khác biệt căn bản trong cấu trúc gia đình."},{"en":"There are radical differences between the two theories of learning.","vi":"Có những khác biệt căn bản giữa hai lý thuyết về việc học."},{"en":"Researchers noted radical differences in how the species adapt.","vi":"Các nhà nghiên cứu ghi nhận những khác biệt căn bản trong cách các loài thích nghi."}]', '[]', NULL, '/ˈrædɪkəl ˈdɪfərənsəz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 74, 'radical transformation', 'sự chuyển đổi triệt để', 'adj + n', '[{"en":"The internet caused a radical transformation of global communication.","vi":"Internet đã gây ra sự chuyển đổi triệt để trong giao tiếp toàn cầu."},{"en":"The factory underwent radical transformation after adopting new technology.","vi":"Nhà máy trải qua sự chuyển đổi triệt để sau khi áp dụng công nghệ mới."},{"en":"Climate goals demand a radical transformation of the energy sector.","vi":"Các mục tiêu khí hậu đòi hỏi sự chuyển đổi triệt để của ngành năng lượng."}]', '[]', NULL, '/ˈrædɪkəl ˌtrænsfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 75, 'radically different', 'khác biệt hoàn toàn', 'adv + adj', '[{"en":"The two authors reach radically different conclusions from similar data.","vi":"Hai tác giả đi đến những kết luận khác biệt hoàn toàn từ dữ liệu tương tự."},{"en":"Life in the city is radically different from rural village life.","vi":"Cuộc sống ở thành phố khác biệt hoàn toàn so với đời sống làng quê."},{"en":"Their new strategy is radically different from anything tried before.","vi":"Chiến lược mới của họ khác biệt hoàn toàn so với mọi thứ từng thử trước đây."}]', '[]', NULL, '/ˈrædɪkli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 76, 'raise awareness', 'nâng cao nhận thức', 'v + n', '[{"en":"The charity works to raise awareness of homelessness in the city.","vi":"Tổ chức từ thiện hoạt động để nâng cao nhận thức về tình trạng vô gia cư trong thành phố."},{"en":"Posters and talks helped raise awareness of online safety risks.","vi":"Áp phích và buổi nói chuyện đã giúp nâng cao nhận thức về rủi ro an toàn trực tuyến."},{"en":"Schools raise awareness of healthy eating through practical cooking classes.","vi":"Trường học nâng cao nhận thức về ăn uống lành mạnh qua các lớp nấu ăn thực hành."}]', '[]', NULL, '/reɪz əˈwernəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 77, 'raise a question', 'đặt ra một câu hỏi', 'v + n', '[{"en":"These findings raise a question about the validity of earlier studies.","vi":"Những phát hiện này đặt ra một câu hỏi về tính hợp lệ của các nghiên cứu trước."},{"en":"The student raised a question that the lecturer had not expected.","vi":"Sinh viên đặt ra một câu hỏi mà giảng viên không lường trước."},{"en":"The new policy raises a question about who actually benefits.","vi":"Chính sách mới đặt ra một câu hỏi về việc ai thực sự được hưởng lợi."}]', '[]', NULL, '/reɪz ə ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 78, 'raise an issue', 'nêu lên một vấn đề', 'v + n', '[{"en":"She raised an issue about funding during the committee meeting.","vi":"Cô ấy nêu lên một vấn đề về kinh phí trong cuộc họp ủy ban."},{"en":"The report raises an issue that policymakers can no longer ignore.","vi":"Bản báo cáo nêu lên một vấn đề mà các nhà hoạch định không thể bỏ qua nữa."},{"en":"Feel free to raise an issue if anything seems unclear to you.","vi":"Hãy thoải mái nêu lên một vấn đề nếu điều gì đó còn chưa rõ với bạn."}]', '[]', NULL, '/reɪz ən ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 79, 'random error', 'sai số ngẫu nhiên', 'adj + n', '[{"en":"Repeated measurements help reduce the effect of random error.","vi":"Đo lường lặp lại giúp giảm tác động của sai số ngẫu nhiên."},{"en":"Random error scatters results without favoring any particular direction.","vi":"Sai số ngẫu nhiên làm kết quả phân tán mà không thiên về hướng cụ thể nào."},{"en":"The analysis distinguished random error from a clear systematic bias.","vi":"Phân tích phân biệt sai số ngẫu nhiên với một thiên lệch hệ thống rõ ràng."}]', '[]', NULL, '/ˈrændəm ˈerər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 80, 'random sample', 'mẫu ngẫu nhiên', 'adj + n', '[{"en":"The researchers drew a random sample from the national population.","vi":"Các nhà nghiên cứu lấy một mẫu ngẫu nhiên từ dân số quốc gia."},{"en":"A truly random sample reduces bias and improves generalizability.","vi":"Một mẫu ngẫu nhiên thực sự làm giảm thiên lệch và tăng khả năng khái quát."},{"en":"They surveyed a random sample of two thousand registered voters.","vi":"Họ khảo sát một mẫu ngẫu nhiên gồm hai nghìn cử tri đã đăng ký."}]', '[]', NULL, '/ˈrændəm ˈsæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 81, 'random variable', 'biến ngẫu nhiên', 'adj + n', '[{"en":"In statistics, a random variable assigns numbers to possible outcomes.","vi":"Trong thống kê, một biến ngẫu nhiên gán số cho các kết quả có thể."},{"en":"The model treats waiting time as a continuous random variable.","vi":"Mô hình coi thời gian chờ là một biến ngẫu nhiên liên tục."},{"en":"Each random variable in the equation follows a known distribution.","vi":"Mỗi biến ngẫu nhiên trong phương trình tuân theo một phân phối đã biết."}]', '[]', NULL, '/ˈrændəm ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 82, 'randomly assigned to', 'được phân ngẫu nhiên vào', 'adv + vpp', '[{"en":"Participants were randomly assigned to either the control or treatment group.","vi":"Người tham gia được phân ngẫu nhiên vào nhóm đối chứng hoặc nhóm điều trị."},{"en":"Students were randomly assigned to classes of different sizes.","vi":"Học sinh được phân ngẫu nhiên vào các lớp có quy mô khác nhau."},{"en":"Each patient was randomly assigned to one of three conditions.","vi":"Mỗi bệnh nhân được phân ngẫu nhiên vào một trong ba điều kiện."}]', '[]', NULL, '/ˈrændəmli əˈsaɪnd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 83, 'randomly chosen', 'được chọn ngẫu nhiên', 'adv + vpp', '[{"en":"The names were randomly chosen from a list of all members.","vi":"Các tên được chọn ngẫu nhiên từ danh sách toàn bộ thành viên."},{"en":"A randomly chosen subset was tested to verify the procedure.","vi":"Một tập con được chọn ngẫu nhiên đã được kiểm tra để xác minh quy trình."},{"en":"Participants were randomly chosen to avoid any selection bias.","vi":"Người tham gia được chọn ngẫu nhiên để tránh bất kỳ thiên lệch lựa chọn nào."}]', '[]', NULL, '/ˈrændəmli ˈtʃoʊzən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 84, 'randomly selected', 'được tuyển chọn ngẫu nhiên', 'adv + vpp', '[{"en":"Households were randomly selected to take part in the survey.","vi":"Các hộ gia đình được tuyển chọn ngẫu nhiên để tham gia khảo sát."},{"en":"The sample was randomly selected from official school registers.","vi":"Mẫu được tuyển chọn ngẫu nhiên từ sổ đăng ký chính thức của trường."},{"en":"Reviewers were randomly selected to ensure a fair evaluation process.","vi":"Người đánh giá được tuyển chọn ngẫu nhiên để đảm bảo quá trình đánh giá công bằng."}]', '[]', NULL, '/ˈrændəmli sɪˈlektɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 85, 'rapid expansion', 'sự mở rộng nhanh chóng', 'adj + n', '[{"en":"The company''s rapid expansion created hundreds of new jobs overnight.","vi":"Sự mở rộng nhanh chóng của công ty tạo ra hàng trăm việc làm mới trong một đêm."},{"en":"Rapid expansion of cities has strained local water supplies.","vi":"Sự mở rộng nhanh chóng của các thành phố đã gây áp lực lên nguồn nước địa phương."},{"en":"The rapid expansion of online shopping reshaped traditional retail.","vi":"Sự mở rộng nhanh chóng của mua sắm trực tuyến đã định hình lại bán lẻ truyền thống."}]', '[]', NULL, '/ˈræpɪd ɪkˈspænʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 86, 'rapidly changing', 'đang thay đổi nhanh chóng', 'adv + adj', '[{"en":"Workers must adapt to a rapidly changing technological environment.","vi":"Người lao động phải thích nghi với môi trường công nghệ đang thay đổi nhanh chóng."},{"en":"The course prepares students for a rapidly changing job market.","vi":"Khóa học chuẩn bị cho sinh viên một thị trường việc làm đang thay đổi nhanh chóng."},{"en":"Climate scientists study the rapidly changing conditions in the Arctic.","vi":"Các nhà khoa học khí hậu nghiên cứu điều kiện đang thay đổi nhanh chóng ở Bắc Cực."}]', '[]', NULL, '/ˈræpɪdli ˈtʃeɪndʒɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 87, 'rapidly growing', 'đang phát triển nhanh chóng', 'adv + adj', '[{"en":"Renewable energy is a rapidly growing part of the economy.","vi":"Năng lượng tái tạo là một phần đang phát triển nhanh chóng của nền kinh tế."},{"en":"The city has a rapidly growing population of young professionals.","vi":"Thành phố có dân số chuyên gia trẻ đang phát triển nhanh chóng."},{"en":"Researchers track the rapidly growing demand for clean drinking water.","vi":"Các nhà nghiên cứu theo dõi nhu cầu đang phát triển nhanh chóng về nước uống sạch."}]', '[]', NULL, '/ˈræpɪdli ˈɡroʊɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 88, 'raw data', 'dữ liệu thô', 'adj + n', '[{"en":"The researchers stored all raw data before beginning any analysis.","vi":"Các nhà nghiên cứu lưu trữ toàn bộ dữ liệu thô trước khi bắt đầu phân tích."},{"en":"Raw data must be cleaned carefully to remove obvious errors.","vi":"Dữ liệu thô phải được làm sạch cẩn thận để loại bỏ các lỗi rõ ràng."},{"en":"Other scientists may request the raw data to verify the results.","vi":"Các nhà khoa học khác có thể yêu cầu dữ liệu thô để xác minh kết quả."}]', '[]', NULL, '/rɔː ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 89, 'reach a consensus', 'đạt được sự đồng thuận', 'v + n', '[{"en":"After long discussion, the committee finally reached a consensus.","vi":"Sau cuộc thảo luận dài, ủy ban cuối cùng đạt được sự đồng thuận."},{"en":"Scientists have yet to reach a consensus on the exact cause.","vi":"Các nhà khoa học vẫn chưa đạt được sự đồng thuận về nguyên nhân chính xác."},{"en":"The group worked patiently to reach a consensus everyone accepted.","vi":"Cả nhóm kiên nhẫn làm việc để đạt được sự đồng thuận mà mọi người chấp nhận."}]', '[]', NULL, '/riːtʃ ə kənˈsensəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 90, 'reach a peak', 'đạt đến đỉnh điểm', 'v + n', '[{"en":"Sales reached a peak in December before falling sharply afterward.","vi":"Doanh số đạt đến đỉnh điểm vào tháng Mười Hai trước khi giảm mạnh sau đó."},{"en":"Unemployment reached a peak during the worst of the recession.","vi":"Tỷ lệ thất nghiệp đạt đến đỉnh điểm trong giai đoạn suy thoái tồi tệ nhất."},{"en":"The temperature reaches a peak in the early afternoon each day.","vi":"Nhiệt độ đạt đến đỉnh điểm vào đầu giờ chiều mỗi ngày."}]', '[]', NULL, '/riːtʃ ə piːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 91, 'reach an agreement', 'đạt được một thỏa thuận', 'v + n', '[{"en":"The two sides finally reached an agreement after weeks of talks.","vi":"Hai bên cuối cùng đạt được một thỏa thuận sau nhiều tuần đàm phán."},{"en":"Negotiators hope to reach an agreement before the strike begins.","vi":"Các nhà đàm phán hy vọng đạt được một thỏa thuận trước khi đình công bắt đầu."},{"en":"It took considerable compromise to reach an agreement on the budget.","vi":"Phải nhượng bộ đáng kể mới đạt được một thỏa thuận về ngân sách."}]', '[]', NULL, '/riːtʃ ən əˈɡriːmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 92, 'readily accessible', 'dễ dàng tiếp cận', 'adv + adj', '[{"en":"The library makes most of its resources readily accessible online.","vi":"Thư viện làm cho hầu hết tài nguyên của mình dễ dàng tiếp cận trực tuyến."},{"en":"Good design keeps emergency exits readily accessible to everyone.","vi":"Thiết kế tốt giữ cho các lối thoát hiểm dễ dàng tiếp cận với mọi người."},{"en":"These records are readily accessible to any registered researcher.","vi":"Những hồ sơ này dễ dàng tiếp cận với bất kỳ nhà nghiên cứu đã đăng ký nào."}]', '[]', NULL, '/ˈredəli əkˈsesəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 93, 'readily available', 'sẵn có dễ dàng', 'adv + adj', '[{"en":"Fresh produce is readily available at the local farmers'' market.","vi":"Nông sản tươi sẵn có dễ dàng tại chợ nông sản địa phương."},{"en":"Detailed statistics are now readily available to the public online.","vi":"Số liệu chi tiết hiện đã sẵn có dễ dàng cho công chúng trên mạng."},{"en":"Clean water is not always readily available in remote villages.","vi":"Nước sạch không phải lúc nào cũng sẵn có dễ dàng ở các làng xa xôi."}]', '[]', NULL, '/ˈredəli əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 94, 'readily understood', 'dễ dàng được hiểu', 'adv + vpp', '[{"en":"The instructions were clear and readily understood by every participant.","vi":"Hướng dẫn rõ ràng và dễ dàng được hiểu bởi mọi người tham gia."},{"en":"Simple diagrams make complex ideas more readily understood.","vi":"Sơ đồ đơn giản làm cho các ý tưởng phức tạp dễ dàng được hiểu hơn."},{"en":"Her argument was readily understood despite the technical subject.","vi":"Lập luận của cô dễ dàng được hiểu dù chủ đề mang tính kỹ thuật."}]', '[]', NULL, '/ˈredəli ˌʌndərˈstʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 95, 'ready access', 'khả năng tiếp cận dễ dàng', 'adj + n', '[{"en":"Students need ready access to reliable academic sources online.","vi":"Sinh viên cần tiếp cận dễ dàng các nguồn học thuật đáng tin cậy trực tuyến."},{"en":"The clinic gives patients ready access to qualified doctors.","vi":"Phòng khám giúp bệnh nhân tiếp cận dễ dàng với bác sĩ có chuyên môn."},{"en":"Ready access to data helped the team finish faster.","vi":"Việc tiếp cận dữ liệu dễ dàng giúp nhóm hoàn thành nhanh hơn."}]', '[]', NULL, '/ˈredi ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 96, 'real issue', 'vấn đề thực sự', 'adj + n', '[{"en":"The real issue here is a lack of funding.","vi":"Vấn đề thực sự ở đây là thiếu kinh phí."},{"en":"We must address the real issue, not just the symptoms.","vi":"Chúng ta phải giải quyết vấn đề thực sự, không chỉ các triệu chứng."},{"en":"Her essay finally identified the real issue behind the conflict.","vi":"Bài luận của cô cuối cùng đã chỉ ra vấn đề thực sự đằng sau xung đột."}]', '[]', NULL, '/ˈriːəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 97, 'receive feedback', 'nhận phản hồi', 'v + n', '[{"en":"Students receive feedback on their essays within one week.","vi":"Sinh viên nhận phản hồi về bài luận của mình trong vòng một tuần."},{"en":"It helps to receive feedback from several different readers.","vi":"Việc nhận phản hồi từ nhiều người đọc khác nhau rất hữu ích."},{"en":"Employees who receive feedback regularly tend to improve quickly.","vi":"Những nhân viên thường xuyên nhận phản hồi có xu hướng tiến bộ nhanh."}]', '[]', NULL, '/rɪˈsiːv ˈfiːdbæk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 98, 'receive information', 'nhận thông tin', 'v + n', '[{"en":"Patients receive information about treatment options before deciding.","vi":"Bệnh nhân nhận thông tin về các lựa chọn điều trị trước khi quyết định."},{"en":"We receive information from the database in real time.","vi":"Chúng tôi nhận thông tin từ cơ sở dữ liệu theo thời gian thực."},{"en":"Travellers receive information about delays through a mobile app.","vi":"Hành khách nhận thông tin về sự chậm trễ qua một ứng dụng di động."}]', '[]', NULL, '/rɪˈsiːv ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 99, 'receive treatment', 'được điều trị', 'v + n', '[{"en":"Many patients receive treatment at home rather than in hospital.","vi":"Nhiều bệnh nhân được điều trị tại nhà thay vì trong bệnh viện."},{"en":"Children who receive treatment early often recover completely.","vi":"Trẻ em được điều trị sớm thường hồi phục hoàn toàn."},{"en":"The study tracked how quickly people receive treatment after injury.","vi":"Nghiên cứu theo dõi việc người ta được điều trị nhanh ra sao sau chấn thương."}]', '[]', NULL, '/rɪˈsiːv ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 100, 'recent decades', 'những thập kỷ gần đây', 'adj + n', '[{"en":"In recent decades, technology has transformed how we communicate.","vi":"Trong những thập kỷ gần đây, công nghệ đã thay đổi cách chúng ta giao tiếp."},{"en":"Global temperatures have risen sharply over recent decades.","vi":"Nhiệt độ toàn cầu đã tăng mạnh trong những thập kỷ gần đây."},{"en":"Recent decades have seen rapid growth in online education.","vi":"Những thập kỷ gần đây chứng kiến sự tăng trưởng nhanh của giáo dục trực tuyến."}]', '[]', NULL, '/ˈriːsənt ˈdekeɪdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 101, 'recent evidence', 'bằng chứng gần đây', 'adj + n', '[{"en":"Recent evidence suggests sleep strongly affects academic performance.","vi":"Bằng chứng gần đây cho thấy giấc ngủ ảnh hưởng mạnh đến kết quả học tập."},{"en":"The author cites recent evidence to support her main claim.","vi":"Tác giả trích dẫn bằng chứng gần đây để củng cố luận điểm chính của mình."},{"en":"Recent evidence challenges several long-held assumptions in the field.","vi":"Bằng chứng gần đây thách thức nhiều giả định lâu nay trong lĩnh vực này."}]', '[]', NULL, '/ˈriːsənt ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 102, 'recent research', 'nghiên cứu gần đây', 'adj + n', '[{"en":"Recent research has shown that exercise improves memory and focus.","vi":"Nghiên cứu gần đây cho thấy tập thể dục cải thiện trí nhớ và sự tập trung."},{"en":"Her thesis builds on recent research in cognitive science.","vi":"Luận văn của cô dựa trên nghiên cứu gần đây trong khoa học nhận thức."},{"en":"Recent research challenges the idea that talent is fixed.","vi":"Nghiên cứu gần đây bác bỏ quan niệm cho rằng tài năng là cố định."}]', '[]', NULL, '/ˈriːsənt ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 103, 'recent study', 'nghiên cứu gần đây', 'adj + n', '[{"en":"A recent study found that short breaks boost productivity.","vi":"Một nghiên cứu gần đây phát hiện rằng nghỉ ngắn giúp tăng năng suất."},{"en":"The recent study surveyed over two thousand university students.","vi":"Nghiên cứu gần đây đã khảo sát hơn hai nghìn sinh viên đại học."},{"en":"According to a recent study, diet affects mood significantly.","vi":"Theo một nghiên cứu gần đây, chế độ ăn ảnh hưởng đáng kể đến tâm trạng."}]', '[]', NULL, '/ˈriːsənt ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 104, 'recent survey', 'cuộc khảo sát gần đây', 'adj + n', '[{"en":"A recent survey revealed that most students prefer online lectures.","vi":"Một cuộc khảo sát gần đây cho thấy hầu hết sinh viên thích bài giảng trực tuyến."},{"en":"The recent survey collected responses from five hundred employees.","vi":"Cuộc khảo sát gần đây thu thập câu trả lời từ năm trăm nhân viên."},{"en":"Results from the recent survey appear in the appendix.","vi":"Kết quả của cuộc khảo sát gần đây nằm trong phần phụ lục."}]', '[]', NULL, '/ˈriːsənt ˈsɜːrveɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 105, 'reciprocal relationship', 'mối quan hệ tương hỗ', 'adj + n', '[{"en":"Trust and honesty form a reciprocal relationship between partners.","vi":"Niềm tin và sự trung thực tạo nên một mối quan hệ tương hỗ giữa các đối tác."},{"en":"The study describes a reciprocal relationship between reading and writing.","vi":"Nghiên cứu mô tả một mối quan hệ tương hỗ giữa việc đọc và viết."},{"en":"Predators and prey share a reciprocal relationship within the ecosystem.","vi":"Động vật săn mồi và con mồi có một mối quan hệ tương hỗ trong hệ sinh thái."}]', '[]', NULL, '/rɪˈsɪprəkəl rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 106, 'record data', 'ghi lại dữ liệu', 'v + n', '[{"en":"Researchers record data carefully to avoid measurement errors.","vi":"Các nhà nghiên cứu ghi lại dữ liệu cẩn thận để tránh sai số đo lường."},{"en":"Sensors record data continuously throughout the entire experiment.","vi":"Các cảm biến ghi lại dữ liệu liên tục trong suốt thí nghiệm."},{"en":"Please record data in the spreadsheet after each trial.","vi":"Vui lòng ghi lại dữ liệu vào bảng tính sau mỗi lần thử."}]', '[]', NULL, '/rɪˈkɔːrd ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 107, 'recurrent theme', 'chủ đề lặp lại', 'adj + n', '[{"en":"Isolation is a recurrent theme throughout the author''s novels.","vi":"Sự cô lập là một chủ đề lặp lại xuyên suốt các tiểu thuyết của tác giả."},{"en":"Inequality emerged as a recurrent theme in the interviews.","vi":"Bất bình đẳng nổi lên như một chủ đề lặp lại trong các cuộc phỏng vấn."},{"en":"Hope is a recurrent theme in her early poetry.","vi":"Hy vọng là một chủ đề lặp lại trong thơ thời kỳ đầu của bà."}]', '[]', NULL, '/rɪˈkɜːrənt ˈθiːm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 108, 'reduce emissions', 'giảm khí thải', 'v + n', '[{"en":"Governments are under pressure to reduce emissions from transport.","vi":"Các chính phủ chịu áp lực phải giảm khí thải từ giao thông."},{"en":"Switching to renewable energy can significantly reduce emissions.","vi":"Chuyển sang năng lượng tái tạo có thể giảm khí thải đáng kể."},{"en":"The company pledged to reduce emissions by half within ten years.","vi":"Công ty cam kết giảm khí thải một nửa trong vòng mười năm."}]', '[]', NULL, '/rɪˈduːs ɪˈmɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 109, 'reduce stress', 'giảm căng thẳng', 'v + n', '[{"en":"Regular exercise can help students reduce stress before exams.","vi":"Tập thể dục đều đặn có thể giúp sinh viên giảm căng thẳng trước kỳ thi."},{"en":"Deep breathing is a simple way to reduce stress quickly.","vi":"Hít thở sâu là một cách đơn giản để giảm căng thẳng nhanh chóng."},{"en":"Flexible working hours may reduce stress among employees.","vi":"Giờ làm việc linh hoạt có thể giảm căng thẳng cho nhân viên."}]', '[]', NULL, '/rɪˈduːs ˈstres/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 110, 'reduce the likelihood', 'giảm khả năng xảy ra', 'v + n', '[{"en":"Careful planning can reduce the likelihood of serious mistakes.","vi":"Lập kế hoạch cẩn thận có thể giảm khả năng xảy ra sai sót nghiêm trọng."},{"en":"Vaccination greatly reduces the likelihood of severe illness.","vi":"Tiêm vắc-xin giảm đáng kể khả năng mắc bệnh nặng."},{"en":"Better lighting can reduce the likelihood of accidents at night.","vi":"Chiếu sáng tốt hơn có thể giảm khả năng xảy ra tai nạn vào ban đêm."}]', '[]', NULL, '/rɪˈduːs ðə ˈlaɪklihʊd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 111, 'reflective practice', 'thực hành phản tư', 'adj + n', '[{"en":"Reflective practice helps teachers learn from their daily experiences.","vi":"Thực hành phản tư giúp giáo viên học hỏi từ trải nghiệm hằng ngày."},{"en":"Nurses use reflective practice to improve patient care over time.","vi":"Y tá dùng thực hành phản tư để cải thiện việc chăm sóc bệnh nhân theo thời gian."},{"en":"The course encourages reflective practice through regular journal writing.","vi":"Khóa học khuyến khích thực hành phản tư qua việc viết nhật ký thường xuyên."}]', '[]', NULL, '/rɪˈflektɪv ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 112, 'reflective question', 'câu hỏi gợi suy ngẫm', 'adj + n', '[{"en":"The tutor ended each lesson with a reflective question.","vi":"Người hướng dẫn kết thúc mỗi buổi học bằng một câu hỏi gợi suy ngẫm."},{"en":"A good reflective question encourages learners to examine their assumptions.","vi":"Một câu hỏi gợi suy ngẫm tốt khuyến khích người học xem xét lại các giả định."},{"en":"She wrote a reflective question at the top of each page.","vi":"Cô viết một câu hỏi gợi suy ngẫm ở đầu mỗi trang."}]', '[]', NULL, '/rɪˈflektɪv ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 113, 'regional development', 'phát triển vùng', 'adj + n', '[{"en":"The policy aims to support regional development in rural areas.","vi":"Chính sách này nhằm hỗ trợ phát triển vùng ở các khu vực nông thôn."},{"en":"Investment in roads often drives regional development.","vi":"Đầu tư vào đường sá thường thúc đẩy phát triển vùng."},{"en":"The report compares regional development across several countries.","vi":"Báo cáo so sánh sự phát triển vùng giữa nhiều quốc gia."}]', '[]', NULL, '/ˈriːdʒənəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 114, 'regional differences', 'sự khác biệt giữa các vùng', 'adj + n', '[{"en":"The survey revealed clear regional differences in eating habits.","vi":"Cuộc khảo sát cho thấy rõ sự khác biệt giữa các vùng về thói quen ăn uống."},{"en":"Regional differences in income affect access to healthcare.","vi":"Sự khác biệt thu nhập giữa các vùng ảnh hưởng đến việc tiếp cận y tế."},{"en":"Researchers noted strong regional differences in language use.","vi":"Các nhà nghiên cứu ghi nhận sự khác biệt rõ giữa các vùng trong cách dùng ngôn ngữ."}]', '[]', NULL, '/ˈriːdʒənəl ˈdɪfərənsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 115, 'regional variation', 'sự biến thiên theo vùng', 'adj + n', '[{"en":"There is considerable regional variation in rainfall across the country.","vi":"Có sự biến thiên theo vùng đáng kể về lượng mưa trên cả nước."},{"en":"The map illustrates regional variation in average house prices.","vi":"Bản đồ minh họa sự biến thiên theo vùng về giá nhà trung bình."},{"en":"Regional variation in accent makes the language richer.","vi":"Sự biến thiên theo vùng trong giọng nói khiến ngôn ngữ phong phú hơn."}]', '[]', NULL, '/ˈriːdʒənəl ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 116, 'regulatory agency', 'cơ quan quản lý', 'adj + n', '[{"en":"A national regulatory agency oversees safety standards in the industry.","vi":"Một cơ quan quản lý quốc gia giám sát các tiêu chuẩn an toàn trong ngành."},{"en":"The regulatory agency fined the company for breaking the rules.","vi":"Cơ quan quản lý đã phạt công ty vì vi phạm các quy định."},{"en":"Drug approval requires review by an independent regulatory agency.","vi":"Việc phê duyệt thuốc cần được một cơ quan quản lý độc lập xem xét."}]', '[]', NULL, '/ˈreɡjələtɔːri ˈeɪdʒənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 117, 'regulatory framework', 'khung pháp lý quản lý', 'adj + n', '[{"en":"A clear regulatory framework helps new businesses operate safely.","vi":"Một khung pháp lý quản lý rõ ràng giúp các doanh nghiệp mới hoạt động an toàn."},{"en":"The regulatory framework was updated to address online privacy.","vi":"Khung pháp lý quản lý đã được cập nhật để giải quyết quyền riêng tư trực tuyến."},{"en":"Weak regulatory frameworks can allow harmful practices to continue.","vi":"Khung pháp lý quản lý yếu kém có thể để các hành vi gây hại tiếp diễn."}]', '[]', NULL, '/ˈreɡjələtɔːri ˈfreɪmwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 118, 'related activity', 'hoạt động liên quan', 'adj + n', '[{"en":"The textbook includes a related activity at the end of each chapter.","vi":"Sách giáo khoa có một hoạt động liên quan ở cuối mỗi chương."},{"en":"Reading and any related activity can improve vocabulary together.","vi":"Việc đọc và bất kỳ hoạt động liên quan nào đều có thể cùng cải thiện từ vựng."},{"en":"Each lesson is paired with a related activity for practice.","vi":"Mỗi bài học đi kèm một hoạt động liên quan để luyện tập."}]', '[]', NULL, '/rɪˈleɪtɪd ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 119, 'related area', 'lĩnh vực liên quan', 'adj + n', '[{"en":"Her degree opened doors in engineering and several related areas.","vi":"Bằng cấp của cô mở ra cơ hội trong kỹ thuật và một số lĩnh vực liên quan."},{"en":"The paper reviews findings from psychology and related areas.","vi":"Bài báo điểm lại các phát hiện từ tâm lý học và những lĩnh vực liên quan."},{"en":"Researchers in this related area face similar methodological challenges.","vi":"Các nhà nghiên cứu trong lĩnh vực liên quan này gặp những thách thức phương pháp tương tự."}]', '[]', NULL, '/rɪˈleɪtɪd ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 120, 'related aspect', 'khía cạnh liên quan', 'adj + n', '[{"en":"The chapter explores one related aspect of climate policy in detail.","vi":"Chương này khám phá chi tiết một khía cạnh liên quan của chính sách khí hậu."},{"en":"We will now turn to a closely related aspect of the problem.","vi":"Bây giờ chúng ta sẽ chuyển sang một khía cạnh liên quan chặt chẽ của vấn đề."},{"en":"Each related aspect deserves separate attention in the analysis.","vi":"Mỗi khía cạnh liên quan đều xứng đáng được chú ý riêng trong phân tích."}]', '[]', NULL, '/rɪˈleɪtɪd ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 121, 'related factor', 'yếu tố liên quan', 'adj + n', '[{"en":"Income is one related factor that influences educational outcomes.","vi":"Thu nhập là một yếu tố liên quan ảnh hưởng đến kết quả giáo dục."},{"en":"The study controlled for every related factor it could identify.","vi":"Nghiên cứu đã kiểm soát mọi yếu tố liên quan mà nó có thể xác định."},{"en":"Stress and sleep are two closely related factors here.","vi":"Căng thẳng và giấc ngủ là hai yếu tố liên quan chặt chẽ ở đây."}]', '[]', NULL, '/rɪˈleɪtɪd ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 122, 'related information', 'thông tin liên quan', 'adj + n', '[{"en":"The website groups all related information on a single page.","vi":"Trang web nhóm tất cả thông tin liên quan vào một trang duy nhất."},{"en":"Please attach any related information to support your application.","vi":"Vui lòng đính kèm bất kỳ thông tin liên quan nào để hỗ trợ đơn của bạn."},{"en":"The footnotes point readers toward related information elsewhere.","vi":"Các chú thích chỉ dẫn người đọc đến thông tin liên quan ở nơi khác."}]', '[]', NULL, '/rɪˈleɪtɪd ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 123, 'related issue', 'vấn đề liên quan', 'adj + n', '[{"en":"Privacy is a related issue that the report also addresses.","vi":"Quyền riêng tư là một vấn đề liên quan mà báo cáo cũng đề cập."},{"en":"Before concluding, the author raises one final related issue.","vi":"Trước khi kết luận, tác giả nêu ra một vấn đề liên quan cuối cùng."},{"en":"We should not ignore this closely related issue.","vi":"Chúng ta không nên bỏ qua vấn đề liên quan chặt chẽ này."}]', '[]', NULL, '/rɪˈleɪtɪd ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 124, 'related problem', 'vấn đề liên quan', 'adj + n', '[{"en":"Traffic and pollution are a closely related problem in cities.","vi":"Giao thông và ô nhiễm là một vấn đề liên quan chặt chẽ ở các thành phố."},{"en":"Solving one issue often reveals another related problem.","vi":"Giải quyết một vấn đề thường làm lộ ra một vấn đề liên quan khác."},{"en":"The next section discusses a related problem in detail.","vi":"Phần tiếp theo thảo luận chi tiết một vấn đề liên quan."}]', '[]', NULL, '/rɪˈleɪtɪd ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 125, 'related question', 'câu hỏi liên quan', 'adj + n', '[{"en":"This leads us to a related question about funding.","vi":"Điều này dẫn chúng ta đến một câu hỏi liên quan về kinh phí."},{"en":"The interview ended with a related question about future plans.","vi":"Cuộc phỏng vấn kết thúc bằng một câu hỏi liên quan về kế hoạch tương lai."},{"en":"A related question concerns who should pay for repairs.","vi":"Một câu hỏi liên quan là ai nên trả tiền sửa chữa."}]', '[]', NULL, '/rɪˈleɪtɪd ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 126, 'related topic', 'chủ đề liên quan', 'adj + n', '[{"en":"The seminar covered migration and one related topic afterwards.","vi":"Buổi hội thảo bàn về di cư và sau đó một chủ đề liên quan."},{"en":"Students may choose any related topic for their final essay.","vi":"Sinh viên có thể chọn bất kỳ chủ đề liên quan nào cho bài luận cuối kỳ."},{"en":"The lecture briefly touched on a related topic at the end.","vi":"Bài giảng đề cập ngắn gọn một chủ đề liên quan ở phần cuối."}]', '[]', NULL, '/rɪˈleɪtɪd ˈtɑːpɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 127, 'relative autonomy', 'quyền tự chủ tương đối', 'adj + n', '[{"en":"Local councils enjoy relative autonomy in managing their budgets.","vi":"Các hội đồng địa phương có quyền tự chủ tương đối trong việc quản lý ngân sách."},{"en":"The article examines the relative autonomy of universities from the state.","vi":"Bài báo xem xét quyền tự chủ tương đối của các trường đại học với nhà nước."},{"en":"Teachers value the relative autonomy they have in the classroom.","vi":"Giáo viên coi trọng quyền tự chủ tương đối họ có trong lớp học."}]', '[]', NULL, '/ˈrelətɪv ɔːˈtɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 128, 'relative merits', 'ưu điểm tương đối', 'adj + n', '[{"en":"The essay weighs the relative merits of two teaching methods.","vi":"Bài luận cân nhắc ưu điểm tương đối của hai phương pháp giảng dạy."},{"en":"We debated the relative merits of each proposed solution.","vi":"Chúng tôi tranh luận về ưu điểm tương đối của mỗi giải pháp được đề xuất."},{"en":"Consider the relative merits before choosing a research design.","vi":"Hãy cân nhắc ưu điểm tương đối trước khi chọn một thiết kế nghiên cứu."}]', '[]', NULL, '/ˈrelətɪv ˈmerɪts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 129, 'relative status', 'vị thế tương đối', 'adj + n', '[{"en":"The study compares the relative status of men and women.","vi":"Nghiên cứu so sánh vị thế tương đối của nam giới và nữ giới."},{"en":"Income often shapes a family''s relative status in society.","vi":"Thu nhập thường định hình vị thế tương đối của một gia đình trong xã hội."},{"en":"Language can signal the relative status of the speakers.","vi":"Ngôn ngữ có thể báo hiệu vị thế tương đối của người nói."}]', '[]', NULL, '/ˈrelətɪv ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 130, 'relatively common', 'tương đối phổ biến', 'adv + adj', '[{"en":"This condition is relatively common among older adults.","vi":"Tình trạng này tương đối phổ biến ở người lớn tuổi."},{"en":"Spelling errors are relatively common in early drafts.","vi":"Lỗi chính tả tương đối phổ biến trong các bản nháp đầu tiên."},{"en":"Such mistakes are relatively common but easy to correct.","vi":"Những lỗi như vậy tương đối phổ biến nhưng dễ sửa."}]', '[]', NULL, '/ˈrelətɪvli ˈkɑːmən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 131, 'relatively constant', 'tương đối ổn định', 'adv + adj', '[{"en":"The temperature stayed relatively constant throughout the experiment.","vi":"Nhiệt độ duy trì tương đối ổn định trong suốt thí nghiệm."},{"en":"Prices have remained relatively constant over the past year.","vi":"Giá cả vẫn tương đối ổn định trong năm qua."},{"en":"Population size was relatively constant across the whole period.","vi":"Quy mô dân số tương đối ổn định trong suốt giai đoạn này."}]', '[]', NULL, '/ˈrelətɪvli ˈkɑːnstənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 132, 'relatively few', 'tương đối ít', 'adv + adj', '[{"en":"Relatively few students chose to study the optional module.","vi":"Tương đối ít sinh viên chọn học học phần tự chọn."},{"en":"There are relatively few studies on this rare disease.","vi":"Có tương đối ít nghiên cứu về căn bệnh hiếm gặp này."},{"en":"Relatively few people attended the early morning lecture.","vi":"Tương đối ít người tham dự bài giảng buổi sáng sớm."}]', '[]', NULL, '/ˈrelətɪvli ˈfjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 133, 'relatively high', 'tương đối cao', 'adv + adj', '[{"en":"Unemployment remained relatively high in the region last year.","vi":"Tỷ lệ thất nghiệp vẫn tương đối cao ở khu vực này năm ngoái."},{"en":"The cost of living here is relatively high for students.","vi":"Chi phí sinh hoạt ở đây tương đối cao đối với sinh viên."},{"en":"The course has a relatively high pass rate this term.","vi":"Khóa học có tỷ lệ đậu tương đối cao trong học kỳ này."}]', '[]', NULL, '/ˈrelətɪvli ˈhaɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 134, 'relatively little', 'tương đối ít', 'adv + adj', '[{"en":"Relatively little research exists on this particular topic.","vi":"Có tương đối ít nghiên cứu về chủ đề cụ thể này."},{"en":"The project required relatively little funding to complete.","vi":"Dự án cần tương đối ít kinh phí để hoàn thành."},{"en":"We know relatively little about how the system fails.","vi":"Chúng ta biết tương đối ít về cách hệ thống bị lỗi."}]', '[]', NULL, '/ˈrelətɪvli ˈlɪtəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 135, 'relatively low', 'tương đối thấp', 'adv + adj', '[{"en":"The risk of infection is relatively low in this group.","vi":"Nguy cơ nhiễm trùng tương đối thấp ở nhóm này."},{"en":"Wages in the sector remain relatively low despite demand.","vi":"Lương trong ngành vẫn tương đối thấp dù nhu cầu cao."},{"en":"The error rate was relatively low throughout the test.","vi":"Tỷ lệ lỗi tương đối thấp trong suốt bài kiểm tra."}]', '[]', NULL, '/ˈrelətɪvli ˈloʊ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 136, 'relatively minor', 'tương đối nhỏ', 'adv + adj', '[{"en":"The damage was relatively minor and quickly repaired.","vi":"Thiệt hại tương đối nhỏ và được sửa chữa nhanh chóng."},{"en":"These are relatively minor errors that do not affect the results.","vi":"Đây là những lỗi tương đối nhỏ không ảnh hưởng đến kết quả."},{"en":"Compared to the benefits, the costs seem relatively minor.","vi":"So với lợi ích, chi phí có vẻ tương đối nhỏ."}]', '[]', NULL, '/ˈrelətɪvli ˈmaɪnər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 137, 'relatively rare', 'tương đối hiếm', 'adv + adj', '[{"en":"Such severe reactions are relatively rare among patients.","vi":"Những phản ứng nghiêm trọng như vậy tương đối hiếm ở bệnh nhân."},{"en":"This species has become relatively rare in the wild.","vi":"Loài này đã trở nên tương đối hiếm trong tự nhiên."},{"en":"Genuine breakthroughs are relatively rare in this field.","vi":"Những bước đột phá thực sự tương đối hiếm trong lĩnh vực này."}]', '[]', NULL, '/ˈrelətɪvli ˈrer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 138, 'relatively recent', 'tương đối gần đây', 'adv + adj', '[{"en":"Online learning is a relatively recent development in education.","vi":"Học trực tuyến là một sự phát triển tương đối gần đây trong giáo dục."},{"en":"The practice has a relatively recent history in this country.","vi":"Thông lệ này có một lịch sử tương đối gần đây ở đất nước này."},{"en":"This theory is relatively recent and still being tested.","vi":"Lý thuyết này tương đối gần đây và vẫn đang được kiểm chứng."}]', '[]', NULL, '/ˈrelətɪvli ˈriːsənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 139, 'relatively simple', 'tương đối đơn giản', 'adv + adj', '[{"en":"The procedure is relatively simple and takes only minutes.","vi":"Quy trình tương đối đơn giản và chỉ mất vài phút."},{"en":"She explained the idea in relatively simple terms.","vi":"Cô giải thích ý tưởng bằng những lời lẽ tương đối đơn giản."},{"en":"The first task is relatively simple compared to the rest.","vi":"Nhiệm vụ đầu tiên tương đối đơn giản so với phần còn lại."}]', '[]', NULL, '/ˈrelətɪvli ˈsɪmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 140, 'relatively stable', 'tương đối ổn định', 'adv + adj', '[{"en":"The economy has remained relatively stable in recent months.","vi":"Nền kinh tế vẫn tương đối ổn định trong những tháng gần đây."},{"en":"Their results were relatively stable across all conditions.","vi":"Kết quả của họ tương đối ổn định trong mọi điều kiện."},{"en":"Prices stayed relatively stable despite the disruption.","vi":"Giá cả vẫn tương đối ổn định bất chấp sự gián đoạn."}]', '[]', NULL, '/ˈrelətɪvli ˈsteɪbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 141, 'relatively straightforward', 'tương đối dễ hiểu', 'adv + adj', '[{"en":"The instructions were relatively straightforward and easy to follow.","vi":"Hướng dẫn tương đối dễ hiểu và dễ làm theo."},{"en":"The first stage of the analysis is relatively straightforward.","vi":"Giai đoạn đầu của phân tích tương đối dễ hiểu."},{"en":"Setting up the equipment proved relatively straightforward.","vi":"Việc lắp đặt thiết bị hóa ra tương đối dễ dàng."}]', '[]', NULL, '/ˈrelətɪvli ˌstreɪtˈfɔːrwərd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 142, 'relevant data', 'dữ liệu liên quan', 'adj + n', '[{"en":"The researcher gathered all relevant data before drawing conclusions.","vi":"Nhà nghiên cứu thu thập tất cả dữ liệu liên quan trước khi đưa ra kết luận."},{"en":"Only relevant data should be included in the final report.","vi":"Chỉ những dữ liệu liên quan mới nên được đưa vào báo cáo cuối cùng."},{"en":"The team struggled to find relevant data on rural areas.","vi":"Nhóm gặp khó khăn trong việc tìm dữ liệu liên quan về khu vực nông thôn."}]', '[]', NULL, '/ˈreləvənt ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 143, 'relevant factors', 'các yếu tố liên quan', 'adj + n', '[{"en":"The model accounts for all relevant factors affecting growth.","vi":"Mô hình tính đến tất cả các yếu tố liên quan ảnh hưởng đến tăng trưởng."},{"en":"Before deciding, managers weigh several relevant factors carefully.","vi":"Trước khi quyết định, các quản lý cân nhắc cẩn thận một số yếu tố liên quan."},{"en":"Climate and soil are two relevant factors in farming.","vi":"Khí hậu và đất là hai yếu tố liên quan trong canh tác."}]', '[]', NULL, '/ˈreləvənt ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 144, 'relevant information', 'thông tin liên quan', 'adj + n', '[{"en":"Please highlight the relevant information in each source.","vi":"Vui lòng làm nổi bật thông tin liên quan trong mỗi nguồn."},{"en":"Good readers quickly identify the relevant information in a text.","vi":"Người đọc giỏi nhanh chóng nhận ra thông tin liên quan trong một văn bản."},{"en":"The form asks applicants to provide all relevant information.","vi":"Mẫu đơn yêu cầu người nộp cung cấp tất cả thông tin liên quan."}]', '[]', NULL, '/ˈreləvənt ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 145, 'relevant issue', 'vấn đề liên quan', 'adj + n', '[{"en":"The debate raised every relevant issue surrounding the policy.","vi":"Cuộc tranh luận đã nêu ra mọi vấn đề liên quan xoay quanh chính sách."},{"en":"Cost is the most relevant issue for many families.","vi":"Chi phí là vấn đề liên quan nhất đối với nhiều gia đình."},{"en":"The committee focused only on the most relevant issue.","vi":"Ủy ban chỉ tập trung vào vấn đề liên quan nhất."}]', '[]', NULL, '/ˈreləvənt ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 146, 'relevant literature', 'tài liệu liên quan', 'adj + n', '[{"en":"The thesis reviews all relevant literature on the subject.","vi":"Luận văn điểm lại tất cả tài liệu liên quan về chủ đề này."},{"en":"She spent weeks reading the relevant literature before writing.","vi":"Cô dành nhiều tuần đọc tài liệu liên quan trước khi viết."},{"en":"Citing relevant literature strengthens the credibility of your argument.","vi":"Trích dẫn tài liệu liên quan giúp lập luận của bạn đáng tin hơn."}]', '[]', NULL, '/ˈreləvənt ˈlɪtərətʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 147, 'relevant material', 'tài liệu liên quan', 'adj + n', '[{"en":"The lecturer posts all relevant material on the course website.","vi":"Giảng viên đăng tất cả tài liệu liên quan trên trang web của khóa học."},{"en":"Students should bring relevant material to each tutorial.","vi":"Sinh viên nên mang tài liệu liên quan đến mỗi buổi hướng dẫn."},{"en":"She organised the relevant material into clear folders.","vi":"Cô sắp xếp tài liệu liên quan vào các thư mục rõ ràng."}]', '[]', NULL, '/ˈreləvənt məˈtɪriəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 148, 'reliable data', 'dữ liệu đáng tin cậy', 'adj + n', '[{"en":"Sound conclusions depend on reliable data from careful measurement.","vi":"Kết luận đúng đắn phụ thuộc vào dữ liệu đáng tin cậy từ việc đo lường cẩn thận."},{"en":"Without reliable data, the model cannot make accurate predictions.","vi":"Nếu không có dữ liệu đáng tin cậy, mô hình không thể dự đoán chính xác."},{"en":"Collecting reliable data took the team several months.","vi":"Việc thu thập dữ liệu đáng tin cậy mất của nhóm vài tháng."}]', '[]', NULL, '/rɪˈlaɪəbəl ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 149, 'reliable information', 'thông tin đáng tin cậy', 'adj + n', '[{"en":"Always check several sources to get reliable information.","vi":"Luôn kiểm tra nhiều nguồn để có được thông tin đáng tin cậy."},{"en":"The library provides reliable information for academic research.","vi":"Thư viện cung cấp thông tin đáng tin cậy cho nghiên cứu học thuật."},{"en":"Reliable information is hard to find during a crisis.","vi":"Thông tin đáng tin cậy rất khó tìm trong một cuộc khủng hoảng."}]', '[]', NULL, '/rɪˈlaɪəbəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-13-01', 150, 'religious belief', 'niềm tin tôn giáo', 'adj + n', '[{"en":"The law protects each citizen''s religious belief and practice.","vi":"Luật bảo vệ niềm tin và việc thực hành tôn giáo của mỗi công dân."},{"en":"Religious belief shaped the architecture of these ancient temples.","vi":"Niềm tin tôn giáo đã định hình kiến trúc của những ngôi đền cổ này."},{"en":"The survey explored how religious belief affects daily choices.","vi":"Cuộc khảo sát tìm hiểu niềm tin tôn giáo ảnh hưởng đến lựa chọn hằng ngày ra sao."}]', '[]', NULL, '/rɪˈlɪdʒəs bɪˈliːf/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-14-01', 'colloc-14', 'Cụm học thuật · Nhóm 14', 'Academic Collocation List (Pearson/PTE) — nhóm 14 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 1, 'religious faith', 'đức tin tôn giáo', 'adj + n', '[{"en":"Her religious faith gave her strength during difficult times.","vi":"Đức tin tôn giáo đã cho cô sức mạnh trong những lúc khó khăn."},{"en":"The novel examines the role of religious faith in family life.","vi":"Cuốn tiểu thuyết xem xét vai trò của đức tin tôn giáo trong đời sống gia đình."},{"en":"Many traditions are rooted in deep religious faith.","vi":"Nhiều truyền thống bắt nguồn từ đức tin tôn giáo sâu sắc."}]', '[]', NULL, '/rɪˈlɪdʒəs ˈfeɪθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 2, 'religious freedom', 'tự do tôn giáo', 'adj + n', '[{"en":"The constitution guarantees religious freedom for all citizens.","vi":"Hiến pháp bảo đảm tự do tôn giáo cho mọi công dân."},{"en":"Religious freedom allows people to worship as they choose.","vi":"Tự do tôn giáo cho phép mọi người thờ phụng theo lựa chọn của mình."},{"en":"The essay traces the history of religious freedom in Europe.","vi":"Bài luận lần theo lịch sử tự do tôn giáo ở châu Âu."}]', '[]', NULL, '/rɪˈlɪdʒəs ˈfriːdəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 3, 'religious group', 'nhóm tôn giáo', 'adj + n', '[{"en":"Each religious group celebrates its own important festivals.","vi":"Mỗi nhóm tôn giáo tổ chức những lễ hội quan trọng của riêng mình."},{"en":"The study surveyed members of several different religious groups.","vi":"Nghiên cứu khảo sát thành viên của nhiều nhóm tôn giáo khác nhau."},{"en":"The city is home to many small religious groups.","vi":"Thành phố là nơi cư trú của nhiều nhóm tôn giáo nhỏ."}]', '[]', NULL, '/rɪˈlɪdʒəs ˈɡruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 4, 'religious identity', 'bản sắc tôn giáo', 'adj + n', '[{"en":"Food and dress often express a person''s religious identity.","vi":"Thức ăn và trang phục thường thể hiện bản sắc tôn giáo của một người."},{"en":"Migration can reshape a community''s religious identity over time.","vi":"Di cư có thể định hình lại bản sắc tôn giáo của một cộng đồng theo thời gian."},{"en":"The paper explores how schools influence religious identity.","vi":"Bài báo khám phá cách trường học ảnh hưởng đến bản sắc tôn giáo."}]', '[]', NULL, '/rɪˈlɪdʒəs aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 5, 'religious movement', 'phong trào tôn giáo', 'adj + n', '[{"en":"The historian studied a religious movement from the nineteenth century.","vi":"Nhà sử học nghiên cứu một phong trào tôn giáo từ thế kỷ mười chín."},{"en":"This religious movement quickly spread across several countries.","vi":"Phong trào tôn giáo này nhanh chóng lan rộng qua nhiều quốc gia."},{"en":"A new religious movement emerged among young people in the city.","vi":"Một phong trào tôn giáo mới nổi lên trong giới trẻ ở thành phố."}]', '[]', NULL, '/rɪˈlɪdʒəs ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 6, 'religious practice', 'thực hành tôn giáo', 'adj + n', '[{"en":"Daily prayer is a common religious practice in many cultures.","vi":"Cầu nguyện hằng ngày là một thực hành tôn giáo phổ biến ở nhiều nền văn hóa."},{"en":"Religious practice can vary widely even within one community.","vi":"Thực hành tôn giáo có thể khác nhau rất nhiều ngay trong một cộng đồng."},{"en":"The author links religious practice to community well-being.","vi":"Tác giả gắn thực hành tôn giáo với sự an lành của cộng đồng."}]', '[]', NULL, '/rɪˈlɪdʒəs ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 7, 'rely heavily on', 'phụ thuộc nhiều vào', 'v + adv', '[{"en":"Many farmers rely heavily on rainfall for their crops.","vi":"Nhiều nông dân phụ thuộc nhiều vào lượng mưa cho mùa màng của họ."},{"en":"The argument relies heavily on a single, outdated source.","vi":"Lập luận phụ thuộc nhiều vào một nguồn duy nhất đã lỗi thời."},{"en":"Modern cities rely heavily on a steady supply of energy.","vi":"Các thành phố hiện đại phụ thuộc nhiều vào nguồn cung năng lượng ổn định."}]', '[]', NULL, '/rɪˈlaɪ ˈhevɪli ɑːn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 8, 'remain constant', 'giữ nguyên không đổi', 'v + adj', '[{"en":"The pressure must remain constant for the reaction to work.","vi":"Áp suất phải giữ nguyên không đổi để phản ứng diễn ra."},{"en":"If demand remains constant, prices are unlikely to change.","vi":"Nếu nhu cầu giữ nguyên không đổi, giá khó có khả năng thay đổi."},{"en":"The team kept the temperature remaining constant throughout.","vi":"Nhóm giữ cho nhiệt độ không đổi trong suốt quá trình."}]', '[]', NULL, '/rɪˈmeɪn ˈkɑːnstənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 9, 'remain stable', 'vẫn ổn định', 'v + adj', '[{"en":"House prices are expected to remain stable next year.","vi":"Giá nhà được dự đoán sẽ vẫn ổn định vào năm tới."},{"en":"His blood pressure remained stable after the treatment.","vi":"Huyết áp của anh vẫn ổn định sau khi điều trị."},{"en":"The population is likely to remain stable for a decade.","vi":"Dân số có khả năng vẫn ổn định trong một thập kỷ."}]', '[]', NULL, '/rɪˈmeɪn ˈsteɪbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 10, 'remain unchanged', 'vẫn không thay đổi', 'v + adj', '[{"en":"The basic rules of the game remain unchanged today.","vi":"Các quy tắc cơ bản của trò chơi vẫn không thay đổi đến nay."},{"en":"Despite the reforms, working conditions remained unchanged.","vi":"Dù có cải cách, điều kiện làm việc vẫn không thay đổi."},{"en":"If the policy remains unchanged, the problem will continue.","vi":"Nếu chính sách vẫn không thay đổi, vấn đề sẽ tiếp diễn."}]', '[]', NULL, '/rɪˈmeɪn ʌnˈtʃeɪndʒd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 11, 'remain unclear', 'vẫn chưa rõ ràng', 'v + adj', '[{"en":"The cause of the disease remains unclear to scientists.","vi":"Nguyên nhân của căn bệnh vẫn chưa rõ ràng với các nhà khoa học."},{"en":"It remains unclear whether the policy actually reduced crime.","vi":"Vẫn chưa rõ liệu chính sách có thực sự giảm tội phạm hay không."},{"en":"The author admits the results remain unclear and need further study.","vi":"Tác giả thừa nhận kết quả vẫn chưa rõ ràng và cần nghiên cứu thêm."}]', '[]', NULL, '/rɪˈmeɪn ʌnˈklɪr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 12, 'remarkably similar', 'giống nhau một cách đáng kinh ngạc', 'adv + adj', '[{"en":"The two studies reached remarkably similar conclusions.","vi":"Hai nghiên cứu đi đến những kết luận giống nhau một cách đáng kinh ngạc."},{"en":"Their handwriting was remarkably similar despite the distance.","vi":"Chữ viết của họ giống nhau một cách đáng kinh ngạc dù cách xa nhau."},{"en":"The two languages have remarkably similar grammar structures.","vi":"Hai ngôn ngữ có cấu trúc ngữ pháp giống nhau một cách đáng kinh ngạc."}]', '[]', NULL, '/rɪˈmɑːrkəbli ˈsɪmələr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 13, 'renewable energy', 'năng lượng tái tạo', 'adj + n', '[{"en":"Many countries are investing heavily in renewable energy.","vi":"Nhiều quốc gia đang đầu tư mạnh vào năng lượng tái tạo."},{"en":"Solar and wind are the most common renewable energy sources.","vi":"Mặt trời và gió là những nguồn năng lượng tái tạo phổ biến nhất."},{"en":"Renewable energy could replace much of our fossil fuel use.","vi":"Năng lượng tái tạo có thể thay thế phần lớn việc dùng nhiên liệu hóa thạch."}]', '[]', NULL, '/rɪˈnuːəbəl ˈenərdʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 14, 'renewed interest', 'sự quan tâm trở lại', 'adj + n', '[{"en":"The discovery sparked renewed interest in ancient farming methods.","vi":"Khám phá này khơi dậy sự quan tâm trở lại về các phương pháp canh tác cổ."},{"en":"There is renewed interest in studying local dialects.","vi":"Có sự quan tâm trở lại đối với việc nghiên cứu các phương ngữ địa phương."},{"en":"The film led to renewed interest in the author''s work.","vi":"Bộ phim dẫn đến sự quan tâm trở lại với tác phẩm của nhà văn."}]', '[]', NULL, '/rɪˈnuːd ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 15, 'report data', 'báo cáo dữ liệu', 'v + n', '[{"en":"Researchers must report data honestly, even when results disappoint.","vi":"Các nhà nghiên cứu phải báo cáo dữ liệu trung thực, ngay cả khi kết quả gây thất vọng."},{"en":"The article reports data collected over three full years.","vi":"Bài báo báo cáo dữ liệu thu thập trong suốt ba năm."},{"en":"Please report data clearly using tables and figures.","vi":"Vui lòng báo cáo dữ liệu rõ ràng bằng bảng và biểu đồ."}]', '[]', NULL, '/rɪˈpɔːrt ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 16, 'report findings', 'báo cáo kết quả nghiên cứu', 'v + n', '[{"en":"The committee will report findings to the board next week.","vi":"Ủy ban sẽ báo cáo kết quả nghiên cứu lên hội đồng vào tuần tới."},{"en":"Scientists report findings in peer-reviewed academic journals.","vi":"Các nhà khoa học báo cáo kết quả nghiên cứu trên các tạp chí học thuật được bình duyệt."},{"en":"The team will report findings at the international conference.","vi":"Nhóm sẽ báo cáo kết quả nghiên cứu tại hội nghị quốc tế."}]', '[]', NULL, '/rɪˈpɔːrt ˈfaɪndɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 17, 'representative government', 'chính phủ đại diện', 'adj + n', '[{"en":"Free elections are essential to representative government.","vi":"Bầu cử tự do là yếu tố thiết yếu của chính phủ đại diện."},{"en":"The essay traces the rise of representative government in Europe.","vi":"Bài luận lần theo sự trỗi dậy của chính phủ đại diện ở châu Âu."},{"en":"Representative government depends on citizens trusting their leaders.","vi":"Chính phủ đại diện phụ thuộc vào việc công dân tin tưởng các lãnh đạo của mình."}]', '[]', NULL, '/ˌreprɪˈzentətɪv ˈɡʌvərnmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 18, 'require consideration', 'cần được xem xét', 'v + n', '[{"en":"These ethical questions require careful consideration before any decision.","vi":"Những câu hỏi đạo đức này cần được xem xét cẩn thận trước mọi quyết định."},{"en":"The proposal will require consideration by the whole committee.","vi":"Đề xuất sẽ cần được toàn bộ ủy ban xem xét."},{"en":"Several factors require consideration when designing the experiment.","vi":"Một số yếu tố cần được xem xét khi thiết kế thí nghiệm."}]', '[]', NULL, '/rɪˈkwaɪər kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 19, 'require knowledge', 'đòi hỏi kiến thức', 'v + n', '[{"en":"These tasks require knowledge of basic statistics and coding.","vi":"Những nhiệm vụ này đòi hỏi kiến thức về thống kê cơ bản và lập trình."},{"en":"The job requires knowledge of at least two foreign languages.","vi":"Công việc đòi hỏi kiến thức về ít nhất hai ngoại ngữ."},{"en":"Interpreting the results requires knowledge of the local context.","vi":"Việc diễn giải kết quả đòi hỏi kiến thức về bối cảnh địa phương."}]', '[]', NULL, '/rɪˈkwaɪər ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 20, 'require resources', 'đòi hỏi nguồn lực', 'v + n', '[{"en":"Large projects require resources that small teams rarely have.","vi":"Các dự án lớn đòi hỏi nguồn lực mà những nhóm nhỏ hiếm khi có."},{"en":"Training new staff requires resources and a lot of time.","vi":"Đào tạo nhân viên mới đòi hỏi nguồn lực và rất nhiều thời gian."},{"en":"Such reforms require resources that the government cannot easily find.","vi":"Những cải cách như vậy đòi hỏi nguồn lực mà chính phủ khó tìm được."}]', '[]', NULL, '/rɪˈkwaɪər ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 21, 'research effort', 'nỗ lực nghiên cứu', 'n + n', '[{"en":"The vaccine resulted from a huge international research effort.","vi":"Vắc-xin là kết quả của một nỗ lực nghiên cứu quốc tế khổng lồ."},{"en":"Much research effort has gone into understanding the disease.","vi":"Nhiều nỗ lực nghiên cứu đã được dành để hiểu căn bệnh này."},{"en":"The university coordinates research effort across several departments.","vi":"Trường đại học điều phối nỗ lực nghiên cứu giữa nhiều khoa."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˈefərt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 22, 'research evidence', 'bằng chứng nghiên cứu', 'n + n', '[{"en":"Strong research evidence supports the benefits of early reading.","vi":"Bằng chứng nghiên cứu vững chắc ủng hộ lợi ích của việc đọc sớm."},{"en":"Policy should be based on solid research evidence, not opinion.","vi":"Chính sách nên dựa trên bằng chứng nghiên cứu vững chắc, không phải ý kiến."},{"en":"The author reviews research evidence from the past ten years.","vi":"Tác giả điểm lại bằng chứng nghiên cứu trong mười năm qua."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 23, 'research findings', 'kết quả nghiên cứu', 'n + n', '[{"en":"The research findings were published in a leading journal.","vi":"Kết quả nghiên cứu được công bố trên một tạp chí hàng đầu."},{"en":"These research findings could change how teachers plan lessons.","vi":"Những kết quả nghiên cứu này có thể thay đổi cách giáo viên soạn bài."},{"en":"The author summarises the main research findings in chapter five.","vi":"Tác giả tóm tắt các kết quả nghiên cứu chính trong chương năm."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˈfaɪndɪŋz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 24, 'research methodology', 'phương pháp nghiên cứu', 'n + n', '[{"en":"The chapter explains the research methodology used in the study.","vi":"Chương này giải thích phương pháp nghiên cứu được dùng trong nghiên cứu."},{"en":"A clear research methodology makes results easier to replicate.","vi":"Một phương pháp nghiên cứu rõ ràng giúp kết quả dễ tái lập hơn."},{"en":"Reviewers criticised the weak research methodology of the paper.","vi":"Người bình duyệt chỉ trích phương pháp nghiên cứu yếu của bài báo."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˌmeθəˈdɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 25, 'research purposes', 'mục đích nghiên cứu', 'n + n', '[{"en":"The data may be used only for research purposes.","vi":"Dữ liệu chỉ có thể được dùng cho mục đích nghiên cứu."},{"en":"Volunteers agreed to share their records for research purposes.","vi":"Các tình nguyện viên đồng ý chia sẻ hồ sơ của họ cho mục đích nghiên cứu."},{"en":"The samples were collected purely for research purposes.","vi":"Các mẫu được thu thập hoàn toàn cho mục đích nghiên cứu."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˈpɜːrpəsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 26, 'research topic', 'đề tài nghiên cứu', 'n + n', '[{"en":"Choosing a good research topic is the hardest first step.","vi":"Chọn một đề tài nghiên cứu tốt là bước đầu tiên khó nhất."},{"en":"Her research topic focuses on bilingual children in cities.","vi":"Đề tài nghiên cứu của cô tập trung vào trẻ song ngữ ở thành phố."},{"en":"The supervisor helped him narrow down his research topic.","vi":"Người hướng dẫn giúp anh thu hẹp đề tài nghiên cứu của mình."}]', '[]', NULL, '/ˈriːsɜːrtʃ ˈtɑːpɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 27, 'resolve a conflict', 'giải quyết một xung đột', 'v + n', '[{"en":"The mediator helped both sides resolve a conflict peacefully.","vi":"Người hòa giải đã giúp hai bên giải quyết xung đột một cách ôn hòa."},{"en":"Good leaders know how to resolve a conflict quickly.","vi":"Lãnh đạo giỏi biết cách giải quyết xung đột một cách nhanh chóng."},{"en":"Diplomacy aims to resolve a conflict without using force.","vi":"Ngoại giao nhằm giải quyết xung đột mà không dùng vũ lực."}]', '[]', NULL, '/rɪˈzɑːlv ə ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 28, 'resolve a dispute', 'giải quyết một tranh chấp', 'v + n', '[{"en":"The court was asked to resolve a dispute over land.","vi":"Tòa án được yêu cầu giải quyết một tranh chấp về đất đai."},{"en":"They hired a lawyer to resolve a dispute between partners.","vi":"Họ thuê luật sư để giải quyết tranh chấp giữa các đối tác."},{"en":"Negotiation often helps resolve a dispute more cheaply than litigation.","vi":"Thương lượng thường giúp giải quyết tranh chấp rẻ hơn so với kiện tụng."}]', '[]', NULL, '/rɪˈzɑːlv ə dɪˈspjuːt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 29, 'respond appropriately', 'phản ứng một cách phù hợp', 'v + adv', '[{"en":"Nurses are trained to respond appropriately in emergency situations.","vi":"Y tá được đào tạo để phản ứng phù hợp trong các tình huống khẩn cấp."},{"en":"Students must learn to respond appropriately to difficult questions.","vi":"Học sinh phải học cách phản ứng phù hợp với những câu hỏi khó."},{"en":"The system fails when staff cannot respond appropriately to feedback.","vi":"Hệ thống thất bại khi nhân viên không thể phản ứng phù hợp với phản hồi."}]', '[]', NULL, '/rɪˈspɑːnd əˈproʊpriətli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 30, 'review a study', 'xem xét, đánh giá một nghiên cứu', 'v + n', '[{"en":"Experts were asked to review a study before its publication.","vi":"Các chuyên gia được yêu cầu đánh giá một nghiên cứu trước khi xuất bản."},{"en":"She had to review a study on climate change for class.","vi":"Cô ấy phải đánh giá một nghiên cứu về biến đổi khí hậu cho lớp học."},{"en":"Peer reviewers carefully review a study to ensure its quality.","vi":"Người phản biện cẩn thận đánh giá một nghiên cứu để đảm bảo chất lượng."}]', '[]', NULL, '/rɪˈvjuː ə ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 31, 'revised edition', 'ấn bản sửa đổi', 'adj + n', '[{"en":"The revised edition of the textbook includes several new chapters.","vi":"Ấn bản sửa đổi của giáo trình bao gồm vài chương mới."},{"en":"Students were told to buy the revised edition this year.","vi":"Sinh viên được yêu cầu mua ấn bản sửa đổi năm nay."},{"en":"The revised edition corrects many errors found in earlier printings.","vi":"Ấn bản sửa đổi sửa nhiều lỗi tìm thấy trong các bản in trước."}]', '[]', NULL, '/rɪˈvaɪzd ɪˈdɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 32, 'revised version', 'phiên bản sửa đổi', 'adj + n', '[{"en":"She submitted a revised version of her essay after feedback.","vi":"Cô ấy nộp một phiên bản sửa đổi của bài luận sau khi nhận phản hồi."},{"en":"The revised version of the policy addresses earlier concerns.","vi":"Phiên bản sửa đổi của chính sách giải quyết những lo ngại trước đó."},{"en":"Please read the revised version before the meeting tomorrow.","vi":"Hãy đọc phiên bản sửa đổi trước cuộc họp ngày mai."}]', '[]', NULL, '/rɪˈvaɪzd ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 33, 'rich source', 'nguồn dồi dào, phong phú', 'adj + n', '[{"en":"Old newspapers are a rich source of historical information.","vi":"Những tờ báo cũ là một nguồn thông tin lịch sử phong phú."},{"en":"Vegetables are a rich source of vitamins and fiber.","vi":"Rau củ là một nguồn dồi dào vitamin và chất xơ."},{"en":"Interviews provided a rich source of data for the study.","vi":"Các cuộc phỏng vấn cung cấp một nguồn dữ liệu phong phú cho nghiên cứu."}]', '[]', NULL, '/rɪtʃ sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 34, 'rising cost', 'chi phí tăng cao', 'adj + n', '[{"en":"The rising cost of housing worries many young families.","vi":"Chi phí nhà ở tăng cao khiến nhiều gia đình trẻ lo lắng."},{"en":"Universities struggle with the rising cost of research equipment.","vi":"Các trường đại học chật vật với chi phí thiết bị nghiên cứu tăng cao."},{"en":"The rising cost of fuel affected the whole economy.","vi":"Chi phí nhiên liệu tăng cao ảnh hưởng đến toàn bộ nền kinh tế."}]', '[]', NULL, '/ˈraɪzɪŋ kɔːst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 35, 'risk assessment', 'việc đánh giá rủi ro', 'n + n', '[{"en":"A careful risk assessment was completed before the project began.","vi":"Một bản đánh giá rủi ro kỹ lưỡng đã hoàn thành trước khi dự án bắt đầu."},{"en":"Banks use risk assessment to decide whether to grant loans.","vi":"Ngân hàng dùng việc đánh giá rủi ro để quyết định cho vay hay không."},{"en":"The risk assessment identified several potential safety hazards.","vi":"Việc đánh giá rủi ro đã xác định một số nguy cơ an toàn tiềm ẩn."}]', '[]', NULL, '/rɪsk əˈsesmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 36, 'roughly equal', 'gần như bằng nhau', 'adv + adj', '[{"en":"The two groups were roughly equal in size and ability.","vi":"Hai nhóm gần như bằng nhau về quy mô và năng lực."},{"en":"Both candidates received a roughly equal share of votes.","vi":"Cả hai ứng viên nhận được số phiếu gần như bằng nhau."},{"en":"The costs and benefits turned out to be roughly equal.","vi":"Chi phí và lợi ích hóa ra gần như bằng nhau."}]', '[]', NULL, '/ˈrʌfli ˈiːkwəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 37, 'roughly equivalent', 'gần như tương đương', 'adj + n', '[{"en":"One mile is roughly equivalent to one point six kilometers.","vi":"Một dặm gần như tương đương với một phẩy sáu kilômét."},{"en":"His salary is roughly equivalent to the national average.","vi":"Lương của anh ấy gần như tương đương mức trung bình toàn quốc."},{"en":"The two degrees are roughly equivalent in academic value.","vi":"Hai tấm bằng gần như tương đương về giá trị học thuật."}]', '[]', NULL, '/ˈrʌfli ɪˈkwɪvələnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 38, 'ruling class', 'giai cấp thống trị', 'adj + n', '[{"en":"The ruling class held most of the country''s wealth.","vi":"Giai cấp thống trị nắm giữ phần lớn của cải của đất nước."},{"en":"Historians study how the ruling class maintained its power.","vi":"Các nhà sử học nghiên cứu cách giai cấp thống trị duy trì quyền lực."},{"en":"The revolution aimed to overthrow the old ruling class.","vi":"Cuộc cách mạng nhằm lật đổ giai cấp thống trị cũ."}]', '[]', NULL, '/ˈruːlɪŋ klæs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 39, 'ruling party', 'đảng cầm quyền', 'adj + n', '[{"en":"The ruling party announced new economic reforms this week.","vi":"Đảng cầm quyền công bố các cải cách kinh tế mới trong tuần này."},{"en":"Voters seemed dissatisfied with the ruling party''s recent policies.","vi":"Cử tri có vẻ không hài lòng với các chính sách gần đây của đảng cầm quyền."},{"en":"The ruling party won a comfortable majority in parliament.","vi":"Đảng cầm quyền giành đa số ghế thoải mái trong quốc hội."}]', '[]', NULL, '/ˈruːlɪŋ ˈpɑːrti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 40, 'rural area', 'khu vực nông thôn', 'adj + n', '[{"en":"Many people in the rural area lack access to hospitals.","vi":"Nhiều người ở khu vực nông thôn thiếu khả năng tiếp cận bệnh viện."},{"en":"Internet connections remain slow in this remote rural area.","vi":"Kết nối internet vẫn còn chậm ở khu vực nông thôn xa xôi này."},{"en":"Young people often leave the rural area to find work.","vi":"Người trẻ thường rời khu vực nông thôn để tìm việc làm."}]', '[]', NULL, '/ˈrʊrəl ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 41, 'rural community', 'cộng đồng nông thôn', 'adj + n', '[{"en":"The rural community depends heavily on farming for income.","vi":"Cộng đồng nông thôn phụ thuộc nhiều vào nông nghiệp để kiếm thu nhập."},{"en":"New roads connected the rural community to nearby towns.","vi":"Những con đường mới nối cộng đồng nông thôn với các thị trấn gần đó."},{"en":"Researchers studied health needs in a small rural community.","vi":"Các nhà nghiên cứu khảo sát nhu cầu sức khỏe ở một cộng đồng nông thôn nhỏ."}]', '[]', NULL, '/ˈrʊrəl kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 42, 'rural economy', 'kinh tế nông thôn', 'adj + n', '[{"en":"The rural economy suffered after the factory closed down.","vi":"Kinh tế nông thôn bị ảnh hưởng sau khi nhà máy đóng cửa."},{"en":"Tourism has helped diversify the local rural economy.","vi":"Du lịch đã giúp đa dạng hóa nền kinh tế nông thôn địa phương."},{"en":"Government grants aim to strengthen the struggling rural economy.","vi":"Các khoản tài trợ của chính phủ nhằm củng cố nền kinh tế nông thôn đang khó khăn."}]', '[]', NULL, '/ˈrʊrəl ɪˈkɑːnəmi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 43, 'rural population', 'dân số nông thôn', 'adj + n', '[{"en":"The rural population has declined steadily over recent decades.","vi":"Dân số nông thôn đã giảm đều trong những thập kỷ gần đây."},{"en":"Most of the rural population works in agriculture.","vi":"Phần lớn dân số nông thôn làm việc trong lĩnh vực nông nghiệp."},{"en":"Health services struggle to reach the scattered rural population.","vi":"Các dịch vụ y tế khó tiếp cận được dân số nông thôn rải rác."}]', '[]', NULL, '/ˈrʊrəl ˌpɑːpjəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 44, 'rural society', 'xã hội nông thôn', 'adj + n', '[{"en":"Traditional values remain strong in this rural society.","vi":"Các giá trị truyền thống vẫn còn mạnh mẽ trong xã hội nông thôn này."},{"en":"Industrialization gradually transformed the old rural society.","vi":"Công nghiệp hóa dần dần biến đổi xã hội nông thôn cũ."},{"en":"Family ties play a central role in rural society.","vi":"Mối quan hệ gia đình đóng vai trò trung tâm trong xã hội nông thôn."}]', '[]', NULL, '/ˈrʊrəl səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 45, 'safe sex', 'tình dục an toàn', 'adj + n', '[{"en":"Health campaigns encourage young people to practice safe sex.","vi":"Các chiến dịch sức khỏe khuyến khích người trẻ thực hành tình dục an toàn."},{"en":"Teachers discussed safe sex during the health education class.","vi":"Giáo viên thảo luận về tình dục an toàn trong giờ giáo dục sức khỏe."},{"en":"Practicing safe sex helps prevent the spread of disease.","vi":"Thực hành tình dục an toàn giúp ngăn ngừa lây lan bệnh tật."}]', '[]', NULL, '/seɪf seks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 46, 'salient characteristic', 'đặc điểm nổi bật', 'adj + n', '[{"en":"Honesty is a salient characteristic of his leadership style.","vi":"Sự trung thực là một đặc điểm nổi bật trong phong cách lãnh đạo của anh ấy."},{"en":"The author describes the salient characteristic of each species.","vi":"Tác giả mô tả đặc điểm nổi bật của mỗi loài."},{"en":"Curiosity is a salient characteristic of successful researchers.","vi":"Tính tò mò là một đặc điểm nổi bật của các nhà nghiên cứu thành công."}]', '[]', NULL, '/ˈseɪliənt ˌkerəktəˈrɪstɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 47, 'salient feature', 'đặc trưng nổi bật', 'adj + n', '[{"en":"The report highlights the salient feature of each proposal.","vi":"Báo cáo nhấn mạnh đặc trưng nổi bật của mỗi đề xuất."},{"en":"A salient feature of the design is its simplicity.","vi":"Một đặc trưng nổi bật của thiết kế là sự đơn giản của nó."},{"en":"Students should identify the salient feature of the painting.","vi":"Học sinh nên xác định đặc trưng nổi bật của bức tranh."}]', '[]', NULL, '/ˈseɪliənt ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 48, 'scarce resources', 'nguồn lực khan hiếm', 'adj + n', '[{"en":"Managers must allocate scarce resources as efficiently as possible.","vi":"Người quản lý phải phân bổ các nguồn lực khan hiếm hiệu quả nhất có thể."},{"en":"Wars often break out over scarce resources like water.","vi":"Chiến tranh thường nổ ra vì các nguồn lực khan hiếm như nước."},{"en":"Economics studies how people use scarce resources wisely.","vi":"Kinh tế học nghiên cứu cách con người sử dụng nguồn lực khan hiếm một cách khôn ngoan."}]', '[]', NULL, '/skers ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 49, 'schematic representation', 'biểu diễn dạng sơ đồ', 'adj + n', '[{"en":"The diagram offers a schematic representation of the process.","vi":"Sơ đồ cung cấp một biểu diễn dạng sơ đồ của quá trình."},{"en":"A schematic representation helps readers grasp complex relationships quickly.","vi":"Biểu diễn dạng sơ đồ giúp người đọc nắm bắt các mối quan hệ phức tạp nhanh chóng."},{"en":"The textbook includes a schematic representation of the human heart.","vi":"Giáo trình có một biểu diễn dạng sơ đồ của tim người."}]', '[]', NULL, '/skɪˈmætɪk ˌreprɪzenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 50, 'scholarly journal', 'tạp chí học thuật', 'adj + n', '[{"en":"Her article appeared in a respected scholarly journal last year.","vi":"Bài viết của cô ấy xuất hiện trên một tạp chí học thuật uy tín năm ngoái."},{"en":"A scholarly journal usually requires peer review before publication.","vi":"Một tạp chí học thuật thường yêu cầu phản biện trước khi xuất bản."},{"en":"Students should cite a scholarly journal rather than a blog.","vi":"Sinh viên nên trích dẫn tạp chí học thuật thay vì một blog."}]', '[]', NULL, '/ˈskɑːlərli ˈdʒɜːrnəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 51, 'scholarly literature', 'tài liệu học thuật', 'adj + n', '[{"en":"The thesis reviews recent scholarly literature on the topic.","vi":"Luận văn tổng quan tài liệu học thuật gần đây về chủ đề này."},{"en":"Much scholarly literature supports this particular interpretation.","vi":"Nhiều tài liệu học thuật ủng hộ cách diễn giải cụ thể này."},{"en":"Searching scholarly literature is the first step in research.","vi":"Tìm kiếm tài liệu học thuật là bước đầu tiên trong nghiên cứu."}]', '[]', NULL, '/ˈskɑːlərli ˈlɪtərətʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 52, 'scholarly research', 'nghiên cứu học thuật', 'adj + n', '[{"en":"Years of scholarly research went into writing this book.","vi":"Nhiều năm nghiên cứu học thuật đã được dành để viết cuốn sách này."},{"en":"Scholarly research must follow strict ethical and methodological standards.","vi":"Nghiên cứu học thuật phải tuân theo các chuẩn mực đạo đức và phương pháp nghiêm ngặt."},{"en":"The library supports scholarly research with extensive online databases.","vi":"Thư viện hỗ trợ nghiên cứu học thuật bằng các cơ sở dữ liệu trực tuyến phong phú."}]', '[]', NULL, '/ˈskɑːlərli ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 53, 'scholarly work', 'công trình học thuật', 'adj + n', '[{"en":"Her scholarly work has influenced many younger researchers.","vi":"Công trình học thuật của bà đã ảnh hưởng đến nhiều nhà nghiên cứu trẻ hơn."},{"en":"This scholarly work is widely cited across several disciplines.","vi":"Công trình học thuật này được trích dẫn rộng rãi trong nhiều ngành."},{"en":"Producing serious scholarly work requires patience and discipline.","vi":"Tạo ra công trình học thuật nghiêm túc đòi hỏi sự kiên nhẫn và kỷ luật."}]', '[]', NULL, '/ˈskɑːlərli wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 54, 'scientific community', 'cộng đồng khoa học', 'adj + n', '[{"en":"The discovery surprised much of the scientific community.","vi":"Phát hiện này khiến phần lớn cộng đồng khoa học ngạc nhiên."},{"en":"The scientific community generally accepts the theory of evolution.","vi":"Cộng đồng khoa học nhìn chung chấp nhận thuyết tiến hóa."},{"en":"Her findings were quickly shared with the scientific community.","vi":"Các phát hiện của cô ấy nhanh chóng được chia sẻ với cộng đồng khoa học."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 55, 'scientific discourse', 'diễn ngôn khoa học', 'adj + n', '[{"en":"Scientific discourse relies on clear evidence and logical argument.","vi":"Diễn ngôn khoa học dựa trên bằng chứng rõ ràng và lập luận logic."},{"en":"The journal contributes to ongoing scientific discourse about the climate.","vi":"Tạp chí đóng góp vào diễn ngôn khoa học đang diễn ra về khí hậu."},{"en":"Precise terminology is essential in formal scientific discourse.","vi":"Thuật ngữ chính xác là điều thiết yếu trong diễn ngôn khoa học chính thức."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˈdɪskɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 56, 'scientific evidence', 'bằng chứng khoa học', 'adj + n', '[{"en":"There is strong scientific evidence linking smoking to cancer.","vi":"Có bằng chứng khoa học mạnh mẽ liên kết hút thuốc với ung thư."},{"en":"Policy decisions should be based on solid scientific evidence.","vi":"Các quyết định chính sách nên dựa trên bằng chứng khoa học vững chắc."},{"en":"The claim lacks any reliable scientific evidence to support it.","vi":"Khẳng định này thiếu bất kỳ bằng chứng khoa học đáng tin cậy nào để hỗ trợ."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 57, 'scientific investigation', 'cuộc điều tra khoa học', 'adj + n', '[{"en":"A careful scientific investigation revealed the cause of the outbreak.","vi":"Một cuộc điều tra khoa học kỹ lưỡng đã làm rõ nguyên nhân của đợt bùng phát."},{"en":"Scientific investigation begins with a clear, testable question.","vi":"Điều tra khoa học bắt đầu bằng một câu hỏi rõ ràng, có thể kiểm chứng."},{"en":"The accident prompted a thorough scientific investigation by experts.","vi":"Vụ tai nạn đã thúc đẩy một cuộc điều tra khoa học kỹ lưỡng bởi các chuyên gia."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ɪnˌvestɪˈɡeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 58, 'scientific method', 'phương pháp khoa học', 'adj + n', '[{"en":"The scientific method involves observation, hypothesis, and careful testing.","vi":"Phương pháp khoa học bao gồm quan sát, giả thuyết và kiểm chứng cẩn thận."},{"en":"Students learn the scientific method early in their education.","vi":"Học sinh học phương pháp khoa học sớm trong quá trình học tập."},{"en":"Applying the scientific method reduces bias in research results.","vi":"Áp dụng phương pháp khoa học làm giảm thiên kiến trong kết quả nghiên cứu."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 59, 'scientific objectivity', 'tính khách quan khoa học', 'adj + n', '[{"en":"Scientific objectivity requires researchers to set aside personal beliefs.","vi":"Tính khách quan khoa học đòi hỏi nhà nghiên cứu gạt bỏ niềm tin cá nhân."},{"en":"Critics questioned the scientific objectivity of the funded study.","vi":"Các nhà phê bình nghi ngờ tính khách quan khoa học của nghiên cứu được tài trợ."},{"en":"Maintaining scientific objectivity is difficult when emotions run high.","vi":"Duy trì tính khách quan khoa học rất khó khi cảm xúc dâng cao."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˌɑːbdʒekˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 60, 'scientific research', 'nghiên cứu khoa học', 'adj + n', '[{"en":"The government invests heavily in scientific research each year.","vi":"Chính phủ đầu tư mạnh vào nghiên cứu khoa học mỗi năm."},{"en":"Scientific research often takes years to produce useful results.","vi":"Nghiên cứu khoa học thường mất nhiều năm để tạo ra kết quả hữu ích."},{"en":"New technology has greatly accelerated modern scientific research.","vi":"Công nghệ mới đã đẩy nhanh đáng kể nghiên cứu khoa học hiện đại."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 61, 'scientific theory', 'lý thuyết khoa học', 'adj + n', '[{"en":"A scientific theory must be supported by repeated experiments.","vi":"Một lý thuyết khoa học phải được hỗ trợ bởi các thí nghiệm lặp lại."},{"en":"The professor explained the scientific theory behind black holes.","vi":"Giáo sư giải thích lý thuyết khoa học đằng sau hố đen."},{"en":"New evidence can sometimes overturn an accepted scientific theory.","vi":"Bằng chứng mới đôi khi có thể lật đổ một lý thuyết khoa học đã được chấp nhận."}]', '[]', NULL, '/ˌsaɪənˈtɪfɪk ˈθiːəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 62, 'secondary data', 'dữ liệu thứ cấp', 'adj + n', '[{"en":"The study used secondary data collected by another team.","vi":"Nghiên cứu sử dụng dữ liệu thứ cấp do một nhóm khác thu thập."},{"en":"Analyzing secondary data saved the researchers considerable time.","vi":"Phân tích dữ liệu thứ cấp giúp các nhà nghiên cứu tiết kiệm nhiều thời gian."},{"en":"Secondary data may not perfectly match a new research question.","vi":"Dữ liệu thứ cấp có thể không hoàn toàn phù hợp với câu hỏi nghiên cứu mới."}]', '[]', NULL, '/ˈsekənderi ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 63, 'secondary education', 'giáo dục trung học', 'adj + n', '[{"en":"Most students complete secondary education before entering university.","vi":"Hầu hết học sinh hoàn thành giáo dục trung học trước khi vào đại học."},{"en":"The reform improved the quality of secondary education nationwide.","vi":"Cuộc cải cách đã nâng cao chất lượng giáo dục trung học trên cả nước."},{"en":"Access to secondary education remains limited in some regions.","vi":"Khả năng tiếp cận giáo dục trung học vẫn còn hạn chế ở một số vùng."}]', '[]', NULL, '/ˈsekənderi ˌedʒəˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 64, 'secondary source', 'nguồn thứ cấp', 'adj + n', '[{"en":"A textbook is considered a secondary source, not original research.","vi":"Sách giáo khoa được coi là nguồn thứ cấp, không phải nghiên cứu gốc."},{"en":"Historians compare a secondary source with original documents carefully.","vi":"Các nhà sử học so sánh nguồn thứ cấp với tài liệu gốc một cách cẩn thận."},{"en":"Relying only on a secondary source can introduce errors.","vi":"Chỉ dựa vào một nguồn thứ cấp có thể gây ra sai sót."}]', '[]', NULL, '/ˈsekənderi sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 65, 'security policy', 'chính sách an ninh', 'n + n', '[{"en":"The company updated its security policy after the data breach.","vi":"Công ty đã cập nhật chính sách an ninh sau vụ rò rỉ dữ liệu."},{"en":"A clear security policy protects both staff and customers.","vi":"Một chính sách an ninh rõ ràng bảo vệ cả nhân viên lẫn khách hàng."},{"en":"The government debated changes to its national security policy.","vi":"Chính phủ tranh luận về những thay đổi trong chính sách an ninh quốc gia."}]', '[]', NULL, '/sɪˈkjʊrəti ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 66, 'seek help', 'tìm kiếm sự giúp đỡ', 'v + n', '[{"en":"Students are encouraged to seek help when they struggle.","vi":"Học sinh được khuyến khích tìm kiếm sự giúp đỡ khi gặp khó khăn."},{"en":"Many people hesitate to seek help for mental health.","vi":"Nhiều người ngần ngại tìm kiếm sự giúp đỡ cho sức khỏe tâm thần."},{"en":"If symptoms worsen, you should seek help immediately.","vi":"Nếu triệu chứng trở nặng, bạn nên tìm kiếm sự giúp đỡ ngay lập tức."}]', '[]', NULL, '/siːk help/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 67, 'seek information', 'tìm kiếm thông tin', 'v + n', '[{"en":"Patients increasingly seek information about treatments online.","vi":"Bệnh nhân ngày càng tìm kiếm thông tin về phương pháp điều trị trên mạng."},{"en":"Reporters seek information from multiple sources before publishing.","vi":"Phóng viên tìm kiếm thông tin từ nhiều nguồn trước khi đăng bài."},{"en":"Consumers seek information before making expensive purchasing decisions.","vi":"Người tiêu dùng tìm kiếm thông tin trước khi đưa ra quyết định mua sắm đắt đỏ."}]', '[]', NULL, '/siːk ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 68, 'seem appropriate', 'có vẻ phù hợp', 'v + adj', '[{"en":"This method does not seem appropriate for such young children.","vi":"Phương pháp này có vẻ không phù hợp với trẻ nhỏ như vậy."},{"en":"A formal tone would seem appropriate for this report.","vi":"Một giọng điệu trang trọng có vẻ phù hợp cho báo cáo này."},{"en":"Choose whatever measures seem appropriate to the situation.","vi":"Hãy chọn bất kỳ biện pháp nào có vẻ phù hợp với tình huống."}]', '[]', NULL, '/siːm əˈproʊpriət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 69, 'seem obvious', 'có vẻ hiển nhiên', 'v + adj', '[{"en":"The answer may seem obvious, but it is actually complex.","vi":"Câu trả lời có vẻ hiển nhiên, nhưng thực ra lại phức tạp."},{"en":"Some solutions seem obvious only after careful analysis.","vi":"Một số giải pháp chỉ có vẻ hiển nhiên sau khi phân tích kỹ lưỡng."},{"en":"What seems obvious to experts can confuse beginners completely.","vi":"Điều có vẻ hiển nhiên với chuyên gia có thể làm người mới hoàn toàn bối rối."}]', '[]', NULL, '/siːm ˈɑːbviəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 70, 'seem plausible', 'có vẻ hợp lý', 'v + adj', '[{"en":"His explanation does seem plausible given the available evidence.","vi":"Lời giải thích của anh ấy có vẻ hợp lý dựa trên bằng chứng hiện có."},{"en":"Several theories seem plausible, so further research is needed.","vi":"Một số lý thuyết có vẻ hợp lý, vì vậy cần nghiên cứu thêm."},{"en":"The argument may seem plausible but lacks solid support.","vi":"Lập luận có vẻ hợp lý nhưng thiếu sự hỗ trợ vững chắc."}]', '[]', NULL, '/siːm ˈplɔːzəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 71, 'seem unlikely', 'có vẻ khó xảy ra', 'v + adj', '[{"en":"A quick recovery now seems unlikely given the circumstances.","vi":"Một sự hồi phục nhanh chóng giờ đây có vẻ khó xảy ra trong hoàn cảnh này."},{"en":"It seems unlikely that the project will finish on time.","vi":"Có vẻ khó xảy ra việc dự án sẽ hoàn thành đúng hạn."},{"en":"Such an extreme outcome seems unlikely under normal conditions.","vi":"Một kết quả cực đoan như vậy có vẻ khó xảy ra trong điều kiện bình thường."}]', '[]', NULL, '/siːm ʌnˈlaɪkli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 72, 'seminal study', 'nghiên cứu mang tính nền tảng', 'adj + n', '[{"en":"This seminal study shaped the entire field for decades.","vi":"Nghiên cứu nền tảng này đã định hình cả lĩnh vực trong nhiều thập kỷ."},{"en":"Researchers still cite that seminal study in their papers.","vi":"Các nhà nghiên cứu vẫn trích dẫn nghiên cứu nền tảng đó trong bài viết của họ."},{"en":"Her seminal study introduced a completely new methodology.","vi":"Nghiên cứu nền tảng của bà đã giới thiệu một phương pháp hoàn toàn mới."}]', '[]', NULL, '/ˈseminəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 73, 'seminal work', 'công trình mang tính nền tảng', 'adj + n', '[{"en":"Darwin''s seminal work transformed how we understand life.","vi":"Công trình nền tảng của Darwin đã thay đổi cách chúng ta hiểu về sự sống."},{"en":"The seminal work remains essential reading for new students.","vi":"Công trình nền tảng này vẫn là tài liệu đọc thiết yếu cho sinh viên mới."},{"en":"Many later theories build upon that seminal work.","vi":"Nhiều lý thuyết về sau được xây dựng dựa trên công trình nền tảng đó."}]', '[]', NULL, '/ˈseminəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 74, 'senior management', 'ban quản lý cấp cao', 'adj + n', '[{"en":"Senior management approved the new strategy after long discussions.","vi":"Ban quản lý cấp cao đã phê duyệt chiến lược mới sau các cuộc thảo luận dài."},{"en":"The report goes directly to senior management each quarter.","vi":"Báo cáo được gửi thẳng đến ban quản lý cấp cao mỗi quý."},{"en":"Senior management is responsible for setting the company''s direction.","vi":"Ban quản lý cấp cao chịu trách nhiệm định hướng cho công ty."}]', '[]', NULL, '/ˈsiːnjər ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 75, 'separate entity', 'thực thể riêng biệt', 'adj + n', '[{"en":"Legally, the company is a separate entity from its owners.","vi":"Về mặt pháp lý, công ty là một thực thể riêng biệt với chủ sở hữu."},{"en":"Each subsidiary operates as a separate entity with its own budget.","vi":"Mỗi công ty con hoạt động như một thực thể riêng biệt với ngân sách riêng."},{"en":"The mind and body are sometimes treated as separate entities.","vi":"Tâm trí và cơ thể đôi khi được xem như những thực thể riêng biệt."}]', '[]', NULL, '/ˈsepərət ˈentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 76, 'serious challenge', 'thách thức nghiêm trọng', 'adj + n', '[{"en":"Climate change poses a serious challenge to future generations.","vi":"Biến đổi khí hậu đặt ra một thách thức nghiêm trọng cho các thế hệ tương lai."},{"en":"Funding cuts present a serious challenge for the hospital.","vi":"Việc cắt giảm ngân sách là một thách thức nghiêm trọng cho bệnh viện."},{"en":"The new policy faced a serious challenge in court.","vi":"Chính sách mới đối mặt với một thách thức nghiêm trọng tại tòa án."}]', '[]', NULL, '/ˈsɪriəs ˈtʃælɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 77, 'serious consequences', 'hậu quả nghiêm trọng', 'adj + n', '[{"en":"Ignoring safety rules can lead to serious consequences.","vi":"Phớt lờ các quy tắc an toàn có thể dẫn đến hậu quả nghiêm trọng."},{"en":"The decision had serious consequences for the local economy.","vi":"Quyết định này gây ra hậu quả nghiêm trọng cho nền kinh tế địa phương."},{"en":"Failing to act now may bring serious consequences later.","vi":"Không hành động ngay bây giờ có thể mang lại hậu quả nghiêm trọng về sau."}]', '[]', NULL, '/ˈsɪriəs ˈkɑːnsəkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 78, 'serious offence', 'tội nghiêm trọng', 'adj + n', '[{"en":"Fraud is a serious offence punishable by imprisonment.","vi":"Gian lận là một tội nghiêm trọng có thể bị phạt tù."},{"en":"Cheating in exams is treated as a serious offence.","vi":"Gian lận trong thi cử được xem là một tội nghiêm trọng."},{"en":"He was charged with a serious offence against public safety.","vi":"Anh ta bị buộc tội một tội nghiêm trọng chống lại an toàn công cộng."}]', '[]', NULL, '/ˈsɪriəs əˈfens/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 79, 'serve a function', 'phục vụ một chức năng', 'v + n', '[{"en":"Even small details serve a function in the overall design.","vi":"Ngay cả chi tiết nhỏ cũng phục vụ một chức năng trong tổng thể thiết kế."},{"en":"Rituals serve a function in holding communities together.","vi":"Các nghi lễ phục vụ một chức năng trong việc gắn kết cộng đồng."},{"en":"Each part of the cell serves a specific function.","vi":"Mỗi phần của tế bào phục vụ một chức năng cụ thể."}]', '[]', NULL, '/sɜːrv ə ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 80, 'service sector', 'khu vực dịch vụ', 'n + n', '[{"en":"The service sector now employs most of the workforce.","vi":"Khu vực dịch vụ hiện sử dụng phần lớn lực lượng lao động."},{"en":"Tourism is a major part of the country''s service sector.","vi":"Du lịch là một phần lớn của khu vực dịch vụ của đất nước."},{"en":"Automation is gradually changing jobs in the service sector.","vi":"Tự động hóa đang dần thay đổi các công việc trong khu vực dịch vụ."}]', '[]', NULL, '/ˈsɜːrvɪs ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 81, 'set a goal', 'đặt ra một mục tiêu', 'v + n', '[{"en":"It helps to set a goal before starting any project.","vi":"Việc đặt ra một mục tiêu trước khi bắt đầu dự án rất hữu ích."},{"en":"The coach asked each player to set a personal goal.","vi":"Huấn luyện viên yêu cầu mỗi cầu thủ đặt ra một mục tiêu cá nhân."},{"en":"Companies set a goal to reduce emissions by half.","vi":"Các công ty đặt ra mục tiêu giảm một nửa lượng khí thải."}]', '[]', NULL, '/set ə ɡoʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 82, 'set a target', 'đặt ra một chỉ tiêu', 'v + n', '[{"en":"The government set a target to plant a million trees.","vi":"Chính phủ đặt ra chỉ tiêu trồng một triệu cây xanh."},{"en":"Managers set a target for monthly sales each quarter.","vi":"Người quản lý đặt ra chỉ tiêu doanh số hàng tháng mỗi quý."},{"en":"It is wise to set a target that is realistic.","vi":"Đặt ra một chỉ tiêu thực tế là điều khôn ngoan."}]', '[]', NULL, '/set ə ˈtɑːrɡət/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 83, 'set an objective', 'đặt ra một mục tiêu', 'v + n', '[{"en":"Teachers set an objective for every lesson they plan.","vi":"Giáo viên đặt ra một mục tiêu cho mỗi bài học họ chuẩn bị."},{"en":"The team set an objective to launch the product early.","vi":"Nhóm đặt ra mục tiêu ra mắt sản phẩm sớm."},{"en":"Before research, you should set an objective clearly.","vi":"Trước khi nghiên cứu, bạn nên đặt ra một mục tiêu rõ ràng."}]', '[]', NULL, '/set ən əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 84, 'set the agenda', 'định ra chương trình nghị sự', 'v + n', '[{"en":"The chairperson will set the agenda for tomorrow''s meeting.","vi":"Chủ tọa sẽ định ra chương trình nghị sự cho cuộc họp ngày mai."},{"en":"Powerful media outlets often set the agenda for public debate.","vi":"Các hãng truyền thông lớn thường định ra chương trình nghị sự cho tranh luận công chúng."},{"en":"Activists tried to set the agenda on environmental issues.","vi":"Các nhà hoạt động cố gắng định ra chương trình nghị sự về các vấn đề môi trường."}]', '[]', NULL, '/set ði əˈdʒendə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 85, 'set the parameters', 'thiết lập các thông số', 'v + n', '[{"en":"The professor set the parameters for the final assignment clearly.","vi":"Giáo sư thiết lập rõ ràng các thông số cho bài tập cuối kỳ."},{"en":"We must set the parameters before running the experiment.","vi":"Chúng ta phải thiết lập các thông số trước khi tiến hành thí nghiệm."},{"en":"The contract sets the parameters within which both parties operate.","vi":"Hợp đồng thiết lập các thông số mà cả hai bên hoạt động trong đó."}]', '[]', NULL, '/set ðə pəˈræmətərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 86, 'severely affect', 'ảnh hưởng nghiêm trọng', 'adv + v', '[{"en":"The drought severely affected crops across the entire region.","vi":"Hạn hán đã ảnh hưởng nghiêm trọng đến mùa màng trên toàn khu vực."},{"en":"Pollution can severely affect the health of local residents.","vi":"Ô nhiễm có thể ảnh hưởng nghiêm trọng đến sức khỏe của cư dân địa phương."},{"en":"The strike severely affected public transport for several days.","vi":"Cuộc đình công đã ảnh hưởng nghiêm trọng đến giao thông công cộng trong vài ngày."}]', '[]', NULL, '/səˈvɪrli əˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 87, 'sexual abuse', 'lạm dụng tình dục', 'adj + n', '[{"en":"The charity supports survivors of childhood sexual abuse.","vi":"Tổ chức từ thiện hỗ trợ những người sống sót sau lạm dụng tình dục thời thơ ấu."},{"en":"Schools must report any suspected case of sexual abuse.","vi":"Trường học phải báo cáo bất kỳ trường hợp nghi ngờ lạm dụng tình dục nào."},{"en":"New laws aim to prevent sexual abuse and protect victims.","vi":"Luật mới nhằm ngăn chặn lạm dụng tình dục và bảo vệ nạn nhân."}]', '[]', NULL, '/ˈsekʃuəl əˈbjuːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 88, 'sexual act', 'hành vi tình dục', 'adj + n', '[{"en":"The law clearly defines what counts as a sexual act.","vi":"Luật pháp định nghĩa rõ ràng điều gì được coi là một hành vi tình dục."},{"en":"Consent must be present for any sexual act to be legal.","vi":"Phải có sự đồng thuận thì một hành vi tình dục mới hợp pháp."},{"en":"Researchers studied attitudes toward depicting a sexual act in media.","vi":"Các nhà nghiên cứu khảo sát thái độ đối với việc mô tả hành vi tình dục trên truyền thông."}]', '[]', NULL, '/ˈsekʃuəl ækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 89, 'sexual behavior', 'hành vi tình dục', 'adj + n', '[{"en":"The survey examined the sexual behavior of young adults.","vi":"Cuộc khảo sát xem xét hành vi tình dục của thanh niên."},{"en":"Culture strongly influences attitudes toward sexual behavior.","vi":"Văn hóa ảnh hưởng mạnh đến thái độ đối với hành vi tình dục."},{"en":"Education can promote safer and more responsible sexual behavior.","vi":"Giáo dục có thể thúc đẩy hành vi tình dục an toàn và có trách nhiệm hơn."}]', '[]', NULL, '/ˈsekʃuəl bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 90, 'sexual contact', 'tiếp xúc tình dục', 'adj + n', '[{"en":"Some infections spread mainly through sexual contact.","vi":"Một số bệnh nhiễm trùng lây lan chủ yếu qua tiếp xúc tình dục."},{"en":"The study tracked rates of unprotected sexual contact.","vi":"Nghiên cứu theo dõi tỷ lệ tiếp xúc tình dục không được bảo vệ."},{"en":"Health classes explain how sexual contact can transmit disease.","vi":"Các lớp sức khỏe giải thích cách tiếp xúc tình dục có thể truyền bệnh."}]', '[]', NULL, '/ˈsekʃuəl ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 91, 'sexual difference', 'sự khác biệt giới tính', 'adj + n', '[{"en":"The book explores how culture interprets sexual difference.","vi":"Cuốn sách khám phá cách văn hóa diễn giải sự khác biệt giới tính."},{"en":"Biologists describe the sexual difference between the two species.","vi":"Các nhà sinh học mô tả sự khác biệt giới tính giữa hai loài."},{"en":"Feminist theory often questions assumptions about sexual difference.","vi":"Lý thuyết nữ quyền thường chất vấn các giả định về sự khác biệt giới tính."}]', '[]', NULL, '/ˈsekʃuəl ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 92, 'sexual exploitation', 'bóc lột tình dục', 'adj + n', '[{"en":"The organization fights against the sexual exploitation of children.","vi":"Tổ chức đấu tranh chống lại nạn bóc lột tình dục trẻ em."},{"en":"Trafficking often leads to forced labor and sexual exploitation.","vi":"Buôn người thường dẫn đến lao động cưỡng bức và bóc lột tình dục."},{"en":"Stronger laws are needed to prevent sexual exploitation online.","vi":"Cần có luật mạnh hơn để ngăn chặn bóc lột tình dục trên mạng."}]', '[]', NULL, '/ˈsekʃuəl ˌeksplɔɪˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 93, 'sexual identity', 'bản dạng giới tính', 'adj + n', '[{"en":"Many teenagers explore their sexual identity during adolescence.","vi":"Nhiều thiếu niên khám phá bản dạng giới tính của mình trong tuổi vị thành niên."},{"en":"The film portrays a young woman''s struggle with sexual identity.","vi":"Bộ phim khắc họa cuộc đấu tranh của một cô gái với bản dạng giới tính."},{"en":"Society is slowly becoming more accepting of diverse sexual identity.","vi":"Xã hội đang dần trở nên cởi mở hơn với bản dạng giới tính đa dạng."}]', '[]', NULL, '/ˈsekʃuəl aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 94, 'sexual intercourse', 'quan hệ tình dục', 'adj + n', '[{"en":"The study examined attitudes toward sexual intercourse among teenagers.","vi":"Nghiên cứu xem xét thái độ đối với quan hệ tình dục ở thanh thiếu niên."},{"en":"Doctors advised waiting before resuming sexual intercourse after surgery.","vi":"Bác sĩ khuyên nên chờ trước khi quan hệ tình dục trở lại sau phẫu thuật."},{"en":"Some diseases are transmitted through unprotected sexual intercourse.","vi":"Một số bệnh lây truyền qua quan hệ tình dục không được bảo vệ."}]', '[]', NULL, '/ˈsekʃuəl ˈɪntərkɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 95, 'sexual orientation', 'khuynh hướng tính dục', 'adj + n', '[{"en":"The law protects employees from discrimination based on sexual orientation.","vi":"Luật bảo vệ nhân viên khỏi phân biệt đối xử dựa trên khuynh hướng tính dục."},{"en":"People should not be judged by their sexual orientation.","vi":"Người ta không nên bị đánh giá qua khuynh hướng tính dục của họ."},{"en":"The survey asked participants about their sexual orientation anonymously.","vi":"Cuộc khảo sát hỏi người tham gia về khuynh hướng tính dục một cách ẩn danh."}]', '[]', NULL, '/ˈsekʃuəl ˌɔːriənˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 96, 'sexual violence', 'bạo lực tình dục', 'adj + n', '[{"en":"Survivors of sexual violence often need long-term support.","vi":"Những người sống sót sau bạo lực tình dục thường cần hỗ trợ lâu dài."},{"en":"The campaign raises awareness about sexual violence on campus.","vi":"Chiến dịch nâng cao nhận thức về bạo lực tình dục trong khuôn viên trường."},{"en":"Conflict zones often see high rates of sexual violence.","vi":"Các vùng xung đột thường có tỷ lệ bạo lực tình dục cao."}]', '[]', NULL, '/ˈsekʃuəl ˈvaɪələns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 97, 'share information', 'chia sẻ thông tin', 'v + n', '[{"en":"The two agencies agreed to share information about the threat.","vi":"Hai cơ quan đồng ý chia sẻ thông tin về mối đe dọa."},{"en":"Researchers should share information openly to advance science.","vi":"Các nhà nghiên cứu nên chia sẻ thông tin một cách cởi mở để thúc đẩy khoa học."},{"en":"Employees are reminded not to share information with competitors.","vi":"Nhân viên được nhắc nhở không chia sẻ thông tin với đối thủ cạnh tranh."}]', '[]', NULL, '/ʃer ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 98, 'shared experience', 'trải nghiệm chung', 'adj + n', '[{"en":"A shared experience can quickly bring strangers closer together.","vi":"Một trải nghiệm chung có thể nhanh chóng gắn kết những người xa lạ."},{"en":"The trip became a meaningful shared experience for the class.","vi":"Chuyến đi trở thành một trải nghiệm chung ý nghĩa cho cả lớp."},{"en":"Language often grows out of shared experience within a community.","vi":"Ngôn ngữ thường nảy sinh từ trải nghiệm chung trong một cộng đồng."}]', '[]', NULL, '/ʃerd ɪkˈspɪriəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 99, 'shared meaning', 'ý nghĩa chung', 'adj + n', '[{"en":"Communication depends on a shared meaning between speakers.","vi":"Giao tiếp phụ thuộc vào ý nghĩa chung giữa những người nói."},{"en":"Symbols carry a shared meaning understood across the culture.","vi":"Các biểu tượng mang ý nghĩa chung được hiểu trong cả nền văn hóa."},{"en":"Teams work better when they build a shared meaning of success.","vi":"Các nhóm làm việc tốt hơn khi họ xây dựng ý nghĩa chung về thành công."}]', '[]', NULL, '/ʃerd ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 100, 'shared values', 'các giá trị chung', 'adj + n', '[{"en":"Strong communities are usually built on shared values.","vi":"Các cộng đồng vững mạnh thường được xây dựng trên các giá trị chung."},{"en":"The partners discovered they had many shared values in common.","vi":"Các đối tác phát hiện họ có nhiều giá trị chung."},{"en":"Shared values help an organization stay united under pressure.","vi":"Các giá trị chung giúp một tổ chức đoàn kết dưới áp lực."}]', '[]', NULL, '/ʃerd ˈvæljuːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 101, 'sharp contrast', 'sự tương phản rõ rệt', 'adj + n', '[{"en":"There is a sharp contrast between rich and poor neighborhoods.","vi":"Có một sự tương phản rõ rệt giữa các khu giàu và nghèo."},{"en":"Her calm tone stood in sharp contrast to the chaos.","vi":"Giọng điệu bình tĩnh của cô tương phản rõ rệt với sự hỗn loạn."},{"en":"The results show a sharp contrast with earlier findings.","vi":"Kết quả cho thấy sự tương phản rõ rệt với các phát hiện trước đây."}]', '[]', NULL, '/ʃɑːrp ˈkɑːntræst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 102, 'sharp distinction', 'sự phân biệt rạch ròi', 'adj + n', '[{"en":"The author draws a sharp distinction between fact and opinion.","vi":"Tác giả vạch ra một sự phân biệt rạch ròi giữa sự thật và ý kiến."},{"en":"There is no sharp distinction between the two categories.","vi":"Không có sự phân biệt rạch ròi nào giữa hai loại."},{"en":"Philosophers debate whether such a sharp distinction really exists.","vi":"Các nhà triết học tranh luận liệu một sự phân biệt rạch ròi như vậy có thực sự tồn tại."}]', '[]', NULL, '/ʃɑːrp dɪˈstɪŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 103, 'shift emphasis', 'chuyển trọng tâm', 'v + n', '[{"en":"The new policy shifts emphasis from punishment to prevention.","vi":"Chính sách mới chuyển trọng tâm từ trừng phạt sang phòng ngừa."},{"en":"Schools increasingly shift emphasis toward practical, hands-on learning.","vi":"Các trường học ngày càng chuyển trọng tâm sang học thực hành."},{"en":"The author shifts emphasis to social rather than economic factors.","vi":"Tác giả chuyển trọng tâm sang các yếu tố xã hội thay vì kinh tế."}]', '[]', NULL, '/ʃɪft ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 104, 'short duration', 'thời gian ngắn', 'adj + n', '[{"en":"The treatment is effective despite its short duration.","vi":"Phương pháp điều trị hiệu quả dù chỉ kéo dài trong thời gian ngắn."},{"en":"Symptoms of short duration usually require no medication.","vi":"Các triệu chứng kéo dài thời gian ngắn thường không cần thuốc."},{"en":"Because of its short duration, the course covered only basics.","vi":"Vì thời gian ngắn, khóa học chỉ bao quát những kiến thức cơ bản."}]', '[]', NULL, '/ʃɔːrt dʊˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 105, 'short period', 'khoảng thời gian ngắn', 'adj + n', '[{"en":"Prices rose sharply over a remarkably short period.","vi":"Giá cả tăng mạnh trong một khoảng thời gian ngắn đáng kể."},{"en":"In a short period, the company doubled its revenue.","vi":"Trong một khoảng thời gian ngắn, công ty đã tăng gấp đôi doanh thu."},{"en":"The experiment was repeated several times within a short period.","vi":"Thí nghiệm được lặp lại nhiều lần trong một khoảng thời gian ngắn."}]', '[]', NULL, '/ʃɔːrt ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 106, 'show evidence', 'cho thấy bằng chứng', 'v + n', '[{"en":"The fossils show evidence of life millions of years ago.","vi":"Các hóa thạch cho thấy bằng chứng về sự sống hàng triệu năm trước."},{"en":"Patients began to show evidence of improvement after treatment.","vi":"Bệnh nhân bắt đầu cho thấy bằng chứng cải thiện sau khi điều trị."},{"en":"The data show evidence of a clear upward trend.","vi":"Dữ liệu cho thấy bằng chứng về một xu hướng đi lên rõ ràng."}]', '[]', NULL, '/ʃoʊ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 107, 'show variation', 'thể hiện sự biến thiên', 'v + n', '[{"en":"Temperatures show variation between the coast and the mountains.","vi":"Nhiệt độ thể hiện sự biến thiên giữa vùng ven biển và vùng núi."},{"en":"The samples show variation in size, color, and shape.","vi":"Các mẫu thể hiện sự biến thiên về kích thước, màu sắc và hình dạng."},{"en":"Test scores show variation depending on the time of day.","vi":"Điểm kiểm tra thể hiện sự biến thiên tùy theo thời điểm trong ngày."}]', '[]', NULL, '/ʃoʊ ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 108, 'show a tendency', 'thể hiện một xu hướng', 'v + n', '[{"en":"Young children show a tendency to imitate adults around them.","vi":"Trẻ nhỏ thể hiện xu hướng bắt chước người lớn xung quanh."},{"en":"The market shows a tendency to recover after sharp falls.","vi":"Thị trường thể hiện xu hướng phục hồi sau những đợt giảm mạnh."},{"en":"These materials show a tendency to expand when heated.","vi":"Những vật liệu này thể hiện xu hướng giãn nở khi bị nung nóng."}]', '[]', NULL, '/ʃoʊ ə ˈtendənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 109, 'show a trend', 'thể hiện một xu hướng', 'v + n', '[{"en":"The data show a trend toward higher unemployment in rural areas.","vi":"Dữ liệu thể hiện xu hướng thất nghiệp gia tăng ở nông thôn."},{"en":"These figures show a clear trend over the past decade.","vi":"Những con số này cho thấy một xu hướng rõ ràng trong thập kỷ qua."},{"en":"The graph shows a trend that researchers found surprising.","vi":"Biểu đồ thể hiện một xu hướng mà các nhà nghiên cứu thấy bất ngờ."}]', '[]', NULL, '/ʃoʊ ə trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 110, 'sign a treaty', 'ký một hiệp ước', 'v + n', '[{"en":"The two nations agreed to sign a treaty ending the conflict.","vi":"Hai quốc gia đồng ý ký một hiệp ước chấm dứt xung đột."},{"en":"Leaders gathered in Geneva to sign a treaty on trade.","vi":"Các nhà lãnh đạo họp tại Geneva để ký một hiệp ước thương mại."},{"en":"Many countries refused to sign a treaty limiting their emissions.","vi":"Nhiều nước từ chối ký hiệp ước hạn chế khí thải của họ."}]', '[]', NULL, '/saɪn ə ˈtriːti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 111, 'significant amount of', 'một lượng đáng kể', 'adj + n', '[{"en":"The study required a significant amount of funding to complete.","vi":"Nghiên cứu này cần một lượng kinh phí đáng kể để hoàn thành."},{"en":"Students spend a significant amount of time on group projects.","vi":"Sinh viên dành một lượng thời gian đáng kể cho dự án nhóm."},{"en":"The factory produces a significant amount of waste each year.","vi":"Nhà máy thải ra một lượng chất thải đáng kể mỗi năm."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 112, 'significant change', 'sự thay đổi đáng kể', 'adj + n', '[{"en":"The new policy brought a significant change to school funding.","vi":"Chính sách mới mang lại sự thay đổi đáng kể cho ngân sách trường học."},{"en":"Researchers observed a significant change in patient behavior.","vi":"Các nhà nghiên cứu nhận thấy sự thay đổi đáng kể trong hành vi bệnh nhân."},{"en":"There has been a significant change in public opinion lately.","vi":"Gần đây đã có một sự thay đổi đáng kể trong dư luận."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt tʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 113, 'significant contribution', 'đóng góp đáng kể', 'adj + n', '[{"en":"Her research made a significant contribution to modern medicine.","vi":"Nghiên cứu của cô có đóng góp đáng kể cho y học hiện đại."},{"en":"Volunteers made a significant contribution to the relief effort.","vi":"Các tình nguyện viên đã đóng góp đáng kể cho nỗ lực cứu trợ."},{"en":"Small donations together formed a significant contribution overall.","vi":"Những khoản quyên góp nhỏ cộng lại tạo nên đóng góp đáng kể."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˌkɑːntrɪˈbjuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 114, 'significant correlation', 'mối tương quan đáng kể', 'adj + n', '[{"en":"Analysis revealed a significant correlation between income and health.","vi":"Phân tích cho thấy mối tương quan đáng kể giữa thu nhập và sức khỏe."},{"en":"The study found no significant correlation between the two variables.","vi":"Nghiên cứu không tìm thấy mối tương quan đáng kể giữa hai biến số."},{"en":"Researchers reported a significant correlation in their final results.","vi":"Các nhà nghiên cứu báo cáo mối tương quan đáng kể trong kết quả cuối."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˌkɔːrəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 115, 'significant degree of', 'mức độ đáng kể', 'adj + n', '[{"en":"The task requires a significant degree of skill and patience.","vi":"Công việc đòi hỏi một mức độ kỹ năng và kiên nhẫn đáng kể."},{"en":"There remains a significant degree of uncertainty in the forecast.","vi":"Vẫn còn một mức độ không chắc chắn đáng kể trong dự báo."},{"en":"The plan allows a significant degree of local flexibility.","vi":"Kế hoạch cho phép một mức độ linh hoạt đáng kể ở địa phương."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt dɪˈɡriː əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 116, 'significant development', 'sự phát triển đáng kể', 'adj + n', '[{"en":"The vaccine was a significant development in public health.","vi":"Vắc-xin là một bước phát triển đáng kể trong y tế công cộng."},{"en":"Recent significant developments have transformed the entire industry.","vi":"Những phát triển đáng kể gần đây đã thay đổi toàn ngành."},{"en":"This represents a significant development in renewable energy technology.","vi":"Đây là một bước phát triển đáng kể trong công nghệ năng lượng tái tạo."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 117, 'significant difference', 'sự khác biệt đáng kể', 'adj + n', '[{"en":"There was a significant difference between the two test groups.","vi":"Có một sự khác biệt đáng kể giữa hai nhóm thử nghiệm."},{"en":"The results showed no significant difference in performance.","vi":"Kết quả không cho thấy sự khác biệt đáng kể về hiệu suất."},{"en":"A significant difference in price affected consumer choices.","vi":"Một sự khác biệt đáng kể về giá đã ảnh hưởng đến lựa chọn của người tiêu dùng."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 118, 'significant effect', 'tác động đáng kể', 'adj + n', '[{"en":"The new law had a significant effect on small businesses.","vi":"Luật mới có tác động đáng kể đến các doanh nghiệp nhỏ."},{"en":"Sleep deprivation has a significant effect on concentration levels.","vi":"Thiếu ngủ có tác động đáng kể đến khả năng tập trung."},{"en":"The treatment produced a significant effect within just two weeks.","vi":"Phương pháp điều trị tạo ra tác động đáng kể chỉ trong hai tuần."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 119, 'significant factor', 'yếu tố quan trọng', 'adj + n', '[{"en":"Cost was a significant factor in the company''s final decision.","vi":"Chi phí là một yếu tố quan trọng trong quyết định cuối của công ty."},{"en":"Diet is a significant factor in preventing many diseases.","vi":"Chế độ ăn là một yếu tố quan trọng trong việc phòng bệnh."},{"en":"Location remains a significant factor for many young buyers.","vi":"Vị trí vẫn là một yếu tố quan trọng với nhiều người mua trẻ."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 120, 'significant feature', 'đặc điểm nổi bật', 'adj + n', '[{"en":"Symmetry is a significant feature of the building''s design.","vi":"Tính đối xứng là một đặc điểm nổi bật trong thiết kế tòa nhà."},{"en":"One significant feature of the report is its detailed data.","vi":"Một đặc điểm nổi bật của báo cáo là dữ liệu chi tiết."},{"en":"The map highlights every significant feature of the landscape.","vi":"Bản đồ làm nổi bật mọi đặc điểm quan trọng của cảnh quan."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 121, 'significant figures', 'chữ số có nghĩa', 'adj + n', '[{"en":"Round your answer to three significant figures for accuracy.","vi":"Làm tròn đáp án đến ba chữ số có nghĩa cho chính xác."},{"en":"The teacher explained how to count significant figures correctly.","vi":"Giáo viên giải thích cách đếm chữ số có nghĩa cho đúng."},{"en":"Reporting too many significant figures can mislead the reader.","vi":"Ghi quá nhiều chữ số có nghĩa có thể gây hiểu lầm cho người đọc."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈfɪɡjərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 122, 'significant growth', 'sự tăng trưởng đáng kể', 'adj + n', '[{"en":"The region experienced significant growth in its tech sector.","vi":"Khu vực này có sự tăng trưởng đáng kể trong lĩnh vực công nghệ."},{"en":"Significant growth in demand surprised the entire market.","vi":"Sự tăng trưởng đáng kể về nhu cầu khiến cả thị trường bất ngờ."},{"en":"The company reported significant growth despite the recession.","vi":"Công ty báo cáo tăng trưởng đáng kể dù kinh tế suy thoái."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ɡroʊθ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 123, 'significant impact', 'tác động lớn', 'adj + n', '[{"en":"Climate change has a significant impact on global agriculture.","vi":"Biến đổi khí hậu có tác động lớn đến nông nghiệp toàn cầu."},{"en":"Her speech had a significant impact on the audience.","vi":"Bài phát biểu của cô có tác động lớn đến khán giả."},{"en":"The reform made a significant impact on rural communities.","vi":"Cuộc cải cách có tác động lớn đến các cộng đồng nông thôn."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈɪmpækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 124, 'significant improvement', 'sự cải thiện đáng kể', 'adj + n', '[{"en":"Patients showed significant improvement after the new treatment.","vi":"Bệnh nhân có sự cải thiện đáng kể sau phương pháp điều trị mới."},{"en":"There was a significant improvement in test scores this year.","vi":"Năm nay điểm kiểm tra có sự cải thiện đáng kể."},{"en":"The upgrade brought a significant improvement in system speed.","vi":"Bản nâng cấp mang lại sự cải thiện đáng kể về tốc độ hệ thống."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ɪmˈpruːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 125, 'significant increase', 'sự gia tăng đáng kể', 'adj + n', '[{"en":"The city recorded a significant increase in air pollution.","vi":"Thành phố ghi nhận sự gia tăng đáng kể về ô nhiễm không khí."},{"en":"There was a significant increase in applications this semester.","vi":"Học kỳ này số đơn đăng ký tăng đáng kể."},{"en":"Researchers noted a significant increase in average temperatures.","vi":"Các nhà nghiên cứu ghi nhận sự gia tăng đáng kể về nhiệt độ trung bình."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈɪnkriːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 126, 'significant influence', 'ảnh hưởng đáng kể', 'adj + n', '[{"en":"His mentor had a significant influence on his career.","vi":"Người cố vấn có ảnh hưởng đáng kể đến sự nghiệp của anh."},{"en":"Media has a significant influence on young people''s opinions.","vi":"Truyền thông có ảnh hưởng đáng kể đến quan điểm của giới trẻ."},{"en":"Family background exerts a significant influence on academic success.","vi":"Hoàn cảnh gia đình có ảnh hưởng đáng kể đến thành tích học tập."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈɪnfluəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 127, 'significant interaction', 'sự tương tác đáng kể', 'adj + n', '[{"en":"The model revealed a significant interaction between the two factors.","vi":"Mô hình cho thấy sự tương tác đáng kể giữa hai yếu tố."},{"en":"Researchers detected a significant interaction affecting the outcome.","vi":"Các nhà nghiên cứu phát hiện một tương tác đáng kể ảnh hưởng đến kết quả."},{"en":"There was no significant interaction between age and treatment.","vi":"Không có sự tương tác đáng kể giữa tuổi tác và phương pháp điều trị."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˌɪntərˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 128, 'significant number', 'một số lượng đáng kể', 'adj + n', '[{"en":"A significant number of students dropped out last year.","vi":"Một số lượng đáng kể sinh viên đã bỏ học năm ngoái."},{"en":"The survey reached a significant number of rural households.","vi":"Cuộc khảo sát tiếp cận một số lượng đáng kể hộ gia đình nông thôn."},{"en":"A significant number of voters supported the new proposal.","vi":"Một số lượng đáng kể cử tri ủng hộ đề xuất mới."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 129, 'significant part', 'một phần đáng kể', 'adj + n', '[{"en":"Tourism forms a significant part of the local economy.","vi":"Du lịch là một phần đáng kể của nền kinh tế địa phương."},{"en":"She spent a significant part of her life abroad.","vi":"Cô đã dành một phần đáng kể cuộc đời ở nước ngoài."},{"en":"A significant part of the budget went to research.","vi":"Một phần đáng kể ngân sách được dùng cho nghiên cứu."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 130, 'significant portion', 'một phần đáng kể', 'adj + n', '[{"en":"A significant portion of the forest was destroyed by fire.","vi":"Một phần đáng kể của khu rừng bị lửa thiêu rụi."},{"en":"Wages take up a significant portion of household income.","vi":"Tiền lương chiếm một phần đáng kể trong thu nhập hộ gia đình."},{"en":"A significant portion of the data was lost during transfer.","vi":"Một phần đáng kể dữ liệu bị mất trong quá trình chuyển."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˈpɔːrʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 131, 'significant proportion of', 'một tỷ lệ đáng kể', 'adj + n', '[{"en":"A significant proportion of workers commute over an hour daily.","vi":"Một tỷ lệ đáng kể người lao động đi làm hơn một giờ mỗi ngày."},{"en":"A significant proportion of energy is wasted in old buildings.","vi":"Một tỷ lệ đáng kể năng lượng bị lãng phí ở các tòa nhà cũ."},{"en":"A significant proportion of respondents disagreed with the plan.","vi":"Một tỷ lệ đáng kể người trả lời không đồng ý với kế hoạch."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 132, 'significant reduction', 'sự giảm đáng kể', 'adj + n', '[{"en":"The policy led to a significant reduction in crime rates.","vi":"Chính sách dẫn đến sự giảm đáng kể tỷ lệ tội phạm."},{"en":"Recycling caused a significant reduction in landfill waste.","vi":"Tái chế giúp giảm đáng kể lượng rác chôn lấp."},{"en":"There was a significant reduction in costs after automation.","vi":"Chi phí giảm đáng kể sau khi tự động hóa."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt rɪˈdʌkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 133, 'significant relationship', 'mối quan hệ đáng kể', 'adj + n', '[{"en":"The study found a significant relationship between sleep and memory.","vi":"Nghiên cứu tìm thấy mối quan hệ đáng kể giữa giấc ngủ và trí nhớ."},{"en":"There is a significant relationship between exercise and mood.","vi":"Có một mối quan hệ đáng kể giữa tập thể dục và tâm trạng."},{"en":"Analysis showed no significant relationship between the variables.","vi":"Phân tích không cho thấy mối quan hệ đáng kể giữa các biến số."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 134, 'significant role', 'vai trò quan trọng', 'adj + n', '[{"en":"Technology plays a significant role in modern education today.","vi":"Công nghệ đóng vai trò quan trọng trong giáo dục hiện đại."},{"en":"She played a significant role in the project''s success.","vi":"Cô đóng vai trò quan trọng trong thành công của dự án."},{"en":"Diet plays a significant role in overall long-term health.","vi":"Chế độ ăn đóng vai trò quan trọng với sức khỏe lâu dài."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 135, 'significant shift', 'sự chuyển dịch đáng kể', 'adj + n', '[{"en":"There has been a significant shift toward remote work recently.","vi":"Gần đây đã có sự chuyển dịch đáng kể sang làm việc từ xa."},{"en":"The election marked a significant shift in voter priorities.","vi":"Cuộc bầu cử đánh dấu sự chuyển dịch đáng kể trong ưu tiên của cử tri."},{"en":"A significant shift in climate patterns worried scientists.","vi":"Một sự chuyển dịch đáng kể về khí hậu khiến các nhà khoa học lo ngại."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ʃɪft/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 136, 'significant variation', 'sự biến thiên đáng kể', 'adj + n', '[{"en":"There is significant variation in rainfall across the region.","vi":"Có sự biến thiên đáng kể về lượng mưa trên khắp khu vực."},{"en":"The results showed significant variation between the test groups.","vi":"Kết quả cho thấy sự biến thiên đáng kể giữa các nhóm thử nghiệm."},{"en":"Significant variation in prices confused many first-time buyers.","vi":"Sự biến thiên đáng kể về giá khiến nhiều người mua lần đầu bối rối."}]', '[]', NULL, '/sɪɡˈnɪfɪkənt ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 137, 'significantly affect', 'ảnh hưởng đáng kể', 'adv + v', '[{"en":"Pollution can significantly affect the health of nearby residents.","vi":"Ô nhiễm có thể ảnh hưởng đáng kể đến sức khỏe của cư dân lân cận."},{"en":"Rising fuel prices significantly affect transportation costs nationwide.","vi":"Giá nhiên liệu tăng ảnh hưởng đáng kể đến chi phí vận tải cả nước."},{"en":"Sleep quality can significantly affect a student''s daily performance.","vi":"Chất lượng giấc ngủ có thể ảnh hưởng đáng kể đến thành tích hằng ngày."}]', '[]', NULL, '/sɪɡˈnɪfɪkəntli əˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 138, 'significantly correlated with', 'tương quan đáng kể với', 'adv + vpp', '[{"en":"Income was significantly correlated with access to quality healthcare.","vi":"Thu nhập tương quan đáng kể với khả năng tiếp cận y tế chất lượng."},{"en":"Exam scores were significantly correlated with hours of study.","vi":"Điểm thi tương quan đáng kể với số giờ học."},{"en":"Stress levels were significantly correlated with poor sleep habits.","vi":"Mức độ căng thẳng tương quan đáng kể với thói quen ngủ kém."}]', '[]', NULL, '/sɪɡˈnɪfɪkəntli ˈkɔːrəleɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 139, 'significantly higher', 'cao hơn đáng kể', 'adv + adj', '[{"en":"Prices were significantly higher in the city than in villages.","vi":"Giá cả ở thành phố cao hơn đáng kể so với ở làng quê."},{"en":"Survival rates were significantly higher among treated patients.","vi":"Tỷ lệ sống sót cao hơn đáng kể ở các bệnh nhân được điều trị."},{"en":"The new model''s efficiency was significantly higher than expected.","vi":"Hiệu suất của mẫu mới cao hơn đáng kể so với dự kiến."}]', '[]', NULL, '/sɪɡˈnɪfɪkəntli ˈhaɪər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 140, 'significantly increase', 'tăng đáng kể', 'adv + v', '[{"en":"Regular exercise can significantly increase a person''s life expectancy.","vi":"Tập thể dục đều đặn có thể làm tăng đáng kể tuổi thọ."},{"en":"The new method could significantly increase crop yields next season.","vi":"Phương pháp mới có thể tăng đáng kể năng suất mùa vụ tới."},{"en":"Higher tuition fees may significantly increase student debt levels.","vi":"Học phí cao hơn có thể làm tăng đáng kể mức nợ sinh viên."}]', '[]', NULL, '/sɪɡˈnɪfɪkəntli ˈɪnkriːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 141, 'significantly reduced', 'giảm đáng kể', 'adv + vpp', '[{"en":"The new policy significantly reduced traffic in the city center.","vi":"Chính sách mới đã giảm đáng kể lượng giao thông ở trung tâm."},{"en":"Vaccination significantly reduced the number of severe cases.","vi":"Tiêm chủng đã giảm đáng kể số ca bệnh nặng."},{"en":"Better insulation significantly reduced the building''s energy use.","vi":"Cách nhiệt tốt hơn đã giảm đáng kể mức tiêu thụ năng lượng của tòa nhà."}]', '[]', NULL, '/sɪɡˈnɪfɪkəntli rɪˈduːst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 142, 'similar approach', 'cách tiếp cận tương tự', 'adj + n', '[{"en":"Other countries have adopted a similar approach to recycling.","vi":"Các nước khác đã áp dụng cách tiếp cận tương tự với tái chế."},{"en":"Researchers used a similar approach in their earlier study.","vi":"Các nhà nghiên cứu đã dùng cách tiếp cận tương tự trong nghiên cứu trước."},{"en":"A similar approach might solve the company''s current problems.","vi":"Một cách tiếp cận tương tự có thể giải quyết vấn đề hiện tại của công ty."}]', '[]', NULL, '/ˈsɪmələr əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 143, 'similar argument', 'lập luận tương tự', 'adj + n', '[{"en":"Critics raised a similar argument against the previous proposal.","vi":"Các nhà phê bình đưa ra lập luận tương tự chống lại đề xuất trước."},{"en":"She made a similar argument in her opening statement.","vi":"Cô đưa ra lập luận tương tự trong phần mở đầu."},{"en":"A similar argument appears throughout much of his writing.","vi":"Một lập luận tương tự xuất hiện xuyên suốt nhiều bài viết của ông."}]', '[]', NULL, '/ˈsɪmələr ˈɑːrɡjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 144, 'similar characteristics', 'đặc điểm tương tự', 'adj + n', '[{"en":"The two species share many similar characteristics in behavior.","vi":"Hai loài này chia sẻ nhiều đặc điểm tương tự trong hành vi."},{"en":"Researchers grouped the samples with similar characteristics together.","vi":"Các nhà nghiên cứu nhóm các mẫu có đặc điểm tương tự lại với nhau."},{"en":"These regions display similar characteristics in their climate patterns.","vi":"Những vùng này thể hiện đặc điểm tương tự về kiểu khí hậu."}]', '[]', NULL, '/ˈsɪmələr ˌkærəktəˈrɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 145, 'similar effect', 'tác dụng tương tự', 'adj + n', '[{"en":"The two drugs produced a similar effect on blood pressure.","vi":"Hai loại thuốc tạo ra tác dụng tương tự lên huyết áp."},{"en":"A similar effect was observed in the second experiment.","vi":"Một tác dụng tương tự được ghi nhận trong thí nghiệm thứ hai."},{"en":"Both policies had a similar effect on local employment.","vi":"Cả hai chính sách đều có tác dụng tương tự lên việc làm địa phương."}]', '[]', NULL, '/ˈsɪmələr ɪˈfekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 146, 'similar issue', 'vấn đề tương tự', 'adj + n', '[{"en":"Many other schools face a similar issue with funding.","vi":"Nhiều trường khác cũng đối mặt với vấn đề tương tự về kinh phí."},{"en":"The committee addressed a similar issue at last month''s meeting.","vi":"Ủy ban đã giải quyết một vấn đề tương tự tại cuộc họp tháng trước."},{"en":"A similar issue arose during the early stages of testing.","vi":"Một vấn đề tương tự nảy sinh trong giai đoạn đầu thử nghiệm."}]', '[]', NULL, '/ˈsɪmələr ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 147, 'similar pattern', 'khuôn mẫu tương tự', 'adj + n', '[{"en":"The data followed a similar pattern across all three years.","vi":"Dữ liệu theo một khuôn mẫu tương tự trong cả ba năm."},{"en":"Researchers noticed a similar pattern in the second sample.","vi":"Các nhà nghiên cứu nhận thấy khuôn mẫu tương tự ở mẫu thứ hai."},{"en":"Migration showed a similar pattern to previous decades.","vi":"Di cư thể hiện một khuôn mẫu tương tự với những thập kỷ trước."}]', '[]', NULL, '/ˈsɪmələr ˈpætərn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 148, 'similar properties', 'tính chất tương tự', 'adj + n', '[{"en":"These metals have similar properties when heated to high temperatures.","vi":"Những kim loại này có tính chất tương tự khi nung ở nhiệt độ cao."},{"en":"The new material shows similar properties to natural rubber.","vi":"Vật liệu mới thể hiện tính chất tương tự cao su tự nhiên."},{"en":"Both compounds share similar properties in chemical reactions.","vi":"Cả hai hợp chất có tính chất tương tự trong phản ứng hóa học."}]', '[]', NULL, '/ˈsɪmələr ˈprɑːpərtiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 149, 'similar result', 'kết quả tương tự', 'adj + n', '[{"en":"The second trial produced a similar result to the first.","vi":"Thử nghiệm thứ hai cho kết quả tương tự lần đầu."},{"en":"Other teams reported a similar result in their experiments.","vi":"Các nhóm khác báo cáo kết quả tương tự trong thí nghiệm của họ."},{"en":"We expected a similar result under different conditions.","vi":"Chúng tôi mong đợi một kết quả tương tự trong điều kiện khác."}]', '[]', NULL, '/ˈsɪmələr rɪˈzʌlt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-14-01', 150, 'similar situation', 'tình huống tương tự', 'adj + n', '[{"en":"Many families found themselves in a similar situation that year.","vi":"Nhiều gia đình rơi vào tình huống tương tự năm đó."},{"en":"A similar situation occurred during the previous economic crisis.","vi":"Một tình huống tương tự đã xảy ra trong cuộc khủng hoảng kinh tế trước."},{"en":"Imagine a similar situation where resources are very limited.","vi":"Hãy hình dung một tình huống tương tự khi tài nguyên rất hạn chế."}]', '[]', NULL, '/ˈsɪmələr ˌsɪtʃuˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-15-01', 'colloc-15', 'Cụm học thuật · Nhóm 15', 'Academic Collocation List (Pearson/PTE) — nhóm 15 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 1, 'simple majority', 'đa số quá bán', 'adj + n', '[{"en":"The motion passed with a simple majority of votes.","vi":"Kiến nghị được thông qua với đa số quá bán phiếu."},{"en":"Only a simple majority is needed to approve the budget.","vi":"Chỉ cần đa số quá bán để thông qua ngân sách."},{"en":"A simple majority cannot amend the country''s constitution.","vi":"Đa số quá bán không thể sửa đổi hiến pháp của quốc gia."}]', '[]', NULL, '/ˈsɪmpəl məˈdʒɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 2, 'simplified version', 'phiên bản đơn giản hóa', 'adj + n', '[{"en":"The textbook presents a simplified version of the theory.","vi":"Sách giáo khoa trình bày một phiên bản đơn giản hóa của lý thuyết."},{"en":"Teachers gave students a simplified version of the rules.","vi":"Giáo viên đưa cho học sinh một phiên bản đơn giản hóa của các quy tắc."},{"en":"The app offers a simplified version for new users.","vi":"Ứng dụng cung cấp một phiên bản đơn giản hóa cho người dùng mới."}]', '[]', NULL, '/ˈsɪmpləfaɪd ˈvɜːrʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 3, 'single currency', 'đồng tiền chung', 'adj + n', '[{"en":"Member states adopted a single currency to ease trade.","vi":"Các nước thành viên áp dụng đồng tiền chung để thuận lợi thương mại."},{"en":"A single currency removed the need for constant exchange.","vi":"Đồng tiền chung loại bỏ nhu cầu đổi tiền liên tục."},{"en":"Critics debated whether a single currency suited every economy.","vi":"Các nhà phê bình tranh luận liệu đồng tiền chung có hợp với mọi nền kinh tế."}]', '[]', NULL, '/ˈsɪŋɡəl ˈkɜːrənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 4, 'single element', 'một yếu tố đơn lẻ', 'adj + n', '[{"en":"No single element alone explains the experiment''s complex outcome.","vi":"Không một yếu tố đơn lẻ nào giải thích được kết quả phức tạp của thí nghiệm."},{"en":"Changing a single element can alter the whole design.","vi":"Thay đổi một yếu tố đơn lẻ có thể làm thay đổi toàn bộ thiết kế."},{"en":"The diagram highlights each single element of the process.","vi":"Sơ đồ làm nổi bật từng yếu tố đơn lẻ của quá trình."}]', '[]', NULL, '/ˈsɪŋɡəl ˈeləmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 5, 'single entity', 'một thực thể đơn nhất', 'adj + n', '[{"en":"The merger combined both firms into a single entity.","vi":"Vụ sáp nhập gộp cả hai công ty thành một thực thể đơn nhất."},{"en":"The law treats the group as a single entity legally.","vi":"Luật pháp coi nhóm này như một thực thể đơn nhất về mặt pháp lý."},{"en":"Several departments now operate as a single entity.","vi":"Nhiều phòng ban giờ hoạt động như một thực thể đơn nhất."}]', '[]', NULL, '/ˈsɪŋɡəl ˈentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 6, 'single individual', 'một cá nhân đơn lẻ', 'adj + n', '[{"en":"No single individual can solve this problem alone.","vi":"Không một cá nhân đơn lẻ nào có thể tự giải quyết vấn đề này."},{"en":"A single individual cannot represent the entire community fairly.","vi":"Một cá nhân đơn lẻ không thể đại diện công bằng cho cả cộng đồng."},{"en":"The decision rested on a single individual''s judgment.","vi":"Quyết định dựa vào phán đoán của một cá nhân đơn lẻ."}]', '[]', NULL, '/ˈsɪŋɡəl ˌɪndɪˈvɪdʒuəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 7, 'single issue', 'một vấn đề đơn lẻ', 'adj + n', '[{"en":"The campaign focused on a single issue throughout the year.","vi":"Chiến dịch tập trung vào một vấn đề đơn lẻ trong suốt năm."},{"en":"Voters rarely choose based on a single issue alone.","vi":"Cử tri hiếm khi chọn dựa trên một vấn đề đơn lẻ."},{"en":"The debate narrowed down to a single issue eventually.","vi":"Cuộc tranh luận cuối cùng thu hẹp về một vấn đề đơn lẻ."}]', '[]', NULL, '/ˈsɪŋɡəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 8, 'single source', 'một nguồn duy nhất', 'adj + n', '[{"en":"Relying on a single source weakens any research argument.","vi":"Dựa vào một nguồn duy nhất làm yếu đi mọi lập luận nghiên cứu."},{"en":"The report drew its data from a single source.","vi":"Báo cáo lấy dữ liệu từ một nguồn duy nhất."},{"en":"A single source of income made the family vulnerable.","vi":"Một nguồn thu nhập duy nhất khiến gia đình dễ tổn thương."}]', '[]', NULL, '/ˈsɪŋɡəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 9, 'single variable', 'một biến số đơn lẻ', 'adj + n', '[{"en":"The experiment changed only a single variable at a time.","vi":"Thí nghiệm chỉ thay đổi một biến số đơn lẻ mỗi lần."},{"en":"Isolating a single variable helps clarify the true cause.","vi":"Tách riêng một biến số đơn lẻ giúp làm rõ nguyên nhân thực sự."},{"en":"A single variable cannot explain such a complex result.","vi":"Một biến số đơn lẻ không thể giải thích kết quả phức tạp như vậy."}]', '[]', NULL, '/ˈsɪŋɡəl ˈveriəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 10, 'skilled worker', 'lao động có tay nghề', 'adj + n', '[{"en":"The factory struggled to recruit enough skilled workers.","vi":"Nhà máy gặp khó khăn trong việc tuyển đủ lao động có tay nghề."},{"en":"A skilled worker can complete the task far more quickly.","vi":"Một lao động có tay nghề có thể hoàn thành công việc nhanh hơn nhiều."},{"en":"The country relies on skilled workers from abroad.","vi":"Đất nước phụ thuộc vào lao động có tay nghề từ nước ngoài."}]', '[]', NULL, '/skɪld ˈwɜːrkər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 11, 'slightly different', 'hơi khác một chút', 'adv + adj', '[{"en":"Each sample produced a slightly different result in testing.","vi":"Mỗi mẫu cho ra một kết quả hơi khác một chút khi thử nghiệm."},{"en":"The new edition uses a slightly different layout.","vi":"Phiên bản mới dùng bố cục hơi khác một chút."},{"en":"Her conclusion was slightly different from the others.","vi":"Kết luận của cô hơi khác một chút so với những người khác."}]', '[]', NULL, '/ˈslaɪtli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 12, 'slightly higher', 'cao hơn một chút', 'adv + adj', '[{"en":"Temperatures were slightly higher than the seasonal average.","vi":"Nhiệt độ cao hơn một chút so với mức trung bình mùa."},{"en":"Prices this year are slightly higher than last year.","vi":"Giá năm nay cao hơn một chút so với năm ngoái."},{"en":"The treated group showed a slightly higher recovery rate.","vi":"Nhóm được điều trị có tỷ lệ hồi phục cao hơn một chút."}]', '[]', NULL, '/ˈslaɪtli ˈhaɪər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 13, 'slow process', 'quá trình chậm chạp', 'adj + n', '[{"en":"Learning a new language is often a slow process.","vi":"Học một ngôn ngữ mới thường là một quá trình chậm chạp."},{"en":"Rebuilding trust after the scandal was a slow process.","vi":"Xây dựng lại niềm tin sau vụ bê bối là một quá trình chậm chạp."},{"en":"Coral reefs recover through a slow process over decades.","vi":"Rạn san hô phục hồi qua một quá trình chậm chạp suốt nhiều thập kỷ."}]', '[]', NULL, '/sloʊ ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 14, 'small fraction', 'một phần nhỏ', 'adj + n', '[{"en":"Only a small fraction of applicants were finally accepted.","vi":"Chỉ một phần nhỏ ứng viên cuối cùng được nhận."},{"en":"A small fraction of the budget covers maintenance costs.","vi":"Một phần nhỏ ngân sách dùng cho chi phí bảo trì."},{"en":"Wind power supplies only a small fraction of the energy.","vi":"Điện gió chỉ cung cấp một phần nhỏ năng lượng."}]', '[]', NULL, '/smɔːl ˈfrækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 15, 'small minority', 'một thiểu số nhỏ', 'adj + n', '[{"en":"Only a small minority opposed the proposed changes.","vi":"Chỉ một thiểu số nhỏ phản đối những thay đổi được đề xuất."},{"en":"A small minority of students prefer online classes entirely.","vi":"Một thiểu số nhỏ sinh viên hoàn toàn thích học trực tuyến."},{"en":"The survey showed a small minority remained undecided.","vi":"Khảo sát cho thấy một thiểu số nhỏ vẫn chưa quyết định."}]', '[]', NULL, '/smɔːl maɪˈnɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 16, 'small percentage', 'một tỷ lệ phần trăm nhỏ', 'adj + n', '[{"en":"Only a small percentage of waste is actually recycled.","vi":"Chỉ một tỷ lệ phần trăm nhỏ rác thải thực sự được tái chế."},{"en":"A small percentage of patients experienced minor side effects.","vi":"Một tỷ lệ phần trăm nhỏ bệnh nhân gặp tác dụng phụ nhẹ."},{"en":"Only a small percentage of voters turned out yesterday.","vi":"Chỉ một tỷ lệ phần trăm nhỏ cử tri đi bầu hôm qua."}]', '[]', NULL, '/smɔːl pərˈsentɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 17, 'small portion', 'một phần nhỏ', 'adj + n', '[{"en":"Only a small portion of the land is suitable for farming.","vi":"Chỉ một phần nhỏ đất đai phù hợp cho canh tác."},{"en":"She saved a small portion of her salary each month.","vi":"Cô tiết kiệm một phần nhỏ lương mỗi tháng."},{"en":"A small portion of the report focused on safety.","vi":"Một phần nhỏ của báo cáo tập trung vào an toàn."}]', '[]', NULL, '/smɔːl ˈpɔːrʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 18, 'small proportion of', 'một tỷ lệ nhỏ', 'adj + n', '[{"en":"A small proportion of households still lack internet access.","vi":"Một tỷ lệ nhỏ hộ gia đình vẫn chưa có internet."},{"en":"Only a small proportion of income goes toward savings.","vi":"Chỉ một tỷ lệ nhỏ thu nhập được dùng để tiết kiệm."},{"en":"A small proportion of cases required hospital treatment.","vi":"Một tỷ lệ nhỏ ca bệnh cần điều trị tại bệnh viện."}]', '[]', NULL, '/smɔːl prəˈpɔːrʃən əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 19, 'small quantities of', 'một lượng nhỏ', 'adj + n', '[{"en":"The recipe uses only small quantities of salt.","vi":"Công thức chỉ dùng một lượng nhỏ muối."},{"en":"Small quantities of the chemical were found in the water.","vi":"Một lượng nhỏ hóa chất được tìm thấy trong nước."},{"en":"Plants absorb small quantities of nutrients through their roots.","vi":"Cây hấp thụ một lượng nhỏ chất dinh dưỡng qua rễ."}]', '[]', NULL, '/smɔːl ˈkwɑːntətiz əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 20, 'social activity', 'hoạt động xã hội', 'adj + n', '[{"en":"The club organizes a social activity every weekend.","vi":"Câu lạc bộ tổ chức một hoạt động xã hội mỗi cuối tuần."},{"en":"Social activity helps older adults stay mentally healthy.","vi":"Hoạt động xã hội giúp người lớn tuổi giữ sức khỏe tinh thần."},{"en":"Many students value social activity as much as study.","vi":"Nhiều sinh viên coi trọng hoạt động xã hội ngang với học tập."}]', '[]', NULL, '/ˈsoʊʃəl ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 21, 'social aspect', 'khía cạnh xã hội', 'adj + n', '[{"en":"The study explored the social aspect of online gaming.","vi":"Nghiên cứu khám phá khía cạnh xã hội của trò chơi trực tuyến."},{"en":"Teachers often overlook the social aspect of learning.","vi":"Giáo viên thường bỏ qua khía cạnh xã hội của việc học."},{"en":"The social aspect of the festival attracts many visitors.","vi":"Khía cạnh xã hội của lễ hội thu hút nhiều du khách."}]', '[]', NULL, '/ˈsoʊʃəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 22, 'social attitudes', 'thái độ xã hội', 'adj + n', '[{"en":"Social attitudes toward marriage have changed considerably over time.","vi":"Thái độ xã hội đối với hôn nhân đã thay đổi đáng kể theo thời gian."},{"en":"Education can gradually reshape social attitudes about disability.","vi":"Giáo dục có thể dần định hình lại thái độ xã hội về khuyết tật."},{"en":"The survey measured social attitudes across different age groups.","vi":"Cuộc khảo sát đo lường thái độ xã hội ở các nhóm tuổi khác nhau."}]', '[]', NULL, '/ˈsoʊʃəl ˈætətuːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 23, 'social background', 'hoàn cảnh xã hội', 'adj + n', '[{"en":"Students come from very different social backgrounds here.","vi":"Học sinh ở đây đến từ những hoàn cảnh xã hội rất khác nhau."},{"en":"Social background can strongly influence a child''s opportunities.","vi":"Hoàn cảnh xã hội có thể ảnh hưởng mạnh đến cơ hội của trẻ."},{"en":"The program supports students regardless of social background.","vi":"Chương trình hỗ trợ học sinh bất kể hoàn cảnh xã hội."}]', '[]', NULL, '/ˈsoʊʃəl ˈbækɡraʊnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 24, 'social behavior', 'hành vi xã hội', 'adj + n', '[{"en":"Researchers study how culture shapes social behavior in children.","vi":"Các nhà nghiên cứu tìm hiểu cách văn hóa định hình hành vi xã hội ở trẻ."},{"en":"Social behavior often differs greatly between rural and urban areas.","vi":"Hành vi xã hội thường khác nhau nhiều giữa nông thôn và thành thị."},{"en":"The experiment measured changes in social behavior over months.","vi":"Thí nghiệm đo lường thay đổi trong hành vi xã hội qua nhiều tháng."}]', '[]', NULL, '/ˈsoʊʃəl bɪˈheɪvjər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 25, 'social circumstances', 'hoàn cảnh xã hội', 'adj + n', '[{"en":"Their social circumstances limited access to higher education.","vi":"Hoàn cảnh xã hội của họ hạn chế việc tiếp cận giáo dục đại học."},{"en":"Health outcomes often depend on a person''s social circumstances.","vi":"Kết quả sức khỏe thường phụ thuộc vào hoàn cảnh xã hội của một người."},{"en":"Policies should account for the social circumstances of families.","vi":"Chính sách nên tính đến hoàn cảnh xã hội của các gia đình."}]', '[]', NULL, '/ˈsoʊʃəl ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 26, 'social conflict', 'xung đột xã hội', 'adj + n', '[{"en":"Rising inequality can fuel serious social conflict over time.","vi":"Bất bình đẳng gia tăng có thể gây ra xung đột xã hội nghiêm trọng."},{"en":"The region has a long history of social conflict.","vi":"Khu vực này có lịch sử xung đột xã hội lâu dài."},{"en":"Dialogue between groups helped reduce the social conflict.","vi":"Đối thoại giữa các nhóm đã giúp giảm xung đột xã hội."}]', '[]', NULL, '/ˈsoʊʃəl ˈkɑːnflɪkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 27, 'social consequences', 'hệ quả xã hội', 'adj + n', '[{"en":"Unemployment carries serious social consequences for whole communities.","vi":"Thất nghiệp mang lại hệ quả xã hội nghiêm trọng cho cả cộng đồng."},{"en":"The policy ignored the long-term social consequences of poverty.","vi":"Chính sách đã bỏ qua hệ quả xã hội lâu dài của nghèo đói."},{"en":"New technology often brings unexpected social consequences.","vi":"Công nghệ mới thường mang lại hệ quả xã hội bất ngờ."}]', '[]', NULL, '/ˈsoʊʃəl ˈkɑːnsəkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 28, 'social construct', 'kiến tạo xã hội', 'adj + n', '[{"en":"Many scholars argue that race is a social construct.","vi":"Nhiều học giả cho rằng chủng tộc là một kiến tạo xã hội."},{"en":"Gender roles are often described as a social construct.","vi":"Vai trò giới thường được mô tả như một kiến tạo xã hội."},{"en":"The idea of beauty is partly a social construct.","vi":"Quan niệm về cái đẹp một phần là kiến tạo xã hội."}]', '[]', NULL, '/ˈsoʊʃəl ˈkɑːnstrʌkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 29, 'social contact', 'tiếp xúc xã hội', 'adj + n', '[{"en":"Regular social contact improves mental health in elderly people.","vi":"Tiếp xúc xã hội thường xuyên cải thiện sức khỏe tinh thần người già."},{"en":"The lockdown reduced everyday social contact for many people.","vi":"Đợt phong tỏa làm giảm tiếp xúc xã hội hằng ngày của nhiều người."},{"en":"Children develop language skills through frequent social contact.","vi":"Trẻ phát triển kỹ năng ngôn ngữ qua tiếp xúc xã hội thường xuyên."}]', '[]', NULL, '/ˈsoʊʃəl ˈkɑːntækt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 30, 'social context', 'bối cảnh xã hội', 'adj + n', '[{"en":"Language always carries meaning within its social context.","vi":"Ngôn ngữ luôn mang ý nghĩa trong bối cảnh xã hội của nó."},{"en":"We must understand the social context of the historical event.","vi":"Chúng ta phải hiểu bối cảnh xã hội của sự kiện lịch sử."},{"en":"Behavior changes depending on the surrounding social context.","vi":"Hành vi thay đổi tùy theo bối cảnh xã hội xung quanh."}]', '[]', NULL, '/ˈsoʊʃəl ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 31, 'social democracy', 'dân chủ xã hội', 'adj + n', '[{"en":"Many Nordic countries are seen as models of social democracy.","vi":"Nhiều nước Bắc Âu được xem là hình mẫu của dân chủ xã hội."},{"en":"Social democracy combines free markets with strong welfare systems.","vi":"Dân chủ xã hội kết hợp thị trường tự do với hệ thống phúc lợi mạnh."},{"en":"The party promoted social democracy throughout its long campaign.","vi":"Đảng cổ vũ dân chủ xã hội trong suốt chiến dịch dài của mình."}]', '[]', NULL, '/ˈsoʊʃəl dɪˈmɑːkrəsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 32, 'social dimension', 'chiều kích xã hội', 'adj + n', '[{"en":"The project considered the social dimension of urban planning.","vi":"Dự án xem xét chiều kích xã hội của quy hoạch đô thị."},{"en":"Economists sometimes ignore the social dimension of their policies.","vi":"Các nhà kinh tế đôi khi bỏ qua chiều kích xã hội trong chính sách."},{"en":"Health care has an important social dimension beyond medicine.","vi":"Chăm sóc sức khỏe có chiều kích xã hội quan trọng ngoài y học."}]', '[]', NULL, '/ˈsoʊʃəl dɪˈmenʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 33, 'social environment', 'môi trường xã hội', 'adj + n', '[{"en":"A supportive social environment helps children thrive at school.","vi":"Một môi trường xã hội hỗ trợ giúp trẻ phát triển ở trường."},{"en":"The social environment of a workplace affects employee morale.","vi":"Môi trường xã hội nơi làm việc ảnh hưởng đến tinh thần nhân viên."},{"en":"Habits are shaped strongly by the surrounding social environment.","vi":"Thói quen được định hình mạnh bởi môi trường xã hội xung quanh."}]', '[]', NULL, '/ˈsoʊʃəl ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 34, 'social equality', 'bình đẳng xã hội', 'adj + n', '[{"en":"The movement fought for greater social equality among citizens.","vi":"Phong trào đấu tranh cho sự bình đẳng xã hội lớn hơn giữa các công dân."},{"en":"Education is often seen as a path to social equality.","vi":"Giáo dục thường được coi là con đường đến bình đẳng xã hội."},{"en":"True social equality requires fair access to opportunity.","vi":"Bình đẳng xã hội thực sự đòi hỏi tiếp cận cơ hội công bằng."}]', '[]', NULL, '/ˈsoʊʃəl ɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 35, 'social exclusion', 'sự loại trừ xã hội', 'adj + n', '[{"en":"Poverty often leads to social exclusion for many families.","vi":"Nghèo đói thường dẫn đến sự loại trừ xã hội đối với nhiều gia đình."},{"en":"The charity works to reduce social exclusion among migrants.","vi":"Tổ chức từ thiện hoạt động nhằm giảm sự loại trừ xã hội ở người di cư."},{"en":"Language barriers can cause lasting social exclusion.","vi":"Rào cản ngôn ngữ có thể gây ra sự loại trừ xã hội dai dẳng."}]', '[]', NULL, '/ˈsoʊʃəl ɪkˈskluːʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 36, 'social expectations', 'kỳ vọng xã hội', 'adj + n', '[{"en":"Young people often feel pressured by social expectations.","vi":"Người trẻ thường cảm thấy áp lực bởi kỳ vọng xã hội."},{"en":"Social expectations about careers differ across cultures.","vi":"Kỳ vọng xã hội về sự nghiệp khác nhau giữa các nền văn hóa."},{"en":"She struggled to meet her family''s social expectations.","vi":"Cô vất vả để đáp ứng kỳ vọng xã hội của gia đình."}]', '[]', NULL, '/ˈsoʊʃəl ˌekspekˈteɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 37, 'social factors', 'các yếu tố xã hội', 'adj + n', '[{"en":"Social factors strongly influence a child''s educational outcomes.","vi":"Các yếu tố xã hội ảnh hưởng mạnh đến kết quả học tập của trẻ."},{"en":"Researchers examined the social factors behind rising obesity.","vi":"Các nhà nghiên cứu xem xét các yếu tố xã hội đằng sau béo phì gia tăng."},{"en":"Health depends on biological and social factors together.","vi":"Sức khỏe phụ thuộc vào cả yếu tố sinh học và xã hội."}]', '[]', NULL, '/ˈsoʊʃəl ˈfæktərz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 38, 'social function', 'chức năng xã hội', 'adj + n', '[{"en":"Festivals serve an important social function in many communities.","vi":"Lễ hội phục vụ một chức năng xã hội quan trọng ở nhiều cộng đồng."},{"en":"Language has a clear social function beyond simple communication.","vi":"Ngôn ngữ có chức năng xã hội rõ ràng ngoài việc giao tiếp đơn thuần."},{"en":"The museum also fulfills a valuable social function locally.","vi":"Bảo tàng cũng thực hiện một chức năng xã hội quý giá tại địa phương."}]', '[]', NULL, '/ˈsoʊʃəl ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 39, 'social identity', 'bản sắc xã hội', 'adj + n', '[{"en":"Language plays a key role in shaping social identity.","vi":"Ngôn ngữ đóng vai trò then chốt trong việc hình thành bản sắc xã hội."},{"en":"Teenagers often explore their social identity through friendships.","vi":"Thanh thiếu niên thường khám phá bản sắc xã hội qua tình bạn."},{"en":"Migration can deeply affect a person''s social identity.","vi":"Di cư có thể ảnh hưởng sâu sắc đến bản sắc xã hội của một người."}]', '[]', NULL, '/ˈsoʊʃəl aɪˈdentəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 40, 'social implications', 'hàm ý xã hội', 'adj + n', '[{"en":"The new technology raises serious social implications for privacy.","vi":"Công nghệ mới đặt ra những hàm ý xã hội nghiêm trọng về quyền riêng tư."},{"en":"Scientists discussed the social implications of their discovery.","vi":"Các nhà khoa học thảo luận về hàm ý xã hội của phát hiện của họ."},{"en":"The policy has wide social implications for low-income families.","vi":"Chính sách có hàm ý xã hội sâu rộng đối với các gia đình thu nhập thấp."}]', '[]', NULL, '/ˈsoʊʃəl ˌɪmplɪˈkeɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 41, 'social inequality', 'sự bất bình đẳng xã hội', 'adj + n', '[{"en":"Rising social inequality often leads to political tension in many countries.","vi":"Bất bình đẳng xã hội gia tăng thường dẫn đến căng thẳng chính trị ở nhiều quốc gia."},{"en":"The report examines how education can reduce social inequality over time.","vi":"Báo cáo xem xét giáo dục có thể giảm bất bình đẳng xã hội theo thời gian như thế nào."},{"en":"Economists debate the main causes of widening social inequality today.","vi":"Các nhà kinh tế tranh luận về những nguyên nhân chính của bất bình đẳng xã hội ngày càng lớn."}]', '[]', NULL, '/ˈsoʊʃəl ˌɪnɪˈkwɑːləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 42, 'social institution', 'thiết chế xã hội', 'adj + n', '[{"en":"The family is often described as the most basic social institution.","vi":"Gia đình thường được mô tả là thiết chế xã hội cơ bản nhất."},{"en":"Schools function as a social institution that shapes young people''s values.","vi":"Trường học hoạt động như một thiết chế xã hội định hình giá trị của giới trẻ."},{"en":"Religious social institutions have influenced laws throughout human history.","vi":"Các thiết chế xã hội tôn giáo đã ảnh hưởng đến luật pháp suốt lịch sử nhân loại."}]', '[]', NULL, '/ˈsoʊʃəl ˌɪnstɪˈtuːʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 43, 'social integration', 'sự hòa nhập xã hội', 'adj + n', '[{"en":"Language classes promote social integration among newly arrived immigrants.","vi":"Các lớp học ngôn ngữ thúc đẩy sự hòa nhập xã hội của người nhập cư mới đến."},{"en":"The program supports the social integration of refugees into local communities.","vi":"Chương trình hỗ trợ sự hòa nhập xã hội của người tị nạn vào cộng đồng địa phương."},{"en":"Sports teams can encourage social integration across different cultural groups.","vi":"Các đội thể thao có thể khuyến khích sự hòa nhập xã hội giữa các nhóm văn hóa khác nhau."}]', '[]', NULL, '/ˈsoʊʃəl ˌɪntɪˈɡreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 44, 'social interaction', 'sự tương tác xã hội', 'adj + n', '[{"en":"Daily social interaction is essential for a child''s emotional development.","vi":"Tương tác xã hội hằng ngày rất cần thiết cho sự phát triển cảm xúc của trẻ."},{"en":"Online platforms have changed the way social interaction takes place.","vi":"Các nền tảng trực tuyến đã thay đổi cách thức diễn ra tương tác xã hội."},{"en":"Researchers observed social interaction patterns within the small group.","vi":"Các nhà nghiên cứu quan sát các mô hình tương tác xã hội trong nhóm nhỏ."}]', '[]', NULL, '/ˈsoʊʃəl ˌɪntərˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 45, 'social isolation', 'sự cô lập xã hội', 'adj + n', '[{"en":"Long-term social isolation can seriously affect a person''s mental health.","vi":"Cô lập xã hội kéo dài có thể ảnh hưởng nghiêm trọng đến sức khỏe tinh thần."},{"en":"The pandemic increased social isolation among elderly people living alone.","vi":"Đại dịch làm gia tăng sự cô lập xã hội ở người già sống một mình."},{"en":"Community centers help reduce social isolation in rural areas.","vi":"Các trung tâm cộng đồng giúp giảm sự cô lập xã hội ở vùng nông thôn."}]', '[]', NULL, '/ˈsoʊʃəl ˌaɪsəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 46, 'social mobility', 'sự dịch chuyển tầng lớp xã hội', 'adj + n', '[{"en":"Good education can improve social mobility for children from poor families.","vi":"Giáo dục tốt có thể cải thiện sự dịch chuyển xã hội cho trẻ em nhà nghèo."},{"en":"The study measures social mobility across three different generations.","vi":"Nghiên cứu đo lường sự dịch chuyển xã hội qua ba thế hệ khác nhau."},{"en":"Limited social mobility keeps many people trapped in poverty.","vi":"Sự dịch chuyển xã hội hạn chế khiến nhiều người mắc kẹt trong nghèo đói."}]', '[]', NULL, '/ˈsoʊʃəl moʊˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 47, 'social movement', 'phong trào xã hội', 'adj + n', '[{"en":"The civil rights social movement transformed laws across the country.","vi":"Phong trào xã hội về dân quyền đã thay đổi luật pháp trên cả nước."},{"en":"A new social movement emerged to demand stronger climate action.","vi":"Một phong trào xã hội mới nổi lên đòi hỏi hành động khí hậu mạnh mẽ hơn."},{"en":"Historians study how each social movement shaped public opinion.","vi":"Các nhà sử học nghiên cứu cách mỗi phong trào xã hội định hình dư luận."}]', '[]', NULL, '/ˈsoʊʃəl ˈmuːvmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 48, 'social norm', 'chuẩn mực xã hội', 'adj + n', '[{"en":"Greeting strangers politely is a common social norm in many cultures.","vi":"Chào hỏi người lạ một cách lịch sự là chuẩn mực xã hội phổ biến ở nhiều nền văn hóa."},{"en":"Breaking a social norm can lead to disapproval from the community.","vi":"Vi phạm một chuẩn mực xã hội có thể dẫn đến sự phản đối từ cộng đồng."},{"en":"Social norms often change slowly as generations grow up.","vi":"Các chuẩn mực xã hội thường thay đổi chậm khi các thế hệ trưởng thành."}]', '[]', NULL, '/ˈsoʊʃəl nɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 49, 'social organization', 'tổ chức xã hội', 'adj + n', '[{"en":"Anthropologists study the social organization of small tribal groups.","vi":"Các nhà nhân học nghiên cứu tổ chức xã hội của các nhóm bộ lạc nhỏ."},{"en":"Complex social organization allowed early cities to grow rapidly.","vi":"Tổ chức xã hội phức tạp đã giúp các thành phố cổ phát triển nhanh chóng."},{"en":"The book compares social organization in farming and hunting societies.","vi":"Cuốn sách so sánh tổ chức xã hội ở các xã hội nông nghiệp và săn bắt."}]', '[]', NULL, '/ˈsoʊʃəl ˌɔːrɡənəˈzeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 50, 'social phenomenon', 'hiện tượng xã hội', 'adj + n', '[{"en":"The rapid spread of memes is an interesting social phenomenon online.","vi":"Sự lan truyền nhanh chóng của meme là một hiện tượng xã hội thú vị trên mạng."},{"en":"Sociologists try to explain this complex social phenomenon scientifically.","vi":"Các nhà xã hội học cố gắng giải thích hiện tượng xã hội phức tạp này một cách khoa học."},{"en":"Urban migration is a global social phenomenon affecting many nations.","vi":"Di cư đô thị là một hiện tượng xã hội toàn cầu ảnh hưởng đến nhiều quốc gia."}]', '[]', NULL, '/ˈsoʊʃəl fəˈnɑːmɪnən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 51, 'social policy', 'chính sách xã hội', 'adj + n', '[{"en":"The government introduced a new social policy to support working families.","vi":"Chính phủ đưa ra một chính sách xã hội mới để hỗ trợ các gia đình lao động."},{"en":"Effective social policy can reduce poverty and improve public health.","vi":"Chính sách xã hội hiệu quả có thể giảm nghèo và cải thiện sức khỏe cộng đồng."},{"en":"The lecture compared social policy in several European countries.","vi":"Bài giảng so sánh chính sách xã hội ở một số quốc gia châu Âu."}]', '[]', NULL, '/ˈsoʊʃəl ˈpɑːləsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 52, 'social reform', 'cải cách xã hội', 'adj + n', '[{"en":"The activists campaigned for social reform to improve workers'' rights.","vi":"Các nhà hoạt động vận động cho cải cách xã hội nhằm cải thiện quyền của người lao động."},{"en":"Major social reform often requires support from a broad coalition.","vi":"Cải cách xã hội lớn thường cần sự ủng hộ từ một liên minh rộng rãi."},{"en":"Nineteenth-century social reform led to better factory conditions.","vi":"Cải cách xã hội thế kỷ mười chín đã mang lại điều kiện nhà máy tốt hơn."}]', '[]', NULL, '/ˈsoʊʃəl rɪˈfɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 53, 'social relationship', 'mối quan hệ xã hội', 'adj + n', '[{"en":"Strong social relationships are linked to greater happiness and longer life.","vi":"Các mối quan hệ xã hội bền chặt gắn liền với hạnh phúc và tuổi thọ cao hơn."},{"en":"Moving to a new city can disrupt established social relationships.","vi":"Chuyển đến thành phố mới có thể làm gián đoạn các mối quan hệ xã hội đã có."},{"en":"The study explores how technology reshapes our social relationships.","vi":"Nghiên cứu khám phá cách công nghệ định hình lại các mối quan hệ xã hội của chúng ta."}]', '[]', NULL, '/ˈsoʊʃəl rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 54, 'social responsibility', 'trách nhiệm xã hội', 'adj + n', '[{"en":"Many companies now take social responsibility seriously in their decisions.","vi":"Nhiều công ty hiện coi trọng trách nhiệm xã hội trong các quyết định của họ."},{"en":"Teaching social responsibility helps students become engaged citizens.","vi":"Dạy trách nhiệm xã hội giúp học sinh trở thành công dân tích cực."},{"en":"Corporate social responsibility includes protecting the environment.","vi":"Trách nhiệm xã hội của doanh nghiệp bao gồm việc bảo vệ môi trường."}]', '[]', NULL, '/ˈsoʊʃəl rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 55, 'social setting', 'bối cảnh xã hội', 'adj + n', '[{"en":"People often behave differently depending on the social setting around them.","vi":"Người ta thường cư xử khác nhau tùy thuộc vào bối cảnh xã hội xung quanh."},{"en":"The experiment was repeated in a more relaxed social setting.","vi":"Thí nghiệm được lặp lại trong một bối cảnh xã hội thoải mái hơn."},{"en":"Language use varies greatly across formal and informal social settings.","vi":"Cách dùng ngôn ngữ thay đổi nhiều giữa các bối cảnh xã hội trang trọng và thân mật."}]', '[]', NULL, '/ˈsoʊʃəl ˈsetɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 56, 'social significance', 'ý nghĩa xã hội', 'adj + n', '[{"en":"The festival has deep social significance for the local community.","vi":"Lễ hội mang ý nghĩa xã hội sâu sắc đối với cộng đồng địa phương."},{"en":"Historians often debate the social significance of this old ritual.","vi":"Các nhà sử học thường tranh luận về ý nghĩa xã hội của nghi lễ cổ này."},{"en":"The painting is admired for both its beauty and social significance.","vi":"Bức tranh được ngưỡng mộ vì cả vẻ đẹp lẫn ý nghĩa xã hội của nó."}]', '[]', NULL, '/ˈsoʊʃəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 57, 'social status', 'địa vị xã hội', 'adj + n', '[{"en":"In some cultures, clothing clearly signals a person''s social status.","vi":"Ở một số nền văn hóa, trang phục thể hiện rõ địa vị xã hội của một người."},{"en":"Education can raise the social status of an entire family.","vi":"Giáo dục có thể nâng cao địa vị xã hội của cả một gia đình."},{"en":"The novel describes how marriage affected a woman''s social status.","vi":"Cuốn tiểu thuyết mô tả cách hôn nhân ảnh hưởng đến địa vị xã hội của người phụ nữ."}]', '[]', NULL, '/ˈsoʊʃəl ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 58, 'social structure', 'cấu trúc xã hội', 'adj + n', '[{"en":"The rigid social structure made it hard for people to advance.","vi":"Cấu trúc xã hội cứng nhắc khiến người ta khó thăng tiến."},{"en":"Industrialization gradually changed the social structure of the country.","vi":"Công nghiệp hóa dần thay đổi cấu trúc xã hội của đất nước."},{"en":"Sociologists analyze the social structure of modern urban communities.","vi":"Các nhà xã hội học phân tích cấu trúc xã hội của các cộng đồng đô thị hiện đại."}]', '[]', NULL, '/ˈsoʊʃəl ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 59, 'social theory', 'lý thuyết xã hội', 'adj + n', '[{"en":"The course introduces classic social theory from the nineteenth century.","vi":"Khóa học giới thiệu lý thuyết xã hội kinh điển từ thế kỷ mười chín."},{"en":"Modern social theory tries to explain inequality and power relations.","vi":"Lý thuyết xã hội hiện đại cố gắng giải thích bất bình đẳng và quan hệ quyền lực."},{"en":"She applied social theory to understand the recent protests.","vi":"Cô áp dụng lý thuyết xã hội để hiểu các cuộc biểu tình gần đây."}]', '[]', NULL, '/ˈsoʊʃəl ˈθɪri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 60, 'social transformation', 'sự chuyển biến xã hội', 'adj + n', '[{"en":"The internet triggered a rapid social transformation worldwide.","vi":"Internet đã tạo ra một sự chuyển biến xã hội nhanh chóng trên toàn thế giới."},{"en":"Deep social transformation usually takes several decades to complete.","vi":"Sự chuyển biến xã hội sâu sắc thường mất vài thập kỷ để hoàn thành."},{"en":"The revolution led to a profound social transformation of the nation.","vi":"Cuộc cách mạng dẫn đến một sự chuyển biến xã hội sâu sắc của quốc gia."}]', '[]', NULL, '/ˈsoʊʃəl ˌtrænsfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 61, 'social trend', 'xu hướng xã hội', 'adj + n', '[{"en":"Marketers study current social trends to predict consumer behavior.","vi":"Các nhà tiếp thị nghiên cứu xu hướng xã hội hiện tại để dự đoán hành vi người tiêu dùng."},{"en":"A clear social trend toward remote work emerged after the pandemic.","vi":"Một xu hướng xã hội rõ rệt hướng tới làm việc từ xa xuất hiện sau đại dịch."},{"en":"The article identifies several social trends shaping family life today.","vi":"Bài báo xác định một số xu hướng xã hội đang định hình đời sống gia đình ngày nay."}]', '[]', NULL, '/ˈsoʊʃəl trend/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 62, 'social welfare', 'phúc lợi xã hội', 'adj + n', '[{"en":"The country invests heavily in social welfare for its citizens.","vi":"Quốc gia này đầu tư mạnh vào phúc lợi xã hội cho người dân."},{"en":"Social welfare programs provide support to unemployed and disabled people.","vi":"Các chương trình phúc lợi xã hội hỗ trợ người thất nghiệp và người khuyết tật."},{"en":"Debates about social welfare spending often divide political parties.","vi":"Các tranh luận về chi tiêu phúc lợi xã hội thường chia rẽ các đảng phái chính trị."}]', '[]', NULL, '/ˈsoʊʃəl ˈwelfer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 63, 'socially acceptable', 'được xã hội chấp nhận', 'adv + adj', '[{"en":"What is socially acceptable in one country may offend another.","vi":"Điều được xã hội chấp nhận ở nước này có thể xúc phạm ở nước khác."},{"en":"Over time, attitudes about what is socially acceptable change.","vi":"Theo thời gian, quan niệm về điều được xã hội chấp nhận thay đổi."},{"en":"The advertisement was considered no longer socially acceptable today.","vi":"Quảng cáo đó bị coi là không còn được xã hội chấp nhận ngày nay."}]', '[]', NULL, '/ˈsoʊʃəli əkˈseptəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 64, 'socially constructed', 'được kiến tạo về mặt xã hội', 'adv + vpp', '[{"en":"Many scholars argue that gender roles are socially constructed.","vi":"Nhiều học giả cho rằng vai trò giới được kiến tạo về mặt xã hội."},{"en":"The idea of beauty is largely socially constructed and changes over time.","vi":"Quan niệm về cái đẹp phần lớn được kiến tạo về mặt xã hội và thay đổi theo thời gian."},{"en":"This theory claims that race is a socially constructed category.","vi":"Lý thuyết này cho rằng chủng tộc là một phạm trù được kiến tạo về mặt xã hội."}]', '[]', NULL, '/ˈsoʊʃəli kənˈstrʌktɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 65, 'socially desirable', 'được xã hội coi trọng', 'adv + adj', '[{"en":"Survey respondents often give socially desirable rather than honest answers.","vi":"Người trả lời khảo sát thường đưa ra câu trả lời được xã hội coi trọng thay vì trung thực."},{"en":"Generosity is generally seen as a socially desirable trait.","vi":"Sự hào phóng thường được xem là một phẩm chất được xã hội coi trọng."},{"en":"People may exaggerate socially desirable behaviors in interviews.","vi":"Người ta có thể phóng đại các hành vi được xã hội coi trọng trong các cuộc phỏng vấn."}]', '[]', NULL, '/ˈsoʊʃəli dɪˈzaɪərəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 66, 'socially responsible', 'có trách nhiệm với xã hội', 'adv + adj', '[{"en":"Socially responsible businesses consider their impact on local communities.","vi":"Các doanh nghiệp có trách nhiệm với xã hội cân nhắc tác động đến cộng đồng địa phương."},{"en":"Investors increasingly prefer socially responsible companies and funds.","vi":"Các nhà đầu tư ngày càng ưa chuộng những công ty và quỹ có trách nhiệm với xã hội."},{"en":"The school encourages students to become socially responsible adults.","vi":"Nhà trường khuyến khích học sinh trở thành người lớn có trách nhiệm với xã hội."}]', '[]', NULL, '/ˈsoʊʃəli rɪˈspɑːnsəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 67, 'socioeconomic status', 'tình trạng kinh tế - xã hội', 'adj + n', '[{"en":"Children''s socioeconomic status often affects their access to good schools.","vi":"Tình trạng kinh tế - xã hội của trẻ thường ảnh hưởng đến việc tiếp cận trường tốt."},{"en":"The study controlled for socioeconomic status when comparing the groups.","vi":"Nghiên cứu đã kiểm soát tình trạng kinh tế - xã hội khi so sánh các nhóm."},{"en":"Higher socioeconomic status is linked with better health outcomes.","vi":"Tình trạng kinh tế - xã hội cao hơn gắn liền với kết quả sức khỏe tốt hơn."}]', '[]', NULL, '/ˌsoʊsioʊˌekəˈnɑːmɪk ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 68, 'solar energy', 'năng lượng mặt trời', 'adj + n', '[{"en":"Solar energy is a clean and renewable source of electricity.","vi":"Năng lượng mặt trời là nguồn điện sạch và có thể tái tạo."},{"en":"Many homes now use solar energy to reduce their power bills.","vi":"Nhiều ngôi nhà hiện dùng năng lượng mặt trời để giảm hóa đơn tiền điện."},{"en":"Governments are investing in solar energy to fight climate change.","vi":"Các chính phủ đang đầu tư vào năng lượng mặt trời để chống biến đổi khí hậu."}]', '[]', NULL, '/ˈsoʊlər ˈenərdʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 69, 'solar panel', 'tấm pin mặt trời', 'adj + n', '[{"en":"They installed solar panels on the roof to generate electricity.","vi":"Họ lắp đặt các tấm pin mặt trời trên mái nhà để tạo ra điện."},{"en":"A single solar panel can power several household appliances.","vi":"Một tấm pin mặt trời có thể cung cấp điện cho vài thiết bị gia dụng."},{"en":"The cost of each solar panel has dropped sharply in recent years.","vi":"Chi phí của mỗi tấm pin mặt trời đã giảm mạnh trong những năm gần đây."}]', '[]', NULL, '/ˈsoʊlər ˈpænəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 70, 'solar power', 'điện mặt trời', 'adj + n', '[{"en":"The remote village relies entirely on solar power for its electricity.","vi":"Ngôi làng hẻo lánh hoàn toàn dựa vào điện mặt trời để có điện."},{"en":"Solar power has become much cheaper over the last decade.","vi":"Điện mặt trời đã trở nên rẻ hơn nhiều trong thập kỷ qua."},{"en":"Engineers are improving how solar power is stored at night.","vi":"Các kỹ sư đang cải tiến cách lưu trữ điện mặt trời vào ban đêm."}]', '[]', NULL, '/ˈsoʊlər ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 71, 'solar system', 'hệ mặt trời', 'adj + n', '[{"en":"Our solar system contains eight planets orbiting the sun.","vi":"Hệ mặt trời của chúng ta có tám hành tinh quay quanh mặt trời."},{"en":"Astronomers are searching for life elsewhere in the solar system.","vi":"Các nhà thiên văn đang tìm kiếm sự sống ở nơi khác trong hệ mặt trời."},{"en":"The lecture explained how the solar system formed billions of years ago.","vi":"Bài giảng giải thích hệ mặt trời hình thành hàng tỷ năm trước như thế nào."}]', '[]', NULL, '/ˈsoʊlər ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 72, 'source material', 'tư liệu gốc', 'n + n', '[{"en":"The historian gathered source material from several national archives.","vi":"Nhà sử học thu thập tư liệu gốc từ nhiều kho lưu trữ quốc gia."},{"en":"Students must cite all source material used in their essays.","vi":"Sinh viên phải trích dẫn mọi tư liệu gốc được dùng trong bài luận."},{"en":"The documentary draws on rare source material from the war.","vi":"Bộ phim tài liệu dựa trên tư liệu gốc hiếm có từ thời chiến."}]', '[]', NULL, '/ˈsɔːrs məˈtɪriəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 73, 'sovereign state', 'quốc gia có chủ quyền', 'adj + n', '[{"en":"Each sovereign state has the right to make its own laws.","vi":"Mỗi quốc gia có chủ quyền đều có quyền tự đặt ra luật pháp của mình."},{"en":"The treaty was signed between two independent sovereign states.","vi":"Hiệp ước được ký kết giữa hai quốc gia có chủ quyền độc lập."},{"en":"International law recognizes the borders of every sovereign state.","vi":"Luật quốc tế công nhận biên giới của mọi quốc gia có chủ quyền."}]', '[]', NULL, '/ˈsɑːvrɪn steɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 74, 'sparsely populated', 'thưa dân', 'adv + vpp', '[{"en":"The northern region is sparsely populated and mostly covered by forest.","vi":"Vùng phía bắc thưa dân và phần lớn được rừng bao phủ."},{"en":"Sparsely populated areas often lack good roads and hospitals.","vi":"Các khu vực thưa dân thường thiếu đường tốt và bệnh viện."},{"en":"Much of the desert remains sparsely populated even today.","vi":"Phần lớn sa mạc vẫn thưa dân cho đến ngày nay."}]', '[]', NULL, '/ˈspɑːrsli ˈpɑːpjəleɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 75, 'special circumstances', 'hoàn cảnh đặc biệt', 'adj + n', '[{"en":"Extensions are granted only under special circumstances such as illness.","vi":"Gia hạn chỉ được cấp trong những hoàn cảnh đặc biệt như ốm đau."},{"en":"The rule may be waived if special circumstances clearly apply.","vi":"Quy tắc có thể được miễn nếu rõ ràng có hoàn cảnh đặc biệt."},{"en":"Please explain any special circumstances affecting your application.","vi":"Vui lòng giải thích bất kỳ hoàn cảnh đặc biệt nào ảnh hưởng đến đơn của bạn."}]', '[]', NULL, '/ˈspeʃəl ˈsɜːrkəmstænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 76, 'special emphasis', 'sự nhấn mạnh đặc biệt', 'adj + n', '[{"en":"The course places special emphasis on practical writing skills.","vi":"Khóa học đặt sự nhấn mạnh đặc biệt vào kỹ năng viết thực hành."},{"en":"She gave special emphasis to safety throughout the training session.","vi":"Cô đặc biệt nhấn mạnh vào an toàn trong suốt buổi huấn luyện."},{"en":"The report puts special emphasis on the needs of rural communities.","vi":"Báo cáo đặc biệt nhấn mạnh đến nhu cầu của các cộng đồng nông thôn."}]', '[]', NULL, '/ˈspeʃəl ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 77, 'special issue', 'số chuyên đề', 'adj + n', '[{"en":"The journal published a special issue on climate science this year.","vi":"Tạp chí đã xuất bản một số chuyên đề về khoa học khí hậu năm nay."},{"en":"Her article appeared in a special issue devoted to education.","vi":"Bài viết của cô xuất hiện trong một số chuyên đề dành cho giáo dục."},{"en":"The magazine''s special issue sold out within a single week.","vi":"Số chuyên đề của tạp chí đã bán hết chỉ trong một tuần."}]', '[]', NULL, '/ˈspeʃəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 78, 'special relationship', 'mối quan hệ đặc biệt', 'adj + n', '[{"en":"The two countries have maintained a special relationship for decades.","vi":"Hai quốc gia đã duy trì một mối quan hệ đặc biệt trong nhiều thập kỷ."},{"en":"Teachers can build a special relationship with their youngest students.","vi":"Giáo viên có thể xây dựng một mối quan hệ đặc biệt với những học sinh nhỏ tuổi nhất."},{"en":"The book describes the special relationship between the king and his advisor.","vi":"Cuốn sách mô tả mối quan hệ đặc biệt giữa nhà vua và cố vấn của ông."}]', '[]', NULL, '/ˈspeʃəl rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 79, 'special status', 'quy chế đặc biệt', 'adj + n', '[{"en":"The historic city was granted special status to protect its buildings.","vi":"Thành phố lịch sử được trao quy chế đặc biệt để bảo vệ các tòa nhà của nó."},{"en":"Refugees may be given special status under international law.","vi":"Người tị nạn có thể được trao quy chế đặc biệt theo luật quốc tế."},{"en":"The region enjoys special status that allows greater self-government.","vi":"Khu vực này có quy chế đặc biệt cho phép quyền tự quản lớn hơn."}]', '[]', NULL, '/ˈspeʃəl ˈsteɪtəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 80, 'specific area', 'lĩnh vực cụ thể', 'adj + n', '[{"en":"The training focuses on one specific area of clinical practice.","vi":"Khóa đào tạo tập trung vào một lĩnh vực cụ thể của thực hành lâm sàng."},{"en":"Researchers often specialize in a narrow specific area of study.","vi":"Các nhà nghiên cứu thường chuyên sâu vào một lĩnh vực cụ thể hẹp."},{"en":"Please describe the specific area where you need more support.","vi":"Vui lòng mô tả lĩnh vực cụ thể mà bạn cần thêm hỗ trợ."}]', '[]', NULL, '/spəˈsɪfɪk ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 81, 'specific aspect', 'khía cạnh cụ thể', 'adj + n', '[{"en":"Each chapter examines a different specific aspect of the problem.","vi":"Mỗi chương xem xét một khía cạnh cụ thể khác nhau của vấn đề."},{"en":"The interview focused on one specific aspect of her career.","vi":"Cuộc phỏng vấn tập trung vào một khía cạnh cụ thể trong sự nghiệp của cô."},{"en":"Let us now consider a more specific aspect of the theory.","vi":"Bây giờ chúng ta hãy xem xét một khía cạnh cụ thể hơn của lý thuyết."}]', '[]', NULL, '/spəˈsɪfɪk ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 82, 'specific case', 'trường hợp cụ thể', 'adj + n', '[{"en":"The lawyer used a specific case to illustrate the legal principle.","vi":"Luật sư dùng một trường hợp cụ thể để minh họa nguyên tắc pháp lý."},{"en":"In this specific case, the usual rules do not apply.","vi":"Trong trường hợp cụ thể này, các quy tắc thông thường không áp dụng."},{"en":"The textbook analyzes a specific case in great detail.","vi":"Sách giáo khoa phân tích một trường hợp cụ thể rất chi tiết."}]', '[]', NULL, '/spəˈsɪfɪk keɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 83, 'specific characteristic', 'đặc điểm cụ thể', 'adj + n', '[{"en":"Each species has a specific characteristic that helps it survive.","vi":"Mỗi loài có một đặc điểm cụ thể giúp nó tồn tại."},{"en":"The scientist measured one specific characteristic of every sample.","vi":"Nhà khoa học đo một đặc điểm cụ thể của mỗi mẫu vật."},{"en":"This material is chosen for one specific characteristic: its strength.","vi":"Vật liệu này được chọn vì một đặc điểm cụ thể: độ bền của nó."}]', '[]', NULL, '/spəˈsɪfɪk ˌkærəktəˈrɪstɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 84, 'specific context', 'ngữ cảnh cụ thể', 'adj + n', '[{"en":"The meaning of a word depends on its specific context.","vi":"Nghĩa của một từ phụ thuộc vào ngữ cảnh cụ thể của nó."},{"en":"These findings apply only within a specific context like this one.","vi":"Những phát hiện này chỉ áp dụng trong một ngữ cảnh cụ thể như thế này."},{"en":"Researchers must describe the specific context of their experiment.","vi":"Các nhà nghiên cứu phải mô tả ngữ cảnh cụ thể của thí nghiệm."}]', '[]', NULL, '/spəˈsɪfɪk ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 85, 'specific example', 'ví dụ cụ thể', 'adj + n', '[{"en":"The teacher gave a specific example to make the idea clearer.","vi":"Giáo viên đưa ra một ví dụ cụ thể để làm rõ ý tưởng hơn."},{"en":"Can you provide a specific example to support your argument?","vi":"Bạn có thể đưa ra một ví dụ cụ thể để hỗ trợ lập luận của mình không?"},{"en":"Each claim in the essay is backed by a specific example.","vi":"Mỗi luận điểm trong bài luận đều được hỗ trợ bằng một ví dụ cụ thể."}]', '[]', NULL, '/spəˈsɪfɪk ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 86, 'specific factor', 'yếu tố cụ thể', 'adj + n', '[{"en":"The study isolated one specific factor causing the rise in sales.","vi":"Nghiên cứu tách riêng một yếu tố cụ thể gây ra sự tăng doanh số."},{"en":"Several specific factors influenced the outcome of the experiment.","vi":"Một số yếu tố cụ thể đã ảnh hưởng đến kết quả của thí nghiệm."},{"en":"It is hard to identify the specific factor behind the failure.","vi":"Thật khó để xác định yếu tố cụ thể đằng sau sự thất bại."}]', '[]', NULL, '/spəˈsɪfɪk ˈfæktər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 87, 'specific feature', 'tính năng cụ thể', 'adj + n', '[{"en":"Users praised one specific feature of the new mobile application.","vi":"Người dùng khen ngợi một tính năng cụ thể của ứng dụng di động mới."},{"en":"The design includes a specific feature to help disabled customers.","vi":"Thiết kế bao gồm một tính năng cụ thể để hỗ trợ khách hàng khuyết tật."},{"en":"Each model offers a specific feature that the others lack.","vi":"Mỗi mẫu cung cấp một tính năng cụ thể mà các mẫu khác không có."}]', '[]', NULL, '/spəˈsɪfɪk ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 88, 'specific focus', 'trọng tâm cụ thể', 'adj + n', '[{"en":"The seminar has a specific focus on renewable energy this term.","vi":"Hội thảo có một trọng tâm cụ thể về năng lượng tái tạo trong học kỳ này."},{"en":"Her thesis maintains a specific focus throughout every chapter.","vi":"Luận văn của cô duy trì một trọng tâm cụ thể xuyên suốt mọi chương."},{"en":"The committee asked the team to choose a more specific focus.","vi":"Ủy ban yêu cầu nhóm chọn một trọng tâm cụ thể hơn."}]', '[]', NULL, '/spəˈsɪfɪk ˈfoʊkəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 89, 'specific form', 'hình thức cụ thể', 'adj + n', '[{"en":"The disease appears in a specific form among older patients.","vi":"Căn bệnh xuất hiện dưới một hình thức cụ thể ở bệnh nhân lớn tuổi."},{"en":"This specific form of art developed in the seventeenth century.","vi":"Hình thức nghệ thuật cụ thể này phát triển vào thế kỷ mười bảy."},{"en":"Each language expresses politeness through a specific form of address.","vi":"Mỗi ngôn ngữ thể hiện sự lịch sự qua một hình thức xưng hô cụ thể."}]', '[]', NULL, '/spəˈsɪfɪk fɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 90, 'specific function', 'chức năng cụ thể', 'adj + n', '[{"en":"Each part of the cell performs a specific function in the body.","vi":"Mỗi bộ phận của tế bào thực hiện một chức năng cụ thể trong cơ thể."},{"en":"The tool was designed for one specific function in the factory.","vi":"Công cụ này được thiết kế cho một chức năng cụ thể trong nhà máy."},{"en":"Every department in the company has its own specific function.","vi":"Mỗi phòng ban trong công ty có chức năng cụ thể riêng của mình."}]', '[]', NULL, '/spəˈsɪfɪk ˈfʌŋkʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 91, 'specific information', 'thông tin cụ thể', 'adj + n', '[{"en":"The form asks for specific information about your work history.","vi":"Mẫu đơn yêu cầu thông tin cụ thể về lịch sử làm việc của bạn."},{"en":"Readers can search the website for specific information quickly.","vi":"Người đọc có thể tìm thông tin cụ thể trên trang web một cách nhanh chóng."},{"en":"The report lacks the specific information needed for a decision.","vi":"Báo cáo thiếu thông tin cụ thể cần thiết để đưa ra quyết định."}]', '[]', NULL, '/spəˈsɪfɪk ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 92, 'specific issue', 'vấn đề cụ thể', 'adj + n', '[{"en":"The meeting was called to discuss one specific issue only.","vi":"Cuộc họp được tổ chức để thảo luận chỉ một vấn đề cụ thể."},{"en":"She raised a specific issue about safety at the construction site.","vi":"Cô nêu ra một vấn đề cụ thể về an toàn tại công trường xây dựng."},{"en":"The committee will address each specific issue in turn.","vi":"Ủy ban sẽ giải quyết từng vấn đề cụ thể một cách lần lượt."}]', '[]', NULL, '/spəˈsɪfɪk ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 93, 'specific knowledge', 'kiến thức cụ thể', 'adj + n', '[{"en":"The job requires specific knowledge of computer programming languages.","vi":"Công việc đòi hỏi kiến thức cụ thể về các ngôn ngữ lập trình máy tính."},{"en":"Doctors need specific knowledge about each medicine they prescribe.","vi":"Bác sĩ cần kiến thức cụ thể về từng loại thuốc họ kê đơn."},{"en":"Without specific knowledge of the region, the plan could fail.","vi":"Nếu không có kiến thức cụ thể về khu vực, kế hoạch có thể thất bại."}]', '[]', NULL, '/spəˈsɪfɪk ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 94, 'specific meaning', 'ý nghĩa cụ thể', 'adj + n', '[{"en":"In law, this word carries a very specific meaning.","vi":"Trong luật, từ này mang một ý nghĩa rất cụ thể."},{"en":"Each symbol in the diagram has a specific meaning.","vi":"Mỗi ký hiệu trong sơ đồ đều có một ý nghĩa cụ thể."},{"en":"The author explains the specific meaning of the technical term.","vi":"Tác giả giải thích ý nghĩa cụ thể của thuật ngữ kỹ thuật."}]', '[]', NULL, '/spəˈsɪfɪk ˈmiːnɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 95, 'specific needs', 'nhu cầu cụ thể', 'adj + n', '[{"en":"The program is tailored to the specific needs of each student.","vi":"Chương trình được điều chỉnh theo nhu cầu cụ thể của mỗi học sinh."},{"en":"Older patients often have specific needs that require special care.","vi":"Bệnh nhân lớn tuổi thường có nhu cầu cụ thể đòi hỏi chăm sóc đặc biệt."},{"en":"The company surveys customers to understand their specific needs.","vi":"Công ty khảo sát khách hàng để hiểu nhu cầu cụ thể của họ."}]', '[]', NULL, '/spəˈsɪfɪk niːdz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 96, 'specific problem', 'vấn đề cụ thể', 'adj + n', '[{"en":"The research was designed to solve one specific problem.","vi":"Nghiên cứu được thiết kế để giải quyết một vấn đề cụ thể."},{"en":"Please describe the specific problem you encountered with the software.","vi":"Vui lòng mô tả vấn đề cụ thể bạn gặp phải với phần mềm."},{"en":"Each section of the report addresses a specific problem.","vi":"Mỗi phần của báo cáo giải quyết một vấn đề cụ thể."}]', '[]', NULL, '/spəˈsɪfɪk ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 97, 'specific purpose', 'mục đích cụ thể', 'adj + n', '[{"en":"The fund was created for one specific purpose: student scholarships.","vi":"Quỹ được lập ra cho một mục đích cụ thể: học bổng cho sinh viên."},{"en":"Each tool in the kit serves a specific purpose.","vi":"Mỗi dụng cụ trong bộ đều phục vụ một mục đích cụ thể."},{"en":"The course teaches English for the specific purpose of business.","vi":"Khóa học dạy tiếng Anh cho mục đích cụ thể là kinh doanh."}]', '[]', NULL, '/spəˈsɪfɪk ˈpɜːrpəs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 98, 'specific question', 'câu hỏi cụ thể', 'adj + n', '[{"en":"The interviewer asked a very specific question about my experience.","vi":"Người phỏng vấn hỏi một câu hỏi rất cụ thể về kinh nghiệm của tôi."},{"en":"Each specific question on the survey targets one behavior.","vi":"Mỗi câu hỏi cụ thể trong khảo sát nhắm vào một hành vi."},{"en":"Students should prepare a specific question for the guest speaker.","vi":"Sinh viên nên chuẩn bị một câu hỏi cụ thể cho diễn giả khách mời."}]', '[]', NULL, '/spəˈsɪfɪk ˈkwestʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 99, 'specific reference', 'sự đề cập cụ thể', 'adj + n', '[{"en":"The essay makes specific reference to two recent studies.","vi":"Bài luận đề cập cụ thể đến hai nghiên cứu gần đây."},{"en":"His speech contained a specific reference to last year''s report.","vi":"Bài phát biểu của ông có sự đề cập cụ thể đến báo cáo năm ngoái."},{"en":"Please add a specific reference to support each claim.","vi":"Vui lòng thêm một sự đề cập cụ thể để hỗ trợ mỗi luận điểm."}]', '[]', NULL, '/spəˈsɪfɪk ˈrefərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 100, 'specific sense', 'nghĩa cụ thể', 'adj + n', '[{"en":"The word is used here in a very specific sense.","vi":"Từ này được dùng ở đây theo một nghĩa cụ thể rất rõ ràng."},{"en":"In a specific sense, freedom means the absence of restriction.","vi":"Theo một nghĩa cụ thể, tự do nghĩa là không có sự ràng buộc."},{"en":"The author defines the term in its specific sense early on.","vi":"Tác giả định nghĩa thuật ngữ theo nghĩa cụ thể của nó từ đầu."}]', '[]', NULL, '/spəˈsɪfɪk sens/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 101, 'specific type', 'loại cụ thể', 'adj + n', '[{"en":"This medicine treats one specific type of infection.","vi":"Loại thuốc này điều trị một loại nhiễm trùng cụ thể."},{"en":"The factory produces a specific type of steel for bridges.","vi":"Nhà máy sản xuất một loại thép cụ thể dùng cho cầu."},{"en":"Researchers studied a specific type of cell under the microscope.","vi":"Các nhà nghiên cứu nghiên cứu một loại tế bào cụ thể dưới kính hiển vi."}]', '[]', NULL, '/spəˈsɪfɪk taɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 102, 'specifically designed to', 'được thiết kế riêng để', 'adv + vpp', '[{"en":"The software was specifically designed to help blind users read.","vi":"Phần mềm được thiết kế riêng để giúp người khiếm thị đọc."},{"en":"This chair is specifically designed to support the lower back.","vi":"Chiếc ghế này được thiết kế riêng để hỗ trợ phần lưng dưới."},{"en":"The program is specifically designed to train young athletes.","vi":"Chương trình được thiết kế riêng để huấn luyện các vận động viên trẻ."}]', '[]', NULL, '/spəˈsɪfɪkli dɪˈzaɪnd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 103, 'standard approach', 'cách tiếp cận tiêu chuẩn', 'adj + n', '[{"en":"Doctors followed the standard approach to treating the infection.","vi":"Các bác sĩ tuân theo cách tiếp cận tiêu chuẩn để điều trị nhiễm trùng."},{"en":"The standard approach to this problem may not always work.","vi":"Cách tiếp cận tiêu chuẩn cho vấn đề này không phải lúc nào cũng hiệu quả."},{"en":"Researchers compared a new method with the standard approach.","vi":"Các nhà nghiên cứu so sánh phương pháp mới với cách tiếp cận tiêu chuẩn."}]', '[]', NULL, '/ˈstændərd əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 104, 'standard error', 'sai số chuẩn', 'adj + n', '[{"en":"The table reports the mean along with its standard error.","vi":"Bảng báo cáo giá trị trung bình cùng với sai số chuẩn của nó."},{"en":"A smaller standard error suggests a more precise estimate.","vi":"Sai số chuẩn nhỏ hơn cho thấy một ước lượng chính xác hơn."},{"en":"Students learned how to calculate the standard error of the mean.","vi":"Sinh viên học cách tính sai số chuẩn của giá trị trung bình."}]', '[]', NULL, '/ˈstændərd ˈerər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 105, 'standard format', 'định dạng tiêu chuẩn', 'adj + n', '[{"en":"All reports must follow the standard format set by the journal.","vi":"Tất cả báo cáo phải tuân theo định dạng tiêu chuẩn do tạp chí đặt ra."},{"en":"Saving the file in a standard format makes sharing easier.","vi":"Lưu tệp ở định dạng tiêu chuẩn giúp việc chia sẻ dễ dàng hơn."},{"en":"The template provides a standard format for every assignment.","vi":"Mẫu cung cấp một định dạng tiêu chuẩn cho mọi bài tập."}]', '[]', NULL, '/ˈstændərd ˈfɔːrmæt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 106, 'standard method', 'phương pháp tiêu chuẩn', 'adj + n', '[{"en":"Scientists used the standard method to measure water quality.","vi":"Các nhà khoa học dùng phương pháp tiêu chuẩn để đo chất lượng nước."},{"en":"The new technique is faster than the standard method.","vi":"Kỹ thuật mới nhanh hơn phương pháp tiêu chuẩn."},{"en":"Following a standard method makes the results easy to compare.","vi":"Tuân theo một phương pháp tiêu chuẩn giúp kết quả dễ so sánh."}]', '[]', NULL, '/ˈstændərd ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 107, 'stark contrast', 'sự tương phản rõ rệt', 'adj + n', '[{"en":"The rich neighborhood stood in stark contrast to the nearby slums.","vi":"Khu phố giàu có tương phản rõ rệt với khu ổ chuột gần đó."},{"en":"Her calm reply was in stark contrast to his angry shouting.","vi":"Câu trả lời bình tĩnh của cô tương phản rõ rệt với tiếng la hét giận dữ của anh."},{"en":"The data shows a stark contrast between the two regions.","vi":"Dữ liệu cho thấy sự tương phản rõ rệt giữa hai khu vực."}]', '[]', NULL, '/stɑːrk ˈkɑːntræst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 108, 'start a process', 'bắt đầu một quy trình', 'v + n', '[{"en":"The new law will start a process of major political change.","vi":"Luật mới sẽ bắt đầu một quy trình thay đổi chính trị lớn."},{"en":"Click the button to start a process that cannot be undone.","vi":"Nhấn nút để bắt đầu một quy trình không thể hoàn tác."},{"en":"Their meeting helped start a process of reconciliation between rivals.","vi":"Cuộc gặp của họ giúp bắt đầu một quy trình hòa giải giữa các đối thủ."}]', '[]', NULL, '/stɑːrt ə ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 109, 'state explicitly', 'nêu rõ ràng', 'v + adv', '[{"en":"The contract does not state explicitly who pays for repairs.","vi":"Hợp đồng không nêu rõ ràng ai sẽ trả tiền sửa chữa."},{"en":"The author fails to state explicitly the goal of the study.","vi":"Tác giả không nêu rõ ràng mục tiêu của nghiên cứu."},{"en":"Please state explicitly which option you prefer.","vi":"Vui lòng nêu rõ ràng bạn thích phương án nào."}]', '[]', NULL, '/steɪt ɪkˈsplɪsɪtli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 110, 'state sector', 'khu vực nhà nước', 'n + n', '[{"en":"Many graduates choose careers in the state sector for job security.","vi":"Nhiều sinh viên tốt nghiệp chọn nghề trong khu vực nhà nước vì sự ổn định."},{"en":"Wages in the state sector are often lower than private firms.","vi":"Tiền lương ở khu vực nhà nước thường thấp hơn các công ty tư nhân."},{"en":"The reform reduced the size of the state sector significantly.","vi":"Cuộc cải cách đã giảm đáng kể quy mô của khu vực nhà nước."}]', '[]', NULL, '/steɪt ˈsektər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 111, 'statistical analysis', 'phân tích thống kê', 'adj + n', '[{"en":"The researchers performed a statistical analysis of the survey results.","vi":"Các nhà nghiên cứu thực hiện phân tích thống kê các kết quả khảo sát."},{"en":"Statistical analysis revealed a strong link between the two variables.","vi":"Phân tích thống kê cho thấy mối liên hệ chặt chẽ giữa hai biến số."},{"en":"She used software to speed up the statistical analysis.","vi":"Cô dùng phần mềm để tăng tốc độ phân tích thống kê."}]', '[]', NULL, '/stəˈtɪstɪkəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 112, 'statistical data', 'dữ liệu thống kê', 'adj + n', '[{"en":"The government collects statistical data on employment every month.","vi":"Chính phủ thu thập dữ liệu thống kê về việc làm hằng tháng."},{"en":"Reliable statistical data is essential for good policy decisions.","vi":"Dữ liệu thống kê đáng tin cậy rất cần thiết cho các quyết định chính sách tốt."},{"en":"The report presents statistical data in clear, simple charts.","vi":"Báo cáo trình bày dữ liệu thống kê bằng các biểu đồ rõ ràng, đơn giản."}]', '[]', NULL, '/stəˈtɪstɪkəl ˈdætə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 113, 'statistical information', 'thông tin thống kê', 'adj + n', '[{"en":"The website offers detailed statistical information about population growth.","vi":"Trang web cung cấp thông tin thống kê chi tiết về tăng trưởng dân số."},{"en":"Journalists rely on statistical information to support their stories.","vi":"Các nhà báo dựa vào thông tin thống kê để hỗ trợ các bài viết của họ."},{"en":"The agency publishes statistical information once every year.","vi":"Cơ quan này công bố thông tin thống kê mỗi năm một lần."}]', '[]', NULL, '/stəˈtɪstɪkəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 114, 'statistical method', 'phương pháp thống kê', 'adj + n', '[{"en":"The team applied a modern statistical method to the dataset.","vi":"Nhóm đã áp dụng một phương pháp thống kê hiện đại cho tập dữ liệu."},{"en":"Choosing the right statistical method depends on your research question.","vi":"Việc chọn phương pháp thống kê phù hợp phụ thuộc vào câu hỏi nghiên cứu của bạn."},{"en":"The course teaches each statistical method with practical examples.","vi":"Khóa học dạy từng phương pháp thống kê kèm các ví dụ thực tế."}]', '[]', NULL, '/stəˈtɪstɪkəl ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 115, 'statistical significance', 'ý nghĩa thống kê', 'adj + n', '[{"en":"The results reached statistical significance at the chosen level.","vi":"Kết quả đạt ý nghĩa thống kê ở mức đã chọn."},{"en":"Without statistical significance, the findings cannot be trusted fully.","vi":"Nếu không có ý nghĩa thống kê, các phát hiện không thể được tin tưởng hoàn toàn."},{"en":"The professor explained how to test for statistical significance.","vi":"Giáo sư giải thích cách kiểm tra ý nghĩa thống kê."}]', '[]', NULL, '/stəˈtɪstɪkəl sɪɡˈnɪfɪkəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 116, 'statistical technique', 'kỹ thuật thống kê', 'adj + n', '[{"en":"Analysts used an advanced statistical technique to detect the pattern.","vi":"Các nhà phân tích dùng một kỹ thuật thống kê nâng cao để phát hiện mẫu hình."},{"en":"This statistical technique works best with very large samples.","vi":"Kỹ thuật thống kê này hoạt động tốt nhất với các mẫu rất lớn."},{"en":"The workshop introduced several useful statistical techniques.","vi":"Hội thảo giới thiệu một số kỹ thuật thống kê hữu ích."}]', '[]', NULL, '/stəˈtɪstɪkəl tekˈniːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 117, 'statistical test', 'kiểm định thống kê', 'adj + n', '[{"en":"They ran a statistical test to compare the two groups.","vi":"Họ chạy một kiểm định thống kê để so sánh hai nhóm."},{"en":"Choosing an appropriate statistical test is a crucial step.","vi":"Chọn một kiểm định thống kê phù hợp là một bước quan trọng."},{"en":"The statistical test confirmed that the difference was real.","vi":"Kiểm định thống kê xác nhận rằng sự khác biệt là thật."}]', '[]', NULL, '/stəˈtɪstɪkəl test/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 118, 'statistically significant', 'có ý nghĩa thống kê', 'adv + adj', '[{"en":"The difference between the groups was statistically significant.","vi":"Sự khác biệt giữa các nhóm là có ý nghĩa thống kê."},{"en":"A statistically significant result still needs careful interpretation.","vi":"Một kết quả có ý nghĩa thống kê vẫn cần được diễn giải cẩn thận."},{"en":"The trend was clear but not statistically significant.","vi":"Xu hướng rất rõ nhưng không có ý nghĩa thống kê."}]', '[]', NULL, '/stəˈtɪstɪkli sɪɡˈnɪfɪkənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 119, 'store data', 'lưu trữ dữ liệu', 'v + n', '[{"en":"Companies must store data securely to protect their customers.","vi":"Các công ty phải lưu trữ dữ liệu an toàn để bảo vệ khách hàng."},{"en":"The hospital uses servers to store data about every patient.","vi":"Bệnh viện dùng máy chủ để lưu trữ dữ liệu về mỗi bệnh nhân."},{"en":"Researchers store data in the cloud so it never gets lost.","vi":"Các nhà nghiên cứu lưu trữ dữ liệu trên đám mây để không bao giờ bị mất."}]', '[]', NULL, '/stɔːr ˈdætə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 120, 'store information', 'lưu trữ thông tin', 'v + n', '[{"en":"The brain can store information for many years.","vi":"Bộ não có thể lưu trữ thông tin trong nhiều năm."},{"en":"We use a database to store information about all our members.","vi":"Chúng tôi dùng cơ sở dữ liệu để lưu trữ thông tin về tất cả thành viên."},{"en":"Libraries store information in both printed and digital forms.","vi":"Các thư viện lưu trữ thông tin ở cả dạng in và dạng kỹ thuật số."}]', '[]', NULL, '/stɔːr ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 121, 'strategic decision', 'quyết định chiến lược', 'adj + n', '[{"en":"The board made a strategic decision to enter the Asian market.","vi":"Hội đồng quản trị đưa ra một quyết định chiến lược để gia nhập thị trường châu Á."},{"en":"Every strategic decision should be based on careful analysis.","vi":"Mỗi quyết định chiến lược nên dựa trên phân tích cẩn thận."},{"en":"Closing the old factory was a difficult strategic decision.","vi":"Đóng cửa nhà máy cũ là một quyết định chiến lược khó khăn."}]', '[]', NULL, '/strəˈtiːdʒɪk dɪˈsɪʒən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 122, 'strategic importance', 'tầm quan trọng chiến lược', 'adj + n', '[{"en":"The port has great strategic importance for international trade.","vi":"Cảng có tầm quan trọng chiến lược lớn đối với thương mại quốc tế."},{"en":"Both nations recognized the strategic importance of the region.","vi":"Cả hai quốc gia đều nhận ra tầm quan trọng chiến lược của khu vực."},{"en":"The bridge holds strategic importance during times of conflict.","vi":"Cây cầu có tầm quan trọng chiến lược trong thời kỳ xung đột."}]', '[]', NULL, '/strəˈtiːdʒɪk ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 123, 'strategic management', 'quản trị chiến lược', 'adj + n', '[{"en":"The company hired consultants to improve its strategic management practices.","vi":"Công ty thuê tư vấn để cải thiện hoạt động quản trị chiến lược."},{"en":"Good strategic management helps firms adapt to changing markets quickly.","vi":"Quản trị chiến lược tốt giúp doanh nghiệp thích ứng nhanh với thị trường."},{"en":"Her thesis examines strategic management in small technology startups.","vi":"Luận văn của cô nghiên cứu quản trị chiến lược tại các startup công nghệ nhỏ."}]', '[]', NULL, '/strəˈtiːdʒɪk ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 124, 'strategic objective', 'mục tiêu chiến lược', 'adj + n', '[{"en":"The board defined three strategic objectives for the coming year.","vi":"Hội đồng quản trị xác định ba mục tiêu chiến lược cho năm tới."},{"en":"Every department must align its work with the strategic objectives.","vi":"Mỗi phòng ban phải gắn công việc của mình với các mục tiêu chiến lược."},{"en":"Achieving the strategic objective required significant investment and planning.","vi":"Đạt được mục tiêu chiến lược đòi hỏi đầu tư và lập kế hoạch đáng kể."}]', '[]', NULL, '/strəˈtiːdʒɪk əbˈdʒektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 125, 'strategic planning', 'lập kế hoạch chiến lược', 'adj + n', '[{"en":"Effective strategic planning prepares organizations for future challenges.","vi":"Lập kế hoạch chiến lược hiệu quả giúp tổ chức sẵn sàng cho thách thức tương lai."},{"en":"The team spent two days on strategic planning for the project.","vi":"Nhóm đã dành hai ngày để lập kế hoạch chiến lược cho dự án."},{"en":"Strategic planning involves setting goals and allocating resources wisely.","vi":"Lập kế hoạch chiến lược bao gồm đặt mục tiêu và phân bổ nguồn lực hợp lý."}]', '[]', NULL, '/strəˈtiːdʒɪk ˈplænɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 126, 'stress level', 'mức độ căng thẳng', 'n + n', '[{"en":"Students reported higher stress levels during the exam period.","vi":"Sinh viên cho biết mức độ căng thẳng cao hơn trong kỳ thi."},{"en":"Regular exercise can significantly reduce daily stress levels.","vi":"Tập thể dục đều đặn có thể giảm đáng kể mức độ căng thẳng hằng ngày."},{"en":"The survey measured stress levels among full-time hospital nurses.","vi":"Khảo sát đo lường mức độ căng thẳng ở các y tá bệnh viện làm toàn thời gian."}]', '[]', NULL, '/ˈstres ˈlevəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 127, 'striking contrast', 'sự tương phản rõ rệt', 'adj + n', '[{"en":"There is a striking contrast between the two cities'' economies.","vi":"Có sự tương phản rõ rệt giữa nền kinh tế của hai thành phố."},{"en":"The results stand in striking contrast to earlier findings.","vi":"Kết quả tương phản rõ rệt với những phát hiện trước đây."},{"en":"Her bright painting offered a striking contrast to the gray walls.","vi":"Bức tranh tươi sáng của cô tương phản rõ rệt với những bức tường xám."}]', '[]', NULL, '/ˈstraɪkɪŋ ˈkɑːntræst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 128, 'striking example', 'ví dụ điển hình nổi bật', 'adj + n', '[{"en":"This case is a striking example of successful urban planning.","vi":"Trường hợp này là một ví dụ nổi bật về quy hoạch đô thị thành công."},{"en":"The author gives a striking example to illustrate her point.","vi":"Tác giả đưa ra một ví dụ nổi bật để minh họa luận điểm của mình."},{"en":"The bridge remains a striking example of modern engineering.","vi":"Cây cầu vẫn là một ví dụ nổi bật về kỹ thuật hiện đại."}]', '[]', NULL, '/ˈstraɪkɪŋ ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 129, 'striking feature', 'đặc điểm nổi bật', 'adj + n', '[{"en":"The most striking feature of the design is its simplicity.","vi":"Đặc điểm nổi bật nhất của thiết kế là sự đơn giản của nó."},{"en":"A striking feature of this region is its rich biodiversity.","vi":"Một đặc điểm nổi bật của vùng này là sự đa dạng sinh học phong phú."},{"en":"The building''s curved roof is its most striking feature.","vi":"Mái cong của tòa nhà là đặc điểm nổi bật nhất của nó."}]', '[]', NULL, '/ˈstraɪkɪŋ ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 130, 'strong bond', 'mối liên kết bền chặt', 'adj + n', '[{"en":"Shared experiences create a strong bond between team members.","vi":"Trải nghiệm chung tạo nên mối liên kết bền chặt giữa các thành viên."},{"en":"The children formed a strong bond with their new teacher.","vi":"Những đứa trẻ hình thành mối liên kết bền chặt với giáo viên mới."},{"en":"A strong bond between parents and children supports healthy development.","vi":"Mối liên kết bền chặt giữa cha mẹ và con cái hỗ trợ sự phát triển lành mạnh."}]', '[]', NULL, '/ˈstrɔːŋ ˈbɑːnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 131, 'strong correlation', 'mối tương quan chặt chẽ', 'adj + n', '[{"en":"The study found a strong correlation between exercise and mood.","vi":"Nghiên cứu tìm thấy mối tương quan chặt chẽ giữa vận động và tâm trạng."},{"en":"There is a strong correlation between education and income levels.","vi":"Có mối tương quan chặt chẽ giữa trình độ học vấn và mức thu nhập."},{"en":"Researchers reported a strong correlation between sleep and memory.","vi":"Các nhà nghiên cứu báo cáo mối tương quan chặt chẽ giữa giấc ngủ và trí nhớ."}]', '[]', NULL, '/ˈstrɔːŋ ˌkɔːrəˈleɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 132, 'strong emphasis', 'sự nhấn mạnh mạnh mẽ', 'adj + n', '[{"en":"The program places strong emphasis on practical, hands-on learning.","vi":"Chương trình đặt sự nhấn mạnh mạnh mẽ vào học tập thực hành."},{"en":"Her lecture put strong emphasis on the importance of evidence.","vi":"Bài giảng của cô nhấn mạnh mạnh mẽ tầm quan trọng của bằng chứng."},{"en":"The school has a strong emphasis on teamwork and respect.","vi":"Trường học nhấn mạnh mạnh mẽ vào tinh thần đồng đội và sự tôn trọng."}]', '[]', NULL, '/ˈstrɔːŋ ˈemfəsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 133, 'strong evidence', 'bằng chứng thuyết phục', 'adj + n', '[{"en":"The data provide strong evidence for the new theory.","vi":"Dữ liệu cung cấp bằng chứng thuyết phục cho lý thuyết mới."},{"en":"There is strong evidence linking smoking to several diseases.","vi":"Có bằng chứng thuyết phục liên hệ hút thuốc với một số bệnh."},{"en":"Scientists need strong evidence before accepting any bold claim.","vi":"Các nhà khoa học cần bằng chứng thuyết phục trước khi chấp nhận một tuyên bố táo bạo."}]', '[]', NULL, '/ˈstrɔːŋ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 134, 'strong link', 'mối liên hệ chặt chẽ', 'adj + n', '[{"en":"Research shows a strong link between diet and overall health.","vi":"Nghiên cứu cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"There is a strong link between poverty and poor education.","vi":"Có mối liên hệ chặt chẽ giữa nghèo đói và giáo dục kém."},{"en":"The report highlights a strong link between stress and illness.","vi":"Báo cáo nêu bật mối liên hệ chặt chẽ giữa căng thẳng và bệnh tật."}]', '[]', NULL, '/ˈstrɔːŋ ˈlɪŋk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 135, 'strong reaction', 'phản ứng mạnh mẽ', 'adj + n', '[{"en":"The new policy provoked a strong reaction from local residents.","vi":"Chính sách mới gây ra phản ứng mạnh mẽ từ người dân địa phương."},{"en":"Her speech triggered a strong reaction among the students.","vi":"Bài phát biểu của cô khơi dậy phản ứng mạnh mẽ trong sinh viên."},{"en":"The film received a strong reaction from both critics and audiences.","vi":"Bộ phim nhận được phản ứng mạnh mẽ từ cả giới phê bình lẫn khán giả."}]', '[]', NULL, '/ˈstrɔːŋ riˈækʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 136, 'strong relationship', 'mối quan hệ bền chặt', 'adj + n', '[{"en":"The company built a strong relationship with its loyal customers.","vi":"Công ty xây dựng mối quan hệ bền chặt với khách hàng trung thành."},{"en":"A strong relationship with mentors helps young researchers grow.","vi":"Mối quan hệ bền chặt với người hướng dẫn giúp nhà nghiên cứu trẻ phát triển."},{"en":"There is a strong relationship between trust and effective teamwork.","vi":"Có mối quan hệ bền chặt giữa sự tin tưởng và làm việc nhóm hiệu quả."}]', '[]', NULL, '/ˈstrɔːŋ rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 137, 'strong tendency', 'xu hướng rõ rệt', 'adj + n', '[{"en":"There is a strong tendency for prices to rise in winter.","vi":"Có một xu hướng rõ rệt là giá cả tăng vào mùa đông."},{"en":"The data show a strong tendency toward urban migration.","vi":"Dữ liệu cho thấy xu hướng rõ rệt về di cư ra thành thị."},{"en":"Young people show a strong tendency to adopt new technologies.","vi":"Người trẻ thể hiện xu hướng rõ rệt trong việc tiếp nhận công nghệ mới."}]', '[]', NULL, '/ˈstrɔːŋ ˈtendənsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 138, 'strongly agree', 'hoàn toàn đồng ý', 'adv + v', '[{"en":"Most participants strongly agree that the new rule is fair.","vi":"Phần lớn người tham gia hoàn toàn đồng ý rằng quy định mới là công bằng."},{"en":"I strongly agree with the author''s main argument here.","vi":"Tôi hoàn toàn đồng ý với luận điểm chính của tác giả ở đây."},{"en":"Many teachers strongly agree that smaller classes improve learning.","vi":"Nhiều giáo viên hoàn toàn đồng ý rằng lớp nhỏ giúp cải thiện việc học."}]', '[]', NULL, '/ˈstrɔːŋli əˈɡriː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 139, 'strongly associated with', 'có liên hệ chặt chẽ với', 'adv + vpp', '[{"en":"High blood pressure is strongly associated with heart disease.","vi":"Huyết áp cao có liên hệ chặt chẽ với bệnh tim."},{"en":"Poverty is strongly associated with limited access to education.","vi":"Nghèo đói có liên hệ chặt chẽ với việc tiếp cận giáo dục hạn chế."},{"en":"These symptoms are strongly associated with prolonged stress.","vi":"Những triệu chứng này có liên hệ chặt chẽ với căng thẳng kéo dài."}]', '[]', NULL, '/ˈstrɔːŋli əˈsoʊsieɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 140, 'strongly correlated with', 'tương quan chặt chẽ với', 'adv + vpp', '[{"en":"Income is strongly correlated with access to quality healthcare.","vi":"Thu nhập tương quan chặt chẽ với việc tiếp cận chăm sóc y tế chất lượng."},{"en":"Study time is strongly correlated with exam performance.","vi":"Thời gian học tương quan chặt chẽ với kết quả thi."},{"en":"Air pollution is strongly correlated with respiratory problems.","vi":"Ô nhiễm không khí tương quan chặt chẽ với các vấn đề hô hấp."}]', '[]', NULL, '/ˈstrɔːŋli ˈkɔːrəleɪtɪd wɪð/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 141, 'strongly disagree', 'hoàn toàn không đồng ý', 'adv + v', '[{"en":"Several experts strongly disagree with the proposed reform.","vi":"Một số chuyên gia hoàn toàn không đồng ý với cải cách được đề xuất."},{"en":"I strongly disagree with the conclusion of this report.","vi":"Tôi hoàn toàn không đồng ý với kết luận của báo cáo này."},{"en":"Many residents strongly disagree about building the new highway.","vi":"Nhiều cư dân hoàn toàn không đồng ý về việc xây đường cao tốc mới."}]', '[]', NULL, '/ˈstrɔːŋli ˌdɪsəˈɡriː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 142, 'strongly influenced by', 'chịu ảnh hưởng mạnh mẽ bởi', 'adv + vpp', '[{"en":"Her early work was strongly influenced by classical philosophy.","vi":"Tác phẩm đầu tay của cô chịu ảnh hưởng mạnh mẽ bởi triết học cổ điển."},{"en":"Consumer choices are strongly influenced by online reviews.","vi":"Lựa chọn của người tiêu dùng chịu ảnh hưởng mạnh mẽ bởi đánh giá trực tuyến."},{"en":"His theory was strongly influenced by recent neuroscience research.","vi":"Lý thuyết của ông chịu ảnh hưởng mạnh mẽ bởi nghiên cứu thần kinh học gần đây."}]', '[]', NULL, '/ˈstrɔːŋli ˈɪnfluənst baɪ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 143, 'strongly linked', 'gắn liền chặt chẽ', 'adv + vpp', '[{"en":"Obesity is strongly linked to several chronic health conditions.","vi":"Béo phì gắn liền chặt chẽ với một số bệnh mãn tính."},{"en":"Economic growth is strongly linked to political stability.","vi":"Tăng trưởng kinh tế gắn liền chặt chẽ với ổn định chính trị."},{"en":"Sleep quality is strongly linked to overall mental health.","vi":"Chất lượng giấc ngủ gắn liền chặt chẽ với sức khỏe tinh thần."}]', '[]', NULL, '/ˈstrɔːŋli ˈlɪŋkt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 144, 'strongly opposed', 'phản đối mạnh mẽ', 'adv + vpp', '[{"en":"Local farmers were strongly opposed to the new land tax.","vi":"Nông dân địa phương phản đối mạnh mẽ loại thuế đất mới."},{"en":"Many scientists are strongly opposed to cutting research funding.","vi":"Nhiều nhà khoa học phản đối mạnh mẽ việc cắt giảm ngân sách nghiên cứu."},{"en":"The union remained strongly opposed to the wage freeze.","vi":"Công đoàn vẫn phản đối mạnh mẽ việc đóng băng tiền lương."}]', '[]', NULL, '/ˈstrɔːŋli əˈpoʊzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 145, 'strongly related to', 'liên quan chặt chẽ tới', 'adv + vpp', '[{"en":"Job satisfaction is strongly related to employee productivity.","vi":"Sự hài lòng trong công việc liên quan chặt chẽ tới năng suất nhân viên."},{"en":"Reading habits are strongly related to vocabulary growth.","vi":"Thói quen đọc liên quan chặt chẽ tới sự phát triển vốn từ vựng."},{"en":"Diet is strongly related to long-term cardiovascular health.","vi":"Chế độ ăn liên quan chặt chẽ tới sức khỏe tim mạch lâu dài."}]', '[]', NULL, '/ˈstrɔːŋli rɪˈleɪtɪd tə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 146, 'strongly suggest', 'cho thấy rõ ràng', 'adv + v', '[{"en":"The results strongly suggest that the treatment is effective.","vi":"Kết quả cho thấy rõ ràng rằng phương pháp điều trị có hiệu quả."},{"en":"These findings strongly suggest a need for further research.","vi":"Những phát hiện này cho thấy rõ ràng cần nghiên cứu thêm."},{"en":"The evidence strongly suggests a link between the two events.","vi":"Bằng chứng cho thấy rõ ràng có mối liên hệ giữa hai sự kiện."}]', '[]', NULL, '/ˈstrɔːŋli səˈdʒest/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 147, 'structural adjustment', 'điều chỉnh cơ cấu', 'adj + n', '[{"en":"The government introduced structural adjustment to stabilize the economy.","vi":"Chính phủ tiến hành điều chỉnh cơ cấu để ổn định nền kinh tế."},{"en":"Structural adjustment programs often affect public spending heavily.","vi":"Các chương trình điều chỉnh cơ cấu thường ảnh hưởng mạnh đến chi tiêu công."},{"en":"The bank required structural adjustment before approving the loan.","vi":"Ngân hàng yêu cầu điều chỉnh cơ cấu trước khi phê duyệt khoản vay."}]', '[]', NULL, '/ˈstrʌktʃərəl əˈdʒʌstmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 148, 'structural change', 'thay đổi cơ cấu', 'adj + n', '[{"en":"The industry underwent major structural change over the decade.","vi":"Ngành đã trải qua sự thay đổi cơ cấu lớn trong thập kỷ qua."},{"en":"Structural change in the economy created new types of jobs.","vi":"Sự thay đổi cơ cấu trong nền kinh tế tạo ra nhiều loại việc làm mới."},{"en":"The reform aimed at deep structural change within the organization.","vi":"Cuộc cải cách nhắm tới sự thay đổi cơ cấu sâu sắc trong tổ chức."}]', '[]', NULL, '/ˈstrʌktʃərəl ˈtʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 149, 'structural element', 'yếu tố cấu trúc', 'adj + n', '[{"en":"Engineers checked every structural element of the old bridge.","vi":"Các kỹ sư kiểm tra từng yếu tố cấu trúc của cây cầu cũ."},{"en":"Each structural element must support the building''s total weight.","vi":"Mỗi yếu tố cấu trúc phải chịu được toàn bộ trọng lượng của tòa nhà."},{"en":"The essay analyzes the structural elements of the novel.","vi":"Bài luận phân tích các yếu tố cấu trúc của cuốn tiểu thuyết."}]', '[]', NULL, '/ˈstrʌktʃərəl ˈelɪmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-15-01', 150, 'structural feature', 'đặc điểm cấu trúc', 'adj + n', '[{"en":"The study compares structural features of several languages.","vi":"Nghiên cứu so sánh các đặc điểm cấu trúc của một số ngôn ngữ."},{"en":"A key structural feature of the cell is its membrane.","vi":"Một đặc điểm cấu trúc quan trọng của tế bào là màng của nó."},{"en":"The architect preserved the building''s original structural features.","vi":"Kiến trúc sư bảo tồn các đặc điểm cấu trúc nguyên bản của tòa nhà."}]', '[]', NULL, '/ˈstrʌktʃərəl ˈfiːtʃər/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-16-01', 'colloc-16', 'Cụm học thuật · Nhóm 16', 'Academic Collocation List (Pearson/PTE) — nhóm 16 (150 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 1, 'structural properties', 'tính chất cấu trúc', 'adj + n', '[{"en":"Scientists tested the structural properties of the new alloy.","vi":"Các nhà khoa học kiểm tra tính chất cấu trúc của hợp kim mới."},{"en":"The structural properties of wood vary with moisture content.","vi":"Tính chất cấu trúc của gỗ thay đổi theo độ ẩm."},{"en":"Understanding structural properties helps engineers design safer materials.","vi":"Hiểu tính chất cấu trúc giúp kỹ sư thiết kế vật liệu an toàn hơn."}]', '[]', NULL, '/ˈstrʌktʃərəl ˈprɑːpərtiz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 2, 'subject area', 'lĩnh vực môn học', 'adj + n', '[{"en":"Students may choose electives outside their main subject area.","vi":"Sinh viên có thể chọn môn tự chọn ngoài lĩnh vực môn học chính."},{"en":"The conference covered many subject areas within social science.","vi":"Hội nghị bao quát nhiều lĩnh vực môn học trong khoa học xã hội."},{"en":"Each teacher specializes in a particular subject area.","vi":"Mỗi giáo viên chuyên về một lĩnh vực môn học cụ thể."}]', '[]', NULL, '/ˈsʌbdʒɪkt ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 3, 'subsequent analysis', 'phân tích tiếp theo', 'adj + n', '[{"en":"Subsequent analysis confirmed the patterns seen in early data.","vi":"Phân tích tiếp theo xác nhận các mẫu hình thấy trong dữ liệu ban đầu."},{"en":"The subsequent analysis revealed several unexpected results.","vi":"Phân tích tiếp theo cho thấy một số kết quả bất ngờ."},{"en":"Subsequent analysis will focus on long-term effects of the policy.","vi":"Phân tích tiếp theo sẽ tập trung vào tác động lâu dài của chính sách."}]', '[]', NULL, '/ˈsʌbsɪkwənt əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 4, 'subsequent chapter', 'chương tiếp theo', 'adj + n', '[{"en":"These issues are discussed in detail in subsequent chapters.","vi":"Những vấn đề này được bàn chi tiết ở các chương tiếp theo."},{"en":"The subsequent chapter explains the methodology in more depth.","vi":"Chương tiếp theo giải thích phương pháp luận sâu hơn."},{"en":"Each subsequent chapter builds on ideas from the previous one.","vi":"Mỗi chương tiếp theo xây dựng dựa trên ý tưởng của chương trước."}]', '[]', NULL, '/ˈsʌbsɪkwənt ˈtʃæptər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 5, 'subsequent development', 'diễn biến tiếp theo', 'adj + n', '[{"en":"The treaty shaped the subsequent development of the region.","vi":"Hiệp ước định hình diễn biến tiếp theo của khu vực."},{"en":"Subsequent development of the software fixed many early problems.","vi":"Diễn biến phát triển tiếp theo của phần mềm khắc phục nhiều lỗi ban đầu."},{"en":"Historians trace the subsequent development of the movement.","vi":"Các sử gia theo dõi diễn biến tiếp theo của phong trào."}]', '[]', NULL, '/ˈsʌbsɪkwənt dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 6, 'subsequent study', 'nghiên cứu tiếp theo', 'adj + n', '[{"en":"A subsequent study confirmed the earlier surprising findings.","vi":"Một nghiên cứu tiếp theo xác nhận các phát hiện gây bất ngờ trước đó."},{"en":"Subsequent studies used larger and more diverse samples.","vi":"Các nghiên cứu tiếp theo dùng mẫu lớn hơn và đa dạng hơn."},{"en":"The authors recommend a subsequent study with a control group.","vi":"Các tác giả đề xuất một nghiên cứu tiếp theo có nhóm đối chứng."}]', '[]', NULL, '/ˈsʌbsɪkwənt ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 7, 'subsequent work', 'công trình tiếp theo', 'adj + n', '[{"en":"Her subsequent work expanded on these initial conclusions.","vi":"Công trình tiếp theo của cô mở rộng từ những kết luận ban đầu này."},{"en":"Subsequent work in the field built directly on his ideas.","vi":"Công trình tiếp theo trong lĩnh vực này dựa trực tiếp vào ý tưởng của ông."},{"en":"The paper laid a foundation for much subsequent work.","vi":"Bài báo đặt nền móng cho nhiều công trình tiếp theo."}]', '[]', NULL, '/ˈsʌbsɪkwənt ˈwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 8, 'substantial amount of', 'một lượng đáng kể', 'adj + n', '[{"en":"The project required a substantial amount of time and money.","vi":"Dự án đòi hỏi một lượng đáng kể thời gian và tiền bạc."},{"en":"Researchers collected a substantial amount of survey data.","vi":"Các nhà nghiên cứu thu thập một lượng đáng kể dữ liệu khảo sát."},{"en":"A substantial amount of evidence supports this conclusion.","vi":"Một lượng đáng kể bằng chứng ủng hộ kết luận này."}]', '[]', NULL, '/səbˈstænʃəl əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 9, 'substantial difference', 'sự khác biệt đáng kể', 'adj + n', '[{"en":"There is a substantial difference between the two methods.","vi":"Có một sự khác biệt đáng kể giữa hai phương pháp."},{"en":"The study found a substantial difference in test scores.","vi":"Nghiên cứu tìm thấy sự khác biệt đáng kể về điểm kiểm tra."},{"en":"A substantial difference in income separates the two regions.","vi":"Một sự khác biệt đáng kể về thu nhập chia tách hai khu vực."}]', '[]', NULL, '/səbˈstænʃəl ˈdɪfərəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 10, 'substantial evidence', 'bằng chứng đáng kể', 'adj + n', '[{"en":"There is substantial evidence supporting the new approach.","vi":"Có bằng chứng đáng kể ủng hộ phương pháp mới."},{"en":"The court found substantial evidence of wrongdoing.","vi":"Tòa án tìm thấy bằng chứng đáng kể về hành vi sai trái."},{"en":"Substantial evidence shows that exercise improves mental health.","vi":"Bằng chứng đáng kể cho thấy tập thể dục cải thiện sức khỏe tinh thần."}]', '[]', NULL, '/səbˈstænʃəl ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 11, 'substantial number', 'một số lượng đáng kể', 'adj + n', '[{"en":"A substantial number of students passed the difficult exam.","vi":"Một số lượng đáng kể sinh viên đã vượt qua kỳ thi khó."},{"en":"The survey reached a substantial number of households nationwide.","vi":"Khảo sát tiếp cận một số lượng đáng kể hộ gia đình trên toàn quốc."},{"en":"A substantial number of jobs depend on the local factory.","vi":"Một số lượng đáng kể việc làm phụ thuộc vào nhà máy địa phương."}]', '[]', NULL, '/səbˈstænʃəl ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 12, 'substantial part', 'một phần đáng kể', 'adj + n', '[{"en":"A substantial part of the budget goes toward research.","vi":"Một phần đáng kể ngân sách được dành cho nghiên cứu."},{"en":"She spent a substantial part of her career studying bees.","vi":"Cô dành một phần đáng kể sự nghiệp để nghiên cứu loài ong."},{"en":"A substantial part of the population lives in rural areas.","vi":"Một phần đáng kể dân số sống ở khu vực nông thôn."}]', '[]', NULL, '/səbˈstænʃəl ˈpɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 13, 'substantially different', 'khác biệt đáng kể', 'adv + adj', '[{"en":"The two samples produced substantially different results.","vi":"Hai mẫu cho ra những kết quả khác biệt đáng kể."},{"en":"Her conclusions are substantially different from earlier studies.","vi":"Kết luận của cô khác biệt đáng kể so với các nghiên cứu trước."},{"en":"Life in the city is substantially different from rural life.","vi":"Cuộc sống ở thành phố khác biệt đáng kể so với nông thôn."}]', '[]', NULL, '/səbˈstænʃəli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 14, 'successful implementation', 'việc triển khai thành công', 'adj + n', '[{"en":"Successful implementation of the plan depends on strong leadership.","vi":"Việc triển khai thành công kế hoạch phụ thuộc vào sự lãnh đạo vững mạnh."},{"en":"Training was key to the successful implementation of the system.","vi":"Đào tạo là yếu tố then chốt cho việc triển khai thành công hệ thống."},{"en":"The report describes the successful implementation of the reform.","vi":"Báo cáo mô tả việc triển khai thành công cuộc cải cách."}]', '[]', NULL, '/səkˈsesfəl ˌɪmplɪmenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 15, 'sufficient condition', 'điều kiện đủ', 'adj + n', '[{"en":"Hard work alone is not a sufficient condition for success.","vi":"Chỉ chăm chỉ thôi không phải là điều kiện đủ để thành công."},{"en":"The author distinguishes necessary from sufficient conditions.","vi":"Tác giả phân biệt điều kiện cần với điều kiện đủ."},{"en":"Funding is a sufficient condition for starting the project.","vi":"Kinh phí là điều kiện đủ để khởi động dự án."}]', '[]', NULL, '/səˈfɪʃənt kənˈdɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 16, 'sufficient detail', 'đủ chi tiết', 'adj + n', '[{"en":"The method is described in sufficient detail to be repeated.","vi":"Phương pháp được mô tả đủ chi tiết để có thể lặp lại."},{"en":"Please provide sufficient detail in your project proposal.","vi":"Vui lòng cung cấp đủ chi tiết trong đề xuất dự án của bạn."},{"en":"The report lacks sufficient detail about the data sources.","vi":"Báo cáo thiếu đủ chi tiết về các nguồn dữ liệu."}]', '[]', NULL, '/səˈfɪʃənt ˈdiːteɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 17, 'sufficient evidence', 'bằng chứng đầy đủ', 'adj + n', '[{"en":"There is not yet sufficient evidence to support the claim.","vi":"Vẫn chưa có đủ bằng chứng để ủng hộ tuyên bố này."},{"en":"The jury found sufficient evidence to reach a verdict.","vi":"Bồi thẩm đoàn tìm thấy đủ bằng chứng để đưa ra phán quyết."},{"en":"Researchers need sufficient evidence before publishing conclusions.","vi":"Các nhà nghiên cứu cần đủ bằng chứng trước khi công bố kết luận."}]', '[]', NULL, '/səˈfɪʃənt ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 18, 'sufficient information', 'đủ thông tin', 'adj + n', '[{"en":"We did not have sufficient information to make a decision.","vi":"Chúng tôi không có đủ thông tin để đưa ra quyết định."},{"en":"The form must contain sufficient information for verification.","vi":"Biểu mẫu phải chứa đủ thông tin để xác minh."},{"en":"Patients need sufficient information about possible side effects.","vi":"Bệnh nhân cần đủ thông tin về các tác dụng phụ có thể xảy ra."}]', '[]', NULL, '/səˈfɪʃənt ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 19, 'sufficient resources', 'đủ nguồn lực', 'adj + n', '[{"en":"The school lacks sufficient resources to support every student.","vi":"Trường thiếu đủ nguồn lực để hỗ trợ mọi học sinh."},{"en":"Without sufficient resources, the program cannot expand further.","vi":"Không có đủ nguồn lực, chương trình không thể mở rộng thêm."},{"en":"Managers must ensure teams have sufficient resources to succeed.","vi":"Người quản lý phải đảm bảo các nhóm có đủ nguồn lực để thành công."}]', '[]', NULL, '/səˈfɪʃənt ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 20, 'superior performance', 'hiệu suất vượt trội', 'adj + n', '[{"en":"The new engine delivers superior performance at lower cost.","vi":"Động cơ mới mang lại hiệu suất vượt trội với chi phí thấp hơn."},{"en":"The study attributes superior performance to better training.","vi":"Nghiên cứu cho rằng hiệu suất vượt trội đến từ việc đào tạo tốt hơn."},{"en":"Her team''s superior performance earned them the top award.","vi":"Hiệu suất vượt trội của nhóm cô giành được giải thưởng cao nhất."}]', '[]', NULL, '/suːˈpɪriər pərˈfɔːrməns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 21, 'support an argument', 'củng cố một luận điểm', 'v + n', '[{"en":"Use reliable data to support an argument in your essay.","vi":"Dùng dữ liệu đáng tin cậy để củng cố một luận điểm trong bài luận."},{"en":"The author cites several studies to support an argument.","vi":"Tác giả trích dẫn vài nghiên cứu để củng cố một luận điểm."},{"en":"Strong examples help support an argument more convincingly.","vi":"Những ví dụ mạnh giúp củng cố một luận điểm thuyết phục hơn."}]', '[]', NULL, '/səˈpɔːrt ən ˈɑːrɡjumənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 22, 'supporting evidence', 'bằng chứng hỗ trợ', 'adj + n', '[{"en":"Each claim should be backed by clear supporting evidence.","vi":"Mỗi tuyên bố nên được hậu thuẫn bằng bằng chứng hỗ trợ rõ ràng."},{"en":"The essay presents strong supporting evidence for its thesis.","vi":"Bài luận trình bày bằng chứng hỗ trợ mạnh mẽ cho luận đề của nó."},{"en":"Reviewers asked for more supporting evidence in the paper.","vi":"Người phản biện yêu cầu thêm bằng chứng hỗ trợ trong bài báo."}]', '[]', NULL, '/səˈpɔːrtɪŋ ˈevɪdəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 23, 'survey data', 'dữ liệu khảo sát', 'n + n', '[{"en":"The researchers analyzed survey data from over a thousand people.","vi":"Các nhà nghiên cứu phân tích dữ liệu khảo sát từ hơn một nghìn người."},{"en":"Survey data revealed clear trends in consumer behavior.","vi":"Dữ liệu khảo sát cho thấy các xu hướng rõ ràng trong hành vi tiêu dùng."},{"en":"We must check the survey data carefully for errors.","vi":"Chúng ta phải kiểm tra dữ liệu khảo sát cẩn thận để tìm lỗi."}]', '[]', NULL, '/ˈsɜːrveɪ ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 24, 'symbiotic relationship', 'mối quan hệ cộng sinh', 'adj + n', '[{"en":"Bees and flowers share a fascinating symbiotic relationship.","vi":"Ong và hoa có một mối quan hệ cộng sinh thú vị."},{"en":"The two companies developed a symbiotic relationship over time.","vi":"Hai công ty phát triển một mối quan hệ cộng sinh theo thời gian."},{"en":"A symbiotic relationship benefits both species involved.","vi":"Mối quan hệ cộng sinh mang lại lợi ích cho cả hai loài liên quan."}]', '[]', NULL, '/ˌsɪmbaɪˈɑːtɪk rɪˈleɪʃənʃɪp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 25, 'systematic analysis', 'phân tích có hệ thống', 'adj + n', '[{"en":"A systematic analysis of the data revealed hidden patterns.","vi":"Phân tích có hệ thống dữ liệu cho thấy các mẫu hình tiềm ẩn."},{"en":"The team conducted a systematic analysis of past research.","vi":"Nhóm tiến hành phân tích có hệ thống các nghiên cứu trước."},{"en":"Systematic analysis reduces the risk of biased conclusions.","vi":"Phân tích có hệ thống giảm nguy cơ kết luận thiên lệch."}]', '[]', NULL, '/ˌsɪstəˈmætɪk əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 26, 'systematic approach', 'phương pháp có hệ thống', 'adj + n', '[{"en":"A systematic approach helps solve complex problems step by step.","vi":"Phương pháp có hệ thống giúp giải quyết vấn đề phức tạp từng bước."},{"en":"The lab follows a systematic approach to testing samples.","vi":"Phòng thí nghiệm theo một phương pháp có hệ thống để kiểm tra mẫu."},{"en":"She recommends a systematic approach to reviewing the literature.","vi":"Cô đề xuất một phương pháp có hệ thống để rà soát tài liệu."}]', '[]', NULL, '/ˌsɪstəˈmætɪk əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 27, 'systematic study', 'nghiên cứu có hệ thống', 'adj + n', '[{"en":"The book offers a systematic study of urban migration patterns.","vi":"Cuốn sách cung cấp một nghiên cứu có hệ thống về các mẫu di cư đô thị."},{"en":"A systematic study requires careful planning and consistent methods.","vi":"Một nghiên cứu có hệ thống đòi hỏi lập kế hoạch cẩn thận và phương pháp nhất quán."},{"en":"Her systematic study of the language took several years.","vi":"Nghiên cứu có hệ thống của cô về ngôn ngữ kéo dài vài năm."}]', '[]', NULL, '/ˌsɪstəˈmætɪk ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 28, 'tacit knowledge', 'tri thức ngầm', 'adj + n', '[{"en":"Much expert skill relies on tacit knowledge gained through practice.","vi":"Nhiều kỹ năng chuyên gia dựa vào tri thức ngầm có được qua thực hành."},{"en":"Tacit knowledge is hard to write down or fully explain.","vi":"Tri thức ngầm rất khó viết ra hay giải thích đầy đủ."},{"en":"Experienced workers share tacit knowledge through close mentoring.","vi":"Người lao động giàu kinh nghiệm truyền tri thức ngầm qua việc kèm cặp sát sao."}]', '[]', NULL, '/ˈtæsɪt ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 29, 'take initiative', 'chủ động hành động', 'v + n', '[{"en":"Good leaders encourage their staff to take initiative.","vi":"Người lãnh đạo giỏi khuyến khích nhân viên chủ động hành động."},{"en":"She decided to take initiative and propose a new plan.","vi":"Cô quyết định chủ động hành động và đề xuất một kế hoạch mới."},{"en":"Students who take initiative often learn more independently.","vi":"Những sinh viên chủ động hành động thường học độc lập hơn."}]', '[]', NULL, '/ˈteɪk ɪˈnɪʃətɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 30, 'take precedence over', 'được ưu tiên hơn', 'v + n', '[{"en":"Safety must take precedence over speed on any construction site.","vi":"An toàn phải được ưu tiên hơn tốc độ tại mọi công trường xây dựng."},{"en":"Urgent tasks usually take precedence over routine ones.","vi":"Các nhiệm vụ khẩn cấp thường được ưu tiên hơn việc thường ngày."},{"en":"Patient care should take precedence over administrative paperwork.","vi":"Chăm sóc bệnh nhân nên được ưu tiên hơn giấy tờ hành chính."}]', '[]', NULL, '/ˈteɪk ˈpresɪdəns ˈoʊvər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 31, 'take responsibility', 'chịu trách nhiệm', 'v + n', '[{"en":"Managers must take responsibility for their team''s mistakes.","vi":"Người quản lý phải chịu trách nhiệm về sai lầm của nhóm mình."},{"en":"He was willing to take responsibility for the failed project.","vi":"Anh ấy sẵn sàng chịu trách nhiệm về dự án thất bại."},{"en":"Citizens should take responsibility for protecting the environment.","vi":"Người dân nên chịu trách nhiệm bảo vệ môi trường."}]', '[]', NULL, '/ˈteɪk rɪˌspɑːnsəˈbɪləti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 32, 'take a role in', 'đóng vai trò trong', 'v + n', '[{"en":"Parents should take a role in their children''s education.","vi":"Cha mẹ nên đóng vai trò trong việc giáo dục con cái."},{"en":"Volunteers take a role in organizing the annual festival.","vi":"Các tình nguyện viên đóng vai trò trong việc tổ chức lễ hội hằng năm."},{"en":"She hopes to take a role in shaping company policy.","vi":"Cô hy vọng được đóng vai trò trong việc định hình chính sách công ty."}]', '[]', NULL, '/ˈteɪk ə ˈroʊl ɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 33, 'take an approach', 'áp dụng một cách tiếp cận', 'v + n', '[{"en":"The researchers decided to take a different approach this time.","vi":"Các nhà nghiên cứu quyết định áp dụng một cách tiếp cận khác lần này."},{"en":"We should take a more practical approach to the problem.","vi":"Chúng ta nên áp dụng một cách tiếp cận thực tế hơn với vấn đề."},{"en":"Teachers can take an approach suited to each student''s needs.","vi":"Giáo viên có thể áp dụng một cách tiếp cận phù hợp với nhu cầu từng học sinh."}]', '[]', NULL, '/ˈteɪk ən əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 34, 'take into consideration', 'cân nhắc đến', 'v + n', '[{"en":"We must take into consideration the needs of every student.","vi":"Chúng ta phải cân nhắc đến nhu cầu của mọi học sinh."},{"en":"The plan takes into consideration both cost and safety.","vi":"Kế hoạch cân nhắc đến cả chi phí lẫn an toàn."},{"en":"Judges take into consideration the circumstances of each case.","vi":"Thẩm phán cân nhắc đến hoàn cảnh của từng vụ việc."}]', '[]', NULL, '/ˈteɪk ˌɪntə kənˌsɪdəˈreɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 35, 'take on the role of', 'đảm nhận vai trò', 'v + n', '[{"en":"She agreed to take on the role of team leader.","vi":"Cô đồng ý đảm nhận vai trò trưởng nhóm."},{"en":"He will take on the role of project coordinator next month.","vi":"Anh ấy sẽ đảm nhận vai trò điều phối dự án vào tháng tới."},{"en":"New graduates often take on the role of junior analyst.","vi":"Sinh viên mới ra trường thường đảm nhận vai trò chuyên viên phân tích cấp dưới."}]', '[]', NULL, '/ˈteɪk ˈɑːn ðə ˈroʊl əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 36, 'take up the role of', 'tiếp nhận vai trò', 'v + n', '[{"en":"He will take up the role of department head in July.","vi":"Ông sẽ tiếp nhận vai trò trưởng khoa vào tháng Bảy."},{"en":"She was asked to take up the role of mentor.","vi":"Cô được đề nghị tiếp nhận vai trò người hướng dẫn."},{"en":"After retirement, he took up the role of adviser.","vi":"Sau khi nghỉ hưu, ông tiếp nhận vai trò cố vấn."}]', '[]', NULL, '/ˈteɪk ˈʌp ðə ˈroʊl əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 37, 'target audience', 'đối tượng mục tiêu', 'n + n', '[{"en":"Writers should always consider their target audience first.","vi":"Người viết nên luôn cân nhắc đối tượng mục tiêu trước tiên."},{"en":"The campaign was designed for a young target audience.","vi":"Chiến dịch được thiết kế cho đối tượng mục tiêu là người trẻ."},{"en":"Knowing your target audience improves the impact of a message.","vi":"Hiểu đối tượng mục tiêu giúp tăng tác động của thông điệp."}]', '[]', NULL, '/ˈtɑːrɡɪt ˈɔːdiəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 38, 'teaching strategy', 'chiến lược giảng dạy', 'n + n', '[{"en":"The teacher adopted a new teaching strategy this semester.","vi":"Giáo viên áp dụng một chiến lược giảng dạy mới trong học kỳ này."},{"en":"An effective teaching strategy keeps students actively engaged.","vi":"Một chiến lược giảng dạy hiệu quả giữ cho học sinh tích cực tham gia."},{"en":"The workshop introduced several teaching strategies for large classes.","vi":"Buổi tập huấn giới thiệu một số chiến lược giảng dạy cho lớp đông."}]', '[]', NULL, '/ˈtiːtʃɪŋ ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 39, 'technical aspect', 'khía cạnh kỹ thuật', 'adj + n', '[{"en":"The report explains the technical aspects of the new system.","vi":"Báo cáo giải thích các khía cạnh kỹ thuật của hệ thống mới."},{"en":"She struggled with the technical aspects of the software.","vi":"Cô gặp khó khăn với các khía cạnh kỹ thuật của phần mềm."},{"en":"We hired an expert to handle the technical aspects.","vi":"Chúng tôi thuê một chuyên gia để xử lý các khía cạnh kỹ thuật."}]', '[]', NULL, '/ˈteknɪkəl ˈæspekt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 40, 'technical assistance', 'hỗ trợ kỹ thuật', 'adj + n', '[{"en":"The organization provides technical assistance to developing countries.","vi":"Tổ chức cung cấp hỗ trợ kỹ thuật cho các nước đang phát triển."},{"en":"Customers can request technical assistance by phone or email.","vi":"Khách hàng có thể yêu cầu hỗ trợ kỹ thuật qua điện thoại hoặc email."},{"en":"The project received technical assistance from international experts.","vi":"Dự án nhận được hỗ trợ kỹ thuật từ các chuyên gia quốc tế."}]', '[]', NULL, '/ˈteknɪkəl əˈsɪstəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 41, 'technical detail', 'chi tiết kỹ thuật', 'adj + n', '[{"en":"The manual covers every technical detail of the machine.","vi":"Sách hướng dẫn bao gồm mọi chi tiết kỹ thuật của máy."},{"en":"She explained the technical details clearly to the audience.","vi":"Cô giải thích các chi tiết kỹ thuật rõ ràng cho khán giả."},{"en":"Don''t get lost in technical details during the presentation.","vi":"Đừng sa vào các chi tiết kỹ thuật trong khi thuyết trình."}]', '[]', NULL, '/ˈteknɪkəl ˈdiːteɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 42, 'technical expertise', 'chuyên môn kỹ thuật', 'adj + n', '[{"en":"The job requires strong technical expertise in data analysis.","vi":"Công việc đòi hỏi chuyên môn kỹ thuật vững về phân tích dữ liệu."},{"en":"Her technical expertise made her a valuable team member.","vi":"Chuyên môn kỹ thuật khiến cô trở thành thành viên quý giá của nhóm."},{"en":"The company lacked the technical expertise to finish the project.","vi":"Công ty thiếu chuyên môn kỹ thuật để hoàn thành dự án."}]', '[]', NULL, '/ˈteknɪkəl ˌekspɜːrˈtiːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 43, 'technical issue', 'vấn đề kỹ thuật', 'adj + n', '[{"en":"A technical issue delayed the start of the online exam.","vi":"Một vấn đề kỹ thuật làm trễ giờ bắt đầu kỳ thi trực tuyến."},{"en":"The team quickly resolved the technical issue with the server.","vi":"Nhóm nhanh chóng khắc phục vấn đề kỹ thuật với máy chủ."},{"en":"We apologize for the technical issues during the broadcast.","vi":"Chúng tôi xin lỗi về các vấn đề kỹ thuật trong buổi phát sóng."}]', '[]', NULL, '/ˈteknɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 44, 'technical knowledge', 'kiến thức kỹ thuật', 'adj + n', '[{"en":"The course builds technical knowledge in network security.","vi":"Khóa học xây dựng kiến thức kỹ thuật về an ninh mạng."},{"en":"Practical projects deepen students'' technical knowledge.","vi":"Các dự án thực hành làm sâu kiến thức kỹ thuật của sinh viên."},{"en":"He gained valuable technical knowledge during the internship.","vi":"Anh ấy tích lũy kiến thức kỹ thuật quý báu trong kỳ thực tập."}]', '[]', NULL, '/ˈteknɪkəl ˈnɑːlɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 45, 'technical problem', 'trục trặc kỹ thuật', 'adj + n', '[{"en":"A technical problem caused the website to crash repeatedly.","vi":"Một trục trặc kỹ thuật khiến trang web liên tục bị sập."},{"en":"Engineers worked overnight to fix the technical problem.","vi":"Các kỹ sư làm việc suốt đêm để khắc phục trục trặc kỹ thuật."},{"en":"The flight was delayed because of a minor technical problem.","vi":"Chuyến bay bị hoãn vì một trục trặc kỹ thuật nhỏ."}]', '[]', NULL, '/ˈteknɪkəl ˈprɑːbləm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 46, 'technical skill', 'kỹ năng kỹ thuật', 'adj + n', '[{"en":"Employers value both technical skills and good communication.","vi":"Nhà tuyển dụng coi trọng cả kỹ năng kỹ thuật lẫn giao tiếp tốt."},{"en":"The training program develops practical technical skills.","vi":"Chương trình đào tạo phát triển các kỹ năng kỹ thuật thực tế."},{"en":"She improved her technical skills through online courses.","vi":"Cô nâng cao kỹ năng kỹ thuật của mình qua các khóa học trực tuyến."}]', '[]', NULL, '/ˈteknɪkəl ˈskɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 47, 'technical support', 'hỗ trợ kỹ thuật', 'adj + n', '[{"en":"Call technical support if the device stops responding.","vi":"Gọi bộ phận hỗ trợ kỹ thuật nếu thiết bị ngừng phản hồi."},{"en":"The software includes free technical support for one year.","vi":"Phần mềm bao gồm hỗ trợ kỹ thuật miễn phí trong một năm."},{"en":"Their technical support team responds within a few hours.","vi":"Đội hỗ trợ kỹ thuật của họ phản hồi trong vài giờ."}]', '[]', NULL, '/ˈteknɪkəl səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 48, 'technical term', 'thuật ngữ chuyên môn', 'adj + n', '[{"en":"The author defines each technical term before using it.","vi":"Tác giả định nghĩa từng thuật ngữ chuyên môn trước khi dùng nó."},{"en":"Avoid too many technical terms when writing for general readers.","vi":"Tránh dùng quá nhiều thuật ngữ chuyên môn khi viết cho độc giả phổ thông."},{"en":"The glossary explains all the technical terms in the report.","vi":"Bảng thuật ngữ giải thích mọi thuật ngữ chuyên môn trong báo cáo."}]', '[]', NULL, '/ˈteknɪkəl ˈtɜːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 49, 'technological advances', 'những tiến bộ công nghệ', 'adj + n', '[{"en":"Recent technological advances have transformed how we communicate.","vi":"Những tiến bộ công nghệ gần đây đã thay đổi cách chúng ta giao tiếp."},{"en":"Technological advances in medicine save millions of lives.","vi":"Những tiến bộ công nghệ trong y học cứu sống hàng triệu người."},{"en":"The industry depends on continuous technological advances.","vi":"Ngành này phụ thuộc vào những tiến bộ công nghệ liên tục."}]', '[]', NULL, '/ˌteknəˈlɑːdʒɪkəl ədˈvænsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 50, 'technological change', 'sự thay đổi công nghệ', 'adj + n', '[{"en":"Rapid technological change reshaped the global job market.","vi":"Sự thay đổi công nghệ nhanh chóng định hình lại thị trường lao động toàn cầu."},{"en":"Workers must adapt to constant technological change.","vi":"Người lao động phải thích ứng với sự thay đổi công nghệ liên tục."},{"en":"The essay examines how technological change affects daily life.","vi":"Bài luận xem xét sự thay đổi công nghệ ảnh hưởng đến đời sống thường nhật ra sao."}]', '[]', NULL, '/ˌteknəˈlɑːdʒɪkəl ˈtʃeɪndʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 51, 'technological development', 'sự phát triển công nghệ', 'adj + n', '[{"en":"Technological development drives much of modern economic growth.","vi":"Sự phát triển công nghệ thúc đẩy phần lớn tăng trưởng kinh tế hiện đại."},{"en":"The country invested heavily in technological development.","vi":"Quốc gia này đầu tư mạnh vào sự phát triển công nghệ."},{"en":"Technological development has improved access to education worldwide.","vi":"Sự phát triển công nghệ đã cải thiện việc tiếp cận giáo dục trên toàn cầu."}]', '[]', NULL, '/ˌteknəˈlɑːdʒɪkəl dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 52, 'technological innovation', 'đổi mới công nghệ', 'adj + n', '[{"en":"Technological innovation gives companies a strong competitive edge.","vi":"Đổi mới công nghệ mang lại cho công ty lợi thế cạnh tranh lớn."},{"en":"The region became a hub for technological innovation.","vi":"Khu vực này trở thành trung tâm đổi mới công nghệ."},{"en":"Government funding supports technological innovation in universities.","vi":"Ngân sách chính phủ hỗ trợ đổi mới công nghệ tại các trường đại học."}]', '[]', NULL, '/ˌteknəˈlɑːdʒɪkəl ˌɪnəˈveɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 53, 'technological progress', 'tiến bộ công nghệ', 'adj + n', '[{"en":"Technological progress has made information far easier to access.","vi":"Tiến bộ công nghệ đã làm cho việc tiếp cận thông tin dễ dàng hơn nhiều."},{"en":"Some worry that technological progress may replace many jobs.","vi":"Một số người lo rằng tiến bộ công nghệ có thể thay thế nhiều việc làm."},{"en":"Rapid technological progress requires constant learning and adaptation.","vi":"Tiến bộ công nghệ nhanh chóng đòi hỏi học hỏi và thích ứng liên tục."}]', '[]', NULL, '/ˌteknəˈlɑːdʒɪkəl ˈprɑːɡres/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 54, 'test score', 'điểm kiểm tra', 'n + n', '[{"en":"Her test scores improved steadily throughout the school year.","vi":"Điểm kiểm tra của cô cải thiện đều đặn suốt năm học."},{"en":"The study compared test scores across different teaching methods.","vi":"Nghiên cứu so sánh điểm kiểm tra giữa các phương pháp giảng dạy khác nhau."},{"en":"High test scores do not always reflect deep understanding.","vi":"Điểm kiểm tra cao không phải lúc nào cũng phản ánh sự hiểu sâu."}]', '[]', NULL, '/ˈtest ˈskɔːr/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 55, 'test a theory', 'kiểm chứng một lý thuyết', 'v + n', '[{"en":"Scientists design experiments to test a theory under controlled conditions.","vi":"Các nhà khoa học thiết kế thí nghiệm để kiểm chứng một lý thuyết trong điều kiện kiểm soát."},{"en":"We collected new data to test a theory about memory.","vi":"Chúng tôi thu thập dữ liệu mới để kiểm chứng một lý thuyết về trí nhớ."},{"en":"Researchers must test a theory before accepting it as fact.","vi":"Các nhà nghiên cứu phải kiểm chứng một lý thuyết trước khi xem nó là sự thật."}]', '[]', NULL, '/test ə ˈθiːəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 56, 'textual analysis', 'phân tích văn bản', 'adj + n', '[{"en":"Her textual analysis revealed hidden themes in the old manuscript.","vi":"Phân tích văn bản của cô đã hé lộ những chủ đề ẩn trong bản thảo cũ."},{"en":"Careful textual analysis helps students understand the author''s intent.","vi":"Phân tích văn bản kỹ lưỡng giúp sinh viên hiểu ý đồ của tác giả."},{"en":"The course introduces methods of textual analysis for literary criticism.","vi":"Khóa học giới thiệu các phương pháp phân tích văn bản cho phê bình văn học."}]', '[]', NULL, '/ˈtekstʃuəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 57, 'thematic analysis', 'phân tích theo chủ đề', 'adj + n', '[{"en":"We used thematic analysis to identify patterns in the interviews.","vi":"Chúng tôi dùng phân tích theo chủ đề để tìm các mẫu trong các cuộc phỏng vấn."},{"en":"Thematic analysis is common in qualitative social science research.","vi":"Phân tích theo chủ đề rất phổ biến trong nghiên cứu khoa học xã hội định tính."},{"en":"The report presents a thematic analysis of student feedback.","vi":"Báo cáo trình bày một phân tích theo chủ đề về phản hồi của sinh viên."}]', '[]', NULL, '/θɪˈmætɪk əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 58, 'theoretical analysis', 'phân tích lý thuyết', 'adj + n', '[{"en":"The paper offers a detailed theoretical analysis of market behavior.","vi":"Bài báo đưa ra một phân tích lý thuyết chi tiết về hành vi thị trường."},{"en":"Theoretical analysis often precedes any practical experiment in physics.","vi":"Phân tích lý thuyết thường đi trước bất kỳ thí nghiệm thực tế nào trong vật lý."},{"en":"Her theoretical analysis explained why the model sometimes failed.","vi":"Phân tích lý thuyết của cô giải thích vì sao mô hình đôi khi thất bại."}]', '[]', NULL, '/ˌθiːəˈretɪkəl əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 59, 'theoretical approach', 'cách tiếp cận lý thuyết', 'adj + n', '[{"en":"Each theoretical approach offers a different way of explaining behavior.","vi":"Mỗi cách tiếp cận lý thuyết đưa ra một cách giải thích hành vi khác nhau."},{"en":"The author combines two theoretical approaches in her new study.","vi":"Tác giả kết hợp hai cách tiếp cận lý thuyết trong nghiên cứu mới của mình."},{"en":"Students compared the theoretical approach with the empirical findings.","vi":"Sinh viên so sánh cách tiếp cận lý thuyết với các kết quả thực nghiệm."}]', '[]', NULL, '/ˌθiːəˈretɪkəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 60, 'theoretical basis', 'cơ sở lý thuyết', 'adj + n', '[{"en":"The study lacks a solid theoretical basis for its claims.","vi":"Nghiên cứu thiếu một cơ sở lý thuyết vững chắc cho các tuyên bố của nó."},{"en":"His argument rests on a clear theoretical basis from psychology.","vi":"Lập luận của anh dựa trên một cơ sở lý thuyết rõ ràng từ tâm lý học."},{"en":"We must establish the theoretical basis before designing the experiment.","vi":"Chúng ta phải thiết lập cơ sở lý thuyết trước khi thiết kế thí nghiệm."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈbeɪsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 61, 'theoretical concept', 'khái niệm lý thuyết', 'adj + n', '[{"en":"The lecture explained an abstract theoretical concept with simple examples.","vi":"Bài giảng giải thích một khái niệm lý thuyết trừu tượng bằng ví dụ đơn giản."},{"en":"Some theoretical concepts are hard to test in real situations.","vi":"Một số khái niệm lý thuyết rất khó kiểm chứng trong tình huống thực tế."},{"en":"She linked the theoretical concept to everyday classroom practice.","vi":"Cô liên hệ khái niệm lý thuyết với thực hành lớp học hằng ngày."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 62, 'theoretical debate', 'cuộc tranh luận lý thuyết', 'adj + n', '[{"en":"The article reviews a long theoretical debate about human motivation.","vi":"Bài viết điểm lại một cuộc tranh luận lý thuyết lâu dài về động lực con người."},{"en":"Her thesis enters an ongoing theoretical debate in economics.","vi":"Luận văn của cô tham gia một cuộc tranh luận lý thuyết đang diễn ra trong kinh tế học."},{"en":"The theoretical debate has shaped research for several decades.","vi":"Cuộc tranh luận lý thuyết đã định hình nghiên cứu trong nhiều thập kỷ."}]', '[]', NULL, '/ˌθiːəˈretɪkəl dɪˈbeɪt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 63, 'theoretical framework', 'khung lý thuyết', 'adj + n', '[{"en":"Her dissertation builds on a well-known theoretical framework.","vi":"Luận án của cô dựa trên một khung lý thuyết nổi tiếng."},{"en":"A clear theoretical framework guides the whole research design.","vi":"Một khung lý thuyết rõ ràng định hướng toàn bộ thiết kế nghiên cứu."},{"en":"The authors adapted the theoretical framework for online learning.","vi":"Các tác giả điều chỉnh khung lý thuyết cho việc học trực tuyến."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈfreɪmwɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 64, 'theoretical issue', 'vấn đề lý thuyết', 'adj + n', '[{"en":"The seminar addressed several theoretical issues in modern linguistics.","vi":"Buổi hội thảo bàn về một số vấn đề lý thuyết trong ngôn ngữ học hiện đại."},{"en":"This theoretical issue remains unresolved despite many studies.","vi":"Vấn đề lý thuyết này vẫn chưa được giải quyết dù đã có nhiều nghiên cứu."},{"en":"She separated the practical problems from the theoretical issues.","vi":"Cô tách các vấn đề thực tiễn ra khỏi các vấn đề lý thuyết."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 65, 'theoretical model', 'mô hình lý thuyết', 'adj + n', '[{"en":"The theoretical model predicts how prices respond to demand.","vi":"Mô hình lý thuyết dự đoán giá phản ứng thế nào với nhu cầu."},{"en":"Researchers tested the theoretical model against real-world data.","vi":"Các nhà nghiên cứu kiểm chứng mô hình lý thuyết với dữ liệu thực tế."},{"en":"A simple theoretical model can still capture key relationships.","vi":"Một mô hình lý thuyết đơn giản vẫn có thể nắm bắt các mối quan hệ chính."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈmɑːdəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 66, 'theoretical perspective', 'góc nhìn lý thuyết', 'adj + n', '[{"en":"From a feminist theoretical perspective, the data look quite different.","vi":"Từ một góc nhìn lý thuyết nữ quyền, dữ liệu trông khá khác biệt."},{"en":"Each theoretical perspective highlights certain aspects of the problem.","vi":"Mỗi góc nhìn lý thuyết làm nổi bật những khía cạnh nhất định của vấn đề."},{"en":"She adopted a sociological theoretical perspective in her analysis.","vi":"Cô áp dụng một góc nhìn lý thuyết xã hội học trong phân tích của mình."}]', '[]', NULL, '/ˌθiːəˈretɪkəl pərˈspektɪv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 67, 'theoretical study', 'nghiên cứu lý thuyết', 'adj + n', '[{"en":"This theoretical study explores how networks grow over time.","vi":"Nghiên cứu lý thuyết này khám phá cách các mạng lưới phát triển theo thời gian."},{"en":"A purely theoretical study may need later experimental support.","vi":"Một nghiên cứu thuần lý thuyết có thể cần sự hỗ trợ thực nghiệm sau này."},{"en":"The journal published a theoretical study on language acquisition.","vi":"Tạp chí đăng một nghiên cứu lý thuyết về việc tiếp thu ngôn ngữ."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˈstʌdi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 68, 'theoretical understanding', 'sự hiểu biết về mặt lý thuyết', 'adj + n', '[{"en":"Good theoretical understanding helps engineers solve practical problems.","vi":"Sự hiểu biết lý thuyết tốt giúp kỹ sư giải quyết các vấn đề thực tế."},{"en":"The course deepens students'' theoretical understanding of climate systems.","vi":"Khóa học giúp sinh viên hiểu sâu hơn về mặt lý thuyết các hệ thống khí hậu."},{"en":"Without theoretical understanding, the experiment was hard to interpret.","vi":"Thiếu hiểu biết lý thuyết, thí nghiệm rất khó diễn giải."}]', '[]', NULL, '/ˌθiːəˈretɪkəl ˌʌndərˈstændɪŋ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 69, 'theoretical work', 'công trình lý thuyết', 'adj + n', '[{"en":"His early theoretical work laid the foundation for later discoveries.","vi":"Công trình lý thuyết đầu tay của ông đặt nền móng cho các khám phá sau này."},{"en":"The lab balances experimental research with serious theoretical work.","vi":"Phòng thí nghiệm cân bằng giữa nghiên cứu thực nghiệm và công trình lý thuyết nghiêm túc."},{"en":"Much theoretical work in this area remains highly abstract.","vi":"Phần lớn công trình lý thuyết trong lĩnh vực này vẫn rất trừu tượng."}]', '[]', NULL, '/ˌθiːəˈretɪkəl wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 70, 'think differently', 'suy nghĩ khác đi', 'v + adv', '[{"en":"Travel encourages people to think differently about their own culture.","vi":"Việc đi du lịch khuyến khích người ta suy nghĩ khác đi về văn hóa của mình."},{"en":"Good teachers help students think differently about difficult problems.","vi":"Giáo viên giỏi giúp học sinh suy nghĩ khác đi về những vấn đề khó."},{"en":"The two scientists think differently, yet they collaborate well.","vi":"Hai nhà khoa học suy nghĩ khác nhau, nhưng họ hợp tác rất tốt."}]', '[]', NULL, '/θɪŋk ˈdɪfrəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 71, 'thinking process', 'quá trình tư duy', 'n + n', '[{"en":"The exercise makes students'' thinking process visible to the teacher.","vi":"Bài tập làm cho quá trình tư duy của học sinh hiện rõ với giáo viên."},{"en":"A clear thinking process leads to better decisions under pressure.","vi":"Một quá trình tư duy rõ ràng dẫn đến quyết định tốt hơn khi áp lực."},{"en":"Researchers studied the thinking process behind expert chess moves.","vi":"Các nhà nghiên cứu nghiên cứu quá trình tư duy đằng sau các nước cờ của chuyên gia."}]', '[]', NULL, '/ˈθɪŋkɪŋ ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 72, 'third party', 'bên thứ ba', 'adj + n', '[{"en":"An independent third party reviewed the contract for both sides.","vi":"Một bên thứ ba độc lập đã xem xét hợp đồng cho cả hai phía."},{"en":"The data were never shared with any third party.","vi":"Dữ liệu chưa bao giờ được chia sẻ với bất kỳ bên thứ ba nào."},{"en":"A neutral third party helped resolve the long dispute.","vi":"Một bên thứ ba trung lập đã giúp giải quyết tranh chấp kéo dài."}]', '[]', NULL, '/θɜːrd ˈpɑːrti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 73, 'thought process', 'tiến trình suy nghĩ', 'n + n', '[{"en":"Explaining your thought process helps others follow the argument.","vi":"Giải thích tiến trình suy nghĩ của bạn giúp người khác theo dõi lập luận."},{"en":"The interview revealed the candidate''s thought process while solving problems.","vi":"Cuộc phỏng vấn cho thấy tiến trình suy nghĩ của ứng viên khi giải quyết vấn đề."},{"en":"Writing a journal can slow down a racing thought process.","vi":"Viết nhật ký có thể làm chậm lại một tiến trình suy nghĩ dồn dập."}]', '[]', NULL, '/θɔːt ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 74, 'tightly controlled', 'được kiểm soát chặt chẽ', 'adv + vpp', '[{"en":"The experiment was tightly controlled to reduce outside influences.","vi":"Thí nghiệm được kiểm soát chặt chẽ để giảm các ảnh hưởng bên ngoài."},{"en":"Access to the laboratory remains tightly controlled for safety.","vi":"Việc ra vào phòng thí nghiệm vẫn được kiểm soát chặt chẽ vì an toàn."},{"en":"In tightly controlled conditions, the results were highly consistent.","vi":"Trong điều kiện được kiểm soát chặt chẽ, kết quả rất nhất quán."}]', '[]', NULL, '/ˈtaɪtli kənˈtroʊld/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 75, 'top management', 'ban lãnh đạo cấp cao', 'adj + n', '[{"en":"Top management approved the new strategy after a long meeting.","vi":"Ban lãnh đạo cấp cao đã phê duyệt chiến lược mới sau cuộc họp dài."},{"en":"Support from top management is essential for any major change.","vi":"Sự ủng hộ từ ban lãnh đạo cấp cao là thiết yếu cho mọi thay đổi lớn."},{"en":"The report goes directly to top management each quarter.","vi":"Báo cáo được gửi thẳng tới ban lãnh đạo cấp cao mỗi quý."}]', '[]', NULL, '/tɑːp ˈmænɪdʒmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 76, 'total income', 'tổng thu nhập', 'adj + n', '[{"en":"The family''s total income rose after the second job started.","vi":"Tổng thu nhập của gia đình tăng lên sau khi công việc thứ hai bắt đầu."},{"en":"Taxes are calculated based on a household''s total income.","vi":"Thuế được tính dựa trên tổng thu nhập của một hộ gia đình."},{"en":"The report compares total income across different regions.","vi":"Báo cáo so sánh tổng thu nhập giữa các vùng khác nhau."}]', '[]', NULL, '/ˈtoʊtəl ˈɪnkʌm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 77, 'totally different', 'hoàn toàn khác biệt', 'adv + adj', '[{"en":"The two studies reached totally different conclusions about the issue.","vi":"Hai nghiên cứu đi đến những kết luận hoàn toàn khác biệt về vấn đề này."},{"en":"Life in a small village is totally different from the city.","vi":"Cuộc sống ở làng nhỏ hoàn toàn khác biệt so với thành phố."},{"en":"After the reform, the system worked in a totally different way.","vi":"Sau cải cách, hệ thống vận hành theo một cách hoàn toàn khác biệt."}]', '[]', NULL, '/ˈtoʊtəli ˈdɪfrənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 78, 'traditional approach', 'cách tiếp cận truyền thống', 'adj + n', '[{"en":"The traditional approach to teaching still works for many learners.","vi":"Cách tiếp cận truyền thống trong giảng dạy vẫn hiệu quả với nhiều người học."},{"en":"Some doctors prefer a traditional approach over newer methods.","vi":"Một số bác sĩ thích cách tiếp cận truyền thống hơn các phương pháp mới."},{"en":"The study challenges the traditional approach to economic planning.","vi":"Nghiên cứu thách thức cách tiếp cận truyền thống trong hoạch định kinh tế."}]', '[]', NULL, '/trəˈdɪʃənəl əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 79, 'traditional culture', 'văn hóa truyền thống', 'adj + n', '[{"en":"Festivals help younger generations connect with traditional culture.","vi":"Các lễ hội giúp thế hệ trẻ kết nối với văn hóa truyền thống."},{"en":"Globalization sometimes threatens local traditional culture.","vi":"Toàn cầu hóa đôi khi đe dọa văn hóa truyền thống địa phương."},{"en":"The museum preserves objects from the region''s traditional culture.","vi":"Bảo tàng lưu giữ các hiện vật từ văn hóa truyền thống của vùng này."}]', '[]', NULL, '/trəˈdɪʃənəl ˈkʌltʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 80, 'traditional form', 'hình thức truyền thống', 'adj + n', '[{"en":"This dance is a traditional form passed down for generations.","vi":"Điệu múa này là một hình thức truyền thống được truyền qua nhiều thế hệ."},{"en":"Email replaced more traditional forms of business communication.","vi":"Email đã thay thế những hình thức giao tiếp kinh doanh truyền thống hơn."},{"en":"The artist blends modern styles with a traditional form.","vi":"Người nghệ sĩ pha trộn phong cách hiện đại với một hình thức truyền thống."}]', '[]', NULL, '/trəˈdɪʃənəl fɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 81, 'traditional method', 'phương pháp truyền thống', 'adj + n', '[{"en":"Farmers here still rely on a traditional method of irrigation.","vi":"Nông dân ở đây vẫn dựa vào một phương pháp tưới tiêu truyền thống."},{"en":"The traditional method takes longer but produces better results.","vi":"Phương pháp truyền thống mất nhiều thời gian hơn nhưng cho kết quả tốt hơn."},{"en":"Researchers compared a new tool with the traditional method.","vi":"Các nhà nghiên cứu so sánh một công cụ mới với phương pháp truyền thống."}]', '[]', NULL, '/trəˈdɪʃənəl ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 82, 'traditional practice', 'tập quán truyền thống', 'adj + n', '[{"en":"Many traditional practices survive only in remote rural villages.","vi":"Nhiều tập quán truyền thống chỉ còn tồn tại ở các làng quê xa xôi."},{"en":"The community defended its traditional practice against new regulations.","vi":"Cộng đồng bảo vệ tập quán truyền thống của mình trước các quy định mới."},{"en":"Scholars recorded the traditional practice before it disappeared.","vi":"Các học giả đã ghi chép tập quán truyền thống trước khi nó biến mất."}]', '[]', NULL, '/trəˈdɪʃənəl ˈpræktɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 83, 'traditional research', 'nghiên cứu truyền thống', 'adj + n', '[{"en":"Traditional research relies heavily on surveys and printed sources.","vi":"Nghiên cứu truyền thống dựa nhiều vào khảo sát và nguồn tài liệu in."},{"en":"Digital tools have transformed methods used in traditional research.","vi":"Các công cụ kỹ thuật số đã thay đổi phương pháp dùng trong nghiên cứu truyền thống."},{"en":"The team combined traditional research with large-scale data analysis.","vi":"Nhóm kết hợp nghiên cứu truyền thống với phân tích dữ liệu quy mô lớn."}]', '[]', NULL, '/trəˈdɪʃənəl ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 84, 'traditional society', 'xã hội truyền thống', 'adj + n', '[{"en":"In traditional society, elders often made the most important decisions.","vi":"Trong xã hội truyền thống, người cao tuổi thường đưa ra những quyết định quan trọng nhất."},{"en":"The book contrasts modern life with traditional society.","vi":"Cuốn sách đối chiếu cuộc sống hiện đại với xã hội truyền thống."},{"en":"Roles in a traditional society were usually fixed by gender.","vi":"Vai trò trong một xã hội truyền thống thường được cố định theo giới tính."}]', '[]', NULL, '/trəˈdɪʃənəl səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 85, 'traditional value', 'giá trị truyền thống', 'adj + n', '[{"en":"Parents try to pass traditional values on to their children.","vi":"Cha mẹ cố gắng truyền lại các giá trị truyền thống cho con cái."},{"en":"Some traditional values conflict with modern ideas of freedom.","vi":"Một số giá trị truyền thống xung đột với các ý niệm hiện đại về tự do."},{"en":"The community works hard to protect its traditional values.","vi":"Cộng đồng nỗ lực bảo vệ các giá trị truyền thống của mình."}]', '[]', NULL, '/trəˈdɪʃənəl ˈvæljuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 86, 'traditional view', 'quan điểm truyền thống', 'adj + n', '[{"en":"The traditional view holds that hard work guarantees success.","vi":"Quan điểm truyền thống cho rằng làm việc chăm chỉ bảo đảm thành công."},{"en":"Recent studies challenge the traditional view of memory.","vi":"Các nghiên cứu gần đây thách thức quan điểm truyền thống về trí nhớ."},{"en":"She rejected the traditional view in favor of newer theories.","vi":"Cô bác bỏ quan điểm truyền thống để ủng hộ những lý thuyết mới hơn."}]', '[]', NULL, '/trəˈdɪʃənəl vjuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 87, 'transferable skill', 'kỹ năng có thể chuyển đổi', 'adj + n', '[{"en":"Communication is a transferable skill valued in almost every job.","vi":"Giao tiếp là một kỹ năng có thể chuyển đổi được coi trọng ở hầu hết mọi công việc."},{"en":"University courses aim to develop students'' transferable skills.","vi":"Các khóa học đại học nhằm phát triển kỹ năng chuyển đổi của sinh viên."},{"en":"Teamwork is a transferable skill useful across many careers.","vi":"Làm việc nhóm là một kỹ năng có thể chuyển đổi hữu ích trong nhiều nghề."}]', '[]', NULL, '/trænsˈfɜːrəbəl skɪl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 88, 'transmit data', 'truyền dữ liệu', 'v + n', '[{"en":"The new network can transmit data far more quickly than before.","vi":"Mạng mới có thể truyền dữ liệu nhanh hơn nhiều so với trước đây."},{"en":"Sensors transmit data to the central server every minute.","vi":"Các cảm biến truyền dữ liệu về máy chủ trung tâm mỗi phút."},{"en":"Engineers encrypt the signal before they transmit data.","vi":"Các kỹ sư mã hóa tín hiệu trước khi truyền dữ liệu."}]', '[]', NULL, '/trænsˈmɪt ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 89, 'transmit information', 'truyền thông tin', 'v + n', '[{"en":"Nerve cells transmit information across the body very rapidly.","vi":"Các tế bào thần kinh truyền thông tin khắp cơ thể rất nhanh."},{"en":"Satellites transmit information to receivers around the world.","vi":"Các vệ tinh truyền thông tin tới các máy thu khắp thế giới."},{"en":"Clear diagrams transmit information faster than long paragraphs.","vi":"Sơ đồ rõ ràng truyền thông tin nhanh hơn những đoạn văn dài."}]', '[]', NULL, '/trænsˈmɪt ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 90, 'transport system', 'hệ thống giao thông', 'n + n', '[{"en":"The city invested heavily in its public transport system.","vi":"Thành phố đầu tư mạnh vào hệ thống giao thông công cộng của mình."},{"en":"An efficient transport system reduces traffic and pollution.","vi":"Một hệ thống giao thông hiệu quả giảm kẹt xe và ô nhiễm."},{"en":"The report compares the transport systems of major cities.","vi":"Báo cáo so sánh hệ thống giao thông của các thành phố lớn."}]', '[]', NULL, '/ˈtrænspɔːrt ˈsɪstəm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 91, 'treat differently', 'đối xử khác biệt', 'v + adv', '[{"en":"Teachers should not treat differently the children of wealthy parents.","vi":"Giáo viên không nên đối xử khác biệt với con của những phụ huynh giàu có."},{"en":"The study found that doctors treat differently male and female patients.","vi":"Nghiên cứu phát hiện bác sĩ đối xử khác biệt với bệnh nhân nam và nữ."},{"en":"Companies that treat differently their staff often lose trust.","vi":"Những công ty đối xử khác biệt với nhân viên thường đánh mất niềm tin."}]', '[]', NULL, '/triːt ˈdɪfrəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 92, 'treat equally', 'đối xử bình đẳng', 'v + adv', '[{"en":"The law requires employers to treat equally all their workers.","vi":"Luật yêu cầu chủ lao động đối xử bình đẳng với mọi nhân viên."},{"en":"Good schools treat equally students from every background.","vi":"Những trường học tốt đối xử bình đẳng với học sinh từ mọi hoàn cảnh."},{"en":"The policy aims to treat equally men and women.","vi":"Chính sách này nhằm đối xử bình đẳng giữa nam và nữ."}]', '[]', NULL, '/triːt ˈiːkwəli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 93, 'typical example', 'ví dụ điển hình', 'adj + n', '[{"en":"This case is a typical example of poor project planning.","vi":"Trường hợp này là một ví dụ điển hình của việc lập kế hoạch dự án kém."},{"en":"The teacher gave a typical example to clarify the rule.","vi":"Giáo viên đưa ra một ví dụ điển hình để làm rõ quy tắc."},{"en":"Her essay offers a typical example of strong academic writing.","vi":"Bài luận của cô là một ví dụ điển hình về văn viết học thuật tốt."}]', '[]', NULL, '/ˈtɪpɪkəl ɪɡˈzæmpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 94, 'ultimate goal', 'mục tiêu cuối cùng', 'adj + n', '[{"en":"The ultimate goal of the program is to reduce poverty.","vi":"Mục tiêu cuối cùng của chương trình là giảm nghèo."},{"en":"Her ultimate goal was to publish in a leading journal.","vi":"Mục tiêu cuối cùng của cô là đăng bài trên một tạp chí hàng đầu."},{"en":"Every small task should serve the team''s ultimate goal.","vi":"Mỗi nhiệm vụ nhỏ đều nên phục vụ mục tiêu cuối cùng của nhóm."}]', '[]', NULL, '/ˈʌltɪmət ɡoʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 95, 'undergo transformation', 'trải qua sự biến đổi', 'adj + n', '[{"en":"The old town will undergo transformation over the next decade.","vi":"Khu phố cũ sẽ trải qua sự biến đổi trong thập kỷ tới."},{"en":"Caterpillars undergo transformation before becoming butterflies.","vi":"Sâu bướm trải qua sự biến đổi trước khi thành bướm."},{"en":"The industry must undergo transformation to survive the crisis.","vi":"Ngành công nghiệp phải trải qua sự biến đổi để sống sót qua khủng hoảng."}]', '[]', NULL, '/ˌʌndərˈɡoʊ ˌtrænsfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 96, 'underlying assumption', 'giả định ngầm', 'adj + n', '[{"en":"The model rests on an underlying assumption about rational behavior.","vi":"Mô hình dựa trên một giả định ngầm về hành vi lý trí."},{"en":"She questioned the underlying assumption behind the whole argument.","vi":"Cô đặt câu hỏi về giả định ngầm đằng sau toàn bộ lập luận."},{"en":"Every method carries underlying assumptions that researchers must state.","vi":"Mỗi phương pháp đều mang những giả định ngầm mà nhà nghiên cứu phải nêu rõ."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ əˈsʌmpʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 97, 'underlying cause', 'nguyên nhân sâu xa', 'adj + n', '[{"en":"Doctors searched for the underlying cause of her fatigue.","vi":"Các bác sĩ tìm kiếm nguyên nhân sâu xa của sự mệt mỏi ở cô."},{"en":"Poverty is often an underlying cause of social conflict.","vi":"Nghèo đói thường là nguyên nhân sâu xa của xung đột xã hội."},{"en":"Treating symptoms ignores the underlying cause of the problem.","vi":"Chữa triệu chứng là bỏ qua nguyên nhân sâu xa của vấn đề."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ kɔːz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 98, 'underlying principle', 'nguyên tắc nền tảng', 'adj + n', '[{"en":"The same underlying principle governs both circuits and pipelines.","vi":"Cùng một nguyên tắc nền tảng chi phối cả mạch điện lẫn đường ống."},{"en":"Fairness is the underlying principle of the whole policy.","vi":"Công bằng là nguyên tắc nền tảng của toàn bộ chính sách."},{"en":"Once you grasp the underlying principle, the rules make sense.","vi":"Khi đã nắm được nguyên tắc nền tảng, các quy tắc trở nên hợp lý."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ ˈprɪnsəpəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 99, 'underlying process', 'tiến trình nền tảng', 'adj + n', '[{"en":"Researchers study the underlying process that drives memory loss.","vi":"Các nhà nghiên cứu nghiên cứu tiến trình nền tảng gây mất trí nhớ."},{"en":"Understanding the underlying process helps engineers fix the fault.","vi":"Hiểu tiến trình nền tảng giúp kỹ sư khắc phục sự cố."},{"en":"The same underlying process shapes growth in many species.","vi":"Cùng một tiến trình nền tảng định hình sự tăng trưởng ở nhiều loài."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ ˈprɑːses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 100, 'underlying reason', 'lý do sâu xa', 'adj + n', '[{"en":"The survey explored the underlying reason for student dropout.","vi":"Cuộc khảo sát tìm hiểu lý do sâu xa khiến sinh viên bỏ học."},{"en":"Low pay is the underlying reason behind the high turnover.","vi":"Lương thấp là lý do sâu xa đằng sau tỷ lệ nghỉ việc cao."},{"en":"She wanted to know the underlying reason for his decision.","vi":"Cô muốn biết lý do sâu xa cho quyết định của anh."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ ˈriːzən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 101, 'underlying structure', 'cấu trúc nền tảng', 'adj + n', '[{"en":"Linguists try to reveal the underlying structure of every language.","vi":"Các nhà ngôn ngữ học cố gắng hé lộ cấu trúc nền tảng của mọi ngôn ngữ."},{"en":"The melody hides a complex underlying structure of harmonies.","vi":"Giai điệu che giấu một cấu trúc nền tảng phức tạp của các hòa âm."},{"en":"Mapping the underlying structure clarified how the data connect.","vi":"Vẽ ra cấu trúc nền tảng đã làm rõ cách dữ liệu liên kết với nhau."}]', '[]', NULL, '/ˌʌndərˈlaɪɪŋ ˈstrʌktʃər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 102, 'undertake research', 'tiến hành nghiên cứu', 'v + n', '[{"en":"The university encourages students to undertake research early.","vi":"Trường đại học khuyến khích sinh viên tiến hành nghiên cứu từ sớm."},{"en":"Her team undertook research into renewable energy storage.","vi":"Nhóm của cô đã tiến hành nghiên cứu về lưu trữ năng lượng tái tạo."},{"en":"Funding allows the lab to undertake research on rare diseases.","vi":"Nguồn tài trợ cho phép phòng thí nghiệm tiến hành nghiên cứu về bệnh hiếm."}]', '[]', NULL, '/ˌʌndərˈteɪk ˈriːsɜːrtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 103, 'undertake work', 'đảm nhận công việc', 'v + n', '[{"en":"The contractor agreed to undertake work on the old bridge.","vi":"Nhà thầu đồng ý đảm nhận công việc trên cây cầu cũ."},{"en":"Volunteers undertake work that local councils cannot afford.","vi":"Các tình nguyện viên đảm nhận công việc mà hội đồng địa phương không đủ khả năng chi trả."},{"en":"Few firms will undertake work in such dangerous conditions.","vi":"Ít công ty chịu đảm nhận công việc trong điều kiện nguy hiểm như vậy."}]', '[]', NULL, '/ˌʌndərˈteɪk wɜːrk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 104, 'undertake an activity', 'thực hiện một hoạt động', 'v + n', '[{"en":"Students must undertake an activity that links theory and practice.","vi":"Sinh viên phải thực hiện một hoạt động gắn kết lý thuyết với thực hành."},{"en":"The class will undertake an activity to test their hypothesis.","vi":"Lớp học sẽ thực hiện một hoạt động để kiểm chứng giả thuyết của mình."},{"en":"Before you undertake an activity, read the safety guidelines.","vi":"Trước khi thực hiện một hoạt động, hãy đọc hướng dẫn an toàn."}]', '[]', NULL, '/ˌʌndərˈteɪk ən ækˈtɪvəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 105, 'unequal power', 'quyền lực bất bình đẳng', 'adj + n', '[{"en":"Unequal power between the two nations shaped the treaty.","vi":"Quyền lực bất bình đẳng giữa hai quốc gia đã định hình hiệp ước."},{"en":"The essay examines unequal power in the workplace.","vi":"Bài luận xem xét quyền lực bất bình đẳng tại nơi làm việc."},{"en":"Unequal power often makes fair negotiation very difficult.","vi":"Quyền lực bất bình đẳng thường khiến việc thương lượng công bằng rất khó."}]', '[]', NULL, '/ʌnˈiːkwəl ˈpaʊər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 106, 'unfair treatment', 'sự đối xử bất công', 'adj + n', '[{"en":"Several workers complained about unfair treatment by their manager.","vi":"Một số nhân viên phàn nàn về sự đối xử bất công của quản lý họ."},{"en":"The law protects citizens from unfair treatment by officials.","vi":"Luật bảo vệ công dân khỏi sự đối xử bất công từ giới chức."},{"en":"She filed a complaint after years of unfair treatment.","vi":"Cô nộp đơn khiếu nại sau nhiều năm bị đối xử bất công."}]', '[]', NULL, '/ʌnˈfer ˈtriːtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 107, 'unintended consequences', 'hậu quả ngoài ý muốn', 'adj + n', '[{"en":"The new tax had several unintended consequences for small businesses.","vi":"Loại thuế mới gây ra vài hậu quả ngoài ý muốn cho doanh nghiệp nhỏ."},{"en":"Good policies sometimes produce serious unintended consequences.","vi":"Những chính sách tốt đôi khi tạo ra hậu quả ngoài ý muốn nghiêm trọng."},{"en":"Engineers test designs to avoid unintended consequences later.","vi":"Các kỹ sư thử nghiệm thiết kế để tránh hậu quả ngoài ý muốn về sau."}]', '[]', NULL, '/ˌʌnɪnˈtendɪd ˈkɑːnsɪkwensɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 108, 'unique individual', 'cá nhân độc nhất', 'adj + n', '[{"en":"Each student is a unique individual with different strengths.","vi":"Mỗi học sinh là một cá nhân độc nhất với những thế mạnh khác nhau."},{"en":"Good teaching respects every unique individual in the room.","vi":"Việc dạy học tốt tôn trọng từng cá nhân độc nhất trong phòng."},{"en":"The theory treats people as unique individuals, not mere statistics.","vi":"Lý thuyết xem con người là những cá nhân độc nhất, không phải chỉ là con số thống kê."}]', '[]', NULL, '/juˈniːk ˌɪndɪˈvɪdʒuəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 109, 'unique opportunity', 'cơ hội độc nhất', 'adj + n', '[{"en":"The scholarship gave her a unique opportunity to study abroad.","vi":"Học bổng đã cho cô một cơ hội độc nhất để du học."},{"en":"This project offers a unique opportunity to test the model.","vi":"Dự án này mang lại một cơ hội độc nhất để kiểm chứng mô hình."},{"en":"Few people get such a unique opportunity in their career.","vi":"Ít người có được một cơ hội độc nhất như vậy trong sự nghiệp."}]', '[]', NULL, '/juˈniːk ˌɑːpərˈtuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 110, 'unique position', 'vị thế độc nhất', 'adj + n', '[{"en":"The company holds a unique position in the local market.","vi":"Công ty giữ một vị thế độc nhất trên thị trường địa phương."},{"en":"Her experience puts her in a unique position to advise.","vi":"Kinh nghiệm đặt cô vào một vị thế độc nhất để tư vấn."},{"en":"The country''s unique position gave it strong trade advantages.","vi":"Vị thế độc nhất của đất nước mang lại lợi thế thương mại lớn."}]', '[]', NULL, '/juˈniːk pəˈzɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 111, 'universally accepted', 'được chấp nhận rộng rãi', 'adv + vpp', '[{"en":"No single definition of culture is universally accepted.","vi":"Không có một định nghĩa duy nhất nào về văn hóa được chấp nhận rộng rãi."},{"en":"These safety standards are now universally accepted in the industry.","vi":"Những tiêu chuẩn an toàn này nay được chấp nhận rộng rãi trong ngành."},{"en":"The theory became universally accepted after decades of debate.","vi":"Lý thuyết trở nên được chấp nhận rộng rãi sau hàng thập kỷ tranh luận."}]', '[]', NULL, '/ˌjuːnɪˈvɜːrsəli əkˈseptɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 112, 'unlimited access', 'quyền truy cập không giới hạn', 'adj + n', '[{"en":"Members enjoy unlimited access to the online research library.","vi":"Thành viên được hưởng quyền truy cập không giới hạn vào thư viện nghiên cứu trực tuyến."},{"en":"The subscription gives unlimited access to every back issue.","vi":"Gói đăng ký cho quyền truy cập không giới hạn vào mọi số báo cũ."},{"en":"Students should not have unlimited access to exam answers.","vi":"Sinh viên không nên có quyền truy cập không giới hạn vào đáp án bài thi."}]', '[]', NULL, '/ʌnˈlɪmɪtɪd ˈækses/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 113, 'unskilled worker', 'lao động phổ thông', 'adj + n', '[{"en":"Many unskilled workers lost their jobs when the factory closed.","vi":"Nhiều lao động phổ thông mất việc khi nhà máy đóng cửa."},{"en":"Automation often replaces unskilled workers first.","vi":"Tự động hóa thường thay thế lao động phổ thông trước tiên."},{"en":"Training programs help unskilled workers find better positions.","vi":"Các chương trình đào tạo giúp lao động phổ thông tìm được vị trí tốt hơn."}]', '[]', NULL, '/ʌnˈskɪld ˈwɜːrkər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 114, 'urban area', 'khu vực đô thị', 'adj + n', '[{"en":"More people are moving from villages into urban areas.","vi":"Ngày càng nhiều người chuyển từ làng quê ra khu vực đô thị."},{"en":"Air pollution is usually worse in dense urban areas.","vi":"Ô nhiễm không khí thường tệ hơn ở các khu vực đô thị đông đúc."},{"en":"The study compared crime rates in urban and rural areas.","vi":"Nghiên cứu so sánh tỷ lệ tội phạm ở khu vực đô thị và nông thôn."}]', '[]', NULL, '/ˈɜːrbən ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 115, 'urban center', 'trung tâm đô thị', 'adj + n', '[{"en":"Jobs are concentrated in the country''s largest urban centers.","vi":"Việc làm tập trung ở những trung tâm đô thị lớn nhất của đất nước."},{"en":"The new railway connects several major urban centers.","vi":"Tuyến đường sắt mới nối liền vài trung tâm đô thị lớn."},{"en":"Housing costs rise quickly near busy urban centers.","vi":"Chi phí nhà ở tăng nhanh gần các trung tâm đô thị sầm uất."}]', '[]', NULL, '/ˈɜːrbən ˈsentər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 116, 'urban design', 'thiết kế đô thị', 'adj + n', '[{"en":"Good urban design makes neighborhoods safer and more walkable.","vi":"Thiết kế đô thị tốt làm cho các khu dân cư an toàn hơn và dễ đi bộ hơn."},{"en":"The course covers principles of sustainable urban design.","vi":"Khóa học bao quát các nguyên tắc thiết kế đô thị bền vững."},{"en":"Poor urban design can increase traffic and isolation.","vi":"Thiết kế đô thị kém có thể làm tăng kẹt xe và sự cô lập."}]', '[]', NULL, '/ˈɜːrbən dɪˈzaɪn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 117, 'urban development', 'phát triển đô thị', 'adj + n', '[{"en":"Rapid urban development has put pressure on local water supplies.","vi":"Phát triển đô thị nhanh đã gây áp lực lên nguồn nước địa phương."},{"en":"The council approved a plan for sustainable urban development.","vi":"Hội đồng phê duyệt một kế hoạch phát triển đô thị bền vững."},{"en":"Urban development often displaces poorer residents from city centers.","vi":"Phát triển đô thị thường đẩy cư dân nghèo ra khỏi trung tâm thành phố."}]', '[]', NULL, '/ˈɜːrbən dɪˈveləpmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 118, 'urban environment', 'môi trường đô thị', 'adj + n', '[{"en":"Children in an urban environment face different health risks.","vi":"Trẻ em trong môi trường đô thị đối mặt với những rủi ro sức khỏe khác nhau."},{"en":"Trees and parks improve the quality of an urban environment.","vi":"Cây xanh và công viên cải thiện chất lượng của môi trường đô thị."},{"en":"The study examined stress levels in a crowded urban environment.","vi":"Nghiên cứu xem xét mức độ căng thẳng trong một môi trường đô thị đông đúc."}]', '[]', NULL, '/ˈɜːrbən ɪnˈvaɪrənmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 119, 'use criteria', 'sử dụng tiêu chí', 'v + n', '[{"en":"Reviewers use criteria to judge each application fairly.","vi":"Người đánh giá sử dụng tiêu chí để chấm mỗi hồ sơ một cách công bằng."},{"en":"The committee will use criteria agreed upon in advance.","vi":"Hội đồng sẽ sử dụng tiêu chí đã được thống nhất từ trước."},{"en":"Teachers use clear criteria when they grade student essays.","vi":"Giáo viên sử dụng tiêu chí rõ ràng khi chấm bài luận của học sinh."}]', '[]', NULL, '/juːz kraɪˈtɪriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 120, 'use effectively', 'sử dụng hiệu quả', 'v + adv', '[{"en":"Students must learn to use effectively the resources available.","vi":"Sinh viên phải học cách sử dụng hiệu quả những nguồn lực sẵn có."},{"en":"Few managers use effectively the data they collect.","vi":"Ít nhà quản lý sử dụng hiệu quả dữ liệu mà họ thu thập."},{"en":"To use effectively your time, plan each day carefully.","vi":"Để sử dụng hiệu quả thời gian của bạn, hãy lên kế hoạch mỗi ngày cẩn thận."}]', '[]', NULL, '/juːz ɪˈfektɪvli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 121, 'use resources', 'sử dụng nguồn lực', 'v + n', '[{"en":"Sustainable companies use resources without harming the environment.","vi":"Các công ty bền vững sử dụng nguồn lực mà không gây hại cho môi trường."},{"en":"We must use resources wisely during the budget shortfall.","vi":"Chúng ta phải sử dụng nguồn lực một cách khôn ngoan trong lúc thiếu hụt ngân sách."},{"en":"The project taught students to use resources more efficiently.","vi":"Dự án dạy sinh viên sử dụng nguồn lực hiệu quả hơn."}]', '[]', NULL, '/juːz ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 122, 'use sparingly', 'sử dụng dè sẻn', 'v + adv', '[{"en":"Writers should use sparingly long and complicated technical terms.","vi":"Người viết nên sử dụng dè sẻn những thuật ngữ kỹ thuật dài và phức tạp."},{"en":"During the drought, families were told to use water sparingly.","vi":"Trong hạn hán, các gia đình được khuyên sử dụng nước dè sẻn."},{"en":"Good designers use bright colors sparingly for emphasis.","vi":"Những nhà thiết kế giỏi sử dụng màu sắc rực rỡ dè sẻn để nhấn mạnh."}]', '[]', NULL, '/juːz ˈsperɪŋli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 123, 'use statistics', 'sử dụng số liệu thống kê', 'v + n', '[{"en":"Economists use statistics to track changes in the labor market.","vi":"Các nhà kinh tế sử dụng số liệu thống kê để theo dõi thay đổi trên thị trường lao động."},{"en":"The article uses statistics to support its main argument.","vi":"Bài báo sử dụng số liệu thống kê để củng cố lập luận chính của nó."},{"en":"Be careful when you use statistics from unreliable sources.","vi":"Hãy cẩn thận khi bạn sử dụng số liệu thống kê từ những nguồn không đáng tin."}]', '[]', NULL, '/juːz stəˈtɪstɪks/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 124, 'use a format', 'sử dụng một định dạng', 'v + n', '[{"en":"Please use a format that all team members can open.","vi":"Vui lòng sử dụng một định dạng mà mọi thành viên trong nhóm có thể mở."},{"en":"Academic journals require authors to use a strict format.","vi":"Các tạp chí học thuật yêu cầu tác giả sử dụng một định dạng nghiêm ngặt."},{"en":"The slides use a clear format that aids understanding.","vi":"Các slide sử dụng một định dạng rõ ràng giúp dễ hiểu hơn."}]', '[]', NULL, '/juːz ə ˈfɔːrmæt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 125, 'use a method', 'sử dụng một phương pháp', 'v + n', '[{"en":"The researchers use a method that reduces measurement errors.","vi":"Các nhà nghiên cứu sử dụng một phương pháp giúp giảm sai số đo lường."},{"en":"We chose to use a method tested in earlier studies.","vi":"Chúng tôi chọn sử dụng một phương pháp đã được kiểm chứng ở các nghiên cứu trước."},{"en":"Teachers often use a method suited to younger learners.","vi":"Giáo viên thường sử dụng một phương pháp phù hợp với người học nhỏ tuổi."}]', '[]', NULL, '/juːz ə ˈmeθəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 126, 'use a methodology', 'sử dụng một phương pháp luận', 'v + n', '[{"en":"The thesis uses a methodology common in social research.","vi":"Luận văn sử dụng một phương pháp luận phổ biến trong nghiên cứu xã hội."},{"en":"They chose to use a methodology that combines surveys and interviews.","vi":"Họ chọn sử dụng một phương pháp luận kết hợp khảo sát và phỏng vấn."},{"en":"Authors must clearly explain why they use a methodology.","vi":"Tác giả phải giải thích rõ vì sao họ sử dụng một phương pháp luận."}]', '[]', NULL, '/juːz ə ˌmeθəˈdɑːlədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 127, 'use a procedure', 'sử dụng một quy trình', 'v + n', '[{"en":"The lab uses a procedure designed to keep samples sterile.","vi":"Phòng thí nghiệm sử dụng một quy trình được thiết kế để giữ mẫu vô trùng."},{"en":"We use a procedure that anyone can repeat exactly.","vi":"Chúng tôi sử dụng một quy trình mà bất kỳ ai cũng có thể lặp lại chính xác."},{"en":"Hospitals must use a procedure approved by safety regulators.","vi":"Các bệnh viện phải sử dụng một quy trình được cơ quan an toàn phê duyệt."}]', '[]', NULL, '/juːz ə prəˈsiːdʒər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 128, 'use a source', 'sử dụng một nguồn', 'v + n', '[{"en":"Always use a source you can cite and verify.","vi":"Hãy luôn sử dụng một nguồn mà bạn có thể trích dẫn và kiểm chứng."},{"en":"Students must not use a source without proper acknowledgment.","vi":"Sinh viên không được sử dụng một nguồn mà không ghi nhận đúng cách."},{"en":"The essay uses a source from a respected academic journal.","vi":"Bài luận sử dụng một nguồn từ một tạp chí học thuật uy tín."}]', '[]', NULL, '/juːz ə sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 129, 'use a strategy', 'sử dụng một chiến lược', 'v + n', '[{"en":"The company will use a strategy focused on online sales.","vi":"Công ty sẽ sử dụng một chiến lược tập trung vào bán hàng trực tuyến."},{"en":"Good students use a strategy to manage exam stress.","vi":"Học sinh giỏi sử dụng một chiến lược để quản lý căng thẳng khi thi."},{"en":"The coach decided to use a strategy that suits younger players.","vi":"Huấn luyện viên quyết định sử dụng một chiến lược phù hợp với cầu thủ trẻ."}]', '[]', NULL, '/juːz ə ˈstrætədʒi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 130, 'use a technique', 'sử dụng một kỹ thuật', 'v + n', '[{"en":"Surgeons use a technique that shortens recovery time.","vi":"Bác sĩ phẫu thuật sử dụng một kỹ thuật giúp rút ngắn thời gian hồi phục."},{"en":"The artist uses a technique borrowed from old masters.","vi":"Người nghệ sĩ sử dụng một kỹ thuật học từ các bậc thầy xưa."},{"en":"We use a technique that improves the accuracy of measurements.","vi":"Chúng tôi sử dụng một kỹ thuật giúp cải thiện độ chính xác của phép đo."}]', '[]', NULL, '/juːz ə tekˈniːk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 131, 'use a theory', 'vận dụng một lý thuyết', 'v + n', '[{"en":"The paper uses a theory developed in cognitive science.","vi":"Bài báo vận dụng một lý thuyết được phát triển trong khoa học nhận thức."},{"en":"She decided to use a theory that explains group behavior.","vi":"Cô quyết định vận dụng một lý thuyết giải thích hành vi nhóm."},{"en":"Good analysts use a theory to interpret their data.","vi":"Những nhà phân tích giỏi vận dụng một lý thuyết để diễn giải dữ liệu của họ."}]', '[]', NULL, '/juːz ə ˈθiːəri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 132, 'use an analysis', 'sử dụng một phân tích', 'v + n', '[{"en":"The report uses an analysis of ten years of sales data.","vi":"Báo cáo sử dụng một phân tích dữ liệu bán hàng trong mười năm."},{"en":"We use an analysis that compares both groups directly.","vi":"Chúng tôi sử dụng một phân tích so sánh trực tiếp cả hai nhóm."},{"en":"Planners use an analysis of traffic flow to design roads.","vi":"Các nhà quy hoạch sử dụng một phân tích lưu lượng giao thông để thiết kế đường."}]', '[]', NULL, '/juːz ən əˈnæləsɪs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 133, 'use an approach', 'sử dụng một cách tiếp cận', 'v + n', '[{"en":"The teacher uses an approach that engages every student.","vi":"Giáo viên sử dụng một cách tiếp cận thu hút mọi học sinh."},{"en":"We decided to use an approach based on real examples.","vi":"Chúng tôi quyết định sử dụng một cách tiếp cận dựa trên ví dụ thực tế."},{"en":"Therapists often use an approach tailored to each patient.","vi":"Các nhà trị liệu thường sử dụng một cách tiếp cận riêng cho từng bệnh nhân."}]', '[]', NULL, '/juːz ən əˈproʊtʃ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 134, 'use an definition', 'sử dụng một định nghĩa', 'v + n', '[{"en":"The study uses an definition of poverty set by the agency.","vi":"Nghiên cứu sử dụng một định nghĩa về nghèo do cơ quan này đặt ra."},{"en":"Researchers must use an definition that others can apply consistently.","vi":"Các nhà nghiên cứu phải sử dụng một định nghĩa mà người khác có thể áp dụng nhất quán."},{"en":"We use an definition broad enough to cover both cases.","vi":"Chúng tôi sử dụng một định nghĩa đủ rộng để bao quát cả hai trường hợp."}]', '[]', NULL, '/juːz ən ˌdefɪˈnɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 135, 'use the concept', 'vận dụng khái niệm', 'v + n', '[{"en":"The author uses the concept of identity throughout the book.","vi":"Tác giả vận dụng khái niệm bản sắc xuyên suốt cuốn sách."},{"en":"We use the concept to explain why prices vary.","vi":"Chúng tôi vận dụng khái niệm này để giải thích vì sao giá cả biến động."},{"en":"Economists use the concept of supply and demand daily.","vi":"Các nhà kinh tế vận dụng khái niệm cung và cầu hằng ngày."}]', '[]', NULL, '/juːz ðə ˈkɑːnsept/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 136, 'use the data', 'sử dụng dữ liệu', 'v + n', '[{"en":"Researchers use the data to test their main hypothesis.","vi":"Các nhà nghiên cứu sử dụng dữ liệu để kiểm chứng giả thuyết chính của họ."},{"en":"The company will use the data to improve its service.","vi":"Công ty sẽ sử dụng dữ liệu để cải thiện dịch vụ của mình."},{"en":"We must use the data carefully to avoid wrong conclusions.","vi":"Chúng ta phải sử dụng dữ liệu cẩn thận để tránh kết luận sai."}]', '[]', NULL, '/juːz ðə ˈdeɪtə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 137, 'useful information', 'thông tin hữu ích', 'adj + n', '[{"en":"The survey gathered useful information about students'' study habits.","vi":"Cuộc khảo sát thu thập thông tin hữu ích về thói quen học tập của sinh viên."},{"en":"This website provides useful information for first-year university applicants.","vi":"Trang web này cung cấp thông tin hữu ích cho thí sinh năm nhất đại học."},{"en":"Interviews can yield useful information that questionnaires often miss.","vi":"Phỏng vấn có thể mang lại thông tin hữu ích mà bảng hỏi thường bỏ sót."}]', '[]', NULL, '/ˈjuːsfəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 138, 'useful material', 'tài liệu hữu ích', 'adj + n', '[{"en":"The library offers useful material for writing research papers.","vi":"Thư viện cung cấp tài liệu hữu ích để viết bài nghiên cứu."},{"en":"She collected useful material before drafting her thesis introduction.","vi":"Cô ấy thu thập tài liệu hữu ích trước khi viết phần mở đầu luận văn."},{"en":"Teachers shared useful material to help students prepare for exams.","vi":"Giáo viên chia sẻ tài liệu hữu ích giúp học sinh ôn thi."}]', '[]', NULL, '/ˈjuːsfəl məˈtɪriəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 139, 'useful means', 'phương tiện hữu ích', 'adj + n', '[{"en":"Surveys are a useful means of measuring public opinion accurately.","vi":"Khảo sát là một phương tiện hữu ích để đo lường dư luận chính xác."},{"en":"Email remains a useful means of communication in academic settings.","vi":"Email vẫn là phương tiện liên lạc hữu ích trong môi trường học thuật."},{"en":"Graphs provide a useful means of presenting complex data clearly.","vi":"Biểu đồ là phương tiện hữu ích để trình bày dữ liệu phức tạp rõ ràng."}]', '[]', NULL, '/ˈjuːsfəl miːnz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 140, 'useful source', 'nguồn hữu ích', 'adj + n', '[{"en":"Academic journals are a useful source of reliable evidence.","vi":"Tạp chí học thuật là nguồn hữu ích cung cấp bằng chứng đáng tin cậy."},{"en":"The internet can be a useful source if used critically.","vi":"Internet có thể là nguồn hữu ích nếu được dùng một cách phê phán."},{"en":"Government reports proved a useful source for the analysis.","vi":"Các báo cáo của chính phủ là nguồn hữu ích cho phần phân tích."}]', '[]', NULL, '/ˈjuːsfəl sɔːrs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 141, 'useful summary', 'bản tóm tắt hữu ích', 'adj + n', '[{"en":"The chapter ends with a useful summary of key points.","vi":"Chương sách kết thúc bằng một bản tóm tắt hữu ích các ý chính."},{"en":"She wrote a useful summary to revise before the test.","vi":"Cô ấy viết một bản tóm tắt hữu ích để ôn tập trước bài kiểm tra."},{"en":"A useful summary helps readers grasp the article quickly.","vi":"Một bản tóm tắt hữu ích giúp người đọc nắm bài viết nhanh chóng."}]', '[]', NULL, '/ˈjuːsfəl ˈsʌməri/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 142, 'useful tool', 'công cụ hữu ích', 'adj + n', '[{"en":"Spreadsheets are a useful tool for organizing research data.","vi":"Bảng tính là công cụ hữu ích để sắp xếp dữ liệu nghiên cứu."},{"en":"Mind maps can be a useful tool when planning essays.","vi":"Sơ đồ tư duy có thể là công cụ hữu ích khi lên dàn ý bài luận."},{"en":"Statistical software is a useful tool for analyzing large datasets.","vi":"Phần mềm thống kê là công cụ hữu ích để phân tích tập dữ liệu lớn."}]', '[]', NULL, '/ˈjuːsfəl tuːl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 143, 'valid argument', 'lập luận hợp lý', 'adj + n', '[{"en":"She presented a valid argument supported by strong evidence.","vi":"Cô ấy đưa ra một lập luận hợp lý được hỗ trợ bằng bằng chứng vững chắc."},{"en":"A valid argument must follow logically from its premises.","vi":"Một lập luận hợp lý phải suy ra logic từ các tiền đề của nó."},{"en":"The essay builds a valid argument against unrestricted social media.","vi":"Bài luận xây dựng một lập luận hợp lý chống lại mạng xã hội không giới hạn."}]', '[]', NULL, '/ˈvælɪd ˈɑːrgjəmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 144, 'valuable information', 'thông tin quý giá', 'adj + n', '[{"en":"The experiment produced valuable information about the chemical reaction.","vi":"Thí nghiệm tạo ra thông tin quý giá về phản ứng hóa học."},{"en":"Patients provided valuable information that improved the treatment plan.","vi":"Bệnh nhân cung cấp thông tin quý giá giúp cải thiện phác đồ điều trị."},{"en":"Field notes often contain valuable information for later analysis.","vi":"Ghi chép thực địa thường chứa thông tin quý giá cho phân tích sau này."}]', '[]', NULL, '/ˈvæljəbəl ˌɪnfərˈmeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 145, 'valuable resources', 'nguồn lực quý giá', 'adj + n', '[{"en":"The project wasted valuable resources on poorly planned activities.","vi":"Dự án lãng phí nguồn lực quý giá vào những hoạt động lập kế hoạch kém."},{"en":"Forests are valuable resources that must be protected carefully.","vi":"Rừng là nguồn lực quý giá cần được bảo vệ cẩn thận."},{"en":"Libraries offer valuable resources for independent academic research.","vi":"Thư viện cung cấp nguồn lực quý giá cho nghiên cứu học thuật độc lập."}]', '[]', NULL, '/ˈvæljəbəl ˈriːsɔːrsɪz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 146, 'various aspects', 'nhiều khía cạnh khác nhau', 'adj + n', '[{"en":"The course examines various aspects of modern economic theory.","vi":"Khóa học xem xét nhiều khía cạnh khác nhau của lý thuyết kinh tế hiện đại."},{"en":"Her study explored various aspects of childhood language development.","vi":"Nghiên cứu của cô khám phá nhiều khía cạnh của sự phát triển ngôn ngữ trẻ em."},{"en":"We discussed various aspects of the problem before deciding.","vi":"Chúng tôi thảo luận nhiều khía cạnh của vấn đề trước khi quyết định."}]', '[]', NULL, '/ˈveriəs ˈæspekts/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 147, 'vary considerably', 'thay đổi đáng kể', 'v + adv', '[{"en":"Prices vary considerably depending on the season and location.","vi":"Giá cả thay đổi đáng kể tùy theo mùa và địa điểm."},{"en":"Test results vary considerably between the two student groups.","vi":"Kết quả kiểm tra thay đổi đáng kể giữa hai nhóm sinh viên."},{"en":"Opinions on the policy vary considerably across different regions.","vi":"Ý kiến về chính sách thay đổi đáng kể giữa các khu vực khác nhau."}]', '[]', NULL, '/ˈveri kənˈsɪdərəbli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 148, 'vary greatly', 'thay đổi rất nhiều', 'v + adv', '[{"en":"Living costs vary greatly from one city to another.","vi":"Chi phí sinh hoạt thay đổi rất nhiều từ thành phố này sang thành phố khác."},{"en":"Students'' learning styles vary greatly within a single classroom.","vi":"Phong cách học của học sinh thay đổi rất nhiều trong cùng một lớp."},{"en":"The quality of online courses can vary greatly nowadays.","vi":"Chất lượng các khóa học trực tuyến ngày nay có thể thay đổi rất nhiều."}]', '[]', NULL, '/ˈveri ˈgreɪtli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 149, 'vary significantly', 'thay đổi rõ rệt', 'v + adv', '[{"en":"Wages vary significantly across industries and levels of experience.","vi":"Tiền lương thay đổi rõ rệt giữa các ngành và mức kinh nghiệm."},{"en":"The findings vary significantly depending on the research method used.","vi":"Kết quả thay đổi rõ rệt tùy thuộc vào phương pháp nghiên cứu được dùng."},{"en":"Temperatures vary significantly between the coastal and inland areas.","vi":"Nhiệt độ thay đổi rõ rệt giữa khu vực ven biển và nội địa."}]', '[]', NULL, '/ˈveri sɪgˈnɪfɪkəntli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-16-01', 150, 'vary widely', 'thay đổi rất khác nhau', 'v + adv', '[{"en":"Cultural attitudes toward time vary widely around the world.","vi":"Quan niệm văn hóa về thời gian thay đổi rất khác nhau trên thế giới."},{"en":"Estimates of the population vary widely among different sources.","vi":"Ước tính dân số thay đổi rất khác nhau giữa các nguồn."},{"en":"The prices of textbooks vary widely between online retailers.","vi":"Giá sách giáo khoa thay đổi rất khác nhau giữa các nhà bán lẻ trực tuyến."}]', '[]', NULL, '/ˈveri ˈwaɪdli/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('colloc-17-01', 'colloc-17', 'Cụm học thuật · Nhóm 17', 'Academic Collocation List (Pearson/PTE) — nhóm 17 (68 cụm, xếp theo bảng chữ cái)', '#5fd4c8', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 1, 'varying degree', 'mức độ khác nhau', 'adj + n', '[{"en":"Students showed a varying degree of interest in the topic.","vi":"Học sinh thể hiện mức độ quan tâm khác nhau đối với chủ đề."},{"en":"The reforms succeeded to a varying degree across different schools.","vi":"Các cải cách thành công ở mức độ khác nhau giữa các trường."},{"en":"Participants experienced stress to a varying degree during the study.","vi":"Người tham gia trải qua căng thẳng ở mức độ khác nhau trong nghiên cứu."}]', '[]', NULL, '/ˈveriɪŋ dɪˈgriː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 2, 'vast amount of', 'một lượng khổng lồ', 'adj + n', '[{"en":"Modern science generates a vast amount of data daily.","vi":"Khoa học hiện đại tạo ra một lượng dữ liệu khổng lồ mỗi ngày."},{"en":"Writing a thesis requires a vast amount of careful reading.","vi":"Viết luận văn đòi hỏi một lượng đọc kỹ lưỡng khổng lồ."},{"en":"The project consumed a vast amount of time and money.","vi":"Dự án tiêu tốn một lượng thời gian và tiền bạc khổng lồ."}]', '[]', NULL, '/væst əˈmaʊnt əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 3, 'vast area', 'khu vực rộng lớn', 'adj + n', '[{"en":"The fire destroyed a vast area of ancient forest.","vi":"Đám cháy phá hủy một khu vực rừng cổ rộng lớn."},{"en":"Satellites can monitor a vast area of the ocean simultaneously.","vi":"Vệ tinh có thể giám sát một khu vực đại dương rộng lớn cùng lúc."},{"en":"The survey covered a vast area of rural farmland.","vi":"Cuộc khảo sát bao phủ một khu vực đất nông nghiệp rộng lớn."}]', '[]', NULL, '/væst ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 4, 'vast array of', 'một loạt phong phú', 'adj + n', '[{"en":"The museum displays a vast array of historical artifacts.","vi":"Bảo tàng trưng bày một loạt phong phú các hiện vật lịch sử."},{"en":"Students can choose from a vast array of elective courses.","vi":"Sinh viên có thể chọn từ một loạt phong phú các môn tự chọn."},{"en":"The library houses a vast array of academic publications.","vi":"Thư viện lưu giữ một loạt phong phú các ấn phẩm học thuật."}]', '[]', NULL, '/væst əˈreɪ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 5, 'vast majority', 'đại đa số', 'adj + n', '[{"en":"The vast majority of students passed the final examination.","vi":"Đại đa số sinh viên đã đậu kỳ thi cuối kỳ."},{"en":"A vast majority of respondents supported the new policy.","vi":"Đại đa số người được hỏi ủng hộ chính sách mới."},{"en":"The vast majority of cases were resolved within a week.","vi":"Đại đa số các trường hợp được giải quyết trong một tuần."}]', '[]', NULL, '/væst məˈdʒɔːrəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 6, 'vast number', 'số lượng khổng lồ', 'adj + n', '[{"en":"A vast number of species remain undiscovered in the rainforest.","vi":"Một số lượng khổng lồ các loài vẫn chưa được phát hiện trong rừng nhiệt đới."},{"en":"The campaign reached a vast number of young voters.","vi":"Chiến dịch tiếp cận được một số lượng khổng lồ cử tri trẻ."},{"en":"Researchers analyzed a vast number of documents for the study.","vi":"Các nhà nghiên cứu phân tích một số lượng khổng lồ tài liệu cho nghiên cứu."}]', '[]', NULL, '/væst ˈnʌmbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 7, 'vast quantities of', 'lượng lớn khổng lồ', 'adj + n', '[{"en":"Factories release vast quantities of waste into the rivers.","vi":"Các nhà máy thải lượng lớn khổng lồ chất thải ra sông."},{"en":"The country imports vast quantities of oil each year.","vi":"Quốc gia nhập khẩu lượng lớn khổng lồ dầu mỗi năm."},{"en":"Vast quantities of data are stored in modern cloud systems.","vi":"Lượng lớn khổng lồ dữ liệu được lưu trữ trong các hệ thống đám mây hiện đại."}]', '[]', NULL, '/væst ˈkwɑːntətiz əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 8, 'vast range of', 'phạm vi rộng lớn', 'adj + n', '[{"en":"The conference covered a vast range of scientific topics.","vi":"Hội nghị bao quát một phạm vi rộng lớn các chủ đề khoa học."},{"en":"This platform offers a vast range of online learning tools.","vi":"Nền tảng này cung cấp một phạm vi rộng lớn các công cụ học trực tuyến."},{"en":"Her research addresses a vast range of social issues.","vi":"Nghiên cứu của cô đề cập đến một phạm vi rộng lớn các vấn đề xã hội."}]', '[]', NULL, '/væst reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 9, 'verbal communication', 'giao tiếp bằng lời', 'adj + n', '[{"en":"Effective verbal communication is essential in clinical practice.","vi":"Giao tiếp bằng lời hiệu quả là điều thiết yếu trong thực hành lâm sàng."},{"en":"The course aims to improve students'' verbal communication skills.","vi":"Khóa học nhằm cải thiện kỹ năng giao tiếp bằng lời của sinh viên."},{"en":"Verbal communication often conveys emotion more directly than text.","vi":"Giao tiếp bằng lời thường truyền tải cảm xúc trực tiếp hơn văn bản."}]', '[]', NULL, '/ˈvɜːrbəl kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 10, 'verbal language', 'ngôn ngữ nói', 'adj + n', '[{"en":"Children acquire verbal language naturally through daily interaction.","vi":"Trẻ em tiếp thu ngôn ngữ nói một cách tự nhiên qua tương tác hằng ngày."},{"en":"Verbal language and gestures together shape how meaning is understood.","vi":"Ngôn ngữ nói và cử chỉ cùng định hình cách hiểu ý nghĩa."},{"en":"The study compared verbal language across several cultural groups.","vi":"Nghiên cứu so sánh ngôn ngữ nói giữa nhiều nhóm văn hóa."}]', '[]', NULL, '/ˈvɜːrbəl ˈlæŋgwɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 11, 'vested interest', 'lợi ích cá nhân gắn liền', 'adj + n', '[{"en":"Companies have a vested interest in shaping public opinion.","vi":"Các công ty có lợi ích cá nhân gắn liền trong việc định hình dư luận."},{"en":"Politicians with a vested interest may resist genuine reform.","vi":"Các chính trị gia có lợi ích cá nhân gắn liền có thể chống lại cải cách thực sự."},{"en":"Researchers must declare any vested interest in their findings.","vi":"Nhà nghiên cứu phải khai báo mọi lợi ích cá nhân gắn liền với kết quả."}]', '[]', NULL, '/ˈvestɪd ˈɪntrəst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 12, 'virtual community', 'cộng đồng ảo', 'adj + n', '[{"en":"Online forums help create a strong virtual community of learners.","vi":"Các diễn đàn trực tuyến giúp tạo ra một cộng đồng ảo người học vững mạnh."},{"en":"A virtual community can offer support across great distances.","vi":"Một cộng đồng ảo có thể hỗ trợ lẫn nhau dù cách xa về khoảng cách."},{"en":"The study examined how a virtual community shapes its members'' identity.","vi":"Nghiên cứu xem xét cách một cộng đồng ảo định hình bản sắc của thành viên."}]', '[]', NULL, '/ˈvɜːrtʃuəl kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 13, 'virtually impossible', 'gần như không thể', 'adv + adj', '[{"en":"It is virtually impossible to predict the stock market precisely.","vi":"Gần như không thể dự đoán thị trường chứng khoán một cách chính xác."},{"en":"Without funding, completing the project was virtually impossible.","vi":"Không có kinh phí, việc hoàn thành dự án là gần như không thể."},{"en":"Reaching total agreement among all experts is virtually impossible.","vi":"Đạt được sự đồng thuận hoàn toàn giữa các chuyên gia là gần như không thể."}]', '[]', NULL, '/ˈvɜːrtʃuəli ɪmˈpɑːsəbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 14, 'visual image', 'hình ảnh trực quan', 'adj + n', '[{"en":"A strong visual image can make an argument more memorable.","vi":"Một hình ảnh trực quan mạnh có thể khiến lập luận đáng nhớ hơn."},{"en":"The advertisement relied on a single striking visual image.","vi":"Quảng cáo dựa vào một hình ảnh trực quan ấn tượng duy nhất."},{"en":"Our memory often stores a visual image more easily than words.","vi":"Trí nhớ của chúng ta thường lưu hình ảnh trực quan dễ hơn từ ngữ."}]', '[]', NULL, '/ˈvɪʒuəl ˈɪmɪdʒ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 15, 'visual media', 'phương tiện truyền thông hình ảnh', 'adj + n', '[{"en":"Visual media now shape how young people understand world events.","vi":"Phương tiện truyền thông hình ảnh nay định hình cách giới trẻ hiểu các sự kiện thế giới."},{"en":"The lecture explored the growing influence of visual media.","vi":"Bài giảng khám phá ảnh hưởng ngày càng lớn của truyền thông hình ảnh."},{"en":"Teachers increasingly use visual media to engage their students.","vi":"Giáo viên ngày càng dùng truyền thông hình ảnh để thu hút học sinh."}]', '[]', NULL, '/ˈvɪʒuəl ˈmiːdiə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 16, 'visual perception', 'tri giác thị giác', 'adj + n', '[{"en":"Visual perception allows us to interpret depth and distance accurately.","vi":"Tri giác thị giác cho phép ta diễn giải độ sâu và khoảng cách chính xác."},{"en":"The experiment tested how lighting affects visual perception.","vi":"Thí nghiệm kiểm tra cách ánh sáng ảnh hưởng đến tri giác thị giác."},{"en":"Studies of visual perception reveal how the brain processes images.","vi":"Các nghiên cứu về tri giác thị giác cho thấy cách não xử lý hình ảnh."}]', '[]', NULL, '/ˈvɪʒuəl pərˈsepʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 17, 'visual representation', 'biểu diễn trực quan', 'adj + n', '[{"en":"A graph offers a clear visual representation of the trend.","vi":"Biểu đồ cung cấp một biểu diễn trực quan rõ ràng về xu hướng."},{"en":"The map provides a visual representation of population density.","vi":"Bản đồ cung cấp một biểu diễn trực quan về mật độ dân số."},{"en":"Diagrams give students a useful visual representation of the process.","vi":"Sơ đồ cho học sinh một biểu diễn trực quan hữu ích về quy trình."}]', '[]', NULL, '/ˈvɪʒuəl ˌreprɪzenˈteɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 18, 'vital importance', 'tầm quan trọng sống còn', 'adj + n', '[{"en":"Clean water is of vital importance to public health.","vi":"Nước sạch có tầm quan trọng sống còn đối với sức khỏe cộng đồng."},{"en":"Early diagnosis is of vital importance in treating cancer.","vi":"Chẩn đoán sớm có tầm quan trọng sống còn trong điều trị ung thư."},{"en":"Teamwork is of vital importance to the project''s success.","vi":"Làm việc nhóm có tầm quan trọng sống còn đối với thành công của dự án."}]', '[]', NULL, '/ˈvaɪtəl ɪmˈpɔːrtəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 19, 'vital part', 'phần thiết yếu', 'adj + n', '[{"en":"Feedback is a vital part of the learning process.","vi":"Phản hồi là một phần thiết yếu của quá trình học tập."},{"en":"Sleep forms a vital part of a healthy lifestyle.","vi":"Giấc ngủ là một phần thiết yếu của lối sống lành mạnh."},{"en":"Reading widely is a vital part of academic preparation.","vi":"Đọc rộng là một phần thiết yếu của việc chuẩn bị học thuật."}]', '[]', NULL, '/ˈvaɪtəl pɑːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 20, 'vital role', 'vai trò thiết yếu', 'adj + n', '[{"en":"Teachers play a vital role in shaping young minds.","vi":"Giáo viên đóng vai trò thiết yếu trong việc hình thành tư duy trẻ."},{"en":"Bees play a vital role in pollinating food crops.","vi":"Ong đóng vai trò thiết yếu trong việc thụ phấn cho cây lương thực."},{"en":"Technology plays a vital role in modern medical research.","vi":"Công nghệ đóng vai trò thiết yếu trong nghiên cứu y học hiện đại."}]', '[]', NULL, '/ˈvaɪtəl roʊl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 21, 'vulnerable group', 'nhóm dễ bị tổn thương', 'adj + n', '[{"en":"The policy aims to protect vulnerable groups during economic crises.","vi":"Chính sách nhằm bảo vệ các nhóm dễ bị tổn thương trong khủng hoảng kinh tế."},{"en":"Elderly people are often a particularly vulnerable group.","vi":"Người cao tuổi thường là một nhóm đặc biệt dễ bị tổn thương."},{"en":"Researchers focused on vulnerable groups affected by the disaster.","vi":"Các nhà nghiên cứu tập trung vào các nhóm dễ bị tổn thương bởi thảm họa."}]', '[]', NULL, '/ˈvʌlnərəbəl gruːp/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 22, 'welfare reform', 'cải cách phúc lợi', 'n + n', '[{"en":"The government introduced welfare reform to reduce dependency on benefits.","vi":"Chính phủ đưa ra cải cách phúc lợi để giảm sự phụ thuộc vào trợ cấp."},{"en":"Critics argued that welfare reform harmed the poorest families.","vi":"Các nhà phê bình cho rằng cải cách phúc lợi làm tổn hại các gia đình nghèo nhất."},{"en":"Welfare reform remains a controversial topic among policymakers.","vi":"Cải cách phúc lợi vẫn là chủ đề gây tranh cãi giữa các nhà hoạch định chính sách."}]', '[]', NULL, '/ˈwelfer rɪˈfɔːrm/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 23, 'well aware', 'nhận thức rõ', 'adv + adj', '[{"en":"The author is well aware of the study''s limitations.","vi":"Tác giả nhận thức rõ những hạn chế của nghiên cứu."},{"en":"Students should be well aware of the deadline requirements.","vi":"Sinh viên nên nhận thức rõ các yêu cầu về thời hạn nộp bài."},{"en":"Managers were well aware of the risks before deciding.","vi":"Các quản lý đã nhận thức rõ các rủi ro trước khi quyết định."}]', '[]', NULL, '/wel əˈwer/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 24, 'well designed', 'được thiết kế tốt', 'adv + vpp', '[{"en":"A well designed experiment controls for unwanted variables.","vi":"Một thí nghiệm được thiết kế tốt kiểm soát các biến không mong muốn."},{"en":"The well designed survey produced clear and reliable results.","vi":"Cuộc khảo sát được thiết kế tốt cho ra kết quả rõ ràng và đáng tin cậy."},{"en":"Well designed buildings make efficient use of natural light.","vi":"Các tòa nhà được thiết kế tốt tận dụng hiệu quả ánh sáng tự nhiên."}]', '[]', NULL, '/wel dɪˈzaɪnd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 25, 'well documented', 'được ghi chép đầy đủ', 'adv + vpp', '[{"en":"The effects of smoking are well documented in medical literature.","vi":"Tác hại của hút thuốc đã được ghi chép đầy đủ trong tài liệu y học."},{"en":"Her claims are well documented with reliable primary sources.","vi":"Các khẳng định của cô được ghi chép đầy đủ bằng nguồn sơ cấp đáng tin cậy."},{"en":"This phenomenon is well documented across several earlier studies.","vi":"Hiện tượng này được ghi chép đầy đủ trong nhiều nghiên cứu trước đó."}]', '[]', NULL, '/wel ˈdɑːkjəmentɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 26, 'well educated', 'có học thức cao', 'adv + vpp', '[{"en":"A well educated workforce is essential for economic growth.","vi":"Một lực lượng lao động có học thức cao là thiết yếu cho tăng trưởng kinh tế."},{"en":"Well educated citizens tend to participate more in politics.","vi":"Công dân có học thức cao thường tham gia chính trị nhiều hơn."},{"en":"The company prefers candidates who are well educated and adaptable.","vi":"Công ty ưu tiên ứng viên có học thức cao và dễ thích nghi."}]', '[]', NULL, '/wel ˈedʒəkeɪtɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 27, 'well established', 'đã được khẳng định vững chắc', 'adv + vpp', '[{"en":"The link between diet and health is well established.","vi":"Mối liên hệ giữa chế độ ăn và sức khỏe đã được khẳng định vững chắc."},{"en":"She joined a well established research team at the university.","vi":"Cô gia nhập một nhóm nghiên cứu đã được khẳng định vững chắc ở trường đại học."},{"en":"This theory is well established and widely taught today.","vi":"Lý thuyết này đã được khẳng định vững chắc và được giảng dạy rộng rãi ngày nay."}]', '[]', NULL, '/wel ɪˈstæblɪʃt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 28, 'well received', 'được đón nhận tốt', 'adv + vpp', '[{"en":"Her presentation was well received by the entire committee.","vi":"Bài thuyết trình của cô được toàn bộ hội đồng đón nhận tốt."},{"en":"The new policy was well received among local residents.","vi":"Chính sách mới được người dân địa phương đón nhận tốt."},{"en":"The book was well received by critics and readers alike.","vi":"Cuốn sách được cả giới phê bình lẫn độc giả đón nhận tốt."}]', '[]', NULL, '/wel rɪˈsiːvd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 29, 'western democracy', 'nền dân chủ phương Tây', 'adj + n', '[{"en":"Western democracy relies on free elections and a free press.","vi":"Nền dân chủ phương Tây dựa vào bầu cử tự do và báo chí tự do."},{"en":"The essay compares western democracy with other political systems.","vi":"Bài luận so sánh nền dân chủ phương Tây với các hệ thống chính trị khác."},{"en":"Many scholars debate the future of western democracy today.","vi":"Nhiều học giả tranh luận về tương lai của nền dân chủ phương Tây hiện nay."}]', '[]', NULL, '/ˈwestərn dɪˈmɑːkrəsi/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 30, 'western society', 'xã hội phương Tây', 'adj + n', '[{"en":"Individualism is a strong value in western society.","vi":"Chủ nghĩa cá nhân là một giá trị mạnh trong xã hội phương Tây."},{"en":"Western society has changed rapidly with new technology.","vi":"Xã hội phương Tây đã thay đổi nhanh chóng với công nghệ mới."},{"en":"The study examines aging populations across western society.","vi":"Nghiên cứu xem xét tình trạng dân số già hóa trong xã hội phương Tây."}]', '[]', NULL, '/ˈwestərn səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 31, 'western tradition', 'truyền thống phương Tây', 'adj + n', '[{"en":"The course traces the western tradition of philosophical thought.","vi":"Khóa học truy nguyên truyền thống tư tưởng triết học phương Tây."},{"en":"This artwork blends eastern and western tradition beautifully.","vi":"Tác phẩm này kết hợp truyền thống phương Đông và phương Tây một cách đẹp đẽ."},{"en":"Western tradition has deeply shaped modern legal systems.","vi":"Truyền thống phương Tây đã định hình sâu sắc các hệ thống pháp luật hiện đại."}]', '[]', NULL, '/ˈwestərn trəˈdɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 32, 'whole area', 'toàn bộ lĩnh vực', 'adj + n', '[{"en":"The whole area of cognitive science has grown rapidly.","vi":"Toàn bộ lĩnh vực khoa học nhận thức đã phát triển nhanh chóng."},{"en":"Her research opened up a whole area of inquiry.","vi":"Nghiên cứu của cô mở ra toàn bộ một lĩnh vực tìm hiểu mới."},{"en":"The flood damaged the whole area surrounding the river.","vi":"Lũ lụt làm hư hại toàn bộ khu vực xung quanh con sông."}]', '[]', NULL, '/hoʊl ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 33, 'whole period', 'toàn bộ giai đoạn', 'adj + n', '[{"en":"Sales remained stable throughout the whole period of study.","vi":"Doanh số ổn định suốt toàn bộ giai đoạn nghiên cứu."},{"en":"The data were collected over the whole period of treatment.","vi":"Dữ liệu được thu thập trong toàn bộ giai đoạn điều trị."},{"en":"Temperatures rose gradually during the whole period observed.","vi":"Nhiệt độ tăng dần trong toàn bộ giai đoạn được quan sát."}]', '[]', NULL, '/hoʊl ˈpɪriəd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 34, 'whole range of', 'toàn bộ phạm vi', 'adj + n', '[{"en":"The program offers a whole range of support services.","vi":"Chương trình cung cấp toàn bộ một phạm vi các dịch vụ hỗ trợ."},{"en":"Climate change affects a whole range of natural systems.","vi":"Biến đổi khí hậu ảnh hưởng đến toàn bộ một phạm vi các hệ thống tự nhiên."},{"en":"Her job involves a whole range of administrative tasks.","vi":"Công việc của cô bao gồm toàn bộ một phạm vi các nhiệm vụ hành chính."}]', '[]', NULL, '/hoʊl reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 35, 'wide area', 'khu vực rộng', 'adj + n', '[{"en":"The new network covers a wide area of the city.","vi":"Mạng lưới mới bao phủ một khu vực rộng của thành phố."},{"en":"Pollution from the factory spread over a wide area.","vi":"Ô nhiễm từ nhà máy lan rộng trên một khu vực rộng."},{"en":"The drought affected a wide area of farmland this year.","vi":"Hạn hán ảnh hưởng đến một khu vực rộng đất nông nghiệp năm nay."}]', '[]', NULL, '/waɪd ˈeriə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 36, 'wide array of', 'một loạt đa dạng', 'adj + n', '[{"en":"The festival featured a wide array of cultural performances.","vi":"Lễ hội có một loạt đa dạng các tiết mục văn hóa."},{"en":"Students explored a wide array of career options at the fair.","vi":"Sinh viên khám phá một loạt đa dạng lựa chọn nghề nghiệp tại hội chợ."},{"en":"The report addresses a wide array of environmental concerns.","vi":"Báo cáo đề cập một loạt đa dạng các mối quan ngại về môi trường."}]', '[]', NULL, '/waɪd əˈreɪ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 37, 'wide range of', 'phạm vi rộng', 'adj + n', '[{"en":"The library holds books on a wide range of subjects.","vi":"Thư viện có sách về một phạm vi rộng các môn học."},{"en":"The survey gathered views from a wide range of people.","vi":"Cuộc khảo sát thu thập quan điểm từ một phạm vi rộng người dân."},{"en":"Her work draws on a wide range of academic disciplines.","vi":"Công trình của cô dựa trên một phạm vi rộng các ngành học thuật."}]', '[]', NULL, '/waɪd reɪndʒ əv/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 38, 'wide variation', 'sự dao động rộng', 'adj + n', '[{"en":"There is wide variation in income across the region.","vi":"Có sự dao động rộng về thu nhập trên khắp khu vực."},{"en":"The study found wide variation in students'' test scores.","vi":"Nghiên cứu phát hiện sự dao động rộng trong điểm thi của học sinh."},{"en":"Wide variation in rainfall makes farming difficult to plan.","vi":"Sự dao động rộng về lượng mưa khiến việc canh tác khó lên kế hoạch."}]', '[]', NULL, '/waɪd ˌveriˈeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 39, 'widely accepted', 'được chấp nhận rộng rãi', 'adv + vpp', '[{"en":"This theory is now widely accepted within the scientific community.","vi":"Lý thuyết này nay được chấp nhận rộng rãi trong cộng đồng khoa học."},{"en":"It is widely accepted that exercise improves mental health.","vi":"Người ta chấp nhận rộng rãi rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"The method became widely accepted after repeated successful trials.","vi":"Phương pháp này được chấp nhận rộng rãi sau nhiều thử nghiệm thành công."}]', '[]', NULL, '/ˈwaɪdli əkˈseptɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 40, 'widely adopted', 'được áp dụng rộng rãi', 'adv + vpp', '[{"en":"The new standard was widely adopted across the industry.","vi":"Tiêu chuẩn mới được áp dụng rộng rãi trong toàn ngành."},{"en":"Renewable technologies are being widely adopted in many countries.","vi":"Công nghệ tái tạo đang được áp dụng rộng rãi ở nhiều quốc gia."},{"en":"The teaching approach was widely adopted in primary schools.","vi":"Phương pháp giảng dạy được áp dụng rộng rãi ở các trường tiểu học."}]', '[]', NULL, '/ˈwaɪdli əˈdɑːptɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 41, 'widely available', 'có sẵn rộng rãi', 'adv + adj', '[{"en":"Vaccines are now widely available in most rural areas.","vi":"Vắc-xin nay có sẵn rộng rãi ở hầu hết các vùng nông thôn."},{"en":"Online courses have made education more widely available.","vi":"Các khóa học trực tuyến đã làm cho giáo dục có sẵn rộng rãi hơn."},{"en":"Such data is widely available through government websites.","vi":"Dữ liệu như vậy có sẵn rộng rãi qua các trang web chính phủ."}]', '[]', NULL, '/ˈwaɪdli əˈveɪləbəl/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 42, 'widely believed', 'được tin tưởng rộng rãi', 'adv + vpp', '[{"en":"It is widely believed that early intervention improves outcomes.","vi":"Người ta tin tưởng rộng rãi rằng can thiệp sớm cải thiện kết quả."},{"en":"This myth was widely believed for many centuries.","vi":"Lầm tưởng này được tin tưởng rộng rãi trong nhiều thế kỷ."},{"en":"It is widely believed that the policy will reduce unemployment.","vi":"Người ta tin tưởng rộng rãi rằng chính sách sẽ giảm thất nghiệp."}]', '[]', NULL, '/ˈwaɪdli bɪˈliːvd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 43, 'widely different', 'khác nhau rõ rệt', 'adv + adj', '[{"en":"The two studies reached widely different conclusions about the cause.","vi":"Hai nghiên cứu đi đến những kết luận khác nhau rõ rệt về nguyên nhân."},{"en":"Participants came from widely different social backgrounds.","vi":"Người tham gia đến từ những hoàn cảnh xã hội khác nhau rõ rệt."},{"en":"Their views on the issue were widely different from ours.","vi":"Quan điểm của họ về vấn đề khác nhau rõ rệt so với chúng tôi."}]', '[]', NULL, '/ˈwaɪdli ˈdɪfərənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 44, 'widely discussed', 'được bàn luận rộng rãi', 'adv + vpp', '[{"en":"The topic of climate change is widely discussed in classrooms.","vi":"Chủ đề biến đổi khí hậu được bàn luận rộng rãi trong lớp học."},{"en":"Her findings were widely discussed at the annual conference.","vi":"Phát hiện của cô được bàn luận rộng rãi tại hội nghị thường niên."},{"en":"This issue has been widely discussed in recent newspapers.","vi":"Vấn đề này đã được bàn luận rộng rãi trên báo chí gần đây."}]', '[]', NULL, '/ˈwaɪdli dɪˈskʌst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 45, 'widely dispersed', 'phân tán rộng', 'adv + vpp', '[{"en":"The population is widely dispersed across remote mountain villages.","vi":"Dân cư phân tán rộng khắp các ngôi làng miền núi xa xôi."},{"en":"Seeds are widely dispersed by wind and passing animals.","vi":"Hạt giống được phân tán rộng nhờ gió và động vật đi qua."},{"en":"The research samples were widely dispersed throughout the country.","vi":"Các mẫu nghiên cứu được phân tán rộng khắp cả nước."}]', '[]', NULL, '/ˈwaɪdli dɪˈspɜːrst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 46, 'widely distributed', 'được phân bố rộng rãi', 'adv + vpp', '[{"en":"This species is widely distributed across temperate regions.","vi":"Loài này được phân bố rộng rãi khắp các vùng ôn đới."},{"en":"The survey forms were widely distributed among the students.","vi":"Các phiếu khảo sát được phân bố rộng rãi giữa các sinh viên."},{"en":"Wealth is not widely distributed across the whole population.","vi":"Của cải không được phân bố rộng rãi trên toàn bộ dân số."}]', '[]', NULL, '/ˈwaɪdli dɪˈstrɪbjutɪd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 47, 'widely known', 'được biết đến rộng rãi', 'adv + vpp', '[{"en":"The scientist is widely known for her work on genetics.","vi":"Nhà khoa học được biết đến rộng rãi nhờ công trình về di truyền học."},{"en":"It is widely known that smoking causes serious illness.","vi":"Người ta biết đến rộng rãi rằng hút thuốc gây bệnh nghiêm trọng."},{"en":"This city is widely known for its historic architecture.","vi":"Thành phố này được biết đến rộng rãi nhờ kiến trúc lịch sử."}]', '[]', NULL, '/ˈwaɪdli noʊn/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 48, 'widely read', 'được đọc rộng rãi', 'adv + vpp', '[{"en":"Her novel became widely read across several generations.","vi":"Tiểu thuyết của bà trở nên được đọc rộng rãi qua nhiều thế hệ."},{"en":"The journal is widely read by researchers in the field.","vi":"Tạp chí được đọc rộng rãi bởi các nhà nghiên cứu trong lĩnh vực."},{"en":"This newspaper remains widely read despite the rise of online media.","vi":"Tờ báo này vẫn được đọc rộng rãi dù truyền thông trực tuyến phát triển."}]', '[]', NULL, '/ˈwaɪdli red/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 49, 'widely recognized', 'được công nhận rộng rãi', 'adv + vpp', '[{"en":"The brand is widely recognized for its high quality.","vi":"Thương hiệu được công nhận rộng rãi về chất lượng cao."},{"en":"It is widely recognized that education reduces poverty over time.","vi":"Người ta công nhận rộng rãi rằng giáo dục giảm nghèo theo thời gian."},{"en":"Her contribution to the field is widely recognized today.","vi":"Đóng góp của cô cho lĩnh vực này được công nhận rộng rãi ngày nay."}]', '[]', NULL, '/ˈwaɪdli ˈrekəgnaɪzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 50, 'widely regarded as', 'được xem rộng rãi là', 'adv + vpp', '[{"en":"She is widely regarded as the leading expert in linguistics.","vi":"Cô được xem rộng rãi là chuyên gia hàng đầu về ngôn ngữ học."},{"en":"This book is widely regarded as a classic in its field.","vi":"Cuốn sách này được xem rộng rãi là tác phẩm kinh điển trong lĩnh vực."},{"en":"The reform is widely regarded as a major political success.","vi":"Cuộc cải cách được xem rộng rãi là một thành công chính trị lớn."}]', '[]', NULL, '/ˈwaɪdli rɪˈgɑːrdɪd æz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 51, 'widely shared', 'được chia sẻ rộng rãi', 'adv + vpp', '[{"en":"The post was widely shared across many social media platforms.","vi":"Bài đăng được chia sẻ rộng rãi trên nhiều nền tảng mạng xã hội."},{"en":"This concern is widely shared among parents and teachers.","vi":"Mối lo ngại này được chia sẻ rộng rãi giữa phụ huynh và giáo viên."},{"en":"The belief in fairness is widely shared across cultures.","vi":"Niềm tin vào sự công bằng được chia sẻ rộng rãi giữa các nền văn hóa."}]', '[]', NULL, '/ˈwaɪdli ʃerd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 52, 'widely used', 'được sử dụng rộng rãi', 'adv + vpp', '[{"en":"This software is widely used in academic data analysis.","vi":"Phần mềm này được sử dụng rộng rãi trong phân tích dữ liệu học thuật."},{"en":"English is widely used as a language of international research.","vi":"Tiếng Anh được sử dụng rộng rãi như ngôn ngữ của nghiên cứu quốc tế."},{"en":"The method is widely used because it is simple and reliable.","vi":"Phương pháp được sử dụng rộng rãi vì nó đơn giản và đáng tin cậy."}]', '[]', NULL, '/ˈwaɪdli juːzd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 53, 'wider audience', 'đối tượng khán giả rộng hơn', 'adj + n', '[{"en":"Publishing online helps research reach a wider audience.","vi":"Xuất bản trực tuyến giúp nghiên cứu tiếp cận đối tượng khán giả rộng hơn."},{"en":"The author simplified the text to attract a wider audience.","vi":"Tác giả đơn giản hóa văn bản để thu hút đối tượng khán giả rộng hơn."},{"en":"Social media allows ideas to spread to a wider audience.","vi":"Mạng xã hội cho phép ý tưởng lan tới đối tượng khán giả rộng hơn."}]', '[]', NULL, '/ˈwaɪdər ˈɔːdiəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 54, 'wider community', 'cộng đồng rộng lớn hơn', 'adj + n', '[{"en":"The university shares its research with the wider community.","vi":"Trường đại học chia sẻ nghiên cứu với cộng đồng rộng lớn hơn."},{"en":"Volunteering builds stronger links with the wider community.","vi":"Hoạt động tình nguyện xây dựng liên kết bền chặt hơn với cộng đồng rộng lớn hơn."},{"en":"The project aims to benefit the wider community as well.","vi":"Dự án cũng nhằm mang lại lợi ích cho cộng đồng rộng lớn hơn."}]', '[]', NULL, '/ˈwaɪdər kəˈmjuːnəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 55, 'wider context', 'bối cảnh rộng hơn', 'adj + n', '[{"en":"The essay places the war in its wider context.","vi":"Bài luận đặt cuộc chiến trong bối cảnh rộng hơn của nó."},{"en":"Understanding the wider context helps interpret the findings correctly.","vi":"Hiểu bối cảnh rộng hơn giúp diễn giải kết quả một cách chính xác."},{"en":"We must consider the wider context of these economic changes.","vi":"Chúng ta phải xem xét bối cảnh rộng hơn của những thay đổi kinh tế này."}]', '[]', NULL, '/ˈwaɪdər ˈkɑːntekst/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 56, 'wider implications', 'những hệ quả rộng hơn', 'adj + n', '[{"en":"The study explores the wider implications of climate policy.","vi":"Nghiên cứu khám phá những hệ quả rộng hơn của chính sách khí hậu."},{"en":"These results have wider implications for public health planning.","vi":"Những kết quả này có hệ quả rộng hơn đối với việc lập kế hoạch y tế công cộng."},{"en":"We should not ignore the wider implications of this decision.","vi":"Chúng ta không nên bỏ qua những hệ quả rộng hơn của quyết định này."}]', '[]', NULL, '/ˈwaɪdər ˌɪmplɪˈkeɪʃənz/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 57, 'wider issue', 'vấn đề rộng hơn', 'adj + n', '[{"en":"This complaint points to a wider issue within the system.","vi":"Lời phàn nàn này chỉ ra một vấn đề rộng hơn trong hệ thống."},{"en":"The debate reflects a wider issue about social inequality.","vi":"Cuộc tranh luận phản ánh một vấn đề rộng hơn về bất bình đẳng xã hội."},{"en":"Her paper connects local data to a wider issue.","vi":"Bài viết của cô kết nối dữ liệu địa phương với một vấn đề rộng hơn."}]', '[]', NULL, '/ˈwaɪdər ˈɪʃuː/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 58, 'wider public', 'công chúng rộng rãi hơn', 'adj + n', '[{"en":"Scientists must explain their findings to the wider public.","vi":"Các nhà khoa học phải giải thích phát hiện của mình cho công chúng rộng rãi hơn."},{"en":"The campaign aimed to raise awareness among the wider public.","vi":"Chiến dịch nhằm nâng cao nhận thức trong công chúng rộng rãi hơn."},{"en":"The exhibition made the artworks accessible to the wider public.","vi":"Cuộc triển lãm giúp các tác phẩm dễ tiếp cận với công chúng rộng rãi hơn."}]', '[]', NULL, '/ˈwaɪdər ˈpʌblɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 59, 'wider society', 'xã hội rộng lớn hơn', 'adj + n', '[{"en":"Schools prepare young people to contribute to wider society.","vi":"Trường học chuẩn bị cho người trẻ đóng góp cho xã hội rộng lớn hơn."},{"en":"The reform had positive effects on wider society overall.","vi":"Cuộc cải cách có tác động tích cực đến xã hội rộng lớn hơn nói chung."},{"en":"Such attitudes can spread quickly throughout wider society.","vi":"Những thái độ như vậy có thể lan nhanh khắp xã hội rộng lớn hơn."}]', '[]', NULL, '/ˈwaɪdər səˈsaɪəti/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 60, 'widespread acceptance', 'sự chấp nhận rộng khắp', 'adj + n', '[{"en":"The new theory gained widespread acceptance among researchers.","vi":"Lý thuyết mới giành được sự chấp nhận rộng khắp giữa các nhà nghiên cứu."},{"en":"Widespread acceptance of recycling took several decades to achieve.","vi":"Sự chấp nhận rộng khắp về tái chế phải mất vài thập kỷ mới đạt được."},{"en":"The idea has not yet won widespread acceptance in practice.","vi":"Ý tưởng này vẫn chưa giành được sự chấp nhận rộng khắp trong thực tế."}]', '[]', NULL, '/ˈwaɪdspred əkˈseptəns/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 61, 'widespread belief', 'niềm tin phổ biến rộng rãi', 'adj + n', '[{"en":"There is a widespread belief that money brings happiness.","vi":"Có một niềm tin phổ biến rộng rãi rằng tiền mang lại hạnh phúc."},{"en":"The study challenged the widespread belief about memory loss.","vi":"Nghiên cứu thách thức niềm tin phổ biến rộng rãi về mất trí nhớ."},{"en":"A widespread belief in fairness underpins many legal systems.","vi":"Một niềm tin phổ biến rộng rãi vào công bằng làm nền cho nhiều hệ thống pháp luật."}]', '[]', NULL, '/ˈwaɪdspred bɪˈliːf/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 62, 'widespread support', 'sự ủng hộ rộng khắp', 'adj + n', '[{"en":"The proposal received widespread support from local residents.","vi":"Đề xuất nhận được sự ủng hộ rộng khắp từ người dân địa phương."},{"en":"Widespread support helped the charity expand its programs quickly.","vi":"Sự ủng hộ rộng khắp giúp tổ chức từ thiện mở rộng chương trình nhanh chóng."},{"en":"The candidate enjoyed widespread support among younger voters.","vi":"Ứng cử viên nhận được sự ủng hộ rộng khắp trong cử tri trẻ."}]', '[]', NULL, '/ˈwaɪdspred səˈpɔːrt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 63, 'widespread use', 'việc sử dụng rộng khắp', 'adj + n', '[{"en":"The widespread use of smartphones has changed daily communication.","vi":"Việc sử dụng rộng khắp điện thoại thông minh đã thay đổi giao tiếp hằng ngày."},{"en":"Researchers warned against the widespread use of antibiotics.","vi":"Các nhà nghiên cứu cảnh báo về việc sử dụng rộng khắp kháng sinh."},{"en":"The widespread use of plastic creates serious environmental problems.","vi":"Việc sử dụng rộng khắp nhựa gây ra các vấn đề môi trường nghiêm trọng."}]', '[]', NULL, '/ˈwaɪdspred juːs/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 64, 'work effectively', 'làm việc hiệu quả', 'v + adv', '[{"en":"Students learn to work effectively in small collaborative groups.","vi":"Sinh viên học cách làm việc hiệu quả trong các nhóm hợp tác nhỏ."},{"en":"The team worked effectively despite the tight deadline.","vi":"Nhóm đã làm việc hiệu quả bất chấp thời hạn gấp rút."},{"en":"Good communication helps colleagues work effectively together.","vi":"Giao tiếp tốt giúp các đồng nghiệp làm việc hiệu quả cùng nhau."}]', '[]', NULL, '/wɜːrk ɪˈfektɪvli/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 65, 'written comment', 'nhận xét bằng văn bản', 'adj + n', '[{"en":"The teacher gave detailed written comments on each essay.","vi":"Giáo viên đưa ra nhận xét bằng văn bản chi tiết cho từng bài luận."},{"en":"Students valued the written comments more than the grades.","vi":"Sinh viên coi trọng nhận xét bằng văn bản hơn cả điểm số."},{"en":"Reviewers provided helpful written comments on the draft paper.","vi":"Người phản biện cung cấp nhận xét bằng văn bản hữu ích cho bản thảo."}]', '[]', NULL, '/ˈrɪtən ˈkɑːment/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 66, 'written communication', 'giao tiếp bằng văn bản', 'adj + n', '[{"en":"Clear written communication is essential in professional workplaces.","vi":"Giao tiếp bằng văn bản rõ ràng là điều thiết yếu ở nơi làm việc chuyên nghiệp."},{"en":"The course develops students'' written communication skills steadily.","vi":"Khóa học phát triển kỹ năng giao tiếp bằng văn bản của sinh viên một cách đều đặn."},{"en":"Email has become a dominant form of written communication.","vi":"Email đã trở thành một hình thức giao tiếp bằng văn bản phổ biến."}]', '[]', NULL, '/ˈrɪtən kəˌmjuːnɪˈkeɪʃən/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 67, 'written statement', 'tuyên bố bằng văn bản', 'adj + n', '[{"en":"The witness provided a written statement to the police.","vi":"Nhân chứng cung cấp một tuyên bố bằng văn bản cho cảnh sát."},{"en":"The company issued a written statement explaining its decision.","vi":"Công ty ra một tuyên bố bằng văn bản giải thích quyết định của mình."},{"en":"Applicants must submit a written statement of their goals.","vi":"Ứng viên phải nộp một tuyên bố bằng văn bản về mục tiêu của họ."}]', '[]', NULL, '/ˈrɪtən ˈsteɪtmənt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('colloc-17-01', 68, 'younger generation', 'thế hệ trẻ hơn', 'adj + n', '[{"en":"The younger generation increasingly relies on digital technology.","vi":"Thế hệ trẻ hơn ngày càng phụ thuộc vào công nghệ số."},{"en":"Traditional values are slowly changing within the younger generation.","vi":"Các giá trị truyền thống đang dần thay đổi trong thế hệ trẻ hơn."},{"en":"The younger generation tends to value flexible working arrangements.","vi":"Thế hệ trẻ hơn có xu hướng coi trọng các thỏa thuận làm việc linh hoạt."}]', '[]', NULL, '/ˈjʌŋgər ˌdʒenəˈreɪʃən/', NULL, NULL, NULL);
